class GameOptions(unittest.TestCase):
    """Things that are the game's own settings: we flip the game's switch and never keep one of our own."""

    def alphas(self, e):
        return [e.g[name].alpha for name in e.mock.cooldownFrames.values()]

    def test_the_hud_never_switches_the_cooldown_manager_by_itself(self):
        e = Env(login=False)
        e.mock.cvars.cooldownViewerEnabled = "0"
        for ev in ("ADDON_LOADED", "PLAYER_LOGIN"):
            e.mock.fire(ev, "ControllerCam_HUD")
        e.mock.state.combat = True
        e.update(1)
        self.assertEqual(e.mock.cvars.cooldownViewerEnabled, "0")
        self.assertEqual(self.alphas(e), [1, 1, 1, 1])              # and its frames are never touched
        self.assertNotIn("cooldown", e.mock.serialize(e.g.ControllerCamHUDDB).lower())

    def test_our_switch_is_the_games_switch(self):
        e = Env()
        self.assertIn("off", e.cmd("cooldowns off"))
        self.assertEqual(e.mock.cvars.cooldownViewerEnabled, "0")
        e.cmd("cooldowns")
        self.assertEqual(e.mock.cvars.cooldownViewerEnabled, "1")
        e.cmd("resource on")
        self.assertEqual(e.mock.cvars.nameplateShowSelf, "1")
        self.assertIn("personal resource", e.cmd(""))

    def test_what_an_earlier_version_forced_on_is_put_back_once(self):
        e = Env(db="{ v = 2, saved = { cooldownViewerEnabled = '0' } }")
        self.assertEqual(e.mock.cvars.cooldownViewerEnabled, "0")
        self.assertIsNone(e.db.saved.cooldownViewerEnabled)

    def test_target_of_target_follows_the_games_option(self):
        e = Env(login=False)
        e.mock.cvars.showTargetOfTarget = "0"
        for ev in ("ADDON_LOADED", "PLAYER_LOGIN"):
            e.mock.fire(ev, "ControllerCam_HUD")
        e.target()
        e.mock.setUnit("targettarget", e.lua.table(name="Tank", health=5, healthMax=10))
        self.assertFalse(e.frames.tot.button.shown)
        e.cmd("tot on")
        self.assertEqual(e.mock.cvars.showTargetOfTarget, "1")
        self.assertTrue(e.frames.tot.button.shown)
        # switched off in the game's own options menu
        e.mock.cvars.showTargetOfTarget = "0"
        e.mock.fire("CVAR_UPDATE", "showTargetOfTarget", "0")
        self.assertFalse(e.frames.tot.button.shown)
        self.assertEqual(e.ns.RunCheck(False)[0], 0)

    def test_the_buff_tooltip_is_off_once_and_can_come_back(self):
        e = Env()
        self.assertEqual(e.mock.cvars.GamepadShowAutoAuraTooltip, "0")     # off to begin with
        e.cmd("auratooltip on")
        self.assertEqual(e.mock.cvars.GamepadShowAutoAuraTooltip, "1")
        saved = e.mock.serialize(e.g.ControllerCamHUDDB)
        e2 = Env(db=saved)
        self.assertEqual(e2.mock.cvars.GamepadShowAutoAuraTooltip, "1")    # never switched off again

    def test_a_client_without_the_option_says_so(self):
        e = Env()
        e.mock.cvars.nameplateShowSelf = None
        self.assertIn("does not have", e.cmd("resource on"))

    def test_focus_has_its_own_frame(self):
        e = Env()
        f = e.frames.focus
        self.assertFalse(f.button.shown)
        self.assertEqual(e.aside("FocusFrame"), True)
        e.mock.setUnit("focus", e.lua.table(name="Healer", level=60, health=300, healthMax=600, isPlayer=True,
                                            **{"class": "MAGE"}))
        self.assertTrue(f.button.shown)
        self.assertIn("Healer", f.name.text)
        self.assertEqual(f.health.fill.value, 300)
        self.assertEqual(e.color(f.health), (0.25, 0.78, 0.92))
        e.cmd("focus off")
        self.assertFalse(f.button.shown)
        self.assertEqual(e.aside("FocusFrame"), False)

    def test_target_of_target_and_focus_move_on_their_own(self):
        e = Env()
        e.mock.editMode(True)
        for key in ("player", "target", "tot", "focus"):
            mover = e.frames[key].mover
            self.assertTrue(mover.movable, key)
            mover.cx, mover.cy = 100, 100
            mover.scripts.OnDragStop(mover)
            self.assertIsNotNone(e.db.pos[key], key)
        self.assertFalse(e.frames.pet.mover.movable)
        e2 = Env(db=e.mock.serialize(e.g.ControllerCamHUDDB))
        self.assertEqual(e2.frames.tot.mover.points[1][1], "CENTER")


class CastLooks(unittest.TestCase):
    """Casts look like what they are: gathering, crafting, travel, or the school of the spell."""

    def player_cast(self, e, seconds=2, **kw):
        now = e.mock.time
        e.mock.units.player.cast = e.lua.table(start=now * 1000, stop=(now + seconds) * 1000, **kw)
        e.mock.fire("UNIT_SPELLCAST_START", "player")
        return e.ns.CastBar

    def test_mining_throws_chips_and_lands_its_own_way(self):
        e = Env()
        e.mock.spellNames = e.lua.table_from({2575: "Mining"})
        cb = self.player_cast(e, name="Mining", spellId=99999)          # another rank: known by its name
        self.assertEqual(cb.look.kind, "mining")
        ore = e.ns.CastLook.KINDS.mining.color
        self.assertEqual(round(cb.bar.fill.color[1], 2), round(ore[1], 2))
        self.assertEqual(cb.art.kind, "mining")                         # a pick works on the bar
        self.assertEqual(len(list(e.ns.Impact.live.keys())), 0)
        chips = 0
        for _ in range(14):
            e.update(0.05)
            chips = max(chips, len(list(e.ns.Impact.live.keys())))
        self.assertEqual(cb.art.state.strikes, 0)                       # hauled back: you swing once a second
        self.assertEqual(chips, 0)
        self.assertGreater(cb.art.state.lift, 0.5)
        for _ in range(8):
            e.update(0.05)
            chips = max(chips, len(list(e.ns.Impact.live.keys())))
        self.assertEqual(cb.art.state.strikes, 1)                       # on the second it comes down,
        self.assertGreater(chips, 0)                                    # chips fly,
        self.assertIsNotNone(cb.art.state.crackAt[1])                   # and a crack stays where it struck
        self.assertEqual(e.errors(), [])

    def test_the_last_blow_crumbles_the_bar(self):
        e = Env()
        e.mock.spellNames = e.lua.table_from({2575: "Mining"})
        cb = self.player_cast(e, seconds=2.5, name="Mining", spellId=2575)
        art = cb.art
        for _ in range(50):
            e.update(0.05)
        self.assertEqual(art.state.strikes, 2)                          # at one second and at two
        self.assertEqual(cb.bar.fill.alpha, 1)
        e.update(0.05, 0.05)                                            # the cast lands: the last blow
        e.update(0.05, 0.05)
        self.assertTrue(art.state.crumbled)
        self.assertEqual(art.state.strikes, 3)
        self.assertEqual(cb.bar.fill.alpha, 0)                          # the bar itself is gone: its pieces stand in
        chunks = list(art.state.chunks.values())
        self.assertGreaterEqual(len(chunks), 6)
        self.assertTrue(all(c.alpha == 1 for c in chunks))
        first = [c.points[1][5] for c in chunks]
        e.update(0.4, 0.05)
        self.assertTrue(cb.frame.shown)                                 # (it stays up long enough to fall)
        self.assertLess(min(c.points[1][5] for c in chunks), min(first) - 10)   # falling
        e.update(1, 0.05)
        self.assertFalse(cb.frame.shown)
        self.assertEqual(cb.bar.fill.alpha, 1)                          # and the bar is whole for the next cast
        self.assertEqual(e.errors(), [])

    def test_an_interrupted_swing_crumbles_nothing(self):
        e = Env()
        e.mock.spellNames = e.lua.table_from({2575: "Mining"})
        cb = self.player_cast(e, seconds=3, name="Mining", spellId=2575)
        e.update(0.5, 0.05)
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_INTERRUPTED", "player")
        e.update(0.1, 0.05)
        self.assertIsNone(cb.art.state.crumbled)
        self.assertEqual(cb.bar.fill.alpha, 1)
        self.assertEqual(e.errors(), [])

    def test_gathering_and_making_know_what_it_is(self):
        e = Env()
        K = e.ns.CastLook
        e.mock.spellNames = e.lua.table_from({2366: "Herb Gathering", 2575: "Mining"})
        self.assertEqual(K.Found("herbs", "Peacebloom").id, 2447)        # a herb's node is named as the herb is
        self.assertEqual(K.Found("herbs", "Wild Steelbloom").id, 3355)
        self.assertIsNone(K.Found("herbs", "Felweed"))                   # (one not listed is not taken for another)
        for node, ore in (("Copper Vein", 2770), ("Tin Vein", 2771), ("Silver Vein", 2775), ("Iron Deposit", 2772),
                          ("Dark Iron Deposit", 11370), ("Truesilver Deposit", 7911), ("Small Thorium Vein", 10620),
                          ("Rich Thorium Vein", 10620), ("Mithril Deposit", 3858), ("Gold Vein", 2776)):
            self.assertEqual(K.Found("mining", node).id, ore, node)     # a vein shares its metal's name with the ore
        self.assertIsNone(K.Found("mining", "Sweet Nectar Barrel"))
        e.mock["items"][2770] = e.lua.table(id=2770, name="Kupfererz")   # in your language, by the item's own name
        self.assertEqual(K.Found("mining", "Kupferader").id, 2770)
        # the game says what the cast is aimed at as it is sent
        e.mock.fire("UNIT_SPELLCAST_SENT", "player", "Kingsblood")
        cb = self.player_cast(e, seconds=1.5, name="Herb Gathering", spellId=2366)
        self.assertEqual(cb.look.what.id, 3356)
        self.assertEqual(cb.frame.label.text, "Herb Gathering: Kingsblood")
        red = list(K.Found("herbs", "Kingsblood").color.values())
        flowers = list(cb.art.state.flowers.values())                   # its own flowers, in its colour,
        self.assertEqual(len(flowers), len(list(cb.art.state.leaves.values())))
        self.assertEqual(list(flowers[0].vcolor.values())[:3], red)
        e.update(1.4, 0.05)
        self.assertEqual(flowers[0].alpha, 1)                           # open once the leaf has grown
        stem, leaf, flower = list(cb.art.state.stems.values())[0], list(cb.art.state.leaves.values())[0], flowers[0]
        self.assertEqual(stem.alpha, 1)                                 # both off one stem: the flower on its tip,
        self.assertAlmostEqual(flower.points[1][4], stem.points[1][4], 3)
        self.assertAlmostEqual(flower.points[1][5], stem.points[1][5] + stem.height / 2, 3)
        self.assertLess(leaf.points[1][5], stem.points[1][5])           # the leaf off its foot, out to one side
        self.assertNotAlmostEqual(leaf.points[1][4], stem.points[1][4], 0)
        e.update(0.6, 0.05)
        self.assertLess(flowers[0].alpha, 1)                            # and plucked with it
        e.update(1, 0.05)
        e.mock.fire("UNIT_SPELLCAST_SENT", "player", "Tin Vein")
        cb = self.player_cast(e, name="Mining", spellId=2575)
        tin = list(K.Found("mining", "Tin Vein").color.values())
        self.assertEqual([round(v, 2) for v in list(cb.bar.fill.color.values())[:3]], tin)   # the bar in the metal's colour
        self.assertEqual(list(cb.look.land.color.values()), tin)        # and the chips
        e.update(4, 0.05)
        cb = self.player_cast(e, name="Mining", spellId=2575)           # later, nothing said: the usual ore colour
        self.assertIsNone(cb.look.what)
        e.update(3, 0.05)
        cb = self.player_cast(e, name="Heavy Linen Bandage", spellId=3276, trade=True, icon=133688)
        self.assertEqual(cb.look.kind, "crafting")
        item = cb.art.state.item                                        # what you are making, at the bar's end
        self.assertEqual(item.texture, 133688)
        e.update(0.2, 0.05)
        faint = item.alpha
        e.update(1.7, 0.05)
        self.assertGreater(item.alpha, faint)                           # taking shape as the cast fills
        self.assertGreater(item.points[1][4], cb.art.w)
        e.update(0.25, 0.05)
        self.assertGreater(item.width, 20)                              # made: it jumps out once
        self.assertEqual(e.errors(), [])

    def test_a_herb_is_picked_and_a_hide_peels_away(self):
        e = Env()
        e.mock.spellNames = e.lua.table_from({2366: "Herb Gathering", 8613: "Skinning"})
        cb = self.player_cast(e, seconds=1.5, name="Herb Gathering", spellId=2366)
        art = cb.art
        self.assertTrue(e.same(art.style, e.ns.CastArt.STYLES.leaves))
        e.update(1.4, 0.05)
        self.assertGreater(art.Shown(art), 2)                           # leaves on the bar while it fills
        self.assertIsNone(art.state.flowers)                            # (which herb it is, nobody said)
        leaves = list(art.state.leaves.values())
        first, last = leaves[0], leaves[-1]
        rest = first.points[1][5]
        tugged = False                                                  # it lands: the first one is tugged,
        for _ in range(5):
            e.update(0.05, 0.05)
            tugged = tugged or (art.state.plucked is None and first.height > first.width)
        self.assertTrue(tugged)                                         # stretched, held by its root
        self.assertEqual(cb.bar.fill.alpha, 1)                          # (the bar itself stays)
        e.update(0.2, 0.05)
        self.assertGreaterEqual(art.state.plucked, 1)                   # and out it comes, with a jump,
        self.assertGreater(first.points[1][5], rest + 10)
        self.assertEqual(last.alpha, 1)                                 # one after another: the last still stands
        crumb = list(art.state.crumbs.values())[0]
        self.assertGreater(crumb.alpha, 0)                              # and a crumb of earth falls
        e.update(0.3, 0.05)
        self.assertEqual(art.state.plucked, len(leaves))                # every one of them
        e.update(1, 0.05)
        self.assertEqual(cb.bar.fill.alpha, 1)
        cb = self.player_cast(e, seconds=1.5, name="Skinning", spellId=8613)
        art = cb.art
        self.assertTrue(e.same(art.style, e.ns.CastArt.STYLES.peel))
        e.update(1.0, 0.05)
        self.assertGreater(art.state.hide.alpha, 0)                     # the hide lifts off what is filled,
        self.assertGreater(art.state.curl.alpha, 0)                     # rolled up at the cut
        self.assertAlmostEqual(art.state.hide.width, art.edge, 3)
        e.update(0.6, 0.05)                                             # it lands: the bar peels away
        self.assertTrue(art.state.peeled)
        self.assertEqual(cb.bar.fill.alpha, 0)
        strips = list(art.state.strips.values())
        e.update(0.2, 0.05)
        self.assertLess(strips[0].alpha, strips[-1].alpha)              # from the left, strip after strip
        e.update(1, 0.05)
        self.assertEqual(cb.bar.fill.alpha, 1)
        self.assertEqual(e.errors(), [])

    def test_opening_says_what_you_open(self):
        e = Env()
