        cb = self.player_cast(e, name="Opening - No Text", spellId=22810)
        self.assertEqual(cb.frame.label.text, "Opening: Sweet Nectar Barrel")
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_STOP", "player")
        e.update(1)
