class GroupFrames(unittest.TestCase):
    def member(self, e, i=1, **kw):
        data = e.lua.table(name="Friend%d" % i, health=800, healthMax=1000, power=50, powerMax=100,
                           powerToken="RAGE", isPlayer=True, **{"class": "MAGE"})
        for k, v in kw.items():
            data[k] = v
        e.mock.setUnit("party%d" % i, data)
        return data, e.ns.Group.overlays[e.g.PartyFrame["MemberFrame%d" % i]]

    def test_our_look_sits_over_the_games_party_frame(self):
        e = Env()
        self.assertEqual(e.g.PartyFrame.alpha, 0)                    # invisible, still there and working
        self.assertEqual(e.parent("PartyFrame"), "UIParent")
        data, o = self.member(e)
        self.assertTrue(o.shown)
        self.assertTrue(e.same(o.points[1][2], e.g.PartyFrame.MemberFrame1))
        self.assertEqual(o.name.text, "Friend1")
        self.assertEqual(o.health.fill.value, 800)
        self.assertEqual(o.status.text, "80%")
        self.assertEqual(e.color(o.health), (0.25, 0.78, 0.92))
        self.assertEqual(o.power.fill.value, 50)
        self.assertIsNone(e.ns.Group.overlays[e.g.PartyFrame.MemberFrame2])
        self.assertEqual(e.errors(), [])

    def test_heals_on_their_way_yours_then_everyone_elses(self):
        e = Env()
        e.lua.eval("""function(mock)
            local real = UnitGetIncomingHeals
            function UnitGetIncomingHeals(unit, healer)
                local u = mock.units[unit]
                if healer == "player" then return u and u.mine end
                return real(unit)
            end
        end""")(e.mock)
        data, o = self.member(e, incoming=300, mine=100)
        e.mock.fire("UNIT_HEAL_PREDICTION", "party1")
        self.assertTrue(o.health.healBar.shown)                      # on a party member's bar too: yours,
        self.assertEqual(o.health.healBar.value, 100)
        self.assertTrue(o.health.othersBar.shown)                    # and everyone else's after it, paler
        self.assertEqual(o.health.othersBar.value, 200)
        self.assertTrue(e.same(o.health.othersBar.points[1][2], o.health.healBar.GetStatusBarTexture(o.health.healBar)))
        t = e.target(health=500, healthMax=1000, incoming=250, mine=0)    # your target, healed by someone else
        tf = e.frames.target
        self.assertFalse(tf.health.healBar and tf.health.healBar.shown)
        self.assertEqual(tf.health.othersBar.value, 250)
        data.incoming, data.mine = 0, 0
        e.mock.fire("UNIT_HEAL_PREDICTION", "party1")
        self.assertFalse(o.health.othersBar.shown)                   # landed: gone
        self.assertEqual(e.errors(), [])

    def test_each_member_is_drawn_once_when_the_game_shows_them_twice(self):
        e = Env(setup=lambda env: env.lua.execute("""
            CompactPartyFrame = CreateFrame("Frame", "CompactPartyFrame", UIParent)
            for i = 1, 5 do
                local m = CreateFrame("Button", "CompactPartyFrameMember" .. i, CompactPartyFrame)
                m.attrs.unit, m.width = i == 1 and "player" or ("party" .. (i - 1)), 90
            end"""))
        data, o = self.member(e)
        e.update(0.5)
        shown = [ov for ov in e.ns.Group.overlays.values() if ov.shown]
        units = sorted(ov.unit for ov in shown)
        self.assertEqual(units, ["party1", "player"])                # party1 once (and you, on the raid-style one)
        self.assertTrue(o.shown)                                     # on the party frame, where the D-pad targets
        twice = e.ns.Group.overlays[e.g.CompactPartyFrameMember2]
        self.assertFalse(twice and twice.shown)                      # not a second time on the raid-style one
        self.assertIn("CompactPartyFrameMember2=party1(again)", list(e.ns.Group.found.values()))
        self.assertEqual(e.errors(), [])

    def test_when_nothing_can_be_drawn_the_games_frames_stay_in_sight(self):
        e = Env()
        self.assertEqual(e.g.CompactRaidFrameContainer.alpha, 0)    # alone: nothing to see either way
        e.mock.setUnit("raid1", e.lua.table(name="Raider", health=5, healthMax=5))   # a raid, its frames not found
        e.update(0.3)
        self.assertEqual(e.g.CompactRaidFrameContainer.alpha, 1)    # in a group with nothing of ours: the game's
        failed, rows = e.ns.RunCheck(False)
        bad = [r.detail for r in rows.values() if not r.ok]
        self.assertEqual(failed, 1)
        self.assertIn("0 drawn", bad[0])

    def test_our_own_party_frames_when_the_game_hides_its_own(self):
        e = Env(setup=lambda env: setattr(env.mock, "partyHidden", True))
        data, _ = (None, None)
        e.mock.setUnit("party1", e.lua.table(name="Friend", health=600, healthMax=1000, isPlayer=True,
                                             **{"class": "MAGE"}))
        e.mock.setUnit("party2", e.lua.table(name="Other", health=1000, healthMax=1000))
        e.update(0.3)
        G = e.ns.Group
        self.assertTrue(G.ownParty)
        b1, o1 = G.party[1].button, G.party[1].o
        self.assertTrue(b1.shown)
        self.assertEqual(b1.attrs.unit, "party1")
        self.assertEqual(b1.attrs.type2, "togglemenu")               # the unit menu works on them
        self.assertTrue(o1.shown)
        self.assertEqual(o1.name.text, "Friend")
        self.assertEqual(o1.health.fill.value, 600)
        self.assertTrue(G.party[2].o.shown)
        self.assertFalse(G.party[3].button.shown)
        self.assertEqual(e.g.PartyFrame.alpha, 0)                    # something of ours is drawn
        e.mock.units.party1.health = 300
        e.mock.fire("UNIT_HEALTH", "party1")
        self.assertEqual(o1.health.goal, 300)
        self.assertEqual(e.ns.RunCheck(False)[0], 0)
        e.cmd("group off")
        self.assertFalse(b1.shown)
        self.assertFalse(G.ownParty)

    def test_a_kicked_member_leaves_and_the_others_move_up(self):
        # kicking someone offline from slot 1: the one in slot 2 becomes "party1", and slot 1 shows them at once
        e = Env(setup=lambda env: setattr(env.mock, "partyHidden", True))
        e.mock.setUnit("party1", e.lua.table(name="Gone", guid="Player-1", health=0, healthMax=1000, connected=False))
        e.mock.setUnit("party2", e.lua.table(name="Stays", guid="Player-2", health=700, healthMax=1000))
        e.update(0.3)
        G = e.ns.Group
        o1 = G.party[1].o
        self.assertEqual(o1.name.text, "Gone")
        e.mock.units.party1 = e.mock.units.party2                     # the roster moves up a slot
        e.mock.units.party2 = None
        e.update(0.3)                                                 # (no event for it at all: still seen)
        self.assertEqual(o1.name.text, "Stays")
        self.assertEqual(o1.health.fill.value, 700)
        self.assertEqual(o1.status.text, "70%")                       # not "Offline", the one who left
        self.assertFalse(G.party[2].o.shown)
        # a roster change draws everything again, even where who it is cannot be told (a secret GUID)
        e.lua.execute("UnitGUID = function() return nil end")
        e.mock.units.party1 = e.lua.table(name="Next", health=1000, healthMax=1000)
        e.mock.fire("GROUP_ROSTER_UPDATE")
        self.assertEqual(o1.name.text, "Next")
        self.assertEqual(e.errors(), [])

    def test_members_found_inside_the_games_containers(self):
        e = Env()
        holder = e.g.CreateFrame("Frame", None, e.g.CompactRaidFrameContainer)
        cell = e.g.CreateFrame("Button", None, holder)
        cell.attrs.unit = "party2"
