class CastBars(unittest.TestCase):
    def cast(self, e, seconds=2, **kw):
        now = e.mock.time
        e.mock.units.player.cast = e.lua.table(name="Aimed Shot", start=now * 1000, stop=(now + seconds) * 1000, **kw)
        e.mock.fire("UNIT_SPELLCAST_CHANNEL_START" if kw.get("channel") else "UNIT_SPELLCAST_START", "player")
        return e.ns.CastBar

    def test_it_runs_where_the_games_bar_sits(self):
        e = Env()
        self.assertEqual(e.parent("PlayerCastingBarFrame"), "ControllerCamHUDHidden")
        cb = self.cast(e)
        self.assertTrue(cb.frame.shown)
        self.assertTrue(e.same(cb.frame.points[1][2], e.g.PlayerCastingBarFrame))
        self.assertEqual(cb.frame.label.text, "Aimed Shot")
        e.update(1)
        self.assertAlmostEqual(cb.bar.fill.value, 0.5, places=1)
        self.assertEqual(cb.frame.time.text, "1.0")
        time, label = cb.frame.timeBox.points[1], cb.frame.label.points
        self.assertEqual((time[1], time[3]), ("TOPRIGHT", "BOTTOMRIGHT"))          # the time under the bar's right end,
        self.assertEqual([(p[1], p[3]) for p in label.values()],                    # the name over the whole bar
                         [("BOTTOMLEFT", "TOPLEFT"), ("BOTTOMRIGHT", "TOPRIGHT")])
        room = cb.ROOM                                               # clear of what grows on the bar as it fills:
        self.assertGreaterEqual(room, 16)                            # leaves and roots reach 16 beyond it
        self.assertEqual([p[5] for p in label.values()], [room, room])
        self.assertAlmostEqual(time[5], -room, places=2)
        self.assertEqual(len(list(cb.frame.timeBox.points.values())), 1)
        cb.FishingLook(cb, True)                                     # nothing grows on the fishing line:
        self.assertEqual([p[5] for p in cb.frame.label.points.values()], [4, 4])   # close, as it was
        self.assertAlmostEqual(cb.frame.timeBox.points[1][5], -5, places=2)
        cb.FishingLook(cb, False)
        self.assertEqual([p[5] for p in cb.frame.label.points.values()], [room, room])
        self.assertEqual(len(list(cb.frame.label.points.values())), 2)
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_STOP", "player")
        self.assertTrue(cb.frame.shown)                              # the result lingers a moment
        self.assertGreater(cb.bar.flashA, 0)
        e.update(0.6)
        self.assertFalse(cb.frame.shown)
        self.assertEqual(e.errors(), [])

    def test_the_time_grows_as_the_end_comes_then_bursts_and_fades(self):
        e = Env()
        cb = self.cast(e, 3)
        box, time = cb.frame.timeBox, cb.frame.time
        muted = list(e.ns.colors.muted.values())[:3]
        e.update(1.5)
        self.assertEqual((box.scale, cb.grown), (1, None))           # nothing until the last second
        self.assertEqual(list(time.tcolor.values())[:3], muted)
        e.update(1)                                                  # half a second left: growing,
        mid = box.scale
        self.assertGreater(mid, 1.1)
        self.assertAlmostEqual(box.points[1][5] * mid, -cb.ROOM, places=2)   # its corner where it was
        self.assertNotEqual(list(time.tcolor.values())[:3], muted)
        e.update(0.4)
        late = box.scale
        self.assertGreater(late, mid)                                # more so at the end
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_STOP", "player")
        self.assertEqual(time.text, "0.0")                           # it landed: the count stays to burst
        e.update(0.15)
        self.assertGreater(box.scale, late)
        self.assertLess(time.alpha, 1)
        e.update(0.2)
        self.assertEqual((time.text, box.scale, time.alpha), ("", 1, 1))
        e.update(0.5)
        cb = self.cast(e, 3)                                         # an interrupt: no burst, the count just goes
        e.update(2.7)
        self.assertGreater(box.scale, 1)
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_INTERRUPTED", "player")
        self.assertEqual((time.text, box.scale), ("", 1))
        e.update(1)
        cb = self.cast(e, 3)                                         # ended early (you moved): nothing to burst
        e.update(1)
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_STOP", "player")
        self.assertEqual((time.text, box.scale), ("", 1))
        e.update(1)
        e.cmd("effects 2")                                           # Subtle: it grows half as much and only fades
        cb = self.cast(e, 3)
        e.update(2.9)
        subtle = box.scale
        self.assertTrue(1 < subtle < late)
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_STOP", "player")
        e.update(0.15)
        self.assertEqual(box.scale, subtle)
        self.assertLess(time.alpha, 1)
        e.update(1)
        for off in ("effects 3", "windup off"):                      # Classic, or without the wind-up: as it was
            e.cmd(off)
            cb = self.cast(e, 3)
            e.update(2.9)
            self.assertEqual(box.scale, 1, off)
            e.mock.units.player.cast = None
            e.mock.fire("UNIT_SPELLCAST_STOP", "player")
            self.assertEqual(time.text, "", off)
            e.update(1)
            e.cmd("effects 1")
        self.assertEqual(e.errors(), [])

    def land(self, e, seconds=2):
        cb = self.cast(e, seconds)
        e.update(seconds + 0.1)                                      # it runs to its end
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_STOP", "player")
        return cb

    def test_casts_one_after_another_are_counted(self):
        e = Env()
        self.assertTrue(e.db.castChain)
        cb = self.land(e)
        combo, box = cb.frame.combo, cb.frame.comboBox
        self.assertFalse(combo.shown)                                # one cast is no chain
        cb = self.cast(e)                                            # the next, straight after: a chain of two
        self.assertEqual((combo.shown, combo.text), (True, "x2"))
        self.assertEqual((box.points[1][1], box.points[1][3]), ("TOPLEFT", "BOTTOMLEFT"))   # under the bar's left end
        self.assertGreater(box.scale, 1)                             # it jumps,
        e.update(0.4)
        self.assertEqual(box.scale, 1)                               # and settles
        e.update(1.7)
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_STOP", "player")
        e.mock.units.player.cast = e.lua.table(name="Aimed Shot", start=e.mock.time * 1000, stop=(e.mock.time + 2) * 1000)
        e.mock.fire("UNIT_SPELLCAST_DELAYED", "player")              # (pushed back: the same cast, not one more)
        e.mock.units.player.cast = None
        cb = self.cast(e)
        self.assertEqual(combo.text, "x3")
        self.assertEqual(list(combo.tcolor.values())[:3], list(cb.color.values())[:3])   # in the cast's colour
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_INTERRUPTED", "player")          # interrupted: the chain is over
        self.assertFalse(combo.shown)
        e.update(0.3)
        cb = self.land(e)
        self.assertFalse(combo.shown)
        e.update(1)                                                  # a pause: the next one starts anew
        cb = self.land(e)
        self.assertFalse(combo.shown)
        cb = self.cast(e)                                            # two again,
        self.assertEqual(combo.text, "x2")
        e.update(1)
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_STOP", "player")                 # but you moved halfway through it:
        cb = self.cast(e)
        self.assertFalse(combo.shown)                                # that was no landed cast
        e.update(2.1)
        cb = self.cast(e, 4, channel=True)                           # a channel goes on with a chain
        self.assertEqual(combo.text, "x2")
        e.update(4.1)
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_CHANNEL_STOP", "player")
        cb = self.cast(e, 2, trade=True)                             # making things is not a chain
        self.assertFalse(combo.shown)
        e.update(2.1)
        e.cmd("chain off")                                           # and it has its own switch
        self.land(e)
        self.cast(e)
        self.assertFalse(combo.shown)
        self.assertEqual(e.errors(), [])

    def hit(self, e, amount, kind="SPELL_DAMAGE", source="player", dest="target"):
        e.mock.logHit(kind, source, dest, 4)                         # (the helper fires it once, as 100)
        e.mock.logEntry[12 if kind == "SWING_DAMAGE" else 15] = amount
        e.mock.fire("COMBAT_LOG_EVENT_UNFILTERED")
        return amount + 100

    def test_a_chain_totals_its_damage_under_the_count(self):
        e = Env()
        e.target()
        cb = self.land(e)
        combo, total = cb.frame.combo, cb.frame.comboSum
        self.assertEqual(total.baseSize, 9)                          # smaller than the count (12),
        self.assertEqual((total.points[1][1], total.points[1][3]), ("TOPLEFT", "BOTTOMLEFT"))   # and under it
        dealt = self.hit(e, 400)                                     # the first cast's bolt lands:
        self.assertFalse(total.shown)                                # one cast is no chain yet,
        cb = self.cast(e)
        self.assertEqual((combo.text, total.shown, total.text), ("x2", True, str(dealt)))   # but it counts
        dealt += self.hit(e, 800)
        self.assertEqual(total.text, "1.4k")                         # cut short from a thousand on
        self.hit(e, 5000, source="target", dest="player")            # what hits you is not yours,
        self.assertEqual(total.text, "1.4k")
        dealt += self.hit(e, 150, kind="SWING_DAMAGE")               # a swing of yours in between is
        self.assertEqual(total.text, "1.6k")
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 150, 1)    # (the game's hit event tells the same swing
        self.assertEqual(total.text, "1.6k")                         # again: the log has it already)
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_INTERRUPTED", "player")          # the chain is over: so is its total
        self.assertFalse(total.shown)
        e.update(1)
        self.land(e)
        cb = self.cast(e)
        self.assertEqual((combo.text, total.shown), ("x2", False))   # a new chain starts from nothing
        self.assertEqual(e.errors(), [])
        S = e.ns.CastBar.Short
        self.assertEqual([S(n) for n in (0, 999.6, 1000, 15340, 99960, 123456, 999600, 2500000)],
                         ["0", "999", "1.0k", "15.3k", "100k", "123k", "1.0m", "2.5m"])

    def test_without_the_log_the_hit_event_totals_a_chain(self):
        e = Env(setup=lambda env: env.lua.execute("CombatLogGetCurrentEventInfo = nil"))
        e.target()
        cb = self.land(e)
        total = cb.frame.comboSum
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 300, 4)
        cb = self.cast(e)
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 450, 4)
        self.assertEqual((total.shown, total.text), (True, "750"))
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", e.mock.secret(), 4)       # an amount the game keeps:
        self.assertFalse(total.shown)                                # no total is better than a wrong one
        self.assertEqual(e.errors(), [])

    def test_upright_beside_the_vertical_bars_when_you_choose_it(self):
        e = Env(db="{ v = 4, units = { vertical = true } }")
        self.assertFalse(e.db.castUpright)                           # not the default
        v = e.frames.vertical
        cb = self.cast(e)
        self.assertFalse(v.upCast.shown)
        self.assertNotEqual(cb.frame.alpha, 0)
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_STOP", "player")
        e.update(1)
        e.cmd("castupright on")
        cb = self.cast(e)
        self.assertTrue(v.upCast.shown)                                # on the right of the mana,
        self.assertTrue(e.same(v.upCast.points[1][2], v.power))
        self.assertEqual((v.upCast.points[1][1], v.upCast.points[1][3]), ("TOPLEFT", "TOPRIGHT"))
        self.assertEqual(v.upCast.fill.orientation, "VERTICAL")        # upright
        self.assertEqual(v.upCast.height, v.power.height)
        self.assertEqual(cb.frame.alpha, 0)                          # the bar under you stands aside
        e.update(1)
        self.assertAlmostEqual(v.upCast.fill.value, 0.5, places=1)
        self.assertEqual(v.upCastTime.text, "1.0")                     # a small timer, no name
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_INTERRUPTED", "player")
        self.assertEqual(e.color(v.upCast), e.theme("danger"))
        e.update(0.6)
        self.assertFalse(v.upCast.shown)
        self.assertEqual(cb.frame.alpha, 1)
        e.cmd("vertical off")                                        # without the vertical bars: the usual bar
        cb = self.cast(e)
        self.assertEqual(cb.frame.alpha, 1)
        self.assertEqual(e.errors(), [])

    def test_an_interrupt_is_shown_as_one(self):
        e = Env()
        cb = self.cast(e)
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_INTERRUPTED", "player")
        self.assertEqual(cb.frame.label.text, "Interrupted")
        self.assertEqual(e.color(cb.bar), e.theme("danger"))
        e.update(0.6)
        self.assertFalse(cb.frame.shown)

    def test_channels_secret_times_and_other_units(self):
        e = Env()
        cb = self.cast(e, 4, channel=True)
        e.update(1)
        self.assertAlmostEqual(cb.bar.fill.value, 0.75, places=1)
        e.mock.units.player.cast = e.lua.table(name="Hidden", start=e.mock.secret(), stop=e.mock.secret())
        e.mock.fire("UNIT_SPELLCAST_START", "player")
        self.assertEqual(cb.bar.fill.value, 1)
        e.update(0.5)
        self.assertEqual(e.errors(), [])
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_STOP", "player")
        e.update(1)
        e.target(cast=e.lua.table(name="Enemy spell", start=0, stop=99999999))
        e.mock.fire("UNIT_SPELLCAST_START", "target")
        self.assertFalse(cb.frame.shown)

    def test_the_cast_winds_up_and_lands(self):
        e = Env()
        cb = self.cast(e, 2)
        e.update(0.2)
        early = cb.bar.charge.alpha
        e.update(1.5)
        self.assertGreater(cb.bar.charge.alpha, early)
        self.assertGreater(cb.bar.spark.width, 20)
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_STOP", "player")
        self.assertEqual(cb.bar.charge.alpha, 0)
        self.assertGreater(len(list(e.ns.Impact.live.keys())), 0)               # it lands with a burst
        e.cmd("windup off")
        self.cast(e, 2)
        e.update(1.5)
        self.assertEqual(cb.bar.charge.alpha, 0)

    def test_fishing_shows_a_float_and_what_bites(self):
        e = Env(setup=lambda env: env.lua.execute("""
            ImprovedForever = { FishingData = {
                items = { [6303] = "Raw Slitherskin Mackerel|1|fish", [6356] = "Raw Rainbow Fin Albacore|1|fish",
                          [6307] = "Message in a Bottle|1|treasure" },
                zones = { [14] = "Durotar|6303:98:0,6356:2:0,6307:0.5:0" },
                areas = { [2] = "Longshore|40|6356:50:0,6307:0.5:0" } } }"""))
        e.mock.zone = "Durotar"
        cb = self.cast(e, 20, channel=True, spellId=7620)
        self.assertTrue(cb.fishing)
        self.assertTrue(cb.bar.bobber.shown)
        self.assertFalse(cb.bar.spark.shown)                         # nothing bright standing on the float
        p = cb.frame.points[1]                                       # the main event: in the middle, and larger
        self.assertEqual(p[1], "CENTER")
        self.assertTrue(e.same(p[2], e.g.UIParent))
        self.assertAlmostEqual(cb.frame.scale, 1.35 * 1.5)
        self.assertAlmostEqual(p[5] * cb.frame.scale, -100)
        self.assertIn("Raw Slitherskin Mackerel 98%", cb.frame.catch.text)
        self.assertIn("Raw Rainbow Fin Albacore 2%", cb.frame.catch.text)
        self.assertNotIn("Message", cb.frame.catch.text)            # fish only
        self.assertEqual(cb.frame.catchIcon.texture, 1000 + 6303)
        y = []
        for _ in range(6):
            e.update(0.1)
            y.append(cb.bar.bobber.points[1][5])
        self.assertGreater(len(set(round(v, 1) for v in y)), 3)      # it bobs
        e.mock.subzone = "Longshore"                                 # a smaller place has its own fish
        e.mock.fire("UNIT_SPELLCAST_CHANNEL_UPDATE", "player")
        self.assertIn("Raw Rainbow Fin Albacore 50%", cb.frame.catch.text)
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_CHANNEL_STOP", "player")
        e.update(1)
        self.assertFalse(cb.bar.bobber.shown)
        self.assertTrue(e.same(cb.frame.points[1][2], e.g.PlayerCastingBarFrame))   # back where the game's bar sits
        self.assertAlmostEqual(cb.frame.scale, 1.35)
        self.cast(e, 2)                                              # another cast has its bright edge again
        self.assertTrue(cb.bar.spark.shown)
        e.cmd("fishbig off")                                         # or leave fishing where every cast is
        e.mock.units.player.cast = None
        e.mock.fire("UNIT_SPELLCAST_STOP", "player")
        e.update(1)
        self.cast(e, 20, channel=True, spellId=7620)
        self.assertTrue(e.same(cb.frame.points[1][2], e.g.PlayerCastingBarFrame))
        self.assertEqual(e.errors(), [])

    def test_fishing_without_the_fishing_data(self):
        e = Env()
        e.mock.zone = "Arathi Highlands"
        cb = self.cast(e, 20, channel=True, spellId=7620)
        self.assertTrue(cb.bar.bobber.shown)
        self.assertEqual(cb.frame.catch.text, "Arathi Highlands")
        e.cmd("fishing off")
        self.cast(e, 20, channel=True, spellId=7620)
        self.assertFalse(cb.bar.bobber.shown)

    def test_an_unfinished_cast_just_ends(self):
        e = Env()
        cb = self.cast(e, 1)
        e.update(1.2)                                                # no stop event arrived
        self.assertFalse(cb.casting)
        e.update(0.6)
        self.assertFalse(cb.frame.shown)

    def test_off_and_edit_mode_give_the_games_bar_back(self):
        e = Env()
        e.cmd("castbar off")
        self.assertEqual(e.parent("PlayerCastingBarFrame"), "UIParent")
        e.cmd("castbar on")
        e.mock.editMode(True)
        self.assertEqual(e.parent("PlayerCastingBarFrame"), "UIParent")
        e.mock.editMode(False)
        self.assertEqual(e.parent("PlayerCastingBarFrame"), "ControllerCamHUDHidden")


class Effects(unittest.TestCase):
    def aura(self, e, **kw):
        a = e.lua.table(icon=136207, applications=1, duration=18, expirationTime=e.mock.time + 18, mine=True)
        for k, v in kw.items():
            a[k] = v
        return a

    def shown(self, e):
        return [bool(b.shown) for b in e.ns.Auras.icons.values()].count(True)

    def test_your_effects_show_under_the_target(self):
        e = Env()
        e.target(auras=e.lua.table(self.aura(e), self.aura(e, icon=5, applications=3, duration=12)))
        e.mock.fire("UNIT_AURA", "target")
        icons = e.ns.Auras.icons
        self.assertEqual(self.shown(e), 2)
        self.assertTrue(e.mock.auraFilters["HARMFUL|PLAYER"])
        self.assertEqual(icons[1].icon.texture, 136207)
        self.assertEqual((icons[1].cooldown.cdStart, icons[1].cooldown.cdDuration), (e.mock.time, 18))
        self.assertEqual((icons[1].count.text, str(icons[2].count.text)), ("", "3"))
        e.target(attackable=False, auras=e.lua.table(self.aura(e)))
        self.assertTrue(e.mock.auraFilters["HELPFUL"])             # on a friend: the buffs they have
        self.assertEqual(self.shown(e), 1)
        e.mock.setUnit("target", None)
        self.assertEqual(self.shown(e), 0)
        self.assertEqual(e.errors(), [])

    def test_secret_times_do_not_break_it(self):
        e = Env()
        e.target(auras=e.lua.table(self.aura(e, duration=e.mock.secret(), expirationTime=e.mock.secret(),
                                             applications=e.mock.secret())))
        self.assertEqual(self.shown(e), 1)
        self.assertEqual(e.errors(), [])

    def test_combo_points(self):
        e = Env()
        e.target()
        A = e.ns.Auras
        self.assertFalse(A.pipRow.shown)
        e.mock.combo = 3
        e.mock.fire("UNIT_POWER_UPDATE", "player")
        self.assertTrue(A.pipRow.shown)
        lit = [round(p.vcolor[4], 2) == 1 for p in A.pips.values()]
        self.assertEqual(lit, [True, True, True, False, False])
        e.mock.combo = 5
        e.mock.fire("UNIT_POWER_UPDATE", "player")
        c = e.ns.colors.danger
        self.assertEqual(round(A.pips[5].vcolor[1], 2), round(c[1], 2))       # full: a different colour
        e.cmd("combo off")
        self.assertFalse(A.pipRow.shown)

    def test_switches(self):
        e = Env()
        e.target(auras=e.lua.table(self.aura(e)))
        self.assertEqual(self.shown(e), 1)
        e.cmd("auras off")
        self.assertEqual(self.shown(e), 0)
        e.cmd("auras on")
        e.cmd("target off")                               # no target frame of ours: nothing to hang them on
        self.assertFalse(e.ns.Auras.active)

    def test_the_demo_shows_them(self):
        e = Env()
        e.cmd("demo")
        self.assertEqual(self.shown(e), 3)                # your debuffs on the made-up enemy
        A = e.ns.Auras
        self.assertEqual(sum(1 for b in A.buffIcons.values() if b.shown), 2)     # its buffs
        self.assertTrue(A.ccIcon.shown)                   # and crowd control on it
        e.update(4.5)
        self.assertEqual(e.ns.Auras.points, 4)
        e.update(5.5)
        self.assertTrue(e.ns.CastBar.frame.shown)         # the made-up heal
        e.cmd("demo")
        self.assertEqual(self.shown(e), 0)
        self.assertFalse(e.ns.Auras.pipRow.shown)
        self.assertFalse(A.ccIcon.shown)
        self.assertEqual(e.errors(), [])

    def test_the_demo_needs_no_target_for_aggro_and_hits(self):
        e = Env()
        e.cmd("demo")
        e.update(2.0)
        t = e.frames.target
        self.assertTrue(t.threatIcon.shown)               # aggro on the made-up enemy
        self.assertEqual(e.ns.UnitFrames.threatState, "max")
        self.assertIsNotNone(e.ns.Impact.last)            # hit effects play on its frame
        self.assertGreater(e.ns.Numbers.shown or 0, 0)    # and the numbers on you
        self.assertEqual(e.errors(), [])


class GameAuraRows(unittest.TestCase):
    """A client with the game's own aura display element: it draws the effects, we only point it."""

    def env(self):
        def setup(env):
            env.mock.auraContainer = True
        return Env(setup=setup)

    def test_plates_use_the_games_rows(self):
        e = self.env()
        data = e.lua.table(name="Raptor", level=34, health=600, healthMax=800, attackable=True, reaction=2)
        plate = e.mock.addPlate("nameplate1", data)
        o = e.ns.Nameplates.byPlate[plate]
        self.assertTrue(o.wDebuffs)
        self.assertEqual(o.wDebuffs.unit, "nameplate1")
        self.assertTrue(o.wDebuffs.enabled and o.wDebuffs.shown)
        self.assertEqual(o.wDebuffs.groups["1"].filter, "HARMFUL|!CROWD_CONTROL|PLAYER")
        self.assertEqual(o.wDebuffs.groups["2"].filter, "HARMFUL|!CROWD_CONTROL|IMPORTANT|!PLAYER")
        self.assertEqual(o.wBuffs.groups["1"].filter, "HELPFUL|IMPORTANT|!PLAYER")    # only what matters
        self.assertEqual(o.wCC.groups["1"].filter, "HARMFUL|CROWD_CONTROL")
        self.assertTrue(o.wCC.shown)
        icon = o.wDebuffs.groups["1"].icon                # our look on the game's icon
        self.assertIsNotNone(icon.iconTex)
        self.assertIsNotNone(icon.cd)
        self.assertIsNotNone(icon.timeText)
        for i in range(1, 5):
            self.assertFalse(o.icons[i].shown)            # our own row stays hidden
        e.cmd("platealldebuffs on")
        e.update(0.4)
        self.assertEqual(o.wDebuffs.groups["1"].filter, "HARMFUL|!CROWD_CONTROL")
        e.cmd("platedebuffs off")
        e.update(0.4)
        self.assertFalse(o.wDebuffs.shown)
        self.assertEqual(e.errors(), [])

    def test_countdowns_turn_red_when_running_out(self):
        e = self.env()
        data = e.lua.table(name="Raptor", level=34, health=600, healthMax=800, attackable=True, reaction=2)
        o = e.ns.Nameplates.byPlate[e.mock.addPlate("nameplate1", data)]
        opts = o.wDebuffs.groups["1"].icon.timeOpts
        rules = list(opts.textFormatter.rules.values())
        self.assertEqual(rules[0].threshold, 0)
        self.assertIn("|cff", rules[0].format)                        # under five seconds: red
        self.assertEqual(rules[1].threshold, 5)
        self.assertEqual(rules[1].format, "%d")

    def test_our_own_icons_turn_red_too(self):
        e = Env()                                                     # no game display: our own icons
        T = e.lua.table
        auras = T(T(icon=41, duration=10, expirationTime=e.mock.time + 4.5, mine=True),
                  T(icon=42, duration=30, expirationTime=e.mock.time + 20, mine=True))
        o = e.ns.Nameplates.byPlate[e.mock.addPlate("nameplate1", T(name="Raptor", level=30, health=5, healthMax=5,
                                                                    attackable=True, reaction=2, auras=auras))]
        e.update(0.3)
        danger = e.ns.colors.danger
        self.assertEqual(round(o.icons[1].time.tcolor[1], 2), round(danger[1], 2))   # 4s left: red
        self.assertEqual(o.icons[1].time.text, "5")
        self.assertNotEqual(round(o.icons[2].time.tcolor[2], 2), round(danger[2], 2))  # 20s: not

    def test_a_reused_plate_looks_again(self):
        e = self.env()
        data = e.lua.table(name="Raptor", level=34, health=600, healthMax=800, attackable=True, reaction=2)
        plate = e.mock.addPlate("nameplate1", data)
        o = e.ns.Nameplates.byPlate[plate]
        before = o.wDebuffs.setUnitCalls
        e.update(1)
        self.assertEqual(o.wDebuffs.setUnitCalls, before)  # not every update
        e.mock.removePlate("nameplate1")
        self.assertFalse(o.wDebuffs.shown)
        e.mock.plates["nameplate1"], e.mock.units["nameplate1"] = plate, data
        e.mock.fire("NAME_PLATE_UNIT_ADDED", "nameplate1")
        self.assertGreater(o.wDebuffs.setUnitCalls, before)

    def test_a_row_the_game_drew_twice_is_set_up_again(self):
        e = self.env()
        e.target(auras=e.lua.table_from([e.lua.table(name="Blessing", mine=True, helpful=True)]),
                 attackable=False, reaction=5)
        A, W = e.ns.Auras, e.ns.AuraWidgets
        row = A.wMine
        e.update(0.5)
        self.assertEqual(W.repairs, 0)                               # one effect, no icons counted: nothing to do
        icon = lambda: e.lua.eval("(function() local f = CreateFrame('Frame'); f:Show(); return f end)()")
        row.groups["1"].frames[1], row.groups["1"].frames[2] = icon(), icon()    # the same effect, twice
        calls, looks = row.setUnitCalls, row.looks or 0
        e.mock.fire("UNIT_AURA", "target")
        e.update(0.5)
        self.assertEqual(W.repairs, 1)                               # counted: two icons for one effect
        self.assertGreater(row.setUnitCalls, calls)                  # the row is set up from nothing
        self.assertGreater(row.looks, looks)
        self.assertTrue(row.enabled)
        self.assertEqual(row.unit, "target")
        self.assertIn("2 icons for 1 effects", W.Describe())
        row.groups["1"].frames[2] = None                             # as it should be: left alone from then on
        e.update(3)
        e.mock.fire("UNIT_AURA", "target")
        e.update(0.5)
        self.assertEqual(W.repairs, 1)
        self.assertEqual(e.errors(), [])

    def test_only_the_effects_that_matter(self):
        e = self.env()
        o = e.ns.Nameplates.byPlate[e.mock.addPlate("nameplate1", e.lua.table(
            name="Raptor", level=34, health=600, healthMax=800, attackable=True, reaction=2))]
        g = o.wBuffs.groups
        self.assertEqual(g["1"].filter, "HELPFUL|IMPORTANT|!PLAYER")              # marked important: boss mechanics
        self.assertEqual(g["2"].filter, "HELPFUL|!IMPORTANT|!PLAYER")
        self.assertTrue(g["2"].candidates.includeDispelTypes.Enrage)               # enraged
        self.assertTrue(g["3"].candidates.isStealable)                             # you can dispel or steal it
        self.assertTrue(g["3"].candidates.excludeDispelTypes.Enrage)               # (not twice)
        self.assertTrue(all(g[k].enabled for k in ("1", "2", "3")))
        # the groups share one short line: each icon laid out at our size, a few from each group
        self.assertEqual(g["1"].layout.elementWidth, g["1"].layout.elementHeight)
        self.assertGreater(g["1"].layout.elementWidth, 0)
        self.assertFalse(g["2"].layout.forceNewLine)
        self.assertEqual([g[k].max for k in ("1", "2", "3")], [3, 1, 2])
        A = e.ns.Auras                                          # under the target's bar: starts at the top
        self.assertEqual(A.wBuffs.point, "TOPRIGHT")
        self.assertEqual(A.wBuffs.flowAnchor, "TOPRIGHT")
        self.assertEqual(o.wBuffs.point, "BOTTOMLEFT")          # over a plate's name: starts at the bottom
        self.assertIsNotNone(g["1"].icon.dispelTex)                                # edged in its kind's colour
        e.cmd("smartauras off")                                                    # every buff, as before
        e.update(0.4)
        self.assertEqual(g["1"].filter, "HELPFUL|!PLAYER")
        self.assertEqual(g["1"].candidates and len(g["1"].candidates), 0)
        self.assertFalse(g["2"].enabled or g["3"].enabled)
        # the target: a friend's debuffs you can dispel, then the important ones, then crowd control
        e.cmd("smartauras on")
        e.target(attackable=False, reaction=5)
        h = e.ns.Auras.wHelp.groups
        self.assertEqual([h[k].filter for k in ("1", "2", "3")],
                         ["HARMFUL|RAID", "HARMFUL|IMPORTANT|!RAID", "HARMFUL|CROWD_CONTROL|!IMPORTANT|!RAID"])
        e.cmd("frienddebuffs off")
        e.target(attackable=False, reaction=5)
        self.assertFalse(e.ns.Auras.wHelp.shown)
        self.assertEqual(e.errors(), [])

    def test_a_filter_the_client_does_not_know_shows_nothing_rather_than_everything(self):
        def setup(env):
            env.mock.auraContainer = True
            env.mock.unknownFilters = env.lua.table(IMPORTANT=True)
        e = Env(setup=setup)
        o = e.ns.Nameplates.byPlate[e.mock.addPlate("nameplate1", e.lua.table(
            name="Raptor", level=34, health=600, healthMax=800, attackable=True, reaction=2))]
        g = o.wBuffs.groups
        self.assertFalse(g["1"].enabled)                       # refused: off
        self.assertTrue(g["2"].enabled)                        # enraged: asked without the unknown word
        self.assertEqual(g["2"].filter, "HELPFUL|!PLAYER")
        self.assertTrue(g["2"].candidates.includeDispelTypes.Enrage)
        self.assertFalse(o.wDebuffs.groups["2"].enabled)       # the important debuffs: off, never everyone's
        self.assertTrue(o.wDebuffs.groups["1"].enabled)        # yours: still there
        self.assertEqual(e.errors(), [])

    def test_a_secret_guid_is_never_a_key(self):
        # in a dungeon the game keeps units' GUIDs secret: a secret cannot be a table key there
        e = self.env()
        data = e.lua.table(name="Raptor", level=34, health=600, healthMax=800, attackable=True, reaction=2,
                           guid=e.mock.secret())
        e.mock.addPlate("nameplate1", data)
        o = e.ns.Nameplates.plates["nameplate1"]
        self.assertIsNone(o.guid)
        self.assertEqual(len([k for k in e.ns.Nameplates.byGuid.keys() if e.g.issecretvalue(k)]), 0)
        e.mock.setUnit("target", data)
        e.cmd("hittest")
        e.mock.removePlate("nameplate1")
        self.assertIsNone(e.ns.GUID("nameplate1"))
        self.assertEqual(e.errors(), [])

    def test_no_stale_plates(self):
        e = self.env()
        T = e.lua.table
        NP = e.ns.Nameplates
        plate = e.mock.addPlate("nameplate1", T(name="Raptor", level=34, health=600, healthMax=800,
                                                 attackable=True, reaction=2))
        o = NP.byPlate[plate]
        self.assertTrue(o.shown)
        # the game moves the plate to someone else without telling us it left: the new one is read, not the old
        e.mock.plates["nameplate1"] = None
        e.mock.plates["nameplate2"] = plate
        e.mock.units["nameplate2"] = T(name="Sel Bridalveil", level=30, health=5, healthMax=5, reaction=5)
        e.mock.fire("NAME_PLATE_UNIT_ADDED", "nameplate2")
        self.assertIsNone(NP.plates["nameplate1"])
        self.assertTrue(e.same(NP.plates["nameplate2"], o))
        self.assertIn("Sel Bridalveil", o.name.text)
        # a plate that goes away with no event at all: dropped within a second
        other = e.mock.addPlate("nameplate3", T(name="Takulah", level=28, health=5, healthMax=5, reaction=5))
        e.mock.plates["nameplate3"] = None                 # the game does not hand it out: kept (friends do this)
        e.update(1.2)
        self.assertTrue(NP.byPlate[other].shown)
        e.mock.units["nameplate3"] = None                  # the unit is gone: dropped
        e.update(1.2)
        self.assertIsNone(NP.plates["nameplate3"])
        self.assertFalse(NP.byPlate[other].shown)
        out = e.cmd("plates")
        self.assertIn("nameplate3: gone", out)
        self.assertGreater(len(e.db.plateReport), 1)
        # a plate the game keeps for itself (friends in a dungeon): never ours, nothing of ours left on it
        e.mock.plates["nameplate2"].IsForbidden = lambda *_: True
        e.mock.fire("NAME_PLATE_UNIT_ADDED", "nameplate2")
        self.assertFalse(o.shown)
        self.assertIsNone(NP.plates["nameplate2"])
        self.assertEqual(e.errors(), [])

    def test_friendly_plates_can_be_left_to_the_game(self):
        e = self.env()
        T = e.lua.table
        NP = e.ns.Nameplates
        friend = e.mock.addPlate("nameplate1", T(name="Sel Bridalveil", level=30, health=5, healthMax=5, reaction=5))
        foe = e.mock.addPlate("nameplate2", T(name="Raptor", level=34, health=600, healthMax=800,
                                               attackable=True, reaction=2))
        self.assertTrue(NP.byPlate[friend].shown)                  # ours by default, friends too
        e.cmd("platefriendsgame on")
        e.update(0.4)
        self.assertIsNone(NP.plates["nameplate1"])
        self.assertFalse(NP.byPlate[friend].shown)                 # the game's own plate shows instead
        self.assertTrue(NP.byPlate[foe].shown)                     # enemies stay ours
        e.cmd("platefriendsgame off")
        e.update(0.4)
        self.assertTrue(NP.byPlate[friend].shown)                  # taken back
        self.assertEqual(e.errors(), [])

    def test_secret_facts_about_a_unit_count_as_unknown(self):
        # in a dungeon the game keeps who a unit is secret: class, player or not, name of its target...
        e = self.env()
        e.lua.execute("""
            setmetatable(CLASS_ICON_TCOORDS, { __index = function(_, k)
                if issecretvalue(k) then error("attempted to index a table that cannot be indexed with secret keys") end
            end })
        """)
        S = e.mock.secret
        e.target(isPlayer=S(), attackable=S(), reaction=S(), dead=S(), **{"class": S()})
        e.mock.setUnit("targettarget", e.lua.table(name=S(), health=5, healthMax=5, level=30))
        e.update(1)
        U = e.ns.Unit
        self.assertIsNone(U.Class("target"))
        dead, tapped, isPlayer, attackable, reaction = U.Standing("target")
        self.assertEqual((dead, isPlayer, attackable, reaction), (False, False, False, None))
        self.assertFalse(e.ns.Yes(S()))
        self.assertIsNone(e.ns.Plain(S()))
        self.assertEqual(e.errors(), [])

    def test_friends_get_none(self):
        e = self.env()
        data = e.lua.table(name="Ally", level=34, health=600, healthMax=800, attackable=False, reaction=5)
        o = e.ns.Nameplates.byPlate[e.mock.addPlate("nameplate1", data)]
        self.assertFalse(o.wDebuffs.shown)
        self.assertFalse(o.wCC.shown)

    def test_target_frame_uses_the_games_rows(self):
        e = self.env()
        e.target()
        A = e.ns.Auras
        self.assertTrue(A.wMine.shown)
        self.assertEqual(A.wMine.unit, "target")
        self.assertEqual(A.wMine.groups["1"].filter, "HARMFUL|!CROWD_CONTROL|PLAYER")
        self.assertTrue(A.wBuffs.shown and A.wCC.shown)
        self.assertFalse(A.wHelp.shown)
        calls, looks = A.wMine.setUnitCalls, A.wMine.looks or 0
        e.target(attackable=False, reaction=5)
        self.assertEqual(A.wMine.groups["1"].filter, "HELPFUL")            # a friend: the buffs they have
        self.assertFalse(A.wMine.groups["2"].enabled)                      # (one group now)
        self.assertFalse(A.wBuffs.shown)
        self.assertTrue(A.wHelp.shown)                                     # and its debuffs worth acting on
        self.assertGreater(A.wMine.looks, looks)                           # a new target: the game looks again,
        self.assertEqual(A.wMine.setUnitCalls, calls + 2)                  # and the row let go first (pointed at
        self.assertEqual(A.wMine.unit, "target")                           # nothing, then at "target" again)
        e.mock.setUnit("target", None)
        self.assertFalse(A.wMine.shown)
        e.cmd("demo")                                      # the demo has no real unit: our rows show it
        self.assertFalse(A.wMine.shown)
        self.assertTrue(A.icons[1].shown)
        self.assertEqual(e.errors(), [])


class Plates(unittest.TestCase):
    def enemy(self, e, unit="nameplate1", **kw):
        data = e.lua.table(name="Raptor", level=34, health=600, healthMax=800, attackable=True, reaction=2)
        for k, v in kw.items():
            data[k] = v
        plate = e.mock.addPlate(unit, data)
        return data, plate, e.ns.Nameplates.byPlate[plate]

    def test_size_name_and_a_whole_look_in_one_press(self):
        e = Env()
        NP = e.ns.Nameplates
        data, plate, o = self.enemy(e, name="Bloodscalp Headhunter")
        normal_w, normal_h = o.health.barWidth, o.health.height
        self.assertIn("Bloodscalp Headhunter", o.name.text)
        e.cmd("platesize 1")                                          # small: slimmer and shorter
        self.assertLess(o.health.barWidth, normal_w)
        self.assertLess(o.health.height, normal_h)
        e.cmd("platesize 3")                                          # large: wider and taller
        self.assertGreater(o.health.barWidth, normal_w)
        self.assertGreater(o.health.height, normal_h)
        e.cmd("platename 2")                                          # short: cut at 14 letters
        self.assertIn("Bloodscalp He…", o.name.text)
        self.assertNotIn("Headhunter", o.name.text)
        e.cmd("platename 3")                                          # none: the level stays, the name goes
        self.assertNotIn("Bloodscalp", o.name.text)
        self.assertIn("34", o.name.text)
        # a friendly NPC with no bar keeps its name whatever the setting
        p2 = e.mock.addPlate("nameplate2", e.lua.table(name="Innkeeper Lard", level=30, health=5, healthMax=5,
                                                       attackable=False, reaction=5))
        o2 = NP.byPlate[p2]
        self.assertFalse(o2.bars)
        self.assertIn("Innkeeper Lard", o2.name.text)
        # a whole look: Minimal mini, the user's own (small, no name, no power, level and class kept)
        e.cmd("platelook 3")
        self.assertEqual((e.db.plateSize, e.db.plateName), (1, 3))
        self.assertFalse(e.db.platePower)
        self.assertTrue(e.db.plateLevels and e.db.plateClassIcons and e.db.plateDebuffs and e.db.platePercent)
        self.assertTrue(e.db.plateThreat and e.db.plateCC and e.db.plateCastAlert)    # never taken away
        self.assertNotIn("Bloodscalp", o.name.text)
        self.assertLess(o.health.barWidth, normal_w)
        e.cmd("platelook 1")                                          # and back to everything
        self.assertEqual((e.db.plateSize, e.db.plateName), (2, 1))
        self.assertTrue(e.db.platePower)
        self.assertIn("Bloodscalp Headhunter", o.name.text)
        self.assertEqual(e.errors(), [])

    def test_our_look_goes_on_the_games_plate(self):
        e = Env()
        data, plate, o = self.enemy(e, classification="elite")
        self.assertTrue(o.shown)
        self.assertTrue(e.same(o.parent, plate))
        self.assertTrue(o.ignoreParentAlpha)              # the game's fade for one out of sight does not flash ours
        self.assertEqual(plate.UnitFrame.alpha, 0)
        self.assertIn("34", o.name.text)
        self.assertIn("Raptor", o.name.text)
        self.assertEqual(o.health.fill.value, 600)
        self.assertEqual(e.color(o.health), e.theme("hostile"))
        self.assertTrue(o.wingL.shown and o.wingR.shown)            # an elite: the classic wings around its name
        self.assertEqual(round(o.name.tcolor[3], 2), round(e.ns.colors.text[3], 2))   # white: readable
        data.health = 300
        e.mock.fire("UNIT_HEALTH", "nameplate1")
        self.assertGreater(o.health.flashA, 0.4)
        self.assertEqual(e.errors(), [])

    def test_friends_show_a_name_only(self):
        e = Env()
        data, plate, o = self.enemy(e, attackable=False, isPlayer=True, **{"class": "MAGE"})
        self.assertFalse(o.health.shown)
        self.assertEqual(bare(o.name.text), "Raptor")
        self.assertRegex(o.name.text, r"^\|T[^|]*\|t\|cff[0-9a-f]{6}\d+\|r Raptor$")   # a player: icon, level, name
        self.assertEqual(tuple(round(o.name.tcolor[i], 2) for i in (1, 2, 3)), (0.25, 0.78, 0.92))

    def test_friendly_npcs_by_your_standing(self):
        e = Env()
        col = lambda o: tuple(round(o.name.tcolor[i], 2) for i in (1, 2, 3))
        data, plate, o = self.enemy(e, attackable=False, reaction=8)
        self.assertEqual(col(o), (0.45, 0.72, 1.0))                  # exalted
        data2, plate2, o2 = self.enemy(e, "nameplate2", name="Guard", attackable=False, reaction=4)
        self.assertEqual(col(o2), tuple(e.ns.colors.neutral.values()))   # neutral
        data3, plate3, o3 = self.enemy(e, "nameplate3", name="Mage", attackable=False, reaction=6, isPlayer=True,
                                       **{"class": "MAGE"})
        self.assertEqual(col(o3), (0.25, 0.78, 0.92))                # a player keeps the class colour
        e.cmd("repcolors off")
        e.mock.removePlate("nameplate1")
        plate = e.mock.addPlate("nameplate1", data)
        o = e.ns.Nameplates.byPlate[plate]
        self.assertEqual(col(o), tuple(e.ns.colors.friendly.values()))   # off: friendly green for all
        self.assertEqual(e.errors(), [])

    def test_only_your_targets_plate_shakes_and_only_for_you(self):
        e = Env()
        IM = e.ns.Impact
        data, plate, o = self.enemy(e)
        data2, plate2, o2 = self.enemy(e, "nameplate2", name="Other")
        e.update(1)
        data2.health = 300                                           # someone else hits another mob
        e.mock.fire("UNIT_HEALTH", "nameplate2")
        self.assertFalse(IM.IsShaking(IM, o2))
        e.mock.setUnit("target", data)
        data.health = 500                                            # your target loses health, nothing of yours
        e.mock.fire("UNIT_HEALTH", "nameplate1")
        self.assertFalse(IM.IsShaking(IM, o))
        e.update(1)
        e.mock.fire("UNIT_SPELLCAST_SUCCEEDED", "player", "cast", 133)   # you cast, and it is hit
        data.health = 400
        e.mock.fire("UNIT_HEALTH", "nameplate1")
        self.assertTrue(IM.IsShaking(IM, o))
        self.assertEqual(e.errors(), [])

    def test_your_target_stands_out(self):
        e = Env()
        data, plate, o = self.enemy(e)
        data2, plate2, o2 = self.enemy(e, "nameplate2", name="Other")
        self.assertEqual((o.scale, o.alpha), (1, 1))
        e.mock.setUnit("target", data)
        self.assertEqual((o.scale, o.alpha), (1.15, 1))
        self.assertTrue(o.edge.shown)
        self.assertEqual((o2.scale, o2.alpha), (1, 0.85))

    def test_casts_and_removal(self):
        e = Env()
        data, plate, o = self.enemy(e)
        now = e.mock.time
        data.cast = e.lua.table(name="Bite", start=now * 1000, stop=(now + 2) * 1000)
        e.mock.fire("UNIT_SPELLCAST_START", "nameplate1")
        self.assertTrue(o.cast.shown)
        e.update(1)
        self.assertAlmostEqual(o.cast.fill.value, 0.5, places=1)
        e.mock.removePlate("nameplate1")
        self.assertFalse(o.shown)
        self.assertEqual(plate.UnitFrame.alpha, 1)
        self.assertIsNone(e.ns.Nameplates.plates.nameplate1)
        # the game reuses the plate for another unit
        e.mock.plates.nameplate3 = plate
        e.mock.units.nameplate3 = e.lua.table(name="Wolf", level=30, health=5, healthMax=5, attackable=True)
        e.mock.fire("NAME_PLATE_UNIT_ADDED", "nameplate3")
        self.assertIn("Wolf", o.name.text)
        self.assertFalse(o.cast.shown)

    def test_off_gives_the_games_plates_back(self):
        e = Env()
        data, plate, o = self.enemy(e)
        e.cmd("nameplates off")
        self.assertEqual(plate.UnitFrame.alpha, 1)
        self.assertFalse(o.shown)
        e.cmd("nameplates on")                            # plates already on screen are picked up
        self.assertEqual(plate.UnitFrame.alpha, 0)
        self.assertTrue(o.shown)

    def test_another_nameplate_addon_is_left_in_charge(self):
        e = Env(addons=("Platynator",))
        data, plate, o = self.enemy(e)
        self.assertIsNone(o)
        self.assertEqual(plate.UnitFrame.alpha, 1)
        self.assertFalse(e.ns.Nameplates.active)
        self.assertEqual(e.ns.RunCheck(False)[0], 0)


class HitsOnTheTarget(unittest.TestCase):
    def test_ticks_and_shots_land_even_when_the_game_keeps_the_guid(self):
        e = Env()
        e.target()
        IM, f = e.ns.Impact, e.frames.target
        e.lua.execute("""
            local real = UnitGUID
            function UnitGUID(unit) if unit == "target" then return nil end return real(unit) end""")   # kept from us
        before = IM.landed
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 40, 8)     # Serpent Sting ticking: nature
        self.assertEqual(IM.landed, before + 1)
        self.assertEqual(IM.last.school, "nature")
        e.update(0.1)
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 60, 4)     # Immolation Trap: fire
        self.assertEqual(IM.last.school, "fire")
        e.update(0.1)
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 90, 1)     # a shot: physical
        self.assertEqual(IM.last.school, "physical")
        self.assertIn("target", IM.DescribeUnits())
        self.assertEqual(e.errors(), [])


    def test_in_a_group_only_your_own_hits_light_the_target(self):
        e = Env()
        e.target()
        e.mock.setUnit("party1", e.lua.table(name="Friend", health=100, healthMax=100))
        IM = e.ns.Impact
        before = IM.landed
        e.update(2)
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 300, 4)    # a party mage's Fireball
        self.assertEqual(IM.landed, before)                          # not yours: left out
        self.assertEqual(IM.others, 1)
        IM.NoteCast(3044)                                            # your Arcane Shot goes off
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 120, 64)   # and lands
        self.assertEqual(IM.landed, before + 1)
        e.update(2)
        IM.SCHOOL_OF[1978] = "nature"                                # your Serpent Sting on it:
        e.lua.eval("""function(ns)
            local real = ns.Unit.Filtered
            ns.Unit.Filtered = function(unit, kind, filter, max)
                if filter == "HARMFUL|PLAYER" then return { { spellId = 1978, name = "Serpent Sting" } } end
                return real(unit, kind, filter, max)
            end
        end""")(e.ns)
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 40, 8)     # its tick is yours
        self.assertEqual(IM.landed, before + 2)
        e.update(0.1)
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 300, 4)    # a fire tick is not
        self.assertEqual(IM.landed, before + 2)
        self.assertEqual(IM.others, 2)
        e.update(0.1)
        e.mock.units.party1 = None                                   # alone again: every hit is yours or your pet's
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 50, 32)
        self.assertEqual(IM.landed, before + 3)
        self.assertEqual(e.errors(), [])


class Wounds(unittest.TestCase):
    """Your hits wound a foe's bar in its own way: blood, ichor, shards, sparks, ash."""

    def test_each_kind_of_foe_has_its_wound(self):
        e = Env()
        IM = e.ns.Impact
        for creature, wound in (("Humanoid", "bleed"), ("Beast", "bleed"), ("Dragonkin", "dragon"),
                                ("Demon", "ichor"), ("Elemental", "shatter"), ("Mechanical", "sparks"),
                                ("Undead", "sludge"), ("Critter", None)):
            e.target(creature=creature)
            self.assertEqual(IM.WoundOf("target"), wound, creature)
        e.cmd("effects 3")                                           # Classic: the undead wither to ash, as before
        e.target(creature="Undead")
        self.assertEqual(IM.WoundOf("target"), "ash")
        self.assertEqual(e.errors(), [])

    def test_your_hit_wounds_the_bar_more_as_it_runs_low(self):
        e = Env()
        IM = e.ns.Impact
        e.target(creature="Elemental", health=800, healthMax=800)
        before = sum(1 for _ in IM.live.keys())
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 100, 1)
        self.assertEqual(IM.lastWound, "shatter")
        full = sum(1 for _ in IM.live.keys()) - before
        self.assertGreater(full, 0)                                  # chips of stone break off
        e.update(2)                                                  # (gone again)
        self.assertEqual(sum(1 for _ in IM.live.keys()), 0)
        e.mock.units.target.health = 80                              # nearly done for
        e.mock.fire("UNIT_HEALTH", "target")
        e.update(0.5)
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 100, 1)
        self.assertGreater(sum(1 for _ in IM.live.keys()), full)                       # more of it
        e.update(2)
        e.cmd("wounds off")
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 100, 1)
        self.assertEqual(IM.lastWound, "shatter")
        self.assertEqual(IM.wounded, 2)                              # the option turns it off
        self.assertEqual(e.errors(), [])


class BleedingOut(unittest.TestCase):
    def test_a_wounded_foe_bleeds_more_the_lower_it_gets(self):
        e = Env()
        IM = e.ns.Impact
        e.target(creature="Humanoid", health=800, healthMax=800)
        f = e.frames.target
        e.update(2)
        self.assertEqual(IM.bled or 0, 0)                            # healthy: nothing between hits
        def bled(health, seconds=2):
            e.mock.units.target.health = health
            e.mock.fire("UNIT_HEALTH", "target")
            before = IM.bled or 0
            e.update(seconds)
            return (IM.bled or 0) - before
        some = bled(400)                                             # half: a drop now and then
        lots = bled(120)                                             # under a quarter: a stream
        self.assertGreater(some, 0)
        self.assertGreater(lots, some * 2)
        self.assertEqual(IM.lastWound, "bleed")
        self.assertEqual(bled(700), 0)                               # healed up: stops
        e.target(creature="Elemental", health=100, healthMax=800)
        self.assertGreater(bled(100), 0)
        self.assertEqual(IM.lastWound, "shatter")                    # its own kind: chips of stone
        e.cmd("wounds off")
        self.assertEqual(bled(90), 0)
        self.assertEqual(e.errors(), [])


class EffectLevels(unittest.TestCase):
    """One choice over the hit effects and the cast bar animations: Full, Subtle, Classic, None."""

    def test_full_is_the_start_and_the_command_changes_it(self):
        e = Env()
        self.assertEqual(e.ns.Effects(), "full")
        for n, level in ((2, "subtle"), (3, "classic"), (4, "none"), (1, "full")):
            e.cmd("effects %d" % n)
            self.assertEqual(e.ns.Effects(), level)
        self.assertEqual(e.errors(), [])

    def test_none_keeps_the_colour_and_nothing_else(self):
        e = Env()
        e.target()
        IM, f, cb = e.ns.Impact, e.frames.target, e.ns.CastBar
        e.cmd("effects 4")
        e.mock.logHit("SWING_DAMAGE", "player", "target", 1, True)
        self.assertGreater(f.health.flashA, 0)                       # the bar still flashes in the hit's colour
        self.assertEqual(len(list(IM.live.keys())), 0)               # no particles,
        self.assertEqual(len(list(IM.marks.keys())), 0)              # no blow drawn,
        self.assertFalse(IM.IsShaking(IM, f.visual))                 # nothing shakes
        self.assertFalse(cb.art.Start(cb.art, e.ns.CastLook.LookOf("fire")))   # and the cast bar is a plain bar
        self.assertEqual(e.errors(), [])

    def test_classic_is_the_look_from_before(self):
        e = Env()
        e.target(health=400, healthMax=800)
        IM, cb, K = e.ns.Impact, e.ns.CastBar, e.ns.CastLook
        e.cmd("effects 3")
        bar = e.frames.target.health
        w = bar.GetWidth(bar)
        e.mock.logHit("SPELL_DAMAGE", "player", "target", 4)
        xs = [t.x for t in IM.live.keys()]
        self.assertTrue(all(abs(x - w / 2) <= 10 for x in xs), xs)   # from where the health ends, as it was
        self.assertEqual(len(list(IM.marks.keys())), 0)
        self.assertIsNone(IM.struck)
        self.assertTrue(cb.art.Start(cb.art, K.SigLook("fireball")))
        self.assertIsNone(cb.art.over)                               # no show of its own: fire, as every fire spell
        self.assertTrue(e.same(cb.art.style, e.ns.CastArt.STYLES.flames))
        self.assertEqual(e.errors(), [])

    def test_reduce_animations_still_means_still(self):
        e = Env()
        e.target()
        IM, cb = e.ns.Impact, e.ns.CastBar
        e.db.reduceMotion = True
        e.mock.logHit("SWING_DAMAGE", "player", "target", 1, True)
        self.assertEqual(len(list(IM.marks.keys())), 0)
        self.assertEqual(len(list(IM.live.keys())), 0)
        self.assertFalse(IM.IsShaking(IM, e.frames.target.visual))
        self.assertFalse(cb.art.Start(cb.art, e.ns.CastLook.SigLook("fireball")))
        self.assertEqual(e.errors(), [])


class HitAreas(unittest.TestCase):
    """Blows land at eight places round a bar; spells come in from its ends; wounds open and stay."""

    def test_a_swing_cuts_at_one_of_eight_areas(self):
        e = Env()
        e.target()
        IM = e.ns.Impact
        areas = set()
        for _ in range(40):
            e.mock.logHit("SWING_DAMAGE", "player", "target", 1)
            self.assertEqual(IM.struck.kind, "slash")
            areas.add(IM.struck.area)
            e.update(0.1)
        self.assertTrue(areas <= set(range(1, 9)), areas)
        self.assertGreater(len(areas), 3)                            # here and there, not one spot
        e.update(1)
        self.assertEqual(len(list(IM.marks.keys())), 0)              # every cut is gone again
        made = len(e.mock.frames)
        for _ in range(5):
            e.mock.logHit("SWING_DAMAGE", "player", "target", 1)
            e.update(1)
        self.assertEqual(len(e.mock.frames), made)                   # and its texture is used again
        self.assertEqual(e.errors(), [])

    def test_the_area_is_on_the_bars_edge(self):
        e = Env()
        e.target()
        IM, bar = e.ns.Impact, e.frames.target.health
        w, h = bar.GetWidth(bar), bar.GetHeight(bar)
        spots = [IM.Area(bar, i) for i in range(1, 9)]
        self.assertEqual(len(set(spots)), 8)
        for i, (x, y) in enumerate(spots, 1):
            self.assertTrue(0 < x < w)
            self.assertEqual(y, h / 2 if i <= 4 else -h / 2)

    def test_your_abilities_strike_in_their_own_way(self):
        e = Env()
        e.target()
        IM, K = e.ns.Impact, e.ns.CastLook
        for spell, key, kind in ((12294, "cross", "cross"), (53, "stab", "stab"), (5221, "claw", "claw"),
                                 (23922, "bash", "bash"), (3044, "arrow", "arrow"), (35395, "light", "slash"),
                                 (5308, "heavy", "cross")):
            e.mock.logHit("SPELL_DAMAGE", "player", "target", 1)
            e.update(0.1)
            e.mock.logEntry[12] = spell
            e.mock.fire("COMBAT_LOG_EVENT_UNFILTERED")
            self.assertEqual((IM.struck.key, IM.struck.kind), (key, kind), spell)
            e.update(1)
        e.mock.logHit("RANGE_DAMAGE", "player", "target", 1)         # a plain shot flies in
        self.assertEqual(IM.struck.kind, "arrow")
        self.assertEqual(K.Strike(None, 999999), None)
        self.assertEqual(e.errors(), [])

    def test_without_the_log_the_ability_you_just_used_is_the_blow(self):
        e = Env(setup=lambda env: env.lua.execute("CombatLogGetCurrentEventInfo = nil"))
        e.target()
        IM = e.ns.Impact
        IM.NoteCast(12294)                                           # Mortal Strike, then its hit
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 90, 1)
        self.assertEqual(IM.struck.key, "cross")
        e.update(0.2)
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 40, 1)     # the next hit is a plain swing: used once
        self.assertEqual(IM.struck.key, "swing")
        e.update(0.2)
        IM.NoteCast(e.mock.secret())                                 # an ability whose ID is kept from us
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 40, 1)
        self.assertEqual(IM.struck.key, "swing")
        self.assertEqual(e.errors(), [])

    def test_a_spell_comes_in_from_an_end_and_a_tick_stays_where_the_health_ends(self):
        e = Env()
        e.target(health=400, healthMax=800)
        IM, bar = e.ns.Impact, e.frames.target.health
        w = bar.GetWidth(bar)
        ends = set()
        for _ in range(12):
            e.mock.logHit("SPELL_DAMAGE", "player", "target", 4)
            for t in IM.live.keys():
                self.assertLessEqual(min(t.x, w - t.x), 6)           # at the left end or the right one,
                self.assertEqual(t.vx > 0, t.x < w / 2)              # travelling in
                ends.add(t.x < w / 2)
            e.update(1.5)
        self.assertEqual(ends, {True, False})
        e.mock.logHit("SPELL_PERIODIC_DAMAGE", "player", "target", 4)
        self.assertTrue(all(abs(t.x - w / 2) <= 10 for t in IM.live.keys()))
        self.assertEqual(len(list(IM.marks.keys())), 0)
        self.assertEqual(e.errors(), [])

    def test_subtle_keeps_to_fixed_places_with_fewer_pieces_and_no_shake(self):
        e = Env()
        e.target()
        IM, f = e.ns.Impact, e.frames.target
        e.cmd("effects 2")
        areas = set()
        for _ in range(10):
            e.mock.logHit("SWING_DAMAGE", "player", "target", 1, True)
            areas.add(IM.struck.area)
            self.assertFalse(IM.IsShaking(IM, f.visual))
            e.update(1.2)
        self.assertEqual(areas, {2, 7})
        e.mock.logHit("SPELL_DAMAGE", "player", "target", 4)
        self.assertLess(len(list(IM.live.keys())), IM.PROFILES.fire.fx.count)
        self.assertEqual(e.errors(), [])

    def test_wounds_open_below_half_and_a_quarter_and_bleed_from_there(self):
        e = Env()
        IM = e.ns.Impact
        e.target(creature="Humanoid", health=800, healthMax=800)
        bar = e.frames.target.health

        def wounds(health):
            e.mock.units.target.health = health
            e.mock.fire("UNIT_HEALTH", "target")
            b = IM.bleeding[bar]
            shown = sum(1 for g in bar.gashes.values() if g.shown) if bar.gashes else 0
            return ((b.open or 0) if b else 0), shown

        self.assertEqual(wounds(700), (0, 0))
        self.assertEqual(wounds(400), (1, 1))                        # half: the first wound
        self.assertEqual(wounds(300), (1, 1))
        self.assertEqual(wounds(180), (3, 3))                        # a quarter: two more
        b = IM.bleeding[bar]
        areas = list(b.areas.values())
        self.assertEqual(len(set(areas)), 3)                         # never two in one place
        e.update(1.5)                                                # what it bleeds comes out of them
        xs = [IM.Area(bar, a)[0] for a in areas]
        drops = [t for t in IM.live.keys() if t.kind == "drip"]
        self.assertGreater(len(drops), 0)
        for t in drops:
            self.assertLessEqual(min(abs(t.x - x) for x in xs), 16)  # under a gash, not at the end of the health
        self.assertGreater(IM.bled, 0)
        self.assertEqual(wounds(700), (0, 0))                        # healed up: they close
        e.cmd("effects 3")                                           # Classic has no gashes, and bleeds from 60%
        self.assertEqual(wounds(180), (0, 0))
        self.assertIsNotNone(IM.bleeding[bar])
        self.assertEqual(e.errors(), [])

    def test_the_first_wound_opens_where_your_last_blow_fell(self):
        e = Env()
        IM = e.ns.Impact
        e.target(creature="Beast", health=800, healthMax=800)
        bar = e.frames.target.health
        e.mock.logHit("SWING_DAMAGE", "player", "target", 1)
        fell = IM.struck.area
        e.mock.units.target.health = 390
        e.mock.fire("UNIT_HEALTH", "target")
        self.assertEqual(IM.bleeding[bar].areas[1], fell)
        self.assertEqual(e.errors(), [])

    def test_hidden_health_opens_nothing_at_half_and_asks_the_game_about_a_quarter(self):
        e = Env()
        e.lua.execute("""
            GATE = { secret = true }
            C_CurveUtil = C_CurveUtil or { CreateCurve = function() return { AddPoint = function() end } end }
            UnitHealthPercent = function() return GATE end
        """)
        IM = e.ns.Impact
        e.target(creature="Humanoid", health=e.mock.secret(), healthMax=e.mock.secret())
        bar = e.frames.target.health
        e.mock.fire("UNIT_HEALTH", "target")
        b = IM.bleeding[bar]
        self.assertIsNotNone(b)
        self.assertEqual(b.open, 3)                                  # all three, on a layer the game's answer shows
        self.assertTrue(e.same(b.layer, bar.bleedLayer))             # or hides, unread
        self.assertTrue(e.same(bar.bleedLayer.alpha, e.g.GATE))
        for g in bar.gashes.values():
            self.assertTrue(e.same(g.parent, bar.bleedLayer))
        e.update(1)
        self.assertEqual(e.errors(), [])

    def test_striketest_shows_every_kind_of_blow(self):
        e = Env()
        e.target()
        IM = e.ns.Impact
        self.assertIn("every kind of blow", e.cmd("striketest"))
        kinds = set()
        for _ in range(12):
            e.update(0.6)
            if IM.struck:
                kinds.add(IM.struck.kind)
        self.assertEqual(kinds, {"slash", "cross", "claw", "stab", "bash", "arrow"})
        e.cmd("effects 3")
        self.assertIn("Full and Subtle", e.cmd("striketest"))
        self.assertEqual(e.errors(), [])


class MainAbilities(unittest.TestCase):
    """The main abilities have a cast of their own: bolts charge and fire, Wrath winds up, Aimed Shot locks on."""

    NAMES = {133: "Fireball", 116: "Frostbolt", 30451: "Arcane Blast", 19434: "Aimed Shot", 5176: "Wrath",
             5143: "Arcane Missiles", 15407: "Mind Flay", 403: "Lightning Bolt", 29722: "Incinerate"}

    def env(self):
        e = Env()
        e.mock.spellNames = e.lua.table_from(self.NAMES)
        return e, e.ns.CastBar.art, e.ns.CastLook, e.ns.CastArt

    def test_a_main_ability_is_known_by_id_or_by_name_and_keeps_its_school(self):
        e, art, K, A = self.env()
        self.assertEqual(K.Look("Fireball", 133).sig.key, "fireball")
        self.assertEqual(K.Look("Fireball", 42833).sig.key, "fireball")         # a higher rank, by its name
        self.assertEqual(K.Look("Fireball", 133).kind, "fire")
        self.assertEqual(K.Look("Arcane Blast", 30451).kind, "arcane")
        self.assertEqual(K.Look("Incinerate", 29722).kind, "fire")
        self.assertEqual(K.Look("Lightning Bolt", 403).kind, "lightning")       # still the sky's own colour
        self.assertEqual(K.Look("Lightning Bolt", 403).sig.key, "lightningbolt")
        aimed = K.Look("Aimed Shot", 19434)                                     # its school not learned yet
        self.assertEqual((aimed.kind, aimed.sig.show), ("physical", "reticle"))
        self.assertIsNone(K.Look("Mystery", 99999))
        self.assertIsNone(K.Look(e.mock.secret(), e.mock.secret()))             # an enemy's cast kept from us
        self.assertIsNone(K.Look("Holy Light", 635).sig)
        known, missing = K.SigsKnown()
        self.assertEqual(known, len(self.NAMES))                                # (what this game can name)
        self.assertIn("pyroblast", list(missing.values()))
        for key, sig in K.SIGS.items():                                         # every one has a show to play
            self.assertIsNotNone(A.SHOWS[sig.show], key)
            self.assertIsNotNone(K.SigLook(key), key)
        self.assertEqual(e.errors(), [])

    def test_a_bolt_gathers_at_the_right_end_and_fires_when_it_lands(self):
        e, art, K, A = self.env()
        self.assertTrue(art.Start(art, K.Look("Fireball", 133)))
        self.assertTrue(e.same(art.over, A.SHOWS.charge))
        self.assertTrue(e.same(art.style, A.STYLES.flames))          # over its school's own flames
        art.Update(art, 0.1, 0.1, 5.0)
        small = art.o.charge
        self.assertLess(abs(art.o.glow.points[1][4] - art.w), 2)     # at the right end of the bar
        art.Update(art, 0.95, 0.95, 6.0)
        self.assertGreater(art.o.charge, small * 3)                  # about to burst
        art.Update(art, 0.5, 0.5, 6.1)                               # pushed back by a hit: it stays in step
        self.assertLess(art.o.charge, small * 3)
        art.Update(art, 1.0, 1.0, 7.0)
        self.assertFalse(art.o.fired)
        art.Finish(art, True, 7.0)
        art.Update(art, None, None, 7.1)
        self.assertTrue(art.o.fired)
        self.assertEqual(art.o.fx[1].alpha, 1)
        self.assertGreater(art.o.fx[1].points[1][4], art.w)          # thrown out past the end, at the enemy
        self.assertEqual(art.Kick(art), 1)                           # and the bar jolts
        art.Update(art, None, None, 8.0)
        self.assertIsNone(art.kind)
        self.assertEqual(art.Shown(art), 0)
        self.assertEqual(e.errors(), [])

    def test_a_cast_cut_short_fizzles_without_firing(self):
        e, art, K, A = self.env()
        art.Start(art, K.Look("Frostbolt", 116))
        art.Update(art, 0.6, 0.6, 5.0)
        art.Finish(art, False, 5.0)
        art.Update(art, None, None, 5.2)
        self.assertTrue(art.o.fizzled)
        self.assertFalse(art.o.fired)
        self.assertTrue(all(t.alpha == 0 for t in art.o.fx.values()))
        self.assertIsNone(art.Kick(art))
        self.assertEqual(e.errors(), [])

    def test_every_bolt_fires_in_its_own_way(self):
        e, art, K, A = self.env()
        ways = set()
        for key, sig in K.SIGS.items():
            if sig.show != "charge":
                continue
            self.assertTrue(art.Start(art, K.SigLook(key)), key)
            art.Update(art, 1.0, 1.0, 5.0)
            art.Finish(art, True, 5.0)
            for step in (0.05, 0.2, 0.4):
                art.Update(art, None, None, 5.0 + step)
            self.assertGreater(sum(1 for t in art.o.fx.values() if t.alpha > 0), 0, key)
            ways.add(sig.fire)
        self.assertEqual(ways, {"burst", "shatter", "lance", "implode", "beam", "engulf", "arc"})
        self.assertEqual(e.errors(), [])

    def test_wrath_winds_up_in_the_middle_and_is_thrown_at_the_enemy(self):
        e, art, K, A = self.env()
        art.Start(art, K.Look("Wrath", 5176))
        self.assertTrue(e.same(art.over, A.SHOWS.orb))
        self.assertTrue(e.same(art.style, A.BARE))                   # alone: no green lightning under it
        art.Update(art, 0.5, 0.5, 10.0)
        self.assertGreater(art.o.speed, 2 * (1.8 + 2.6 * 0.5))       # much faster than the Hearthstone's whirl
        self.assertEqual(art.o.ball.points[1][4], art.w / 2)
        before = [(w.points[1][4], w.points[1][5]) for w in art.o.wisps.values()]
        art.Update(art, 0.52, 0.52, 10.1)
        self.assertNotEqual(before, [(w.points[1][4], w.points[1][5]) for w in art.o.wisps.values()])
        art.Finish(art, True, 11.0)
        art.Update(art, None, None, 11.45)
        self.assertTrue(art.o.thrown)
        self.assertGreater(art.o.ball.points[1][4], art.w)           # off the right end
        art.Start(art, K.Look("Wrath", 5176))
        art.Update(art, 0.5, 0.5, 12.0)
        art.Finish(art, False, 12.0)
        art.Update(art, None, None, 12.3)
        self.assertFalse(art.o.thrown)                               # cut short: it dwindles where it is
        self.assertEqual(art.o.ball.points[1][4], art.w / 2)
        self.assertEqual(e.errors(), [])

    def test_aimed_shot_wanders_and_locks_on_the_middle_as_it_fires(self):
        e, art, K, A = self.env()
        art.Start(art, K.Look("Aimed Shot", 19434))
        mid = art.w / 2

        def wander(p, at):
            off = []
            for i in range(40):
                art.Update(art, p, p, at + i * 0.1)
                off.append(abs(art.o.x - mid))
            return max(off)

        early, late = wander(0.05, 20), wander(0.9, 30)
        self.assertGreater(early, 20)
        self.assertLess(late, early * 0.3)                           # less and less
        ring = art.o.sights[1].ring
        self.assertGreater(ring.vcolor[2], 0.8)                      # not red yet at 90%
        art.Update(art, 1.0, 1.0, 40.0)
        self.assertEqual((art.o.x, art.o.y), (mid, 0))               # dead on the middle
        self.assertTrue(art.o.locked)
        self.assertLess(ring.vcolor[2], 0.5)                         # red: it goes
        art.Finish(art, True, 40.0)
        art.Update(art, None, None, 40.1)
        self.assertEqual(art.o.flash.alpha, 1)
        art.Start(art, K.Look("Aimed Shot", 19434))                  # interrupted: the sights drop away
        art.Update(art, 0.5, 0.5, 50.0)
        y = art.o.sights[1].ring.points[1][5]
        art.Finish(art, False, 50.0)
        art.Update(art, None, None, 50.2)
        self.assertFalse(art.o.locked)
        self.assertLess(art.o.sights[1].ring.points[1][5], y)
        self.assertLess(art.o.sights[1].ring.alpha, 0.9)
        self.assertEqual(art.o.flash.alpha, 0)
        self.assertEqual(e.errors(), [])

    def test_a_gun_has_a_crosshair_and_a_bow_a_ring_and_a_pin(self):
        e, art, K, A = self.env()
        self.assertEqual(A.Sights(), "bow")                          # nothing known: a bow's
        art.Start(art, K.SigLook("aimed"))
        art.Update(art, 0.5, 0.5, 5.0)
        g = art.o.sights[1]
        self.assertGreater(g.pin.alpha, 0)
        self.assertEqual(g.ticks[3].alpha, 0)
        e.mock["items"][777] = e.lua.table_from({"class": 2, "sub": 3})
        e.lua.execute("function GetInventoryItemID(unit, slot) if slot == 18 then return 777 end end")
        self.assertEqual(A.Sights(), "gun")
        art.Start(art, K.SigLook("aimed"))
        art.Update(art, 0.5, 0.5, 6.0)
        g = art.o.sights[1]
        self.assertEqual(g.pin.alpha, 0)
        self.assertGreater(g.ticks[3].alpha, 0)                      # the upright hairs of a crosshair
        self.assertEqual(e.errors(), [])

    def test_channels_empty_the_bar_and_missiles_leave_one_by_one(self):
        e, art, K, A = self.env()
        art.Start(art, K.Look("Arcane Missiles", 5143))
        fired = []
        for i, p in enumerate((0.05, 0.2, 0.4, 0.6, 0.8, 0.99)):
            art.Update(art, 1 - p, p, 50 + i)
            fired.append(art.o.fired)
        self.assertEqual(fired, [0, 1, 2, 3, 4, 5])
        art.Update(art, 0.01, 0.99, 55.1)
        self.assertGreater(art.o.orbs[5].points[1][4], art.w * 0.5)  # the last one on its way off the bar
        art.Start(art, K.Look("Mind Flay", 15407))
        art.Update(art, 0.9, 0.1, 60.0)
        self.assertEqual(art.o.beats, 0)
        art.Update(art, 0.3, 0.7, 61.0)
        self.assertEqual(art.o.beats, 2)                             # a throb at every tick
        self.assertGreater(sum(1 for t in art.o.dots.values() if t.alpha > 0), 0)
        self.assertEqual(e.errors(), [])

    def test_subtle_and_nameplates_get_fewer_pieces_and_no_jolt(self):
        e, art, K, A = self.env()
        art.Start(art, K.SigLook("fireball"))
        full = art.n
        e.cmd("effects 2")
        art.Start(art, K.SigLook("fireball"))
        self.assertLess(art.n, full)
        art.Update(art, 1.0, 1.0, 5.0)
        art.Finish(art, True, 5.0)
        self.assertIsNone(art.Kick(art))
        e.cmd("effects 1")
        light = A.Attach(e.ns.CastBar.bar, 0.65, True)
        light.Start(light, K.SigLook("fireball"))
        self.assertLess(light.n, full)
        light.Update(light, 1.0, 1.0, 6.0)
        light.Finish(light, True, 6.0)
        self.assertIsNone(light.Kick(light))
        self.assertEqual(e.errors(), [])

    def test_your_cast_bar_jolts_as_a_bolt_fires_and_gives_its_show_room(self):
        e, art, K, A = self.env()
        cb = e.ns.CastBar
        self.assertIn("sigtest", e.cmd("help").lower() + "sigtest")
        e.cmd("sigtest")
        seen, jolted, rooms = set(), False, set()
        for _ in range(900):
            e.update(0.05)
            if cb.demo is None and not cb.frame.shown:
                break
            if cb.art.sig:
                seen.add(cb.art.sig.key)
                rooms.add(cb.room)
            jolted = jolted or bool(cb.jolt)
        self.assertEqual(seen, set(A.SIG_DEMO.values()))
        self.assertTrue(jolted)
        self.assertEqual(rooms, {cb.ROOM, cb.ROOM + 6, cb.ROOM + 8})  # Wrath's and the sights' reach further
        p = cb.bar.points[1]
        self.assertEqual((p[4], p[5]), (0, 0))                       # back where it was
        self.assertFalse(cb.frame.shown)
        self.assertEqual(e.errors(), [])


class PetSpells(unittest.TestCase):
    def test_revive_pet_brings_back_life_and_mend_pet_is_a_nature_heal(self):
        e = Env()
        K, A = e.ns.CastLook, e.ns.CastArt
        look = K.Look("Revive Pet", 982)
        self.assertEqual(look.kind, "revive")                        # its own look: new growth,
        self.assertEqual(A.STYLE_OF.revive, "revive")                # a dial of leaves round a beating heart
        mend = K.Look("Mend Pet", 136)
