class Moments(unittest.TestCase):
    def env(self):
        def setup(env):
            env.mock.units.player["class"] = "PALADIN"
        e = Env(setup=setup)
        e.target()
        e.mock.spellNames = e.lua.table_from({20271: "Judgement", 679: "Holy Strike"})
        e.mock.fire("PLAYER_REGEN_DISABLED")
        return e

    def land(self, e, spell, amount=300, crit=False):
        e.mock.fire("UNIT_SPELLCAST_SUCCEEDED", "player", "cast", spell)
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "CRITICAL" if crit else "", amount, 2)

    def test_each_key_ability_has_its_feel(self):
        e = self.env()
        R = e.ns.Rumble
        self.land(e, 20271)
        self.assertEqual(R.last, "splash")                          # Judgement splashes
        e.update(2)
        self.land(e, 679)
        self.assertEqual(R.last, "strike")                          # Holy Strike snaps
        e.update(2)
        e.mock.fire("UNIT_SPELLCAST_SUCCEEDED", "player", "cast", 635)    # not a key ability
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "", 100, 2)
        self.assertNotEqual(R.last, "splash")

    def test_one_cast_names_one_hit_a_swing_behind_it_is_a_swing(self):
        e = self.env()
        M = e.ns.Moments
        self.land(e, 679, 450, True)                                # Holy Strike crits,
        e.update(0.1)
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "CRITICAL", 300, 1)   # and a white swing crits right behind it
        e.update(0.6)
        self.assertEqual(M.frame.label.text, "+ Holy Strike\n+ Melee  |cffffd24d×2|r")   # not Holy Strike twice
        self.assertEqual(e.errors(), [])

    def druid(self):
        e = self.env()
        e.mock.spellNames = e.lua.table_from({5176: "Wrath", 8921: "Moonfire"})
        return e

    def hit(self, e, mask, crit=True):
        e.mock.fire("UNIT_COMBAT", "target", "WOUND", "CRITICAL" if crit else "", 300, mask)

    def cast(self, e, spell):
        e.mock.fire("UNIT_SPELLCAST_SUCCEEDED", "player", "cast", spell)

    def names(self, e):
        seq = e.ns.Moments.fight.chain.seq
        return [seq[i] for i in range(1, len(seq) + 1)]

    def test_spell_damage_is_never_called_melee(self):
        e = self.druid()
        self.hit(e, 64)                                             # an arcane tick, nothing just cast
        e.update(0.1)
        e.g.STRING_SCHOOL_NATURE = "Natur"                          # (the game's own word for the type)
        self.hit(e, 8)
        e.update(0.1)
        self.hit(e, e.mock.secret())                                # a type the game keeps to itself
        e.update(0.1)
        self.hit(e, 1)                                              # only physical damage is Melee
        self.assertEqual(self.names(e), ["Arcane", "Natur", "?", "Melee"])
        self.assertEqual(e.errors(), [])

    def test_a_hit_is_named_after_a_cast_only_when_its_damage_type_fits(self):
        e = self.druid()
        self.cast(e, 5176)                                          # Wrath is on its way,
        e.update(0.3)
        self.hit(e, 64)                                             # an arcane hit crits first: not the Wrath,
        e.update(0.9)
        self.hit(e, 8)                                              # which lands over a second after its cast
        self.assertEqual(self.names(e), ["Arcane", "Wrath"])
        e.update(3)
        self.cast(e, 5176)
        e.update(0.2)
        self.hit(e, 1)                                              # a swing behind a cast is no Wrath
        e.update(0.8)
        self.hit(e, 8, crit=False)                                  # the Wrath lands without a crit:
        e.update(0.2)
        self.hit(e, 8)                                              # the next nature crit is not it
        self.assertEqual(self.names(e), ["Melee", "Nature"])
        self.assertEqual(e.errors(), [])

    def test_hidden_amounts_are_never_added(self):
        # the game refuses arithmetic on amounts it keeps to itself, and every refused try counts as an addon
        # error (in a battleground they reached the game's warning): never tried, the hits shown side by side
        e = self.env()
        M = e.ns.Moments
        tried = []
        make = e.lua.eval("""function(v, tried)
            local mt = {}
            mt.__add = function(a, b) tried[#tried + 1] = true; error("blocked") end
            return setmetatable({ secret = true, v = v }, mt)
        end""")
        log = e.lua.table()
        self.land(e, 20271, make(200, log), True)
        e.update(0.1)
        self.land(e, 679, make(150, log), True)
        e.update(0.6)
        self.assertEqual(len(log), 0)                                # not even tried
        self.assertFalse(M.secretSum)
        self.assertFalse(M.fight.chain.hasTotal)
        self.assertEqual(M.frame.label.text, "+ Judgement\n+ Holy Strike  |cffffd24d×2|r")
        self.assertNotIn("crits", M.frame.number.text)
        self.assertEqual(e.errors(), [])

    def test_small_crits_are_no_moment(self):
        e = self.env()
        M = e.ns.Moments
        for _ in range(6):                                          # your crits usually do about 500
            e.update(2)
            self.land(e, 20271, 500, True)
        e.update(2)
        self.land(e, 20271, 500, True)
        M.FromLog(20424, "Seal of Command", 90, True, 2)            # a small crit right behind: not part of it
        self.assertEqual(M.fight.chain.n, 1)
        self.assertGreater(M.smallSkipped, 0)
        M.FromLog(679, "Holy Strike", 450, True, 1)                 # a real one is
        self.assertEqual(M.fight.chain.n, 2)
        self.assertEqual(e.errors(), [])

    def test_moments_are_a_feed_right_of_the_middle(self):
        e = self.env()
        M = e.ns.Moments
        M.Show(M, e.lua.table(side=e.lua.table(200, 300)), "Judgement + Holy Strike", "holy", None, 2)
        e.update(1.4)                                               # past its hold, fading:
        M.Show(M, 512, "Exorcism + Melee", "holy", None, 2)         # a second moment is a new entry
        e.update(0.05)
        entries = [M.entries[i] for i in range(1, len(M.entries) + 1)]
        self.assertEqual(len(entries), 2)
        self.assertIn("Exorcism", entries[0].f.label.text)          # the newest first,
        p0, p1 = entries[0].f.points[1], entries[1].f.points[1]
        self.assertEqual((p0[1], p0[3]), ("TOPLEFT", "CENTER"))
        self.assertGreater(p0[4], 0)                                # right of the middle,
        self.assertGreater(p1[5], p0[5])                            # the older one moving up over it,
        RC = e.ns.Numbers.Soon                                      # all of it a block above the cooldowns'
        x, y = RC.Spot()[0], RC.Spot()[1]
        self.assertAlmostEqual(p0[4], x, delta=30)                  # (their left edge)
        self.assertGreater(p0[5] - entries[0].f.tall, y + RC.GRIP.y + RC.GRIP.h)
        e.update(3)
        self.assertEqual(len(M.entries), 0)                         # each gone on its own time
        e.cmd("momentplace 2")                                      # or one at a time, in the middle
        M.Show(M, 512, "Exorcism + Melee", "holy", None, 2)
        e.update(1.4)
        M.Show(M, 300, "Judgement + Melee", "holy", None, 2)
        e.update(0.05)
        self.assertEqual(len(M.entries), 1)
        self.assertEqual(M.entries[1].f.points[1][1], "TOP")
        self.assertEqual(M.entries[1].f.points[1][4], 0)
        self.assertEqual(e.errors(), [])

    def test_crits_within_half_a_second_are_a_burst_rarely(self):
        e = self.env()
        M = e.ns.Moments
        self.assertEqual(M.BURST, 1.0)
        self.assertEqual(M.DELAY, 0.5)
        self.land(e, 20271, 500, True)
        self.assertIsNone(M.live)                                   # one crit: felt, not pinned
        e.update(0.1)
        self.land(e, 679, 450, True)                                # right behind it: a burst,
        self.assertIsNone(M.live)                                   # but the numbers fly first
        self.land(e, 679, 300, False)                               # a hit that does not crit leaves it alone
        e.update(0.4)
        self.land(e, 20271, 500, True)                              # the burst goes on
        e.update(0.3)
        self.assertIsNone(M.live)                                   # (put off again by the last crit)
        e.update(0.3)
        self.assertIsNotNone(M.live)                                # over: the total, half a second on
        self.assertEqual(M.frame.number.text, "1450")               # what they did together
        self.assertEqual(M.frame.label.text, "+ Judgement\n+ Holy Strike\n+ Judgement  |cffffd24d×3|r")   # one line a crit
        self.assertEqual(e.ns.Rumble.last, "moment")
        self.assertEqual(M.fight.moments, 1)                        # (one moment, not two)
        e.update(1.0)
        self.assertIsNotNone(M.live)                                # long enough to see what happened,
        e.update(1.2)
        self.assertIsNone(M.live)                                   # gone before it is in the way (under 2.2 s)
        self.land(e, 20271, 500, True)                              # long after: a crit alone is no burst
        e.update(1.2)
        self.land(e, 679, 500, True)                                # and nor is one more than a second on
        self.assertEqual(M.fight.chain.n, 1)
        self.assertEqual(M.fight.moments, 1)
        for _ in range(3):                                          # never more than twice a fight
            e.update(9)
            self.land(e, 20271, 500, True)
            self.land(e, 679, 500, True)
        self.assertEqual(M.fight.moments, 2)
        self.land(e, 20271, 500, True)                              # any spell of yours the log names counts
        e.update(9)
        e.mock.fire("PLAYER_REGEN_DISABLED")
        self.land(e, 20271, 500, True)
        M.FromLog(26573, "Consecration", 300, True, 2)
        self.assertEqual(M.fight.chain.n, 2)
        e.update(0.6)
        self.assertEqual(M.frame.label.text, "+ Judgement\n+ Consecration  |cffffd24d×2|r")
        e.mock.fire("PLAYER_REGEN_DISABLED")                        # a new fight
        self.assertEqual(M.fight.moments, 0)

    def test_without_the_combat_log_any_crit_of_yours_joins(self):
        e = self.env()
        M = e.ns.Moments
