class Grid(unittest.TestCase):
    """Every combination of the switches, end to end: what is on screen must match the settings, the in-game
    self-check must agree, and turning the HUD off must leave the game exactly as it was."""

    FLAGS = ("enabled", "always", "hideBlizzard", "chat", "player", "target", "pet")

    def combos(self):
        import itertools
        for style in ("0", "1"):
            for bits in itertools.product((True, False), repeat=len(self.FLAGS)):
                yield style, dict(zip(self.FLAGS, bits))

    def make(self, style, o, **kw):
        b = lambda v: "true" if v else "false"
        db = ("{ v = 2, enabled = %s, always = %s, hideBlizzard = %s, chat = %s, units = { player = %s, target = %s, "
              "pet = %s } }" % tuple(b(o[k]) for k in self.FLAGS))
        return Env(db=db, style=style, **kw)

    def verify(self, e, style, o, label):
        run = o["enabled"] and (o["always"] or style == "1")
        aside = run and o["hideBlizzard"]
        self.assertEqual(e.aside("PlayerFrame"), bool(aside and o["player"]), label)
        self.assertEqual(e.aside("TargetFrame"), bool(aside and o["target"]), label)
        self.assertEqual(e.aside("FocusFrame"), bool(aside), label)
        self.assertEqual(e.g.ChatFrame1.points[1][1], "TOPLEFT" if run and o["chat"] else "CENTER", label)
        for key, has_unit in (("player", True), ("target", True), ("pet", False)):
            f = e.frames[key]
            shown = bool(f and f.button.shown)
            self.assertEqual(shown, bool(run and o[key] and has_unit), "%s %s" % (label, key))
        failed, rows = e.ns.RunCheck(False)
        bad = [r.name for r in rows.values() if not r.ok]
        self.assertEqual(failed, 0, "%s: %s" % (label, bad))
        self.assertEqual(e.errors(), [], label)

    def pristine(self, e, label):
        for name in e.mock.cooldownFrames.values():
            self.assertEqual(e.g[name].alpha, 1, label)
        self.assertEqual(e.mock.cvars.cooldownViewerEnabled, "1", label)
        self.assertEqual(e.aside("PlayerFrame"), False, label)
        self.assertEqual(e.aside("TargetFrame"), False, label)
        self.assertEqual(e.aside("FocusFrame"), False, label)
        self.assertEqual(e.g.ChatFrame1.points[1][1], "CENTER", label)
        self.assertTrue(e.same(e.g.MerchantSellAllJunkButton.scripts.OnClick, e.mock.nativeJunkClick), label)
        self.assertEqual((e.g.PartyFrame.alpha, e.g.CompactRaidFrameContainer.alpha), (1, 1), label)
        self.assertEqual(e.parent("PlayerCastingBarFrame"), "UIParent", label)
        self.assertEqual(e.g.GamepadMainActionBarFrame.scale, 1, label)
        self.assertEqual((e.g.ChatFrame1.fading, e.g.ChatFrame1.timeVisible), (False, 120), label)
        for key in ("player", "target", "pet", "tot", "focus"):
            f = e.frames[key]
            self.assertFalse(bool(f and f.button.shown), label)

    def test_every_combination(self):
        n = 0
        for style, o in self.combos():
            label = "style %s %s" % (style, o)
            e = self.make(style, o)
            e.target()
            self.verify(e, style, o, label)
            e.update(0.5)
            e.cmd("off")
            self.pristine(e, label + " after off")
            n += 1
        self.assertEqual(n, 256)

    def test_every_combination_when_logging_in_during_combat(self):
        for style, o in self.combos():
            label = "combat login, style %s %s" % (style, o)
            e = self.make(style, o, combat=True)
            self.pristine(e, label)                        # nothing may be touched yet
            e.mock.state.combat = False
            e.mock.fire("PLAYER_REGEN_ENABLED")
            e.target()
            self.verify(e, style, o, label)

    def test_switching_everything_back_and_forth_ends_where_it_started(self):
        e = Env()
        e.target()
        for c in ("chat on", "player off", "blizzard on", "always on", "target off", "pet off", "scale 150",
                  "unlock", "lock", "demo", "demo", "player on", "target on", "blizzard off", "chat off", "pet on"):
            e.cmd(c)
            self.assertEqual(e.ns.RunCheck(False)[0], 0, c)
        self.assertEqual(e.errors(), [])
        e.cmd("off")
        self.pristine(e, "after the tour")

    def test_the_check_notices_when_something_is_wrong(self):
        e = Env()
        self.assertEqual(e.ns.RunCheck(False)[0], 0)
        e.g.PlayerFrame.alpha = 1                          # the game's frame showed through
        e.frames.player.button.shown = False               # and ours vanished
        out = e.cmd("check")
        self.assertIn("FAIL", out)
        self.assertEqual(e.db.check.failed, 2)
        self.assertIn("ok", e.cmd("check all"))


class Levelling(unittest.TestCase):
    """A levelling plan beside a profession's window, broken down to what you gather."""

    WINDOW = """
        RECIPES = {
            { name = "Alchemy" },
            { name = "Minor Healing Potion", kind = "optimal", reagents = { 2447 }, need = { 1 }, product = 118 },
            { name = "Elixir of Strength", kind = "medium", reagents = { 2449, 765 }, need = { 1, 1 }, product = 2454 },
            { name = "Weak Troll Blood", kind = "easy", reagents = { 765 }, need = { 2 }, product = 3382 },
            { name = "Old Remedy", kind = "trivial", reagents = { 2447 }, need = { 1 }, product = 999 },
        }
        TRADE = { "Alchemy", 50, 60 }
        GetTradeSkillLine = function() return TRADE[1], TRADE[2], TRADE[3] end
        GetNumTradeSkills = function() return #RECIPES end
        GetTradeSkillInfo = function(i) local r = RECIPES[i]; return r.name, r.kind or "header", 0, false, nil, r.ups end
        GetTradeSkillNumReagents = function(i) return #(RECIPES[i].reagents or {}) end
        GetTradeSkillReagentItemLink = function(i, k) return "|Hitem:" .. RECIPES[i].reagents[k] .. "|h[x]|h" end
        GetTradeSkillReagentInfo = function(i, k) return "x", 1, RECIPES[i].need[k], 0 end
        GetTradeSkillItemLink = function(i) return RECIPES[i].product and ("|Hitem:" .. RECIPES[i].product .. "|h[x]|h") end
        GetTradeSkillNumMade = function(i) return 1, 1 end
    """

    def env(self, open=True, **kw):
        e = Env(setup=lambda env: env.lua.execute(self.WINDOW), **kw)
        T = e.lua.table
        e.mock.skills = e.lua.table_from([T(name="Alchemy", rank=50, cap=60)])
        for id, name in ((2447, "Peacebloom"), (765, "Silverleaf"), (2449, "Earthroot"), (2770, "Copper Ore"),
                         (2771, "Tin Ore"), (2840, "Copper Bar"), (3576, "Tin Bar"), (2841, "Bronze Bar")):
            e.mock["items"][id] = T(name=name, stack=20, **{"class": 7})
        e.mock.fire("PLAYER_ENTERING_WORLD")
        e.update(0.5)
        if open:
            self.open(e)
        return e

    def open(self, e):
        e.window = e.g.CreateFrame("Frame", "TradeSkillFrame", e.g.UIParent)
        e.window.shown = True
        e.mock.fire("TRADE_SKILL_SHOW")
        e.update(0.5)

    def test_the_plan_takes_the_cheapest_point_and_sits_beside_the_window(self):
        e = self.env()
        LV = e.ns.Levelling
        plan = LV.plan
        self.assertEqual((plan.kind, plan.rank, plan.target), ("alchemy", 50, 60))
        self.assertEqual(len(plan.steps), 1)                         # the orange one, a point every time
        step = plan.steps[1]
        self.assertEqual((step.rec.n, step.colour, step["from"], step.to), ("Minor Healing Potion", 3, 50, 60))
        self.assertEqual(step.crafts, 11)                            # (the last two may miss once it turns yellow)
        self.assertEqual(plan.need[2447], 11)
        panel = e.g.ControllerCamHUD_SkillPlanPanel
        self.assertTrue(panel.shown)
        p = panel.points[1]
        self.assertEqual((p[1], p[3], p[4]), ("TOPLEFT", "TOPRIGHT", 6))
        self.assertTrue(e.same(p[2], e.window))                     # beside the game's window, never in it
        self.assertEqual(len(e.window.points), 0)                     # (nothing done to the game's window)
        self.assertIn("Alchemy 50 > 60", plain(panel.title.text))
        row = plain(LV.rows[1].text.text)                             # (your own recipe: no guide covers 50 here)
        self.assertIn("Minor Healing Potion", row)
        self.assertIn("up to x11", row)
        self.assertEqual(LV.rows[1].right.text, "50-60")
        self.assertIn("Levelling plan", "\n".join(LV.Describe().values()) + "Levelling plan")
        self.assertEqual(e.errors(), [])

    def test_colours_and_learned_changes_give_the_chance(self):
        e = self.env(open=False)
        LV = e.ns.Levelling
        Y, G, X = LV.Thresholds(None, 2, 100)                       # yellow, nothing seen: about three in four
        self.assertAlmostEqual(LV.Chance(100, Y, X), 0.75)
        Y, G, X = LV.Thresholds(None, 1, 100)                       # green: about one in four
        self.assertAlmostEqual(LV.Chance(100, Y, X), 0.25)
        Y, G, X = LV.Thresholds(None, 3, 100)
        self.assertEqual(LV.Chance(100, Y, X), 1)                    # orange: always
        b = e.lua.table(yl=99, yh=100)                               # seen turning yellow at 100
        Y, G, X = LV.Thresholds(b, 2, 100)
        self.assertEqual((Y, G, X), (100, 115, 130))
        self.assertAlmostEqual(LV.Chance(115, Y, X), 0.5)
        self.assertEqual(LV.Chance(130, Y, X), 0)                     # grey
        self.open(e)                                                  # learned from the window, and kept
        e.lua.execute("TRADE = { 'Alchemy', 58, 60 }; RECIPES[2].kind = 'medium'")
        e.mock.fire("TRADE_SKILL_UPDATE")
        e.update(0.5)
        b = e.db.skillSteps.alchemy["Minor Healing Potion"]
        self.assertEqual((b.yl, b.yh), (50, 58))
        again = Env(db=e.mock.serialize(e.g.ControllerCamHUDDB))
        self.assertEqual(again.db.skillSteps.alchemy["Minor Healing Potion"].yh, 58)
        self.assertEqual(again.db.skillMakes[118].r[2447], 1)       # and what the potion is made of
        self.assertEqual(e.errors(), [])

    def test_the_list_shows_what_the_plan_wants_with_the_way_to_get_it(self):
        e = self.env(open=False)
        LV, T = e.ns.Levelling, e.lua.table
        e.db.skillMakes[2318] = T(m=1, k="leatherworking", r=e.lua.table_from({2934: 3}))     # Light Leather: 3 scraps
        e.db.skillMakes[2319] = T(m=1, k="leatherworking", r=e.lua.table_from({2318: 4}))     # Medium Leather: 4 light
        plan = e.lua.eval("function(raw, total, made, via, need) return { raw = raw, total = total, made = made, via = via, need = need } end")(
            *LV.Breakdown(e.lua.table_from({2319: 10})), e.lua.table_from({2319: 10}))
        wanted = LV.Wanted(plan)
        self.assertEqual(len(wanted), 1)
        g = wanted[1]
        self.assertEqual(g.id, 2319)                                  # Medium Leather is what is wanted,
        self.assertEqual(g.more, 10)
        self.assertEqual(g.route[1].id, 2934)                         # the scraps the way to get it
        self.assertEqual(g.route[1].n, 120)
        self.assertFalse(g.buy)
        e.lua.execute("ns_prices = { [2319] = 30, [2934] = 5 }")      # a scrap 5c, 120 of them 600c: Medium Leather 30c each
        e.ns.Market.Auction = e.lua.eval("function(id) return ns_prices[id] end")
        g = LV.Wanted(plan)[1]
        self.assertTrue(g.buy)                                        # 300c to buy against 600c to make: buy it
        self.assertEqual(e.errors(), [])

    def test_what_it_takes_goes_down_to_the_ore(self):
        e = self.env(open=False)
        LV, T = e.ns.Levelling, e.lua.table
        e.db.skillMakes[2841] = T(m=2, k="mining", r=e.lua.table_from({2840: 1, 3576: 1}))   # Bronze: copper and tin
        e.db.skillMakes[2840] = T(m=1, k="mining", r=e.lua.table_from({2770: 1}))
        e.db.skillMakes[3576] = T(m=1, k="mining", r=e.lua.table_from({2771: 1}))
        e.mock.put(0, 1, T(id=2841, name="Bronze Bar", count=4))
        e.mock.put(0, 2, T(id=2840, name="Copper Bar", count=3))
        raw, total, made, via = LV.Breakdown(e.lua.table_from({2841: 20}))
        self.assertEqual(dict(raw), {2770: 5, 2771: 8})              # 16 bars to make: 8 of copper, 8 of tin,
        self.assertEqual((made[2841], made[2840], made[3576]), (16, 5, 8))   # less the 3 copper bars you hold
        self.assertEqual(LV.Chain(T(via=via), 2770), "Copper Bar > Bronze Bar")
        e.db.inventory["Sol-Forever"] = T(bags=e.lua.table_from({2770: 5}), bank=T())       # an alt holds the ore
        raw, total, made, via = LV.Breakdown(e.lua.table_from({2841: 20}))
        self.assertIsNone(raw[2770])
        self.assertEqual(total[2770], 5)
        e.db.skillMakes = T()                                        # read before: from what each reagent makes
        e.db.inventory["Ghostlight-Forever"].prof = T(mining=T(name="Mining", rank=60, cap=75, at=1,
            crafts=e.lua.table_from({2772: e.lua.table_from([T(p=3575, n=1, m=1)])})))
        self.assertEqual(LV.MadeOf(3575).r[2772], 1)
        self.assertEqual(e.errors(), [])

    def test_the_controller_puts_the_plan_on_the_farm_list(self):
        e = self.env()
        e.mock.put(0, 1, e.lua.table(id=2447, name="Peacebloom", count=4))
        e.mock.fire("BAG_UPDATE_DELAYED")
        e.update(0.5)
        LV, ov = e.ns.Levelling, e.mock.overrides
        self.assertEqual(ov.PADLSTICK, "CLICK ControllerCamHUD_Key_PlanKey_PADLSTICK:LeftButton")
        self.assertIsNone(ov.PADDUP)                                  # the window's own buttons stay the game's
        e.g.ControllerCamHUD_Key_PlanKey_PADLSTICK.scripts.OnClick()
        self.assertEqual(ov.PADDUP, "CLICK ControllerCamHUD_Key_Plan_PADDUP:LeftButton")
        LV.plan = LV.Plan(LV.read)                                   # (made again now the bags are counted)
        LV.Refresh(LV)
        self.assertEqual(LV.plan.raw[2447], 7)                       # 11 used, 4 held
        e.g.ControllerCamHUD_Key_Plan_PAD3.scripts.OnClick()         # X: everything missing to the farm list
        self.assertEqual([(x.id, x.need) for x in e.db.farm.values()], [(2447, 11)])
        e.g.ControllerCamHUD_Key_Plan_PADDDOWN.scripts.OnClick()     # (past the heading) to the peacebloom
        self.assertIn("Peacebloom: at most 11 to reach 60. You have 4, so 7 more at most.",
                      plain(e.g.ControllerCamHUD_SkillPlanPanel.detail.text))
        e.g.ControllerCamHUD_Key_Plan_PAD2.scripts.OnClick()         # B: the buttons back
        self.assertIsNone(ov.PADDUP)
        self.assertEqual(ov.PADLSTICK, "CLICK ControllerCamHUD_Key_PlanKey_PADLSTICK:LeftButton")
        e.window.shown = False
        e.mock.fire("TRADE_SKILL_CLOSE")
        e.update(0.5)
        self.assertFalse(e.g.ControllerCamHUD_SkillPlanPanel.shown)
        self.assertIsNone(ov.PADLSTICK)
        e.cmd("levelplan")                                           # away from the window: in the middle
        self.assertTrue(e.g.ControllerCamHUD_SkillPlanPanel.shown)
        self.assertEqual(ov.PADDUP, "CLICK ControllerCamHUD_Key_Plan_PADDUP:LeftButton")
        e.update(1)
        self.assertTrue(e.g.ControllerCamHUD_SkillPlanPanel.shown)
        e.cmd("levelplan")
        self.assertFalse(e.g.ControllerCamHUD_SkillPlanPanel.shown)
        self.assertIsNone(ov.PADDUP)
        self.assertEqual(e.errors(), [])

    def test_at_the_cap_or_switched_off(self):
        e = self.env(open=False)
        e.lua.execute("TRADE = { 'Alchemy', 60, 60 }")
        self.open(e)
        self.assertTrue(e.ns.Levelling.plan.capped)
        self.assertIn("trainer", e.g.ControllerCamHUD_SkillPlanPanel.sub.text)
        e.cmd("levelhelp off")
        self.assertFalse(e.g.ControllerCamHUD_SkillPlanPanel.shown)
        self.assertEqual(e.ns.RunCheck(False)[0], 0)
        self.assertEqual(e.errors(), [])


class Mentor(unittest.TestCase):
    """The Mentor: the levelling plan's own voice, laid out line under line, clear of the window's tabs."""

    def env(self, **kw):
        return Levelling().env(**kw)

    def test_the_mentor_names_the_plan_in_a_few_plain_words(self):
        e = self.env()
        LV = e.ns.Levelling
        panel = e.g.ControllerCamHUD_SkillPlanPanel
        self.assertEqual(plain(panel.title.text), "The Mentor: Alchemy 50 > 60")
        said = set()
        for voice in range(3):
            LV.voice = voice
            LV.Refresh(LV)
            said.add(plain(panel.sub.text))
        self.assertEqual(len(said), 3)                               # three ways of putting it
        for line in said:
            self.assertIn("Minor Healing Potion", line)              # the recipe to start with
        self.assertIn("10 more to 60. Start with Minor Healing Potion.", said)
        e.ns.Professions = None                                      # (the words need nothing else)
        T = e.lua.table
        plan = T(rank=225, target=225, cap=225, capped=True, steps=T())
        LV.voice = 0
        self.assertEqual(LV.Words(plan), "That's the cap, 225. A trainer has the next rank for you.")
        plan = T(rank=192, target=225, cap=225, short=33, steps=T(), next="Smelt Mithril", nextAt=175)
        self.assertEqual(LV.Words(plan), "You've outgrown your recipes. See a trainer: Smelt Mithril is waiting at 175.")
        LV.voice = 1
        self.assertEqual(LV.Words(plan), "33 more to 225, and what you know won't take you there. "
                                         "A trainer has Smelt Mithril for you at 175.")
        plan.nextAt = None
        self.assertEqual(LV.Words(plan), "Your recipes stop teaching you 33 short of 225. Ask a trainer for Smelt Mithril.")
        plan.next = None
        self.assertEqual(LV.Words(plan), "What you know won't carry you the last 33. Time to see a trainer.")
        step = T(rec=T(n="Smelt Iron"), colour=1)
        plan = T(rank=192, target=225, cap=225, steps=e.lua.table_from([step]))
        LV.voice = 0
        self.assertEqual(LV.Words(plan), "Smelt Iron won't teach you much now, but it's the best you have. 33 more to 225.")
        self.assertEqual(LV.Words(None), "Open a profession's window and I'll look over your recipes.")
        self.assertEqual(e.errors(), [])

    def test_each_line_has_its_own_place(self):
        e = self.env()
        LV = e.ns.Levelling
        panel = e.g.ControllerCamHUD_SkillPlanPanel
        for words, rows in ((None, None), ("x " * 120, None)):      # one line, then words wrapping over several
            if words:
                LV.Words = e.lua.eval("function(w) return function() return w end end")(words)
                LV.Refresh(LV)
            lay = LV.layout
            sub = LV.TextHeight(panel.sub, 9)
            self.assertGreaterEqual(lay.top, 8 + 14 + 4 + sub + 8)  # the rows start under the words, however long
            first = LV.rows[1].points[1]
            self.assertEqual(first[5], -lay.top)
            self.assertGreaterEqual(panel.height, lay.top + lay.rows * 20 + 24)   # and the buttons' line under them
        self.assertGreater(LV.TextHeight(panel.sub, 9), 24)          # (the long one took several lines)
        e.lua.execute("TRADE = { 'Alchemy', 60, 60 }")              # at the cap: no rows, words and buttons apart
        e.mock.fire("TRADE_SKILL_UPDATE")
        e.update(0.5)
        self.assertTrue(LV.plan.capped)
        self.assertEqual(LV.layout.rows, 0)
        self.assertGreaterEqual(panel.height, LV.layout.top + 24)
        self.assertEqual(e.errors(), [])

    def test_the_next_recipe_comes_from_your_other_characters(self):
        e = self.env()
        LV, T = e.ns.Levelling, e.lua.table
        steps = e.db.skillSteps.alchemy
        steps["Healing Potion"] = T(o=55)                            # seen with another character from 55
        steps["Swiftness Potion"] = T(o=58)
        steps["Ancient Brew"] = T(o=5, xh=40, xl=35)                 # grey for you by now
        steps["Strong Troll's Blood"] = T(o=90)                      # past this rank's cap
        steps["Lesser Healing Potion"] = T(o=20)
        e.db.skillKnown["Ghostlight-Forever"].alchemy["Lesser Healing Potion"] = True   # you know it (a search hid it)
        self.assertTrue(e.db.skillKnown["Ghostlight-Forever"].alchemy["Minor Healing Potion"])
        name, at = LV.NextRecipe(LV.read)
        self.assertEqual((name, at), ("Healing Potion", 55))
        e.mock.fire("TRADE_SKILL_UPDATE")                            # the plan made again carries it
        e.update(0.5)
        self.assertEqual((LV.plan["next"], LV.plan.nextAt), ("Healing Potion", 55))
        LV.read.missing = e.lua.table_from(["Elixir of Wisdom"])     # the newer window lists one not learned yet
        steps["Healing Potion"] = None
        steps["Swiftness Potion"] = None
        self.assertEqual(tuple(LV.NextRecipe(LV.read)), ("Elixir of Wisdom", None))
        again = Env(db=e.mock.serialize(e.g.ControllerCamHUDDB))    # kept across a reload
        self.assertTrue(again.db.skillKnown["Ghostlight-Forever"].alchemy["Lesser Healing Potion"])
        self.assertEqual(again.db.skillSteps.alchemy["Minor Healing Potion"].o, 50)
        self.assertEqual(e.errors(), [])

    def test_the_panel_sits_clear_of_the_windows_tabs(self):
        e = self.env()
        LV = e.ns.Levelling
        panel = e.g.ControllerCamHUD_SkillPlanPanel
        e.lua.execute("""
            TAB = CreateFrame("Button", nil, TradeSkillFrame)
            TAB.GetRight = function() return 540 end
            FAR = CreateFrame("Frame", nil, TradeSkillFrame)
            FAR.GetRight = function() return 1400 end                -- (not a tab: much too far out)
            TradeSkillFrame.GetRight = function() return 500 end
            TradeSkillFrame.GetLeft = function() return 100 end
            TradeSkillFrame.GetChildren = function() return TAB, FAR end
            UIParent.GetRight = function() return 1920 end
        """)
        LV.Place(LV)
        p = panel.points[1]
        self.assertEqual((p[1], p[3], p[4], p[5]), ("TOPLEFT", "TOPRIGHT", 46, 0))   # past the tabs
        self.assertTrue(e.same(p[2], e.window))
        e.lua.execute("UIParent.GetRight = function() return 800 end; TradeSkillFrame.GetLeft = function() return 400 end")
        LV.Place(LV)
        p = panel.points[1]
        self.assertEqual((p[1], p[3], p[4]), ("TOPRIGHT", "TOPLEFT", -6))             # no room: on the left
        e.lua.execute("TradeSkillFrame.GetLeft = function() return 50 end")
        LV.Place(LV)
        p = panel.points[1]
        self.assertEqual((p[1], p[3], p[4], p[5]), ("TOPLEFT", "BOTTOMLEFT", 0, -6))  # nor there: under it
        self.assertEqual(len(e.window.points), 0)                     # nothing done to the game's window
        self.assertEqual(e.errors(), [])


class MentorGuides(unittest.TestCase):
    """The Mentor follows the levelling guides, offers their alternatives, and shows what the bank can make."""

    GUIDE = """
        ns.LevelGuides = { alchemy = {
            { 1, 55, p = 118, n = 60, r = { 2447, 1 }, name = "Minor Healing Potion",
              alts = { { p = 3382, n = 30, r = { 765, 2 }, why = { "cheap" } } } },
            { 55, 60, p = 2455, n = 10, at = 25, r = { 785, 1, 2447, 1 }, name = "Minor Mana Potion",
              alts = { { p = 2454, n = 8, r = { 2449, 1, 765, 1 }, why = { "useful" } } } },
        } }
    """

    def env(self, guide=None, **kw):
        e = Levelling().env(open=False, **kw)
        e.lua.eval("function(ns, code) setfenv(loadstring(code), setmetatable({ ns = ns }, { __index = _G }))() end")(
            e.ns, guide or self.GUIDE)
        Levelling().open(e)
        return e

    def test_a_stretch_no_guide_covers_is_filled_with_your_own_recipes(self):
        # (this game moved the healing potions to First Aid: Alchemy's guide starts at 140, and your 50 is not it)
        e = self.env(guide="""ns.LevelGuides = { alchemy = {
            { 140, 155, p = 3385, n = 15, at = 120, r = { 785, 1 }, name = "Lesser Mana Potion" } } }""")
        LV = e.ns.Levelling
        plan = LV.plan
        steps = list(plan.steps.values())
        self.assertTrue(steps)
        self.assertEqual(steps[0]["from"], 50)                       # from where you are,
        self.assertTrue(steps[0].filled and steps[0].known)          # with a recipe of yours,
        self.assertNotEqual(steps[0].rec.p, 3385)                    # not the guide's far-off one
        self.assertNotIn("Lesser Mana Potion", [s.rec.n for s in steps])
        LV.voice = 0
        self.assertNotIn("guides", LV.Words(plan))
        self.assertEqual(e.errors(), [])

    def test_alchemy_asks_for_no_healing_potions(self):
        e = Env()
        guide = e.ns.LevelGuides and e.ns.LevelGuides.alchemy
        if guide is None:                                            # (The Mentor loaded)
            e = Levelling().env()
            guide = e.ns.LevelGuides.alchemy
        healing = {118, 858, 929, 1710, 3928, 13446}                 # First Aid's, in this game
        made = set()
        for step in guide.values():
            made.add(step.p)
            made.update(a.p for a in (step.alts.values() if step.alts else []))
        self.assertFalse(healing & made, healing & made)

    def test_the_plan_follows_the_guide_and_offers_its_alternatives(self):
        e = self.env()
        LV = e.ns.Levelling
        plan = LV.plan
        self.assertTrue(plan.guide)
        self.assertEqual(len(plan.steps), 2)
        one, two = plan.steps[1], plan.steps[2]
        self.assertEqual((one.rec.n, one["from"], one.to, one.crafts), ("Minor Healing Potion", 50, 55, 5))
        self.assertEqual(one.alts[1].rec.n, "Weak Troll Blood")      # the guide's other, which you know too
        self.assertTrue(one.alts[1].known)
        self.assertEqual((two.rec.n, two["from"], two.to), ("Elixir of Strength", 55, 60))   # the one you know
        self.assertGreater(two.crafts, 5)                            # (yellow: not a point every time)
        self.assertIsNone(two.learn)
        first = two.alts[1]                                          # the guide's own first choice, still to learn
        self.assertEqual((first.rec.n, first.known, first.learn.at), ("Minor Mana Potion", False, 25))
        self.assertEqual(LV.Why(first.why), "the guides' first choice")
        self.assertEqual(plan.need[2447], 5)                         # only the chosen recipes count
        LV.voice = 0
        self.assertEqual(LV.Words(plan), "10 more to 60. Start with Minor Healing Potion, or Weak Troll Blood if "
                                         "you'd rather: cheaper materials.")
        LV.Refresh(LV)
        texts = [plain(LV.rows[i].text.text) for i in range(1, 6)]
        self.assertIn("Minor Healing Potion  up to x5", texts[0])
        self.assertIn("or Weak Troll Blood  cheaper materials", texts[1])
        self.assertEqual(plain(LV.rows[2].right.text), "x5")             # never fewer than a craft a point
        self.assertIn("Elixir of Strength", texts[2])
        self.assertIn("Minor Mana Potion  the guides' first choice", texts[3])   # one you don't have: its mark
        self.assertIn("ActiveQuestIcon", texts[3])                    # (learnable now: "?"), and where
        self.assertIn("Learn it at a trainer, at 25.", texts[3])
        self.assertEqual(texts[4], "Still needed to reach 60, at most:")
        LV.Focus(LV, True)
        LV.Choose(LV, 4)
        self.assertIn("Learn it at a trainer, at 25.", plain(e.g.ControllerCamHUD_SkillPlanPanel.detail.text))
        self.assertEqual(e.errors(), [])

    def test_a_recipe_still_to_learn_and_a_stretch_of_gathering(self):
        e = self.env("""
            ns.LevelGuides = { alchemy = {
                { 1, 55, p = 2455, n = 60, learn = "vendor", at = 40, r = { 785, 1 }, name = "Minor Mana Potion" },
                { 55, 300, gather = 2447 },
            } }
        """)
        LV = e.ns.Levelling
        plan = LV.plan
        one, two = plan.steps[1], plan.steps[2]
        self.assertEqual((one.rec.n, one.crafts, one.learn.how), ("Minor Mana Potion", 6, "vendor"))   # 60 over 54 points, 5 of them
        self.assertEqual((two.gather, two["from"], two.to), (2447, 55, 60))
        LV.voice = 0
        self.assertEqual(LV.Words(plan), "First you'll want Minor Mana Potion, from a vendor. "
                                         "The guides start this stretch with it.")
        LV.Refresh(LV)
        self.assertIn("Learn it from a vendor, at 40.", plain(LV.rows[1].text.text))
        self.assertEqual(plain(LV.rows[2].text.text), "Gather Peacebloom")
        plan.steps = e.lua.table_from([two])
        self.assertEqual(LV.Words(plan), "10 more to 60. The guides send you out for Peacebloom until 60.")
        self.assertEqual(e.errors(), [])

    def test_no_guide_keeps_the_cheapest_point_by_point(self):
        e = self.env("ns.LevelGuides = {}")
        plan = e.ns.Levelling.plan
        self.assertFalse(plan.guide)
        self.assertEqual(plan.steps[1].rec.n, "Minor Healing Potion")
        self.assertEqual(e.errors(), [])

    def test_what_the_bank_can_make(self):
        e = self.env()
        LV, T = e.ns.Levelling, e.lua.table
        e.mock.put(0, 1, T(id=2447, name="Peacebloom", count=3))
        e.db.inventory["Ghostlight-Forever"].bank = e.lua.table_from({2447: 10, 765: 4})
        e.db.skillKnown["Ghostlight-Forever"].alchemy["Rage Potion"] = 5631        # known, hidden by a filter now
        e.db.skillMakes[5631] = T(m=1, r=e.lua.table_from({765: 1}))
        e.mock.fire("BAG_UPDATE_DELAYED")
        e.update(0.5)
        LV.Focus(LV, True)
        e.g.ControllerCamHUD_Key_Plan_PAD4.scripts.OnClick()        # Y: what the bank can make
        self.assertEqual(LV.mode, "bank")
        panel = e.g.ControllerCamHUD_SkillPlanPanel
        self.assertEqual(plain(panel.title.text), "The Mentor: what your bank can make")
        names = [e_.make.n for e_ in LV.entries.values()]
        self.assertEqual(names, ["Minor Healing Potion", "Old Remedy", "Rage Potion", "Weak Troll Blood"])
        self.assertEqual(plain(panel.sub.text), "4 you can make counting your bank, 4 of them only with it.")
        self.assertEqual(plain(LV.rows[1].right.text), "3 [13]")
        self.assertIn("Peacebloom: 3 in your bags, 10 in the bank, 1 each", plain(panel.detail.text))
        self.assertIn("The plan", plain(panel.hint.text))
        e.g.ControllerCamHUD_Key_Plan_PAD1.scripts.OnClick()        # (A does nothing here)
        self.assertEqual(len(e.db.farm), 0)
        panel.mode.scripts.OnClick(panel.mode)                       # the button back to the plan
        self.assertEqual(LV.mode, "plan")
        self.assertIn("The Mentor: Alchemy", plain(panel.title.text))
        self.assertEqual(e.errors(), [])

    def test_trying_a_recipe_on(self):
        e = self.env()
        LV = e.ns.Levelling
        panel = e.g.ControllerCamHUD_SkillPlanPanel
        e.lua.execute("""
            DRESSED = nil
            C_Item = C_Item or {}
            C_Item.IsDressableItemByID = function(id) return id == 2454 or id == 3382 end
            DressUpItemLink = function(link) DRESSED = link end
            SELECTED = 3
            GetTradeSkillSelectionIndex = function() return SELECTED end
        """)
        LV.Focus(LV, True)
        self.assertIn("Try on", plain(panel.hint.text))              # the window's chosen recipe (index 3) is wearable
        e.g.ControllerCamHUD_Key_Plan_PADRSHOULDER.scripts.OnClick()
        self.assertEqual(e.g.DRESSED, "|Hitem:2454|h[x]|h")          # in the game's dressing room
        e.lua.execute("SELECTED = 2")                                # a potion: nothing to wear
        LV.Choose(LV, 1)
        self.assertNotIn("Try on", plain(panel.hint.text))
        before = len(e.mock.printed)
        e.g.ControllerCamHUD_Key_Plan_PADRSHOULDER.scripts.OnClick()
        self.assertIn("Nothing here to try on.", "\n".join(said(e, before)))
        LV.Choose(LV, 2)                                             # the row of Weak Troll Blood (made wearable here)
        e.g.ControllerCamHUD_Key_Plan_PADRSHOULDER.scripts.OnClick()
        self.assertIn("3382", e.g.DRESSED)
        self.assertEqual(e.errors(), [])

    def test_l3_puts_the_panel_away_and_brings_it_back(self):
        e = self.env()
        LV = e.ns.Levelling
        panel, tab = e.g.ControllerCamHUD_SkillPlanPanel, e.g.ControllerCamHUD_SkillPlanTab
        self.assertIn("twice to hide", plain(panel.hint.text))
        e.g.ControllerCamHUD_Key_PlanKey_PADLSTICK.scripts.OnClick()      # L3: the plan's buttons
        self.assertTrue(LV.focus)
        self.assertIn("Hide", plain(panel.hint.text))
        e.g.ControllerCamHUD_Key_Plan_PADLSTICK.scripts.OnClick()         # L3 again: put away
        self.assertFalse(panel.shown)
        self.assertTrue(tab.shown)                                    # its tab says how to bring it back
        self.assertIn("The Mentor", plain(tab.text.text))
        self.assertTrue(e.same(tab.points[1][2], e.window))
        self.assertTrue(e.db.skillPlanHidden)
        e.g.TradeSkillFrame.shown = False                             # the window closes, and opens again later
        e.mock.fire("TRADE_SKILL_CLOSE")
        e.update(1)
        self.assertFalse(tab.shown)
        again = Env(db=e.mock.serialize(e.g.ControllerCamHUDDB))     # remembered across a reload
        self.assertTrue(again.db.skillPlanHidden)
        e.g.TradeSkillFrame.shown = True
        e.mock.fire("TRADE_SKILL_SHOW")
        e.update(0.5)
        self.assertFalse(panel.shown)
        self.assertTrue(tab.shown)
        e.g.ControllerCamHUD_Key_PlanKey_PADLSTICK.scripts.OnClick()      # L3: back
        self.assertTrue(panel.shown)
        self.assertFalse(tab.shown)
        self.assertFalse(e.db.skillPlanHidden)
        panel.close.scripts.OnClick(panel.close)                      # (or with a mouse: its x)
        self.assertFalse(panel.shown)
        tab.scripts.OnClick(tab)
        self.assertTrue(panel.shown)
        self.assertEqual(e.errors(), [])

    def test_the_guides_cover_every_profession_to_300(self):
        import subprocess
        import sys
        maker = os.path.join(ROOT, "docs", "levelling", "make_guides.py")
        run = subprocess.run([sys.executable, maker, "--check"], capture_output=True, text=True)
        self.assertEqual(run.returncode, 0, run.stdout)              # no gaps, no recipe without an ID
        e = Env()
        guides = e.ns.LevelGuides
        for kind in ("alchemy", "blacksmithing", "enchanting", "engineering", "leatherworking", "tailoring",
                     "cooking", "firstaid", "mining"):
            steps = list(guides[kind].values())
            if kind != "alchemy":                                     # (its healing potions are First Aid's here:
                self.assertEqual(steps[0][1], 1, kind)                #  those stretches are left out, on purpose,
                self.assertEqual(steps[-1][2], 300, kind)             #  and make_guides.py knows which)
                for a, b in zip(steps, steps[1:]):
                    self.assertEqual(a[2], b[1], kind)                # each stretch starts where the last ends
            for st in steps:
                self.assertTrue(st.gather or st.p or st.s, kind)
                for alt in (st.alts.values() if st.alts else []):
                    self.assertTrue(alt.gather or alt.p or alt.s, kind)
        self.assertTrue(guides.enchanting[1].s)                       # (an enchant is matched by its spell)

    def test_mining_goes_by_the_veins(self):
        e = self.env("ns.LevelGuides = { alchemy = { { 1, 300, gather = 2447, alts = { { gather = 765 },"
                     " { p = 118, n = 300, r = { 2447, 1 }, why = { 'gathered' } } } } } }")
        LV = e.ns.Levelling
        step = LV.plan.steps[1]
        self.assertEqual((step.gather, step.alts[1].gather, step.alts[2].rec.n), (2447, 765, "Minor Healing Potion"))
        self.assertEqual(step.alts[2].crafts, 11)                     # 300 over 299 points, 10 of them
        LV.Refresh(LV)
        self.assertEqual(plain(LV.rows[1].text.text), "Gather Peacebloom")
        self.assertEqual(plain(LV.rows[2].text.text), "or Gather Silverleaf")
        self.assertIn("or Minor Healing Potion  materials you gather yourself", plain(LV.rows[3].text.text))
        self.assertEqual(e.errors(), [])

    def test_the_title_takes_the_lines_it_needs(self):
        e = self.env()
        LV = e.ns.Levelling
        panel = e.g.ControllerCamHUD_SkillPlanPanel
        small = LV.layout.top
        e.db.textScale = 2.4                                         # big text: the title wraps
        LV.read.name = "Alchemy of the Long Name"
        LV.plan.name = LV.read.name
        LV.Refresh(LV)
        title = LV.TextHeight(panel.title, 12)
        self.assertGreater(title, 14)
        self.assertGreaterEqual(LV.layout.top, 8 + title + 4 + LV.TextHeight(panel.sub, 9) + 8)
        self.assertGreater(LV.layout.top, small)
        self.assertEqual(LV.rows[1].points[1][5], -LV.layout.top)
        self.assertEqual(e.errors(), [])


class FarmList(unittest.TestCase):
    """Things to farm, beside the quest list."""

    def env(self, **kw):
        e = Env(**kw)
        T = e.lua.table
        for id, name in ((2447, "Peacebloom"), (765, "Silverleaf")):
            e.mock["items"][id] = T(name=name, stack=20, **{"class": 7})
        return e

    def shown(self, e, name):
        return bool(e.g[name] and e.g[name].shown)

    def test_have_and_need_beside_the_quests_on_the_side_chosen(self):
        e = self.env()
        F, T = e.ns.Farm, e.lua.table
        self.assertFalse(self.shown(e, "ControllerCamHUD_FarmList"))   # empty: nothing
        e.mock.put(0, 1, T(id=2447, name="Peacebloom", count=4))
        e.db.inventory["Sol-Forever"] = T(bags=e.lua.table_from({2447: 6}), bank=T())     # an alt's count too
        e.db.inventory["Far-Elsewhere"] = T(bags=e.lua.table_from({2447: 50}), bank=T())  # (not on this realm)
        e.cmd("farm add 2447 20")
        e.cmd("farm add item:765")
        frame = e.g.ControllerCamHUD_FarmList
        self.assertTrue(frame.shown)
        self.assertEqual((plain(F.rows[1].name.text), F.rows[1].have.text), ("Peacebloom", "10/20"))
        self.assertEqual(F.rows[2].have.text, "0/20")                 # a stack, without a number
        tracker = e.g.ObjectiveTrackerFrame
        p = frame.points[1]
        self.assertEqual((p[1], p[3], p[4]), ("TOPRIGHT", "TOPLEFT", -10))      # to the left by default
        self.assertTrue(e.same(p[2], tracker))
        e.cmd("farm right")
        p = frame.points[1]
        self.assertEqual((p[1], p[3], p[4]), ("TOPLEFT", "TOPRIGHT", 10))
        e.cmd("farm bottom")
        self.assertEqual(frame.points[1][3], "BOTTOMLEFT")           # where the lines end cannot be told: its foot
        line = e.g.CreateFrame("Frame", None, tracker)
        e.lua.eval("function(t, l) t.GetTop = function() return 700 end; l.GetBottom = function() return 560 end end")(
            tracker, line)
        e.update(1)
        p = frame.points[1]
        self.assertEqual((p[1], p[3], p[5]), ("TOPLEFT", "TOPLEFT", -150))      # just under the last quest line
        e.mock.put(0, 2, T(id=765, name="Silverleaf", count=20))
        e.mock.fire("BAG_UPDATE_DELAYED")
        e.update(1)
        self.assertEqual((plain(F.rows[2].name.text), F.rows[2].have.text), ("Silverleaf", "20/20"))   # done: last
        self.assertIn("2 things", F.Describe())
        again = Env(db=e.mock.serialize(e.g.ControllerCamHUDDB))
        self.assertEqual(len(again.db.farm), 2)
        self.assertEqual(again.db.farmSide, 3)
        self.assertEqual(e.ns.RunCheck(False)[0], 0)
        self.assertEqual(e.errors(), [])

    def test_the_controller_chooses_raises_removes_and_clears(self):
        e = self.env()
        F, ov = e.ns.Farm, e.mock.overrides
        F.Add(2447, 5, True)
        F.Add(765, 5, True)
        self.assertIsNone(ov.PADDUP)                                  # only while it is chosen
        e.g.ControllerCamHUD_Farm()
        self.assertEqual(ov.PADDUP, "CLICK ControllerCamHUD_Key_Farm_PADDUP:LeftButton")
        e.g.ControllerCamHUD_Key_Farm_PAD1.scripts.OnClick()         # A: a stack more
        self.assertEqual(e.db.farm[1].need, 25)
        e.g.ControllerCamHUD_Key_Farm_PADDDOWN.scripts.OnClick()
        e.g.ControllerCamHUD_Key_Farm_PAD3.scripts.OnClick()         # X: off the list
        self.assertEqual([x.id for x in e.db.farm.values()], [2447])
        popups = len(e.gamePopups)
        e.g.ControllerCamHUD_Key_Farm_PAD4.scripts.OnClick()         # Y: asked first, in a window of ours
        self.assertEqual(e.ns.Dialog.visible.which, "CCHUD_FARM_CLEAR")
        self.assertEqual(len(e.gamePopups), popups)                   # never the game's dialog box
        e.mock.answer("accept")
        self.assertEqual(len(e.db.farm), 0)
        self.assertEqual(ov.PADDUP, "CLICK ControllerCamHUD_Key_Farm_PADDUP:LeftButton")   # still choosing
        e.g.ControllerCamHUD_Key_Farm_PAD2.scripts.OnClick()
        self.assertIsNone(ov.PADDUP)
        self.assertFalse(e.g.ControllerCamHUD_FarmList.shown)        # empty again: gone
        F.Add(2447, 5, True)
        e.g.ControllerCamHUD_Farm()
        e.mock.state.combat = True
        e.mock.fire("PLAYER_REGEN_DISABLED")                         # a fight gives the buttons back at once
        self.assertIsNone(ov.PADDUP)
        self.assertFalse(F.managing)
        self.assertEqual(e.errors(), [])

    def test_the_option_has_three_places(self):
        e = self.env()
        e.ns.BuildOptions()
        row = [r for r in e.ns.optionRows.values() if r["def"].key == "farmSide"][0]
        self.assertEqual(len(row.buttons), 3)
        self.assertEqual(row.page, "Quests and map")
        row.buttons[2].scripts.OnClick()
        self.assertEqual(e.db.farmSide, 2)
        self.assertTrue(row.buttons[2].chosen)                       # the chosen one stands out,
        self.assertEqual(row.buttons[2].alpha, 1)
        self.assertFalse(row.buttons[1].chosen)                      # the others are dimmed
        self.assertLess(row.buttons[1].alpha, 1)
        self.assertEqual(e.errors(), [])

    def test_only_in_the_gamepad_ui_and_gone_when_off(self):
        db = "{ v = 12, farm = { { id = 2447, need = 5 } } }"
        e = self.env(db=db, style="0")
        self.assertFalse(self.shown(e, "ControllerCamHUD_FarmList"))
        e = self.env(db=db)
        self.assertTrue(e.g.ControllerCamHUD_FarmList.shown)
        e.cmd("farmlist off")
        self.assertFalse(e.g.ControllerCamHUD_FarmList.shown)
        e.cmd("farmlist on")
        e.cmd("off")
        self.assertFalse(e.g.ControllerCamHUD_FarmList.shown)
        self.assertEqual(e.errors(), [])

    def test_every_combination_of_its_switches(self):
        b = lambda v: "true" if v else "false"
        for style in ("0", "1"):
            for plan in (True, False):
                for farm in (True, False):
                    db = "{ v = 12, skillPlan = %s, farmList = %s, farm = { { id = 2447, need = 5 } } }" % (b(plan), b(farm))
                    e = Levelling().env(db=db, style=style)
                    label = "style %s plan %s farm %s" % (style, plan, farm)
                    run = style == "1"
                    self.assertEqual(self.shown(e, "ControllerCamHUD_SkillPlanPanel"), run and plan, label)
                    self.assertEqual(self.shown(e, "ControllerCamHUD_FarmList"), run and farm, label)
                    failed, rows = e.ns.RunCheck(False)
                    self.assertEqual(failed, 0, "%s: %s" % (label, [r.name for r in rows.values() if not r.ok]))
                    e.cmd("off")
                    self.assertFalse(self.shown(e, "ControllerCamHUD_SkillPlanPanel"), label)
                    self.assertFalse(self.shown(e, "ControllerCamHUD_FarmList"), label)
                    self.assertIsNone(e.mock.overrides.PADLSTICK, label)
                    self.assertEqual(e.errors(), [], label)



def said(e, since):
    """What was printed to chat since `since` (a count of earlier prints), without colour codes."""
    return [plain(t) for t in list(e.mock.printed.values())[since:]]


class MailSubject(unittest.TestCase):
    """What you attach to a letter names it, unless you named it yourself."""

    def test_the_subject_follows_what_you_attach(self):
        e = Env()
        e.lua.execute("""
            SENDING = {}
            function GetSendMailItem(i) local a = SENDING[i]; if a then return a[1], 1, 0, a[2] end end
            SendMailSubjectEditBox = CreateFrame("EditBox", "SendMailSubjectEditBox", UIParent)
            SendMailSubjectEditBox.text = ""
        """)
        g = e.lua.globals()
        box = g.SendMailSubjectEditBox
        def attach(*items):
            for i in range(1, 13):
                g.SENDING[i] = None
            for i, (name, n) in enumerate(items, 1):
                g.SENDING[i] = e.lua.table(name, n)
            e.mock.fire("MAIL_SEND_INFO_UPDATE")
        attach(("Linen Cloth", 20))
        self.assertEqual(box.text, "Linen Cloth x20")
        attach(("Linen Cloth", 20), ("Wool Cloth", 5))
        self.assertEqual(box.text, "Linen Cloth x20, Wool Cloth x5")
        attach(("Linen Cloth", 20), ("Wool Cloth", 5), ("Silk Cloth", 1), ("Linen Cloth", 20))
        self.assertEqual(box.text, "Linen Cloth x40 and 2 more")
        attach()
        self.assertEqual(box.text, "")                                # taken off again: cleared
        box.text = "for the guild bank"                              # yours
        attach(("Copper Ore", 10))
        self.assertEqual(box.text, "for the guild bank")
        self.assertEqual(e.errors(), [])


class MailTakeAll(unittest.TestCase):
    """The mailbox emptied in one go: every letter, every page, past what the game will not hand over."""

    def env(self, free=5):
        def setup(env):
            env.lua.execute("ERR_ITEM_MAX_COUNT = ERR_ITEM_MAX_COUNT or 'You can not carry any more of those items.'")
            env.lua.eval("""function(mock, free)
                MAIL = {                       -- the letters the server holds, newest first
                    { sender = "Auction House", subject = "Auction successful: Silk Cloth", money = 5000 },
                    { sender = "Alt", subject = "mats", money = 100, items = { { name = "Iron Ore" },
                                                                             { name = "Ring", unique = true } } },
                    { sender = "Stranger", subject = "pay me", cod = 500, items = { { name = "Map" } } },
                    { sender = "Auction House", subject = "Auction successful: Iron Bar", money = 2000 },
                }
                SHOWN, TAKEN, ASKED = 3, {}, 0            -- the mailbox shows 3 of the 4 until asked again
                InboxFrame = CreateFrame("Frame", "InboxFrame", UIParent)
                OpenAllMail = CreateFrame("Button", "OpenAllMail", InboxFrame)
                C_Container.GetContainerNumFreeSlots = function(bag) return bag == 0 and free or 0 end
                local function Shown() return math.min(SHOWN, #MAIL) end
                function GetInboxNumItems() return Shown(), #MAIL end
                function GetInboxHeaderInfo(i)
                    local l = MAIL[i]
                    if not l then return nil end
                    local has = l.items and #l.items > 0 or false
                    return nil, nil, l.sender, l.subject, l.money or 0, l.cod or 0, 30, has
                end
                function GetInboxItem(i, a)
                    local l = MAIL[i]
                    local it = l and l.items and l.items[a]
                    return it and it.name
                end
                local function Empty(i)
                    local l = MAIL[i]
                    if (l.money or 0) == 0 and not (l.items and #l.items > 0) then table.remove(MAIL, i); SHOWN = SHOWN - 1 end
                end
                function TakeInboxMoney(i)
                    C_Timer.After(0.1, function()
                        mock.money = mock.money + MAIL[i].money
                        MAIL[i].money = 0
                        Empty(i)
                        mock.fire("MAIL_INBOX_UPDATE")
                    end)
                end
                function TakeInboxItem(i, a)
                    C_Timer.After(0.1, function()
                        local it = MAIL[i].items[a]
                        if it.unique then mock.fire("UI_ERROR_MESSAGE", 0, ERR_ITEM_MAX_COUNT); return end
                        TAKEN[#TAKEN + 1] = it.name
                        table.remove(MAIL[i].items, a)
                        Empty(i)
                        mock.fire("MAIL_INBOX_UPDATE")
                    end)
                end
                function CheckInbox() ASKED = ASKED + 1; SHOWN = 50 end
            end""")(env.mock, free)
        return Env(setup=setup)

    def test_every_letter_on_every_page_and_what_cannot_be_taken_stays(self):
        e = self.env()
        MB = e.ns.Mail
        e.mock.fire("MAIL_SHOW")
        self.assertTrue(MB.button.shown)                              # beside the game's own Open All
        self.assertEqual(MB.button.text, "Take everything")
        money0, since = e.mock.money, len(e.mock.printed)
        self.assertTrue(MB.Start(MB))
        e.update(20)
        self.assertEqual(e.mock.money - money0, 7100)                 # both sales, the one off the first page too
        self.assertEqual(list(e.g.TAKEN.values()), ["Iron Ore"])      # the ring you hold one of stays put
        self.assertGreaterEqual(e.g.ASKED, 1)                         # it asked for the letters not shown yet
        self.assertIsNone(MB.run)
        names = [e.g.MAIL[i].subject for i in range(1, len(e.g.MAIL) + 1)]
        self.assertEqual(names, ["mats", "pay me"])                   # C.O.D. never opened
        out = " ".join(said(e, since))
        self.assertIn("[Postmaster]", out)
        self.assertIn(" 71s and 1 item", out)                       # in his own words, whichever he picks
        self.assertIn("Letters wanting coin on delivery: 1", out)
        self.assertIn("1 I couldn't pass you", out)
        self.assertEqual(e.errors(), [])

    def test_full_bags_still_take_the_money_and_pressing_again_stops(self):
        e = self.env(free=0)
        MB = e.ns.Mail
        e.mock.fire("MAIL_SHOW")
        money0, since = e.mock.money, len(e.mock.printed)
        MB.Start(MB)
        e.update(20)
        self.assertEqual(e.mock.money - money0, 7100)
        self.assertEqual(len(e.g.TAKEN), 0)
        self.assertIn("Your bags are bursting", " ".join(said(e, since)))
        e2 = self.env()
        e2.mock.fire("MAIL_SHOW")
        M2 = e2.ns.Mail
        M2.Start(M2)
        self.assertFalse(M2.Start(M2))                                # again: stops
        self.assertIsNone(M2.run)
        e2.mock.fire("MAIL_CLOSED")
        self.assertIn("Find a mailbox first", e2.cmd("mail"))
        self.assertIsNotNone(e2.g.BINDING_NAME_CCHUD_TAKEMAIL)
        self.assertEqual(e.errors() + e2.errors(), [])


class QuestProgress(unittest.TestCase):
    """A short line in chat as a quest moves on."""

    def make(self, **kw):
        def setup(e):
            T = e.lua.table
            for i, row in enumerate([T(title="Duskwood", isHeader=True),
                                     T(title="Bloody Bones", questID=1, level=25),
                                     T(title="The Lost Camp", questID=2, level=24)], 1):
                e.mock.log[i] = row
            e.lua.eval("""function(mock)
                mock.objectives = {
                    [1] = { { text = "Bloody Bone Necklace: 3/25", type = "item", numFulfilled = 3, numRequired = 25 },
                            { text = "0/1 Morbent Fel slain", type = "monster" } },
                    [2] = { { text = "Find the lost camp", type = "event", finished = false } },
                }
                mock.ready = {}
                C_QuestLog.GetQuestObjectives = function(id) return mock.objectives[id] end
                C_QuestLog.ReadyForTurnIn = function(id) return mock.ready[id] or false end
            end""")(e.mock)
        return Env(setup=setup, **kw)

    def step(self, e, quest, index, **fields):
        o = e.mock.objectives[quest][index]
        for k, v in fields.items():
            o[k] = v
        n = len(e.mock.printed)
        e.mock.fire("QUEST_LOG_UPDATE")
        e.mock.advance(0.3)
        return said(e, n)

    def test_progress_objectives_done_and_ready(self):
        e = self.make()
        self.assertFalse(any(t.startswith("[Q]") for t in said(e, 0)))       # the log as it was: no news
        self.assertEqual(self.step(e, 1, 1, numFulfilled=4, text="Bloody Bone Necklace: 4/25"),
                         ["[Q] Bloody Bone Necklace: 4/25"])
        self.assertEqual(self.step(e, 1, 1, numFulfilled=4), [])             # nothing moved: nothing said
        self.assertEqual(self.step(e, 1, 1, numFulfilled=25, text="Bloody Bone Necklace: 25/25", finished=True),
                         ["[Q] Bloody Bone Necklace: 25/25  done"])
        self.assertEqual(self.step(e, 1, 2, text="1/1 Morbent Fel slain"),  # counted only in its words
                         ["[Q] Morbent Fel slain: done"])
        e.mock.ready[1] = True
        self.assertEqual(self.step(e, 1, 1), ["[Q] |Hquest:1:25|h[Bloody Bones]|h completed"])
        self.assertEqual(self.step(e, 2, 1, finished=True), ["[Q] Find the lost camp: done"])
        self.assertGreaterEqual(e.ns.Quests.told, 5)
        self.assertIn("progress in chat true", e.ns.Quests.Describe())
        self.assertEqual(e.errors(), [])

    def test_a_new_quest_and_a_secret_say_nothing(self):
        e = self.make()
        e.mock.log[4] = e.lua.table(title="Fresh Quest", questID=3, level=25)
        e.mock.objectives[3] = e.lua.eval('{ { text = "Thing: 5/10", numFulfilled = 5, numRequired = 10 } }')
        self.assertEqual(self.step(e, 1, 1), [])                             # taken just now: its count is no news
        self.assertEqual(self.step(e, 3, 1, numFulfilled=6, text="Thing: 6/10"), ["[Q] Thing: 6/10"])
        self.assertEqual(self.step(e, 1, 1, numFulfilled=e.mock.secret(), text=e.mock.secret()), [])
        e.mock.fire("QUEST_REMOVED", 3)                                      # handed in or abandoned: forgotten
        self.assertIsNone(e.ns.Quests.progress[3])
        self.assertEqual(e.errors(), [])

    def test_off_says_nothing(self):
        e = self.make()
        self.assertIn("off", e.cmd("questchat off"))
        self.assertEqual(self.step(e, 1, 1, numFulfilled=9, text="Bloody Bone Necklace: 9/25"), [])
        e.cmd("questchat on")                                                # back on: from what the log says now
        self.assertEqual(self.step(e, 1, 1), [])
        self.assertEqual(self.step(e, 1, 1, numFulfilled=10, text="Bloody Bone Necklace: 10/25"),
                         ["[Q] Bloody Bone Necklace: 10/25"])
        e.cmd("off")                                                         # the HUD off
        self.assertEqual(self.step(e, 1, 1, numFulfilled=11, text="Bloody Bone Necklace: 11/25"), [])
        plain_game = Env()                                                   # a game that has no objectives to give
        plain_game.mock.fire("QUEST_LOG_UPDATE")
        plain_game.mock.advance(0.5)
        self.assertEqual(plain_game.errors(), [])


    def party(self, e):
        e.lua.eval("""function(mock)
            mock.partySaid = {}
            SendChatMessage = function(text, kind) mock.partySaid[#mock.partySaid + 1] = kind .. ": " .. text end
        end""")(e.mock)
        e.mock.units.party1 = e.lua.table(name="Remy", health=500, healthMax=500, level=25)
        return e

    def test_in_a_party_only_a_finished_quest_goes_to_party_chat(self):
        e = self.party(self.make())
        self.assertEqual(self.step(e, 1, 1, numFulfilled=4, text="Bloody Bone Necklace: 4/25"),
                         ["[Q] Bloody Bone Necklace: 4/25"])                 # the steps stay yours
        self.assertEqual(list(e.mock.partySaid.values()), [])
        e.mock.objectives[1][1].numFulfilled = 25
        e.mock.objectives[1][1].text = "Bloody Bone Necklace: 25/25"
        e.mock.objectives[1][1].finished = True
        e.mock.ready[1] = True
        e.mock.fire("QUEST_LOG_UPDATE")
        e.mock.advance(0.3)
        self.assertEqual(list(e.mock.partySaid.values()), ["PARTY: [CCHUD] |cffffff00|Hquest:1:25|h[Bloody Bones]|h|r completed"])
        self.assertTrue(all("|" not in re.sub(r"\|c\w{8}\|H.*?\|h.*?\|h\|r", "", t) for t in e.mock.partySaid.values()))   # only the link
        self.assertIn("to party true (1 sent, in a party now true)", e.ns.Quests.Describe())
        e.mock.advance(1.5)
        e.cmd("questpartyall on")                                    # every step, when wanted
        self.assertEqual(self.step(e, 2, 1, finished=True), [])
        self.assertEqual(list(e.mock.partySaid.values())[1:], ["PARTY: [CCHUD] Find the lost camp: done"])
        self.assertEqual(e.errors(), [])

    def test_finishing_up_when_the_party_is_done_before_you(self):
        e = self.party(self.make())
        e.lua.eval("""function(mock)
            mock.addonSent = {}
            C_ChatInfo = C_ChatInfo or {}
            C_ChatInfo.RegisterAddonMessagePrefix = function() return true end
            C_ChatInfo.SendAddonMessage = function(prefix, text, kind) mock.addonSent[#mock.addonSent + 1] = prefix .. " " .. text .. " " .. kind end
        end""")(e.mock)
        e.mock.fire("CHAT_MSG_ADDON", "CCHUD", "done:1", "PARTY", "Remy-Forever")    # Remy has finished it
        e.mock.advance(0.2)
        self.assertEqual(list(e.mock.partySaid.values()), ["PARTY: [CCHUD] Finishing up |cffffff00|Hquest:1:25|h[Bloody Bones]|h|r."])
        e.mock.fire("CHAT_MSG_ADDON", "CCHUD", "done:1", "PARTY", "Kel-Forever")     # said once only
        e.mock.advance(1.5)
        self.assertEqual(len(list(e.mock.partySaid.values())), 1)
        e.mock.fire("CHAT_MSG_ADDON", "CCHUD", "done:99", "PARTY", "Remy-Forever")   # one you do not have: nothing
        e.mock.advance(1.5)
        self.assertEqual(len(list(e.mock.partySaid.values())), 1)
        e.mock.objectives[1][1].numFulfilled = 25
        e.mock.objectives[1][1].finished = True
        e.mock.ready[1] = True
        e.mock.fire("QUEST_LOG_UPDATE")
        e.mock.advance(0.3)
        self.assertIn("CCHUD done:1 PARTY", list(e.mock.addonSent.values()))         # yours finished: theirs are told
        self.assertEqual(e.errors(), [])

    def test_alone_in_a_raid_or_switched_off_it_stays_yours(self):
        e = self.party(self.make())
        e.cmd("questparty off")
        self.assertEqual(self.step(e, 1, 1, numFulfilled=4, text="Bloody Bone Necklace: 4/25"),
                         ["[Q] Bloody Bone Necklace: 4/25"])
        e.cmd("questparty on")
        e.mock.units.raid1 = e.lua.table(name="Remy", health=500, healthMax=500)    # a raid: left alone
        self.assertEqual(self.step(e, 1, 1, numFulfilled=5, text="Bloody Bone Necklace: 5/25"),
                         ["[Q] Bloody Bone Necklace: 5/25"])
        e.mock.units.raid1 = None
        e.cmd("questchat off")                                     # your own lines off: a step says nothing
        self.assertEqual(self.step(e, 1, 1, numFulfilled=6, text="Bloody Bone Necklace: 6/25"), [])
        self.assertEqual(list(e.mock.partySaid.values()), [])
        self.assertEqual(e.errors(), [])

class LongFrames(unittest.TestCase):
    """A moment the game stood still is kept with how much of it was the HUD's own work."""

    def test_a_long_frame_is_kept_with_the_huds_part(self):
        e = Env()
        slow = e.lua.eval("function(mock, ns) return ns.Protect(function() mock.clockMs = mock.clockMs + 60 end) end")(e.mock, e.ns)
        slow()
        e.mock.update(0.5, 0.5)                                              # a frame of half a second
        hitches = list(e.ns.Debug.hitches.values())
        self.assertEqual(len(hitches), 1)
        self.assertIn("stood still 500 ms; the HUD's part 60 ms", hitches[0])
        self.assertIn("took 60 ms", list(e.ns.spent.calls.values())[-1])
        e.update(1)                                                          # ordinary frames: nothing more
        self.assertEqual(len(list(e.ns.Debug.hitches.values())), 1)
        self.assertIn("stood still", e.cmd("slow"))
        self.assertTrue(any("stood still" in r for r in e.ns.Debug.Slow().values()))
        self.assertEqual(e.errors(), [])

    def test_no_minimap_redraw_while_the_map_is_open(self):
        e = Env()
        R = e.ns.Rest
        self.assertTrue(R.frames[e.g.MinimapCluster])
        n = R.redraws
        e.g.WorldMapFrame.shown = True
        R.RedrawMinimap()
        e.update(1)
        self.assertEqual(R.redraws, n)                                       # held while the map is open
        e.g.WorldMapFrame.shown = False
        e.update(0.2)
        self.assertEqual(R.redraws, n + 1)                                   # done once it is closed
        self.assertEqual(e.errors(), [])


class OtherFaction(unittest.TestCase):
    """A player of the other faction is plain to see: the faction's badge, and the name blue or red."""

    def test_the_other_faction_wears_its_badge_and_colour(self):
        e = Env()
        e.lua.execute("""
            FACTIONS = { player = "Horde" }
            function UnitFactionGroup(u) return FACTIONS[u], FACTIONS[u] end
        """)
        g = e.lua.globals()
        g.FACTIONS.target = "Alliance"
        g.FACTIONS.nameplate1 = "Alliance"
        g.FACTIONS.nameplate2 = "Horde"
        e.target(isPlayer=True, attackable=False, reaction=4, **{"class": "PALADIN"})
        f = e.frames.target
        badge = f.health.factionBadge                                # the badge, big, beside the bar
        self.assertTrue(badge.shown)
        self.assertIn("UI-PVP-Alliance", badge.texture)
        size = round(f.name.GetFont(f.name)[1] * e.ns.FACTION_BADGE)
        size = max(e.ns.BADGE_MIN, min(e.ns.BADGE_MAX, size))
        self.assertEqual((badge.width, badge.height), (size, size))
        self.assertGreater(size, f.name.GetFont(f.name)[1])         # bigger than the name
        self.assertEqual(badge.points[1][1], "RIGHT")
        self.assertEqual(badge.points[1][3], "LEFT")                 # left of the bar, not in the name's line,
        self.assertNotIn("UI-PVP", f.name.text)                      # which it pushed down into the bar
        self.assertTrue(f.otherFaction)
        self.assertTrue(f.health.factionShown)                       # an outline round the bar,
        c = f.health.factionEdge[1].vcolor
        self.assertGreater(c[3], c[1])                               # Alliance blue
        self.assertEqual(tuple(round(f.name.tcolor[i], 2) for i in (1, 2, 3)),
                         tuple(round(v, 2) for v in e.ns.colors.text.values()))   # the name keeps its colour
        p1 = e.mock.addPlate("nameplate1", e.lua.table(name="Ally", level=38, health=500, healthMax=500,
                                                       isPlayer=True, attackable=False, reaction=4))
        o1 = e.ns.Nameplates.byPlate[p1]
        if o1.bars:                                                  # a plate with a bar: beside it, as above
            self.assertTrue(o1.health.factionBadge.shown)
            self.assertNotIn("UI-PVP", o1.name.text)
        else:                                                        # a name alone: in its line, its own height
            self.assertIn("UI-PVP-Alliance:0:0:", o1.name.text)
        self.assertTrue(o1.health.factionShown)
        # an enemy of the other faction, with a bar: the badge beside it
        g.FACTIONS.nameplate3 = "Alliance"
        p3 = e.mock.addPlate("nameplate3", e.lua.table(name="Foe", level=38, health=500, healthMax=500,
                                                       isPlayer=True, attackable=True, reaction=2))
        o3 = e.ns.Nameplates.byPlate[p3]
        self.assertTrue(o3.bars)
        self.assertTrue(o3.health.factionBadge.shown)
        self.assertNotIn("UI-PVP", o3.name.text)
        # the target's target wears it too, and drops it when the target looks at someone of yours
        g.FACTIONS.targettarget = "Alliance"
        e.mock.setUnit("targettarget", e.lua.table(name="Their Tank", health=500, healthMax=1000, isPlayer=True,
                                                   **{"class": "WARRIOR"}))
        e.update(0.3)
        tot = e.frames.tot
        self.assertTrue(tot.health.factionBadge.shown)
        self.assertIn("UI-PVP-Alliance", tot.health.factionBadge.texture)
        self.assertTrue(tot.health.factionShown)
        g.FACTIONS.targettarget = "Horde"
        e.mock.units.targettarget = e.lua.table(name="My Mate", health=500, healthMax=1000, isPlayer=True)
        e.update(0.3)
        self.assertFalse(tot.health.factionBadge.shown)
        p2 = e.mock.addPlate("nameplate2", e.lua.table(name="Mate", level=38, health=500, healthMax=500,
                                                       isPlayer=True, attackable=False, reaction=5))
        o2 = e.ns.Nameplates.byPlate[p2]
        self.assertNotIn("UI-PVP", o2.name.text)                     # your own faction: as before
        self.assertFalse(o2.otherFaction)
        # its marks live on a layer of their own: a bar showing incoming heals clips to its edges, which hid them
        f.health.SetClipsChildren(f.health, True)
        self.assertFalse(e.same(f.health.factionBadge.parent, f.health))
        self.assertTrue(f.health.factionTint.shown)                   # and the bar lit in its colour
        tint = f.health.factionTint.vcolor
        self.assertGreater(tint[3], tint[1])                          # Alliance blue,
        e.cmd("factionstyle 2")                                       # or an enemy's red, whichever faction
        e.mock.fire("PLAYER_TARGET_CHANGED")
        tint = f.health.factionTint.vcolor
        self.assertGreater(tint[1], tint[3])
        e.cmd("factionstyle 1")
        e.cmd("factionmarks off")
        e.mock.fire("PLAYER_TARGET_CHANGED")
        self.assertNotIn("UI-PVP", f.name.text)
        self.assertFalse(f.health.factionShown)
        self.assertFalse(f.health.factionBadge.shown)
        self.assertEqual(e.errors(), [])


class QuietErrors(unittest.TestCase):
    def test_the_games_red_messages_can_be_kept_out_of_sight(self):
        e = Env()
        e.lua.execute("UIErrorsFrame = CreateFrame('Frame', 'UIErrorsFrame', UIParent)")
        e.cmd("quieterrors on")
        self.assertEqual(e.g.UIErrorsFrame.alpha, 0)
        e.cmd("quieterrors off")
        self.assertEqual(e.g.UIErrorsFrame.alpha, 1)
        self.assertEqual(e.errors(), [])

    def test_not_ready_errors_are_left_out_by_default(self):
        e = Env()
        e.lua.execute("""
            ERR_SPELL_COOLDOWN = "Spell is not ready yet."
            ERR_ABILITY_COOLDOWN = "Ability is not ready yet."
            UIErrorsFrame = CreateFrame('Frame', 'UIErrorsFrame', UIParent)
            SHOWN = {}
            UIErrorsFrame:SetScript("OnEvent", function(self, event, kind, msg) SHOWN[#SHOWN + 1] = msg end)""")
        e.ns.World.Apply(e.ns.World, True)
        h = e.lua.eval("function(ev, kind, msg) UIErrorsFrame:GetScript('OnEvent')(UIErrorsFrame, ev, kind, msg) end")
        h("UI_ERROR_MESSAGE", 51, "Spell is not ready yet.")
        h("UI_ERROR_MESSAGE", 52, "Ability is not ready yet.")
        h("UI_ERROR_MESSAGE", 3, "Not enough mana")
        self.assertEqual(list(e.g.SHOWN.values()), ["Not enough mana"])          # only the others show
        self.assertEqual(e.ns.World.notReadyHidden, 2)
        e.cmd("notready off")
        h("UI_ERROR_MESSAGE", 51, "Spell is not ready yet.")
        self.assertEqual(list(e.g.SHOWN.values()), ["Not enough mana", "Spell is not ready yet."])
        self.assertEqual(e.errors(), [])


class BreathBar(unittest.TestCase):
    """Underwater: a breath bar of ours with bubbles, beside the vertical bars; the game's own kept out of sight."""

    def test_breath_with_bubbles_beside_the_vertical_bars(self):
        e = Env()
        e.lua.execute("""
            BREATH_MS = 60000
            function GetMirrorTimerProgress(t) if t == "BREATH" then return BREATH_MS end end
            MirrorTimer1 = CreateFrame("Frame", "MirrorTimer1", UIParent)
            MirrorTimer1.timer = "BREATH"
        """)
        g = e.lua.globals()
        B = e.ns.Breath
        e.cmd("vertical on")
        e.mock.fire("MIRROR_TIMER_START", "BREATH", 60000, 60000, -1, 0, "Breath")
        e.update(0.5)
        self.assertTrue(B.running)
        self.assertTrue(B.frame.shown)
        self.assertEqual(B.where, "vertical")                        # on the player data
        self.assertEqual(g.MirrorTimer1.alpha, 0)                    # the game's own out of sight
        g.BREATH_MS = 6000                                           # little left
        e.update(1.5)
        c = B.frame.bar.fill.color
        self.assertGreater(c[1], c[3])                               # red now
        self.assertTrue(any(b.born for b in B.bubbles.values()))     # bubbles rising
        e.mock.fire("MIRROR_TIMER_STOP", "BREATH")
        self.assertFalse(B.frame.shown)
        self.assertEqual(g.MirrorTimer1.alpha, 1)                    # the game's own as it was
        e.cmd("vertical off")
        e.mock.fire("MIRROR_TIMER_START", "BREATH", 60000, 60000, -1, 0, "Breath")
        self.assertIn(B.where, ("player", "top"))
        e.cmd("breath off")
        self.assertFalse(B.frame.shown)
        self.assertEqual(e.errors(), [])


class Sleepy(unittest.TestCase):
    """At rest your frame dozes: z's drift up and a moonlit glow breathes; never in a fight."""

    def test_your_frame_dozes_where_you_rest(self):
        e = Env()
        UF = e.ns.UnitFrames
        e.update(1)
        self.assertFalse(UF.sleep.shown)
        e.mock.state.resting = True                                  # an inn
        e.update(1)
        self.assertTrue(UF.sleep.shown)
        f = UF.sleep.f
        self.assertTrue(f.sleepGlow.shown)
        alphas = [z.alpha for z in UF.sleep.z.values()]
        self.assertTrue(any(a > 0.2 for a in alphas), alphas)        # the z's drift
        e.mock.state.combat = True                                   # a fight: awake at once
        e.update(1)
        self.assertFalse(UF.sleep.shown)
        self.assertFalse(f.sleepGlow.shown)
        e.mock.state.combat = False
        e.update(1)
        self.assertTrue(UF.sleep.shown)
        e.cmd("sleepy off")
        e.update(1)
        self.assertFalse(UF.sleep.shown)
        self.assertEqual(e.errors(), [])


class RaidMarks(unittest.TestCase):
    """Raid target marks (skull, cross...) on the target frame and on nameplates, as they are set and taken off."""

    def test_a_mark_on_a_name_alone_sits_before_the_text(self):
        # a friend's plate has no bar: the mark goes just before where the line starts, not over the level
        e = Env()
        e.lua.execute("mock_marks = {}; GetRaidTargetIndex = function(unit) return mock_marks[unit] end")
        marks = e.lua.globals().mock_marks
        p = e.mock.addPlate("nameplate1", e.lua.table(name="Mtt Burgerpants", level=34, isPlayer=True,
                                                      attackable=False, reaction=5, health=5, healthMax=5))
        o = e.ns.Nameplates.byPlate[p]
        marks["nameplate1"] = 1                                        # a star
        e.mock.fire("RAID_TARGET_UPDATE")
        self.assertFalse(o.bars)
        pt = o.raidMark.points[1]
        self.assertTrue(e.same(pt[2], o.name))
        self.assertEqual((pt[1], pt[3]), ("RIGHT", "CENTER"))
        self.assertLess(pt[4], 0)                                       # left of the middle: before the text
        foe = e.mock.addPlate("nameplate2", e.lua.table(name="Foe", level=34, isPlayer=True, attackable=True,
                                                        reaction=2, health=5, healthMax=5, combat=True))
        f = e.ns.Nameplates.byPlate[foe]
        marks["nameplate2"] = 6
        e.mock.fire("RAID_TARGET_UPDATE")
        self.assertTrue(f.bars)
        self.assertTrue(e.same(f.raidMark.points[1][2], f.health))      # with a bar: beside it, as ever
        self.assertEqual(e.errors(), [])

    def test_marks_show_and_go(self):
        e = Env()
        e.lua.execute("mock_marks = {}; GetRaidTargetIndex = function(unit) return mock_marks[unit] end")
        marks = e.lua.globals().mock_marks
        e.target()
        plate = e.mock.addPlate("nameplate1", e.mock.units.target)
        o = e.ns.Nameplates.byPlate[plate]
        f = e.frames.target
        self.assertIsNone(f.raidIndex)
        marks["target"], marks["nameplate1"] = 8, 8                   # a skull
        e.mock.fire("RAID_TARGET_UPDATE")
        self.assertEqual(f.raidIndex, 8)
        self.assertTrue(f.raidMark.shown)
        self.assertEqual(o.raidIndex, 8)
        self.assertTrue(o.raidMark.shown)
        marks["target"], marks["nameplate1"] = None, None             # taken off
        e.mock.fire("RAID_TARGET_UPDATE")
        self.assertFalse(f.raidMark.shown)
        self.assertFalse(o.raidMark.shown)
        # a mark the game keeps secret, set again and again: drawn by the game's own sheet, never compared
        e.lua.execute("SetSpriteSheetCellOK = true")
        for _ in range(3):
            marks["target"], marks["nameplate1"] = e.mock.secret(), e.mock.secret()
            e.mock.fire("RAID_TARGET_UPDATE")
            e.update(0.3)
        self.assertEqual(e.errors(), [])


class Flights(unittest.TestCase):
    """Where a flight goes and how long it takes: said in chat, counted down on a bar, learned per route."""

    def test_your_mount_glides_along_the_bar(self):
        e = Env()
        F = e.ns.Flights
        e.lua.execute('UnitFactionGroup = function() return "Horde", "Horde" end')
        self.fly(e)
        bar = e.g.ControllerCamHUD_Flight
        e.update(1)
        self.assertEqual(bar.mountKind, "windrider")                         # the Horde's: a wind rider
        self.assertTrue(bar.rider.shown)
        first = F.at
        e.update(5)
        self.assertNotEqual(F.at, first)                                     # no time known: it wanders
        self.assertEqual(e.db.flightNow.mount, "windrider")                  # kept for a reload in the air
        e.cmd("flightrider off")
        e.update(1)
        self.assertFalse(bar.rider.shown)
        e.cmd("flightrider on")
        e.mock.landFlight("Booty Bay")
        e.mock.units["npc"] = e.lua.table(guid="Creature-0-1-0-1-4551-0000")   # a bat handler
        self.fly(e, 2, 1)
        e.update(1)
        self.assertEqual(bar.mountKind, "bat")
        self.assertEqual(e.errors(), [])

    NODES = ["Stormwind, Elwynn", "Booty Bay, Stranglethorn", "Ironforge, Dun Morogh"]
    ROUTE = "Stormwind, Elwynn > Booty Bay, Stranglethorn"

    def fly(self, e, start=1, to=2):
        n = len(e.mock.printed)
        e.mock.takeFlight(e.lua.table_from(self.NODES), start, to)
        e.mock.advance(0.6)
        return said(e, n)

    def test_first_flight_learns_then_the_next_counts_down(self):
        e = Env()
        F = e.ns.Flights
        self.assertEqual(self.fly(e), ["[F] Booty Bay, Stranglethorn: first flight on this route, time unknown"])
        bar = e.g.ControllerCamHUD_Flight
        self.assertTrue(bar.shown)
        e.update(42, step=0.5)
        self.assertEqual(bar.name.text, "Booty Bay")                         # the place over the bar,
        self.assertTrue(bar.time.text.startswith("+0:4"), bar.time.text)     # the time it has taken so far,
        self.assertEqual(bar.status.text, "Stranglethorn - first flight on this route: learning its time")
        e.update(48, step=0.5)
        n = len(e.mock.printed)
        e.mock.landFlight("Booty Bay")
        self.assertFalse(bar.shown)                                          # gone on landing
        rec = e.db.flightTimes[self.ROUTE]
        self.assertAlmostEqual(rec.t, 90, delta=1)
        self.assertEqual(said(e, n), ["[F] Booty Bay, Stranglethorn: flight time learned, 1:30"])
        self.assertIsNone(e.db.flightNow)
        # the same route again: an ETA, and a bar that drains towards the landing
        self.assertEqual(self.fly(e), ["[F] Booty Bay, Stranglethorn: about 1:30"])
        e.update(30, step=0.5)
        self.assertEqual(bar.time.text, "1:00")
        e.update(2, step=0.1)
        self.assertAlmostEqual(bar.bar.fill.value, 32.6, delta=1.5)          # how far along the way
        self.assertAlmostEqual(e.ns.Flights.at, 32.6 / rec.t, delta=0.03)    # the rider over the end of it
        self.assertEqual(bar.mountKind, "gryphon")
        e.update(70, step=0.5)
        self.assertEqual(bar.time.text, "landing")                           # longer than usual
        e.mock.taxi.onTaxi = False                                           # (landed with no event: the bar notices)
        e.update(1)
        self.assertFalse(bar.shown)
        self.assertEqual(rec.n, 2)
        self.assertGreater(rec.t, 91)
        self.assertIn("routes known 1", F.Describe())
        self.assertIn("1 flight routes known", e.cmd("routes"))
        self.assertEqual(e.errors(), [])

    def test_destination_from_where_you_land(self):
        e = Env()
        e.mock.taxi.nodes, e.mock.taxi.current = e.lua.table_from(self.NODES), 1
        e.mock.fire("TAXIMAP_OPENED")
        e.mock.fire("TAXIMAP_CLOSED")                                        # nothing under the pointer
        e.mock.taxi.onTaxi = True
        n = len(e.mock.printed)
        e.mock.advance(0.6)
        self.assertEqual(said(e, n), ["[F] On a flight, destination unknown"])
        self.assertEqual(e.g.ControllerCamHUD_Flight.name.text, "Flight")
        e.mock.advance(60)
        e.mock.landFlight("Booty Bay")
        self.assertAlmostEqual(e.db.flightTimes[self.ROUTE].t, 60.5, delta=1)
        # a flight with no map before it (a quest's): nothing to learn from
        e.mock.advance(30)
        e.mock.taxi.onTaxi = True
        e.mock.fire("PLAYER_CONTROL_LOST")
        e.mock.advance(2)
        self.assertIsNotNone(e.ns.Flights.flight)
        self.assertIsNone(e.ns.Flights.flight["from"])
        e.mock.advance(50)
        e.mock.landFlight("Ironforge")
        self.assertEqual(len(list(e.db.flightTimes.keys())), 1)
        self.assertEqual(e.errors(), [])

    def pick_with_the_pad(self, e, start, to, tooltip=True):
        """Open the map, move the choice onto `to` (the game's tooltip shows it), choose it: the map closes."""
        T = e.lua.table
        e.mock.taxi.nodes, e.mock.taxi.current = e.lua.table_from(self.NODES), start
        e.mock.taxi.pos = e.lua.table_from({1: T(0.5, 0.6), 2: T(0.5, 0.9), 3: T(0.7, 0.6)})
        e.mock.fire("TAXIMAP_OPENED")
        b = e.mock.taxiButton(to)
        if tooltip:
            e.lua.eval("""function(b)
                GameTooltip.GetOwner = function() return b end
                GameTooltip:Show()
            end""")(b)
        else:
            e.mock.focus = b
        e.update(0.5)                                                        # (the map is open a moment)
        e.lua.execute("GameTooltip:Hide()")                                  # chosen: the map closes, its tooltip
        e.mock.focus = None                                                  # and the pointer's place go first
        e.mock.update(0.2)
        n = len(e.mock.printed)
        e.mock.fire("TAXIMAP_CLOSED")
        e.mock.taxi.onTaxi = True
        e.mock.fire("PLAYER_CONTROL_LOST")
        e.mock.advance(0.6)
        return said(e, n)

    def test_the_place_chosen_with_the_pad_is_known(self):
        # Undercity to Tarren Mill on a controller: nothing is under the pointer as the map closes, but the place
        # chosen was shown a moment before (its tooltip, or the cursor over it)
        e = Env()
        self.assertEqual(self.pick_with_the_pad(e, 1, 2),
                         ["[F] Booty Bay, Stranglethorn: first flight on this route, time unknown"])
        self.assertEqual(e.g.ControllerCamHUD_Flight.name.text, "Booty Bay")
        self.assertEqual(e.ns.Flights.how, "tooltip")
        e.mock.advance(90)
        e.mock.landFlight("Booty Bay")
        self.assertAlmostEqual(e.db.flightTimes[self.ROUTE].t, 90.6, delta=1)
        # the cursor rather than the tooltip, and the place you stand on is never the choice
        lines = self.pick_with_the_pad(e, 1, 2, tooltip=False)
        self.assertEqual(len(lines), 1)
        self.assertTrue(lines[0].startswith("[F] Booty Bay, Stranglethorn: about 1:3"), lines)
        self.assertEqual(e.ns.Flights.how, "pointer")
        e.mock.landFlight("Booty Bay")
        e.mock.advance(5)
        self.assertEqual(self.pick_with_the_pad(e, 1, 1), ["[F] On a flight, destination unknown"])
        e.mock.landFlight("Stormwind")
        self.assertEqual(e.errors(), [])

    def test_a_new_route_is_guessed_from_the_distance(self):
        e = Env()
        self.assertEqual(self.pick_with_the_pad(e, 1, 2),                    # 0.2 of the map's width (its height
                         ["[F] Booty Bay, Stranglethorn: first flight on this route, time unknown"])   # counts 2/3)
        e.mock.advance(60)
        e.mock.landFlight("Booty Bay")
        pace = e.db.flightPace["1415"]
        self.assertAlmostEqual(pace.s, 60.6 / 0.2, delta=5)                  # seconds for the map's whole width
        # Stormwind to Ironforge, not flown yet: 0.2 too, so about a minute
        lines = self.pick_with_the_pad(e, 1, 3)
        self.assertEqual(len(lines), 1)
        self.assertTrue(lines[0].startswith("[F] Ironforge, Dun Morogh: about 1:0"), lines)
        self.assertTrue(lines[0].endswith(", a guess from the distance"), lines)
        bar = e.g.ControllerCamHUD_Flight
        e.update(30, step=0.5)
        self.assertIn(bar.time.text, ("0:30", "0:31", "0:29"))               # counted down, like a known route
        self.assertIn("a guess", e.ns.Flights.Describe())
        e.update(40, step=0.5)
        e.mock.landFlight("Ironforge")
        self.assertAlmostEqual(e.db.flightTimes["Stormwind, Elwynn > Ironforge, Dun Morogh"].t, 71, delta=2)
        self.assertEqual(pace.n, 2)                                          # and the pace learns from it too
        # along the flight's own legs, where the map draws them
        e.lua.execute("""
            GetNumRoutes = function(slot) return slot == 2 and 2 or 0 end
            local legs = { { 0.5, 0.6, 0.8, 0.6 }, { 0.8, 0.6, 0.5, 0.9 } }
            TaxiGetSrcX = function(slot, i) return legs[i][1] end
            TaxiGetSrcY = function(slot, i) return legs[i][2] end
            TaxiGetDestX = function(slot, i) return legs[i][3] end
            TaxiGetDestY = function(slot, i) return legs[i][4] end""")
        e.mock.taxi.nodes = e.lua.table_from(self.NODES)
        e.mock.taxi.current = 1
        e.ns.Flights.ReadMap()
        self.assertAlmostEqual(e.ns.Flights.Distance(2), 0.3 + (0.09 + 0.04) ** 0.5, delta=0.01)
        self.assertEqual(e.errors(), [])

    def test_each_text_has_a_place_of_its_own(self):
        e = Env()
        self.pick_with_the_pad(e, 1, 2)
        bar = e.g.ControllerCamHUD_Flight
        f = bar.bar
        # the place left over the bar, the time right over it (a width of its own), the status under it
        self.assertEqual(bar.name.points[1][1], "BOTTOMLEFT")
        self.assertTrue(e.same(bar.name.points[1][2], f))
        self.assertEqual(bar.name.points[1][3], "TOPLEFT")
        self.assertEqual(bar.name.points[2][1], "RIGHT")
        self.assertTrue(e.same(bar.name.points[2][2], bar.time))           # stops where the time begins
        self.assertEqual(bar.time.points[1][1], "BOTTOMRIGHT")
        self.assertTrue(e.same(bar.time.points[1][2], f))
        self.assertEqual(bar.time.width, e.ns.Flights.TIME_W)
        self.assertEqual(bar.status.points[1][1], "TOPLEFT")
        self.assertEqual(bar.status.points[1][3], "BOTTOMLEFT")
        self.assertTrue(e.same(bar.status.points[1][2], f))
        self.assertEqual(bar.name.text, "Booty Bay")
        self.assertNotIn("Booty Bay", bar.time.text + bar.status.text)
        e.mock.advance(30)
        e.mock.landFlight("Booty Bay")
        self.assertEqual(e.errors(), [])

    LEGS = """
        GetNumRoutes = function(slot) return slot == 2 and 2 or 0 end
        local legs = { { 0.5, 0.6, 0.7, 0.6 }, { 0.7, 0.6, 0.5, 0.9 } }
        TaxiGetSrcX = function(slot, i) return legs[i][1] end
        TaxiGetSrcY = function(slot, i) return legs[i][2] end
        TaxiGetDestX = function(slot, i) return legs[i][3] end
        TaxiGetDestY = function(slot, i) return legs[i][4] end"""

    def test_landing_early_goes_to_the_next_stop(self):
        # Stormwind to Booty Bay by way of Ironforge (0.2 of the 0.48 of the way), 100 s; 10 s in you ask to land
        db = "{ flightTimes = { ['Stormwind, Elwynn > Booty Bay, Stranglethorn'] = { t = 100, n = 1 } } }"
        e = Env(db=db)
        e.lua.execute(self.LEGS)
        self.pick_with_the_pad(e, 1, 2)
        stops = e.ns.Flights.flight.stops
        self.assertEqual(stops[1].n, "Ironforge, Dun Morogh")
        self.assertAlmostEqual(stops[1].f, 0.2 / (0.2 + 0.08 ** 0.5), delta=0.01)
        self.assertEqual(stops[2].f, 1)
        e.update(10, step=0.5)
        n = len(e.mock.printed)
        e.lua.execute("TaxiRequestEarlyLanding()")
        lines = said(e, n)
        self.assertEqual(len(lines), 1)
        self.assertTrue(lines[0].startswith("[F] Landing early: Ironforge, Dun Morogh, about 0:3"), lines)
        bar = e.g.ControllerCamHUD_Flight
        self.assertEqual(bar.name.text, "Ironforge")
        self.assertIn("landing early", bar.status.text)
        self.assertTrue(e.db.flightNow.early)
        self.assertEqual(e.db.flightNow.to, "Ironforge, Dun Morogh")
        e.update(25, step=0.5)
        e.mock.landFlight("Ironforge")
        self.assertIsNone(e.db.flightTimes["Stormwind, Elwynn > Ironforge, Dun Morogh"])   # not a measure of it
        self.assertEqual(e.db.flightTimes[self.ROUTE].t, 100)
        self.assertEqual(e.errors(), [])

    def test_the_weather_where_you_land(self):
        e = Env()
        F = e.ns.Flights
        e.lua.execute("C_Map.GetBestMapForUnit = function() return 1434 end; GetGameTime = function() return 19, 30 end")
        self.fly(e)
        e.update(40, step=0.5)
        e.mock.landFlight("Booty Bay")
        n = len(e.mock.printed)
        e.mock.advance(1.2)
        lines = said(e, n)
        jungle = list(F.CLIMATES.jungle.values())
        self.assertEqual(len(lines), 1, lines)
        self.assertIn(lines[0], ["[F] Evening at Booty Bay: " + air for air in jungle])
        # a town's own map is part of its zone's; a map not known says nothing
        e.lua.execute("""C_Map.GetBestMapForUnit = function() return 9001 end
            C_Map.GetMapInfo = function(id) return id == 9001 and { parentMapID = 1426 } or nil end
            GetGameTime = function() return 2, 0 end""")
        self.assertTrue(F.Weather("Ironforge, Dun Morogh").startswith("Night at Ironforge: "))
        self.assertIn(F.Weather("Ironforge, Dun Morogh").split(": ", 1)[1], list(F.CLIMATES.snow.values()))
        e.lua.execute("C_Map.GetBestMapForUnit = function() return 12 end")
        self.assertIsNone(F.Weather("Somewhere"))
        e.cmd("flightweather off")                                           # off: not said
        e.lua.execute("C_Map.GetBestMapForUnit = function() return 1434 end")
        self.fly(e)
        e.update(40, step=0.5)
        e.mock.landFlight("Booty Bay")
        n = len(e.mock.printed)
        e.mock.advance(1.2)
        self.assertEqual([l for l in said(e, n) if " at Booty Bay: " in l], [])
        self.assertEqual(e.errors(), [])

    def test_the_weather_is_said_as_you_come_in_to_land(self):
        # a known route: fifteen seconds out, the weather where you land (by its zone, though you are still over
        # another one), and not again once you are down
        db = "{ flightTimes = { ['Stormwind, Elwynn > Booty Bay, Stranglethorn'] = { t = 100, n = 1 } } }"
        e = Env(db=db)
        F = e.ns.Flights
        e.lua.execute("""C_Map.GetBestMapForUnit = function() return 1436 end
            C_Map.GetMapInfo = function(id)
                local names = { [1434] = "Stranglethorn Vale", [1436] = "Westfall" }
                return names[id] and { name = names[id] } or nil
            end
            GetGameTime = function() return 19, 30 end""")
        self.fly(e)
        n = len(e.mock.printed)
        e.update(80, step=0.5)
        self.assertEqual([l for l in said(e, n) if " at Booty Bay: " in l], [])      # not yet
        e.update(6, step=0.5)                                                       # 14 s out
        lines = [l for l in said(e, n) if " at Booty Bay: " in l]
        self.assertEqual(len(lines), 1)
        self.assertIn(lines[0], ["[F] Evening at Booty Bay: " + a for a in F.CLIMATES.jungle.values()])
        e.update(15, step=0.5)
        e.mock.landFlight("Booty Bay")
        e.mock.advance(1.2)
        self.assertEqual(len([l for l in said(e, n) if " at Booty Bay: " in l]), 1)   # said once
        self.assertEqual(e.errors(), [])

    def test_landing_early_past_the_last_stop_or_without_stops(self):
        db = "{ flightTimes = { ['Stormwind, Elwynn > Booty Bay, Stranglethorn'] = { t = 100, n = 1 } } }"
        e = Env(db=db)
        e.lua.execute(self.LEGS)
        self.pick_with_the_pad(e, 1, 2)
        e.update(60, step=0.5)                                               # past Ironforge: Booty Bay anyway
        e.lua.execute("TaxiRequestEarlyLanding()")
        self.assertEqual(e.g.ControllerCamHUD_Flight.name.text, "Booty Bay")
        self.assertFalse(e.ns.Flights.flight.early)
        e.update(45, step=0.5)
        e.mock.landFlight("Booty Bay")
        e.lua.execute("GetNumRoutes = function() return 0 end")              # the map draws no legs
        self.pick_with_the_pad(e, 1, 2)
        e.update(5, step=0.5)
        n = len(e.mock.printed)
        e.lua.execute("TaxiRequestEarlyLanding()")
        self.assertEqual(said(e, n), ["[F] Landing early at the next flight point"])
        bar = e.g.ControllerCamHUD_Flight
        self.assertIn("landing at the next flight point", bar.status.text)
        self.assertTrue(bar.time.text.startswith("+"))                      # counting up: no time to it known
        self.assertEqual(e.errors(), [])

    def test_a_route_flown_before_paces_were_kept_gives_the_pace(self):
        # Undercity to Tarren Mill was learned (2:21) before paces were kept; at Tarren Mill the map shows both
        # ends, so the first flight on to Hammerfall is a guess, not a count up
        nodes = ["Undercity, Tirisfal", "Tarren Mill, Hillsbrad", "Hammerfall, Arathi"]
        db = "{ flightTimes = { ['Undercity, Tirisfal > Tarren Mill, Hillsbrad'] = { t = 140.76, n = 1 } } }"
        e = Env(db=db)
        T = e.lua.table
        e.mock.taxi.nodes, e.mock.taxi.current = e.lua.table_from(nodes), 2
        e.mock.taxi.pos = e.lua.table_from({1: T(0.40, 0.30), 2: T(0.46, 0.39), 3: T(0.55, 0.39)})
        e.mock.fire("TAXIMAP_OPENED")
        pace = e.db.flightPace["1415"]
        d = ((0.06) ** 2 + (0.09 * 2 / 3) ** 2) ** 0.5
        self.assertAlmostEqual(pace.s, 140.76 / d, delta=1)
        b = e.mock.taxiButton(3)
        e.mock.focus = b
        e.update(0.3)
        e.mock.focus = None
        n = len(e.mock.printed)
        e.mock.fire("TAXIMAP_CLOSED")
        e.mock.taxi.onTaxi = True
        e.mock.fire("PLAYER_CONTROL_LOST")
        e.mock.advance(0.6)
        guess = 0.09 * pace.s
        self.assertEqual(said(e, n), ["[F] Hammerfall, Arathi: about %s, a guess from the distance" % e.ns.Flights.Clock(guess)])
        bar = e.g.ControllerCamHUD_Flight
        self.assertEqual(bar.status.text, "Arathi - a guess from the distance")
        self.assertFalse(bar.time.text.startswith("+"))                      # counted down
        e.mock.fire("TAXIMAP_OPENED")                                         # (a pace once kept is not seeded again)
        self.assertAlmostEqual(e.db.flightPace["1415"].s, pace.s, delta=0.01)
        self.assertEqual(e.errors(), [])

    def test_a_reload_in_the_air_carries_on(self):
        db = "{ flightTimes = { ['%s'] = { t = 100, n = 1 } }, flightNow = { from = 'Stormwind, Elwynn', " \
             "to = 'Booty Bay, Stranglethorn', at = 960 } }" % self.ROUTE

        def up(env):
            env.mock.taxi.onTaxi = True
        e = Env(db=db, setup=up)
        F = e.ns.Flights
        self.assertIsNotNone(F.flight)
        e.update(1, step=0.5)
        self.assertEqual(e.g.ControllerCamHUD_Flight.time.text, "0:59")      # 100 s, 41 of them gone
        self.assertFalse(any(t.startswith("[F]") for t in said(e, 0)))       # said when it began, not again
        e.mock.landFlight()
        self.assertEqual(e.db.flightTimes[self.ROUTE].n, 2)
        stale = Env(db=db)                                                   # landed while the game was closed
        self.assertIsNone(stale.ns.Flights.flight)
        self.assertIsNone(stale.db.flightNow)
        self.assertEqual(e.errors() + stale.errors(), [])

    def test_off_and_the_mouse_ui(self):
        for e in (Env(style="0"), Env()):
            e.cmd("flights off")
            self.assertEqual(self.fly(e), [])
            self.assertIsNone(e.g.ControllerCamHUD_Flight)
            e.mock.landFlight("Booty Bay")
            self.assertEqual(len(list(e.db.flightTimes.keys())), 0)
            self.assertEqual(e.errors(), [])


class Hydrate(unittest.TestCase):
    """A gentle reminder to drink water now and then."""

    def remind(self, e, minutes):
        e.mock.advance(minutes * 60)
        e.update(6, step=1)

    def test_every_hour_and_gone_again(self):
        e = Env()
        H = e.ns.Hydrate
        self.remind(e, 30)
        self.assertEqual(H.shown, 0)
        n = len(e.mock.printed)
        self.remind(e, 30)
        self.assertEqual(H.shown, 1)
        w = e.g.ControllerCamHUD_Water
        self.assertTrue(w.shown)
        self.assertEqual(w.title.text, "Time for a sip of water")
        self.assertEqual(w.sub.text, "You have played for 1 h.")
        self.assertIn("[W] Time for a sip of water", said(e, n))
        self.assertGreater(w.glow.alpha, 0)                                   # moving: a glow, a drop, rings
        e.update(10, step=0.5)
        self.assertFalse(w.shown)
        e.cmd("hydrateevery 15")
        self.remind(e, 15)
        self.assertEqual(H.shown, 2)
        self.assertIn("every 15 min", H.Describe())
        self.assertEqual(e.errors(), [])

    def test_never_in_a_fight(self):
        e = Env()
        H = e.ns.Hydrate
        e.mock.state.combat = True
        self.remind(e, 61)
        self.assertEqual(H.shown, 0)
        self.assertTrue(H.waiting)
        e.mock.state.combat = False
        e.mock.fire("PLAYER_REGEN_ENABLED")
        e.mock.advance(5)
        self.assertEqual(H.shown, 1)                                          # after the fight
        e.mock.fire("PLAYER_REGEN_DISABLED")                                  # a fight starts: off the screen
        self.assertFalse(e.g.ControllerCamHUD_Water.shown)
        self.assertEqual(e.errors(), [])

    def test_a_flight_is_a_break(self):
        e = Env()
        H = e.ns.Hydrate
        nodes = e.lua.table_from(Flights.NODES)
        e.mock.takeFlight(nodes, 1, 2)
        e.mock.advance(1)
        self.assertEqual(H.shown, 0)                                          # you only just started
        e.mock.landFlight("Booty Bay")
        e.mock.advance(25 * 60)
        e.mock.takeFlight(nodes, 2, 1)
        e.mock.advance(1)
        self.assertEqual(H.shown, 1)
        self.assertEqual(e.g.ControllerCamHUD_Water.sub.text, "A flight is a good moment for it.")
        e.mock.landFlight("Stormwind")
        e.mock.advance(25 * 60)
        e.cmd("hydrateflight off")
        e.mock.takeFlight(nodes, 1, 2)
        e.mock.advance(1)
        self.assertEqual(H.shown, 1)
        self.assertEqual(e.errors(), [])

    def test_calm_and_off(self):
        e = Env()
        e.cmd("reducemotion on")
        e.cmd("watertest")
        w = e.g.ControllerCamHUD_Water
        self.assertTrue(e.ns.Hydrate.live.calm)
        e.update(2, step=0.25)
        self.assertEqual(w.glow.alpha, 0)                                     # nothing moves: it only fades
        self.assertEqual(max(r.alpha for r in w.rings.values()), 0)
        self.assertEqual(w.drop.alpha, 0)
        off = Env()
        off.cmd("hydrate off")
        self.remind(off, 61)
        self.assertEqual(off.ns.Hydrate.shown, 0)
        mouse = Env(style="0")
        self.remind(mouse, 61)
        self.assertEqual(mouse.ns.Hydrate.shown, 0)
        self.assertEqual(e.errors() + off.errors() + mouse.errors(), [])


class Recruitment(unittest.TestCase):
    """A chat ad is shown the first time and not again; or, if you say so, never."""

    AD = "<Night Watch> is recruiting all levels for raids and fun, /w me for an invite!"
    AD2 = "<Night Watch> is recruiting all levels for raids and fun!! /w me for invite"

    def test_repeats_hidden_first_shown(self):
        e = Env()
        C = e.ns.Chat

        def chat(msg, who, event="CHAT_MSG_CHANNEL"):
            return e.mock.chat(event, msg, who, "Player-1-" + who)
        self.assertIsNotNone(chat(self.AD, "Anna"))
        self.assertIsNone(chat(self.AD, "Anna"))                              # the same player again
        self.assertIsNone(chat(self.AD2, "Bert"))                             # nearly the same, someone else
        other = "Guild Shadow Pact is looking for members, whisper for an inv"
        self.assertIsNotNone(chat(other, "Cara"))                             # another guild: once
        self.assertIsNone(chat("Shadow Pact wants YOU, join us today and get a guild tabard", "Cara"))
        for _ in range(3):                                                    # not recruiting: shown
            self.assertIsNotNone(chat("LFG Deadmines, need a healer", "Dora"))
            e.mock.advance(150)
        self.assertIsNotNone(chat(self.AD, "Anna", "CHAT_MSG_PARTY"))         # never your group
        self.assertEqual(C.recruitHidden, 3)
        self.assertIn("3 of them were repeated guild recruitment", e.cmd("spam"))
        self.assertIn("guild recruitment 3", C.Describe())
        e.mock.advance(3600)
        self.assertIsNone(chat(self.AD, "Anna"))                              # an hour on: still not again
        self.assertIsNotNone(e.mock.chat("CHAT_MSG_CHANNEL", e.mock.secret(), "Anna", "Player-1-Anna"))
        self.assertEqual(e.errors(), [])

    def test_a_trade_ad_shows_once_and_other_wares_still_show(self):
        e = Env()
        C = e.ns.Chat

        def chat(msg, who):
            return e.mock.chat("CHAT_MSG_CHANNEL", msg, who, "Player-1-" + who)
        self.assertIsNotNone(chat("WTS Copper Bar x20, 5s each, whisper me", "Tia"))
        e.mock.advance(1000)
        self.assertIsNone(chat("WTS Copper Bar x20, 4s each, whisper me", "Tia"))       # a new price: the same ad
        self.assertIsNotNone(chat("WTS Linen Cloth, a whole stack, cheap", "Tia"))      # other wares: shown
        self.assertIsNone(chat("WTS Linen Cloth, a whole stack, cheap", "Uma"))         # the very words, anyone
        self.assertIsNotNone(chat("WTB Silk", "Vic"))
        for msg, kind in (("LFW enchanting, your mats", "trade"), ("Selling portals, tips welcome", "trade"),
                          ("Verkaufe Kupferbarren", "trade"), ("出售铜锭", "trade"),
                          ("LFM Deadmines need tank", None), ("LF1M healer then go", None),
                          ("anyone know where the bank is?", None), ("newts everywhere", None)):
            self.assertEqual(C.AdKind(msg), kind, msg)
        self.assertEqual(e.errors(), [])

    def test_ads_can_be_hidden_from_the_first_time(self):
        e = Env()
        self.assertIn("on", e.cmd("chatadsall on"))
        for msg in (self.AD, "WTS Copper Bar x20"):
            self.assertIsNone(e.mock.chat("CHAT_MSG_CHANNEL", msg, "Anna", "Player-1-1"), msg)
        self.assertIsNotNone(e.mock.chat("CHAT_MSG_CHANNEL", "LFM Deadmines need tank", "Anna", "Player-1-1"))
        self.assertIsNotNone(e.mock.chat("CHAT_MSG_PARTY", "WTS Copper Bar x20", "Anna", "Player-1-1"))   # your group
        self.assertEqual(e.ns.Chat.recruitHidden, 0)                          # (none of them was a repeat)
        e.cmd("chatadsall off")
        e.cmd("chatrecruit off")
        self.assertIsNotNone(e.mock.chat("CHAT_MSG_CHANNEL", "WTS Copper Bar x20", "Bo", "Player-1-2"))
        self.assertEqual(e.errors(), [])

    def test_wording_and_switches(self):
        e = Env()
        C = e.ns.Chat
        for msg in (self.AD, "Recruiting for our new raid team, all classes", "Gilde Nachtwache sucht Mitglieder"):
            self.assertTrue(C.IsRecruit(msg), msg)
        for msg in ("LFM Scarlet Monastery", "anyone know where the guild bank is?", "WTS Linen Cloth"):
            self.assertFalse(C.IsRecruit(msg), msg)
        self.assertTrue(C.Alike(self.AD, self.AD2))
        self.assertFalse(C.Alike(self.AD, "<Night Watch> raids tonight, bring flasks and food please"))
        e.cmd("chatspam off")                                                 # the spam filter off: this still works
        e.mock.chat("CHAT_MSG_CHANNEL", self.AD, "Anna", "Player-1-1")
        self.assertIsNone(e.mock.chat("CHAT_MSG_CHANNEL", self.AD, "Anna", "Player-1-1"))
        self.assertIn("off", e.cmd("chatrecruit off"))
        self.assertIsNotNone(e.mock.chat("CHAT_MSG_CHANNEL", self.AD, "Anna", "Player-1-1"))
        self.assertEqual(e.errors(), [])


class Ride(unittest.TestCase):
    """A flight on film: bars, the HUD faded back, the camera wide and swinging; the flight bar and game ride along."""

    NODES = ["Stormwind, Elwynn", "Booty Bay, Stranglethorn", "Ironforge, Dun Morogh"]
    ROUTE = "Stormwind, Elwynn > Booty Bay, Stranglethorn"

    def env(self, eta=120, **kw):
        def setup(env):
            env.lua.execute("""
                TURNS, HOLDS, PAD = {}, {}, nil
                function MoveViewRightStart(k) TURNS[#TURNS + 1] = k end
                function MoveViewLeftStart(k) TURNS[#TURNS + 1] = -k end
                function MoveViewRightStop() TURNS[#TURNS + 1] = "stop" end
                function MoveViewLeftStop() TURNS[#TURNS + 1] = "stop" end
                function GetGameTime() return 19, 30 end
                C_GamePad = { GetDeviceMappedState = function() return PAD end }
                ControllerCam = { Hold = function(on) HOLDS[#HOLDS + 1] = on end }""")
            env.mock.state.zoom = 6
        e = Env(setup=setup, **kw)
        e.g.WorldMapFrame.Hide(e.g.WorldMapFrame)                    # (the map closed)
        e.g.UIParent.height = 768
        e.ns.FlightGame.random = lambda: 0.5
        if eta:
            e.db.flightTimes[self.ROUTE] = e.lua.table(t=eta, n=1)
        return e

    def fly(self, e):
        e.mock.takeFlight(e.lua.table_from(self.NODES), 1, 2)
        e.mock.advance(0.6)
        e.update(0.1)

    def press(self, e, key, tag):
        e.g["ControllerCamHUD_Key_%s_%s" % (tag, key)].scripts.OnClick()

    def turned(self, e):
        return [k for k in e.g.TURNS.values() if k != "stop"]

    def test_names_and_nameplates_leave_the_film(self):
        e = self.env()
        e.mock.cvars.nameplateShowFriends, e.mock.knownCVars.nameplateShowFriends = "1", True
        R = e.ns.Ride
        self.fly(e)
        e.update(3, 0.1)
        self.assertIsNotNone(R.scene)
        self.assertEqual(e.mock.cvars.nameplateShowFriends, "0")
        R.Finish("test")
        self.assertEqual(e.mock.cvars.nameplateShowFriends, "1")
        self.assertEqual(e.errors(), [])

    def test_take_off_rolls_film_and_coming_in_gives_everything_back(self):
        e = self.env()
        R, g = e.ns.Ride, e.g
        self.assertTrue(e.db.flightScene)                            # on by default
        self.fly(e)
        bar = g.ControllerCamHUD_Flight
        self.assertIsNone(R.scene)                                   # taking off: not yet
        e.update(3, 0.1)
        self.assertIsNotNone(R.scene)
        film = R.frame
        self.assertIsNone(film.parent)                               # not under the screen it fades back
        self.assertEqual(list(g.HOLDS.values()), [True])             # the camera addon keeps its hands off
        self.assertEqual(e.mock.state.zoom, 14)                      # drawn out wide
        e.update(4, 0.1)
        self.assertEqual(g.UIParent.alpha, 0)                        # the HUD faded back
        self.assertGreater(film.top.height, 80)                      # black bars
        self.assertGreater(film.bottom.height, 80)
        self.assertTrue(e.same(bar.parent, film))                    # the flight bar rides along, readable,
        y = bar.points[len(bar.points)][5]
        self.assertGreater(y, -film.top.height)                      # inside the top bar
        self.assertEqual(film.title.text, "Booty Bay")               # where you are going
        self.assertEqual(film.sub.text, "Stranglethorn  ·  Evening")
        self.assertGreater(film.title.alpha, 0.5)
        e.update(20, 0.1)
        self.assertGreater(len(self.turned(e)), 3)                   # the camera swings slowly round
        self.assertTrue(all(abs(k) * 180 <= R.VMAX + 0.01 for k in self.turned(e)))
        e.mock.zone = "Stranglethorn Vale"
        e.mock.fire("ZONE_CHANGED_NEW_AREA")
        e.update(1, 0.1)
        self.assertEqual(film.title.text, "Stranglethorn Vale")      # a new zone under you
        e.update(120 - 28 - 17 + 1, 0.1)                             # coming in: it bows out
        self.assertIsNotNone(R.scene)
        e.update(6, 0.1)
        self.assertIsNone(R.scene)
        self.assertEqual(R.last, "coming in to land")
        self.assertEqual(g.UIParent.alpha, 1)
        self.assertEqual(e.mock.state.zoom, 6)                       # the distance it had
        self.assertFalse(film.shown)
        self.assertTrue(e.same(bar.parent, g.UIParent))              # the flight bar back where it was
        self.assertEqual(bar.points[len(bar.points)][5], e.ns.Flights.Y)
        self.assertEqual(list(g.HOLDS.values()), [True, False])
        self.assertEqual(g.TURNS[len(g.TURNS)], "stop")
        e.update(5, 0.1)
        self.assertIsNone(R.scene)                                   # and not again on this flight
        e.mock.landFlight("Booty Bay")
        e.update(1, 0.1)
        self.assertIn("flight film", R.Describe())
        self.assertEqual(e.errors(), [])

    def test_the_flight_game_steps_out_and_high_altitude_brings_it_back(self):
        e = self.env()
        R, G, g = e.ns.Ride, e.ns.FlightGame, e.g
        self.fly(e)
        e.update(6, 0.1)
        self.assertIsNotNone(R.scene)
        self.assertTrue(G.hint.shown)                                # the game's offer, under the flight bar,
        self.assertTrue(e.same(G.hint.parent, R.frame))              # on the film with it
        self.press(e, "PAD4", "FlightStart")                         # Y: play
        self.assertEqual(G.state, "playing")
        e.update(1.5, 0.1)
        self.assertIsNone(R.scene)                                   # out of the way at once
        self.assertEqual(g.UIParent.alpha, 1)
        self.assertTrue(e.same(G.frame.parent, g.UIParent))          # the lane plays over the screen as ever
        self.assertEqual(e.mock.state.zoom, 6)
        e.update(10, 0.1)
        self.assertIsNone(R.scene)                                   # not while you play
        self.press(e, "PAD4", "FlightGame")                          # Y again: high altitude
        self.assertEqual(G.state, "paused")
        e.update(2, 0.1)
        self.assertIsNone(R.scene)                                   # a moment first
        e.update(4, 0.1)
        self.assertIsNotNone(R.scene)                                # back on film
        self.assertTrue(e.same(G.hint.parent, R.frame))
        self.assertEqual(e.errors(), [])

    def test_a_fight_ends_it_at_once_and_for_the_flight(self):
        e = self.env()
        R, g = e.ns.Ride, e.g
        self.fly(e)
        e.update(8, 0.1)
        self.assertIsNotNone(R.scene)
        e.mock.state.combat = True
        e.mock.fire("PLAYER_REGEN_DISABLED")
        self.assertIsNone(R.scene)
        self.assertEqual(g.UIParent.alpha, 1)                        # everything back at once
        self.assertEqual(e.mock.state.zoom, 6)
        self.assertTrue(e.same(g.ControllerCamHUD_Flight.parent, g.UIParent))
        e.mock.state.combat = False
        e.mock.fire("PLAYER_REGEN_ENABLED")
        e.update(15, 0.1)
        self.assertIsNone(R.scene)                                   # not again on this flight
        self.assertEqual(e.errors(), [])

    def test_a_reload_in_the_air_and_a_hand_on_the_controller(self):
        e = self.env()
        R, g = e.ns.Ride, e.g
        self.fly(e)
        e.update(8, 0.1)
        e.mock.fire("PLAYER_LEAVING_WORLD")                          # a reload in the air: given back first
        self.assertIsNone(R.scene)
        self.assertEqual(g.UIParent.alpha, 1)
        self.assertEqual(e.mock.state.zoom, 6)
        e.update(1, 0.1)
        self.assertIsNotNone(R.scene)                                # (still flying: on film again)
        e.update(4, 0.1)
        e.lua.execute("PAD = { buttons = { false, true } }")         # a button
        e.update(0.5, 0.1)
        e.lua.execute("PAD = { buttons = {}, sticks = { { x = 0, y = 0 } } }")
        e.update(4, 0.1)
        self.assertIsNone(R.scene)                                   # stepped out for you
        self.assertEqual(g.UIParent.alpha, 1)
        e.lua.execute("PAD = { buttons = {}, sticks = { { x = 0.8, y = 0 } } }")   # the camera stick, a while
        e.update(2, 0.1)
        e.lua.execute("PAD = { buttons = {}, sticks = { { x = 0, y = 0 } } }")
        e.update(6, 0.1)
        self.assertIsNone(R.scene)
        e.update(3, 0.1)
        self.assertIsNotNone(R.scene)                                # left alone: back on film
        self.assertEqual(e.errors(), [])

    def test_calm_keeps_the_camera_still_and_the_switch_turns_it_off(self):
        e = self.env()
        R, g = e.ns.Ride, e.g
        e.cmd("reducemotion on")
        self.fly(e)
        e.update(8, 0.1)
        self.assertIsNotNone(R.scene)
        self.assertEqual(e.mock.state.zoom, 6)                       # still
        self.assertEqual(self.turned(e), [])
        self.assertGreater(R.frame.top.height, 80)                   # the bars fade in where they stand
        self.assertEqual(R.frame.top.alpha, 1)
        e.cmd("flightscene off")
        e.update(0.5, 0.1)
        self.assertIsNone(R.scene)
        self.assertEqual(g.UIParent.alpha, 1)
        self.assertEqual(e.errors(), [])

    def still(self, e):
        """Not turning: every start since followed by a stop (the camera is never left turning)."""
        turns = list(e.g.TURNS.values())
        starts = [i for i, k in enumerate(turns) if k != "stop"]
        return not starts or any(k == "stop" for k in turns[starts[-1] + 1:])

    def test_the_camera_circles_you_and_comes_round_behind_before_you_land(self):
        e = self.env(eta=240)
        R, g = e.ns.Ride, e.g
        self.assertTrue(e.db.flightOrbit)                            # on by default
        self.fly(e)
        e.update(3.2, 0.1)
        self.assertIsNotNone(R.scene)
        self.assertGreater(len(self.turned(e)), 0)                   # it starts with the film,
        first = self.turned(e)[0]
        self.assertLess(first * 180, 2)                              # eased in
        e.update(30, 0.1)
        speed = self.turned(e)[-1] * 180
        self.assertAlmostEqual(speed, R.ORBIT, delta=0.01)           # slow: a whole turn in 90 seconds
        self.assertTrue(all(k > 0 for k in self.turned(e)))          # one way round
        e.update(100, 0.1)
        self.assertGreater(R.scene.yaw, 360)                         # more than a whole turn by now
        e.update(240 - 133.3 - (17 + 10) + 0.5, 0.1)                 # coming in: round behind you
        self.assertIsNotNone(R.scene.home)
        e.update(12, 0.1)
        self.assertLessEqual(abs(R.scene.home.to - R.scene.yaw), R.HOME)
        self.assertAlmostEqual(R.scene.home.to % 360, 0)             # behind you again,
        self.assertTrue(self.still(e))                               # and still, before it bows out
        self.assertTrue(all(abs(k) * 180 <= R.VMAX + 0.01 for k in self.turned(e)))   # never dizzying
        e.update(6, 0.1)
        self.assertIsNone(R.scene)
        self.assertEqual(R.last, "coming in to land")
        self.assertTrue(self.still(e))
        self.assertEqual(e.errors(), [])

    def test_the_turn_is_always_stopped_when_the_film_ends(self):
        for end in ("landed", "game", "fight", "reload", "off", "early"):
            e = self.env()
            R, G = e.ns.Ride, e.ns.FlightGame
            self.fly(e)
            e.update(10, 0.1)
            self.assertIsNotNone(R.scene, end)
            self.assertFalse(self.still(e), end)                     # turning
            if end == "landed":
                e.mock.landFlight("Booty Bay")
            elif end == "game":
                self.press(e, "PAD4", "FlightStart")
            elif end == "fight":
                e.mock.state.combat = True
                e.mock.fire("PLAYER_REGEN_DISABLED")
            elif end == "reload":
                e.mock.fire("PLAYER_LEAVING_WORLD")
            elif end == "off":
                e.cmd("flightscene off")
            elif end == "early":                                     # asked to land early: down at once
                e.mock.taxi.onTaxi = False
            e.update(1.5, 0.1)
            if end != "reload":
                self.assertIsNone(R.scene, end)
            self.assertTrue(self.still(e) or R.scene is not None, end)
            if end == "reload":
                self.assertTrue("stop" in list(e.g.TURNS.values()), end)
            self.assertEqual(e.errors(), [], end)

    def test_the_switch_leaves_a_still_shot_and_a_refused_turn_is_one_too(self):
        e = self.env()
        R = e.ns.Ride
        e.cmd("flightorbit off")
        self.fly(e)
        e.update(10, 0.1)
        self.assertIsNotNone(R.scene)                                # on film,
        self.assertEqual(self.turned(e), [])                         # but still
        self.assertEqual(e.mock.state.zoom, 14)                      # (still drawn out wide)
        e.cmd("flightorbit on")
        e.update(2, 0.1)
        self.assertGreater(len(self.turned(e)), 0)
        e.cmd("flightorbit off")
        e.update(0.5, 0.1)
        self.assertTrue(self.still(e))                               # switched off mid-flight: stopped at once
        e2 = self.env()
        e2.lua.execute("function MoveViewRightStart() error('blocked') end")   # a client that refuses
        self.fly(e2)
        e2.update(10, 0.1)
        self.assertIsNotNone(e2.ns.Ride.scene)                       # the film plays on, a still shot
        self.assertTrue(e2.ns.Ride.noTurn)
        self.assertTrue(self.still(e2))
        self.assertEqual(e.errors() + e2.errors(), [])

    def test_the_minimap_and_its_marks_hide_for_the_film_and_come_back(self):
        e = self.env()
        R, g = e.ns.Ride, e.g
        self.fly(e)
        e.update(3.5, 0.1)
        self.assertIsNotNone(R.scene)
        self.assertTrue(g.Minimap.shown)                             # not while the screen is still up
        e.update(3, 0.1)
        self.assertFalse(g.MinimapCluster.shown)                     # its arrow and dots don't fade: hidden
        self.assertFalse(g.Minimap.shown)
        redraws = e.ns.Rest.redraws
        e.mock.landFlight("Booty Bay")
        e.update(0.5, 0.1)
        self.assertIsNone(R.scene)
        self.assertTrue(g.MinimapCluster.shown)                      # back as it was
        self.assertTrue(g.Minimap.shown)
        self.assertGreaterEqual(e.ns.Rest.redraws, redraws)
        g.MinimapCluster.Hide(g.MinimapCluster)                      # hidden by you (or another addon) before:
        self.fly(e)
        e.update(8, 0.1)
        self.assertIsNotNone(R.scene)
        self.assertFalse(g.Minimap.shown)
        e.mock.landFlight("Booty Bay")
        e.update(0.5, 0.1)
        self.assertFalse(g.MinimapCluster.shown)                     # stays hidden
        self.assertTrue(g.Minimap.shown)
        self.assertEqual(e.errors(), [])

    def test_a_short_flight_is_not_filmed(self):
        e = self.env(eta=35)
        self.fly(e)
        e.update(20, 0.1)
        self.assertIsNone(e.ns.Ride.scene)
        self.assertEqual(e.errors(), [])


class FlightGame(unittest.TestCase):
    """A game on the way, under the flight bar: offered, played with its own buttons, put away at high altitude."""

    NODES = ["Stormwind, Elwynn", "Booty Bay, Stranglethorn", "Ironforge, Dun Morogh"]

    def env(self, db=None, faction=None):
        e = Env(db=db)
        if faction:
            e.lua.execute('UnitFactionGroup = function() return "%s", "%s" end' % (faction, faction))
        e.ns.FlightGame.random = lambda: 0.5
        return e

    def fly(self, e):
        e.mock.takeFlight(e.lua.table_from(self.NODES), 1, 2)
        e.mock.advance(0.6)
        e.update(0.1)

    def press(self, e, key, tag="FlightGame"):
        e.g["ControllerCamHUD_Key_%s_%s" % (tag, key)].scripts.OnClick()

    def test_offered_on_a_flight_one_button_until_you_start(self):
        e = self.env()
        G, ov = e.ns.FlightGame, e.mock.overrides
        self.assertTrue(e.db.flightGame)                                     # offered by default
        e.update(1)
        self.assertEqual(G.state, "off")                                     # on the ground: nothing at all
        self.assertIsNone(ov.PAD4)
        self.fly(e)
        self.assertEqual(G.state, "offered")
        self.assertEqual(ov.PAD4, "CLICK ControllerCamHUD_Key_FlightStart_PAD4:LeftButton")   # Y, only
        self.assertIsNone(ov.PAD1)
        self.assertIsNone(ov.PAD3)
        self.assertTrue(G.hint.shown)
        self.assertIn("a game on the way", plain(G.hint.text.text))
        self.assertFalse(G.frame.shown)                                      # not started: no lane
        self.press(e, "PAD4", "FlightStart")                                 # Y: play
        self.assertEqual(G.state, "playing")
        self.assertTrue(G.frame.shown)
        self.assertFalse(G.hint.shown)
        self.assertEqual(ov.PAD1, "CLICK ControllerCamHUD_Key_FlightGame_PAD1:LeftButton")    # A flaps
        self.assertEqual(ov.PAD3, "CLICK ControllerCamHUD_Key_FlightGame_PAD3:LeftButton")    # X nets
        self.assertEqual(ov.PAD4, "CLICK ControllerCamHUD_Key_FlightGame_PAD4:LeftButton")    # Y high altitude
        self.assertIsNone(ov.PAD2)                                           # B stays the game's
        self.assertTrue(e.g.ControllerCamHUD_Flight.shown)                   # under the flight bar
        e.update(G.INTRO + 0.5)
        self.assertIn("flap", plain(G.frame.lines[1].text))
        self.assertEqual(e.errors(), [])

    def test_played_mid_screen_over_the_rider_clear_of_the_zone_names(self):
        e = self.env()
        G = e.ns.FlightGame
        self.fly(e)
        bar = e.g.ControllerCamHUD_Flight.bar
        self.assertTrue(e.same(G.hint.points[1][2], bar))                  # the offer: under the flight bar
        self.press(e, "PAD4", "FlightStart")
        point = G.frame.points[1]
        self.assertEqual((point[1], point[3], point[4]), ("CENTER", "CENTER", 0))
        self.assertTrue(e.same(point[2], e.g.UIParent))                      # the lane: the middle of the screen,
        self.assertAlmostEqual(point[5], G.Y / G.SCALE)                      # (in its own, larger units)
        self.assertLessEqual(G.Y, 0)                                         # over you on your mount
        self.assertEqual(G.frame.scale, G.SCALE)
        self.assertGreaterEqual(G.SCALE, 1.25)                               # a quarter to a half larger
        self.assertLessEqual(G.SCALE, 1.5)
        screen = e.g.UIParent.cy * 2
        zone_names_lowest = screen / 2 - 0.35 * screen                       # (the game's zone text: 0.2-0.35 down)
        self.assertLess(G.Y + G.H / 2 * G.SCALE, zone_names_lowest)          # its top stays under them
        self.assertTrue(e.g.ControllerCamHUD_Flight.shown)                   # and the flight bar stays at the top
        self.press(e, "PAD4")
        self.assertTrue(e.same(G.hint.points[1][2], bar))                    # away: the line is under the bar again
        self.assertEqual(e.errors(), [])

    def test_high_altitude_puts_it_away_and_brings_it_back(self):
        e = self.env()
        G, ov = e.ns.FlightGame, e.mock.overrides
        self.fly(e)
        self.press(e, "PAD4", "FlightStart")
        e.update(3)
        G.gold = 7
        clock = G.clock
        self.press(e, "PAD4")                                                # Y: high altitude
        self.assertEqual(G.state, "paused")
        self.assertFalse(G.frame.shown)                                      # the game is away,
        self.assertTrue(e.g.ControllerCamHUD_Flight.shown)                   # the flight bar stays
        self.assertIsNone(ov.PAD1)                                           # and A and X are the game's again
        self.assertIsNone(ov.PAD3)
        self.assertEqual(ov.PAD4, "CLICK ControllerCamHUD_Key_FlightStart_PAD4:LeftButton")
        self.assertIn("7 flight gold", plain(G.hint.text.text))
        e.update(5)
        self.assertEqual(G.clock, clock)                                     # nothing moves while away
        self.press(e, "PAD4", "FlightStart")                                 # Y again: back where it was
        self.assertEqual(G.state, "playing")
        self.assertEqual(G.gold, 7)
        self.assertEqual(ov.PAD1, "CLICK ControllerCamHUD_Key_FlightGame_PAD1:LeftButton")
        e.cmd("flightplay")
        self.assertEqual(G.state, "paused")                                  # the command does the same
        self.assertEqual(e.errors(), [])

    def test_flap_up_and_sink_back_held_in_by_the_lane(self):
        e = self.env()
        G = e.ns.FlightGame
        self.fly(e)
        self.press(e, "PAD4", "FlightStart")
        y = G.y
        e.update(0.5)
        self.assertLess(G.y, y)                                              # it sinks on its own
        e.update(3)
        self.assertEqual(G.y, G.EDGE)                                        # down to the lane's bottom, no further
        self.press(e, "PAD1")                                                # A: a flap
        e.update(0.2)
        self.assertGreater(G.y, G.EDGE + 10)
        for _ in range(30):
            self.press(e, "PAD1")
            e.update(0.1)
        self.assertLessEqual(G.y, G.H - G.EDGE)                              # and the top holds it in
        self.assertEqual(e.errors(), [])

    def test_a_net_grounds_a_rider_for_flight_gold(self):
        e = self.env(faction="Horde")
        G = e.ns.FlightGame
        self.fly(e)
        self.press(e, "PAD4", "FlightStart")
        G.things = e.lua.table()
        G.nextThing = 999
        G.y, G.vy = 42, 0
        r = e.lua.table(x=G.X + 60, y=42, base=42, speed=0, race="Human", female=False, mount="gryphon", phase=0)
        G.riders = e.lua.table_from([r])
        G.nextRider = 999
        self.press(e, "PAD3")                                                # X: a net
        self.assertEqual(G.fired, 1)
        self.press(e, "PAD3")
        self.assertEqual(G.fired, 1)                                         # (one at a time)
        for _ in range(10):
            G.y, G.vy = 42, 0
            e.update(0.05)
        self.assertTrue(r.down)                                              # grounded, not slain
        self.assertEqual(G.grounded, 1)
        self.assertEqual(G.gold, 1)
        self.assertEqual(e.db.flightGold, 1)                                 # kept, for later
        self.assertEqual(e.db.flightGameBest, 1)
        self.assertIn("1 flight gold", plain(G.frame.score.text))
        self.assertIn("Grounded", plain(G.frame.word.text))
        rt = G.riderTex[1]
        self.assertTrue(rt.chute.shown)                                      # down under a parachute
        self.assertTrue(rt.net.shown)
        self.assertEqual(rt.mount.texture, e.ns.Flights.MOUNTS.gryphon)      # the other side's mount
        y = r.y
        e.update(0.5)
        self.assertLess(r.y, y)                                              # floating down
        e.update(5)
        self.assertEqual(len(G.riders), 0)                                   # and gone below
        self.assertEqual(e.errors(), [])

    def test_a_run_of_catches_is_worth_more_and_a_bump_ends_it(self):
        e = self.env()
        G = e.ns.FlightGame
        self.fly(e)
        self.press(e, "PAD4", "FlightStart")
        for _ in range(3):
            G.Ground(G, e.lua.table(x=100, y=40))
        self.assertEqual(G.gold, 1 + 2 + 3)
        lives = G.lives
        G.y = 30
        G.things = e.lua.table_from([e.lua.table(kind="tree", x=G.X, top=60, w=32)])   # flown into a treetop
        G.Step(G, 0.01)
        self.assertEqual(G.streak, 0)
        self.assertEqual(G.lives, lives - 1)                                 # a life,
        self.assertIn("Bumped! Lives left: %d" % (lives - 1), plain(G.word))
        self.assertGreater(G.dazed, 0)
        self.assertFalse(G.Fire(G))                                          # the net gun fogged a moment
        e.update(G.DAZED + 0.1)
        G.cool = 0
        self.assertTrue(G.Fire(G))
        self.assertEqual(G.gold, 6)                                          # and no gold taken
        self.assertEqual(e.errors(), [])

    def test_a_taller_sky_of_treetops_and_zeppelins_that_vary_with_always_a_way_past(self):
        import random
        e = self.env()
        G = e.ns.FlightGame
        self.assertGreaterEqual(G.H, 120)                                    # taller than the old 84
        rnd = random.Random(7)
        G.random = lambda: rnd.random()
        G.things = e.lua.table()
        kinds, trees, zeps, pairs = set(), [], [], 0
        for _ in range(300):
            G.things = e.lua.table()
            G.Spawn(G)
            things = list(G.things.values())
            pairs += len(things) == 2
            for th in things:
                kinds.add(th.kind)
                (trees if th.kind == "tree" else zeps).append(th)
                th.x = G.X                                                   # right where your mount flies:
            free = [y for y in range(G.EDGE, G.H - G.EDGE + 1)
                    if not any(G.Touches(th, y) for th in things)]
            self.assertTrue(free, [(th.kind, th.top, th.y, th.w) for th in things])   # always a way past
        self.assertEqual(kinds, {"tree", "zeppelin"})
        self.assertGreater(pairs, 50)                                        # a treetop with a zeppelin over it
        tops = [th.top for th in trees]
        self.assertGreater(max(tops) - min(tops), 40)                        # tall trees and short ones
        widths = [th.w for th in zeps]
        self.assertGreater(max(widths) - min(widths), 20)                    # big zeppelins and small ones
        heights = [th.y for th in zeps]
        self.assertGreater(max(heights) - min(heights), 60)                  # at all heights
        # and how far apart they come varies too
        e.lua.execute("flight_spawns = {}")
        e.lua.eval("function(G) local old = G.Spawn; G.Spawn = function(self) flight_spawns[#flight_spawns + 1] = self.clock; return old(self) end end")(G)
        G.EVENT_FIRST = 9999                                                 # (no escort or raid in the way)
        self.fly(e)
        self.press(e, "PAD4", "FlightStart")
        for _ in range(600):
            G.y, G.vy, G.lives = G.H / 2, 0, 99                              # (never shot down here)
            e.update(0.1, step=0.1)
        times = list(e.g.flight_spawns.values())
        self.assertGreater(len(times), 15)
        gaps = [b - a for a, b in zip(times, times[1:])]
        self.assertGreater(max(gaps) - min(gaps), 1)
        self.assertGreaterEqual(min(gaps), G.SPACING[1] - 0.15)
        self.assertGreater(G.bumps, 0)                                       # (flying straight on, it bumps)
        drawn = {t.texture for t in G.thingTex.values() if t.shown}
        self.assertTrue(drawn <= {G.ART.tree, G.ART.zeppelin, G.ART.Horde, G.ART.Alliance} and drawn, drawn)
        self.assertEqual(e.errors(), [])

    def test_how_to_play_shows_as_a_run_starts(self):
        e = self.env()
        G = e.ns.FlightGame
        self.fly(e)
        self.press(e, "PAD4", "FlightStart")
        e.update(0.2)
        lines = G.frame.lines
        point = lines[1].points[1]
        self.assertEqual((point[1], point[3]), ("TOP", "BOTTOM"))            # under the lane, not over the game
        self.assertTrue(e.same(point[2], G.frame))
        self.assertTrue(lines[3].shown)
        text = " ".join(plain(lines[i].text) for i in (1, 2, 3))
        for words in ("flap", "dodge treetops, zeppelins, nets and fire", "net riders for flight gold", "high altitude",
                      "Clear a round to bank its gold", "upgrades"):
            self.assertIn(words, text)
        e.update(2)
        self.assertEqual(len(G.things), 0)                                   # time to read before the first one
        e.update(G.INTRO)
        self.assertFalse(lines[3].shown)                                     # then the buttons and the upgrade
        self.assertIn("flap", plain(lines[1].text))
        self.assertIn("gold to spend", plain(lines[2].text))
        self.press(e, "PAD4")                                                # high altitude,
        self.press(e, "PAD4", "FlightStart")                                 # and back: a reminder
        e.update(0.2)
        self.assertTrue(lines[3].shown)
        e.update(G.AGAIN)
        self.assertFalse(lines[3].shown)
        self.assertEqual(e.errors(), [])

    def test_clouds_are_only_scenery_and_the_art_is_our_own(self):
        e = self.env()
        G = e.ns.FlightGame
        self.fly(e)
        self.press(e, "PAD4", "FlightStart")
        self.assertEqual(len(G.clouds), G.CLOUDS)
        c = G.clouds[1]
        G.y, G.vy = c.y, 0
        G.things = e.lua.table()
        G.Step(G, 0.01)
        self.assertEqual(G.bumps, 0)                                         # flying through a cloud is fine
        e.update(0.1)
        self.assertTrue(G.cloudTex[1].shown)
        self.assertEqual(G.cloudTex[1].texture, G.ART.cloud)
        for path in G.ART.values():
            name = path.split("\\")[-1] + ".tga"
            self.assertTrue(os.path.isfile(os.path.join(HUD, "Media", name)), name)
        e.cmd("reducemotion on")
        x = G.clouds[1].x
        e.update(1)
        self.assertEqual(G.clouds[1].x, x)                                   # with fewer animations: still
        self.assertEqual(e.errors(), [])

    def play(self, e):
        self.fly(e)
        self.press(e, "PAD4", "FlightStart")
        G = e.ns.FlightGame
        G.things, G.riders, G.foes = e.lua.table(), e.lua.table(), e.lua.table()
        G.nextThing = G.nextRider = G.nextEvent = 9999
        return G

    def test_upgrades_are_bought_with_lb_and_rb_and_say_what_they_do_in_numbers(self):
        e = self.env(db="{ flightGold = 100 }")
        G, ov = e.ns.FlightGame, e.mock.overrides
        self.play(e)
        self.assertEqual(ov.PADLSHOULDER, "CLICK ControllerCamHUD_Key_FlightGame_PADLSHOULDER:LeftButton")
        self.assertEqual(ov.PADRSHOULDER, "CLICK ControllerCamHUD_Key_FlightGame_PADRSHOULDER:LeftButton")
        e.update(G.INTRO + 0.2)
        shop = plain(G.frame.lines[2].text)
        self.assertIn("Wider net 1: net reach 13 to 16, 40 gold", shop)      # what is on offer, what it does, its
        self.assertIn("100 gold to spend", shop)                             # price, and what you have
        self.assertGreaterEqual(sum(u.cost[1] for u in G.UPGRADES.values()), 120)   # (not had for a few riders)
        self.press(e, "PAD3")
        e.update(0.05)
        small = G.netTex[1].width
        hit = G.Hit()
        self.press(e, "PADRSHOULDER")                                        # RB: bought
        self.assertEqual(e.db.flightGameUpgrades.net, 1)
        self.assertEqual(G.Hit(), hit + 3)
        self.assertIn("Wider net 1: net reach 13 to 16", plain(G.word))      # and what it did
        self.assertEqual((e.db.flightGold, e.db.flightGoldSpent, G.Wallet()), (100, 40, 60))   # earned stays earned
        G.cool = 0
        self.press(e, "PAD3")
        e.update(0.05)
        self.assertGreater(G.netTex[1].width, small)                         # the net drawn is wider: you see it
        self.press(e, "PADLSHOULDER")                                        # LB: the next one, and what it does
        self.assertIn("Quick reload", plain(G.word))
        self.assertIn("fire again sooner", plain(G.word))
        self.assertIn("3 to 4 nets at once", plain(G.word))
        self.press(e, "PADRSHOULDER")
        self.assertEqual((G.Nets(), round(G.Reload(), 2)), (4, 0.42))
        self.press(e, "PADRSHOULDER")
        self.assertEqual(e.db.flightGameUpgrades.reload, 1)                  # not bought,
        self.assertIn("60 more flight gold", plain(G.word))                  # and why
        e.db.flightGameUpgrades.reload = 3
        self.press(e, "PADRSHOULDER")
        self.assertIn("fully upgraded", plain(G.word))
        self.press(e, "PADLSHOULDER")                                        # Thick harness: a life, at once
        self.assertIn("3 to 4 lives", plain(G.word))
        e.db.flightGold = 160
        lives = G.lives
        self.press(e, "PADRSHOULDER")
        self.assertEqual((G.Lives(), G.lives), (4, lives + 1))
        self.assertIn("spent 140", G.Describe())
        self.assertEqual(e.errors(), [])

    def net_on_you(self, e, G):
        G.foes = e.lua.table_from([e.lua.table(x=G.X + 4, y=G.y, vy=0, at="you", spin=0)])
        G.Step(G, 0.01)

    def test_a_hit_costs_a_life_and_out_of_lives_you_are_shot_down(self):
        e = self.env(db="{ flightGold = 20 }")
        G, ov = e.ns.FlightGame, e.mock.overrides
        self.play(e)
        self.assertEqual((G.lives, G.roundNo), (G.LIVES, 1))
        e.update(0.05)
        self.assertEqual(sum(1 for t in G.lifeTex.values() if t.shown), G.LIVES)   # your lives, top left,
        self.assertIn("Round 1", plain(G.frame.roundText.text))              # and the round
        G.Earn(G, 9)
        self.assertEqual(G.Wallet(), 20)                                     # (this round's gold: not banked yet)
        G.y, G.vy = 60, 0
        self.net_on_you(e, G)
        self.assertEqual(G.lives, G.LIVES - 1)                               # a net on you: a life
        self.assertIn("Netted! Lives left: 2", plain(G.word))
        self.assertEqual(G.gold, 9)                                          # (and no gold)
        self.net_on_you(e, G)
        self.assertEqual(G.lives, G.LIVES - 1)                               # a moment's grace after it
        self.assertEqual(len(G.foes), 1)                                     # (it flies through)
        G.grace = 0
        self.net_on_you(e, G)
        G.grace = 0
        G.things = e.lua.table_from([e.lua.table(kind="tree", x=G.X, top=90, w=40)])
        G.Step(G, 0.01)                                                      # the last life:
        self.assertEqual((G.lives, G.phase), (0, "down"))                    # shot down,
        self.assertEqual(e.db.flightGoldLost, 9)                             # the round's gold lost,
        self.assertEqual(e.db.flightGold, 29)                                # (earned stays earned)
        self.assertEqual(G.Wallet(), 20)                                     # what was banked stays yours
        e.update(0.1)
        self.assertIn("Shot down! 9 unbanked gold lost", plain(G.frame.banner.text))
        self.assertIn("Shot down in round 1 with 9 flight gold", plain(G.frame.lines[1].text))
        self.assertIn("fly again from round 1", plain(G.frame.lines[2].text))
        self.assertEqual(ov.PAD1, "CLICK ControllerCamHUD_Key_FlightGame_PAD1:LeftButton")
        self.assertEqual(G.routeBest, 0)
        self.assertEqual(e.db.flightGameRoutes[G.route], 9)                  # the run's gold is its score
        self.press(e, "PAD1")
        self.assertEqual(G.phase, "down")                                    # (not at once: a moment first)
        e.update(G.DOWN_WAIT + 0.1)
        self.press(e, "PAD1")                                                # A: again, from round one
        self.assertEqual((G.phase, G.lives, G.roundNo, G.gold), ("open", G.LIVES, 1, 0))
        self.assertIn("Round 1", plain(G.banner))
        self.assertEqual(G.state, "playing")
        self.assertEqual(e.errors(), [])

    def test_a_cleared_round_banks_its_gold_and_gives_a_life_back(self):
        e = self.env()
        G = e.ns.FlightGame
        self.play(e)
        G.lives = 1
        G.Earn(G, 14)
        self.assertEqual(G.Wallet(), 0)
        G.BeginEvent(G, "boss")
        G.boss.time = G.BOSS_TIME + 0.1                                      # it sails off,
        for _ in range(100):
            G.Step(G, 0.1)
            if G.phase == "open":
                break
        self.assertEqual(G.phase, "open")
        self.assertEqual((G.roundNo, G.lives, G.purse), (2, 2, 0))           # the round cleared: a life back,
        self.assertEqual(G.Wallet(), 14)                                     # its gold banked
        self.assertIn("Round 1 cleared: 14 gold banked", plain(G.banner))
        G.lives = 0
        G.ShotDown(G)
        self.assertEqual(G.Wallet(), 14)                                     # (banked: kept when shot down)
        G.roundNo = 1
        hard = G.Hard(G)
        G.roundNo = 4
        self.assertGreater(G.Hard(G), hard)                                  # each round a little harder
        G.roundNo = 50
        self.assertEqual(G.Hard(G), G.HARDEST)
        G.roundNo = 5                                                        # the second raid: tougher, and weaving
        G.phase = "open"
        G.BeginEvent(G)
        self.assertEqual(G.phase, "boss")
        self.assertGreater(G.boss.hp, G.BOSS_HP)
        self.assertEqual(G.boss.patterns, len(G.PATTERNS))
        G.Earn(G, 3)
        e.mock.landFlight("Booty Bay")                                       # landed mid-round: not your doing,
        self.assertEqual(G.Wallet(), 17)                                     # the round's gold is kept
        self.assertEqual(e.errors(), [])

    def test_their_zeppelin_throws_straight_curving_in_a_fan_and_weaving(self):
        e = self.env(faction="Horde")
        G = e.ns.FlightGame
        self.play(e)
        G.lives = 99
        G.BeginEvent(G, "boss")
        boss = G.boss
        boss.x, boss.y, boss.patterns = G.W - 64, 70, 4
        paths = {}
        for i, kind in enumerate(G.PATTERNS.values()):
            G.foes = e.lua.table()
            G.y, G.vy = 70, 0
            seq = [(i + 0.5) / 4, 0.9]                                       # (which, and which way it bends)
            G.random = lambda seq=seq: seq.pop(0) if seq else 0.5
            boss.shot = 0
            G.Step(G, 0.001)
            self.assertEqual(boss.last, kind)
            paths[kind] = [[] for _ in range(len(G.foes))]
            G.grace, boss.shot = 99, 99                                      # (nothing taken while we watch)
            for _ in range(140):
                G.y, G.vy = 70, 0
                for j, f in enumerate(G.foes.values()):
                    if j < len(paths[kind]):
                        paths[kind][j].append((f.x, f.y))
                G.Step(G, 0.01)
            G.grace = 0
        self.assertEqual(len(paths["fan"]), 3)                               # three in a fan,
        ends = sorted(p[-1][1] for p in paths["fan"])
        self.assertGreater(ends[2] - ends[0], 50)                            # spread above and below you
        self.assertEqual(len(paths["aimed"]), 1)
        straight = paths["aimed"][0]
        self.assertTrue(all(abs(y - 70) < 1 for _, y in straight))           # straight at you
        lob = paths["lob"][0]
        self.assertGreater(max(abs(y - 70) for _, y in lob), 15)             # curving away,
        near = min(lob, key=lambda p: abs(p[0] - G.X))
        self.assertLess(abs(near[1] - 70), 6)                                # and back in on you
        wave = [y for _, y in paths["wave"][0]]
        swings = sum(1 for a, b, c in zip(wave, wave[1:], wave[2:]) if (b - a) * (c - b) < 0)
        self.assertGreaterEqual(swings, 2)                                   # weaving up and down
        self.assertEqual(e.errors(), [])

    def test_a_drake_breathes_a_sweep_of_fire_and_curving_fireballs(self):
        e = self.env()
        G = e.ns.FlightGame
        self.play(e)
        G.roundNo = 3
        G.BeginEvent(G)                                                      # the third round: a drake
        d = G.drake
        self.assertEqual(G.phase, "drake")
        self.assertIn("A drake", plain(G.word))
        d.x, d.wait = G.W - 56, 0
        G.y, G.vy = 70, 0
        G.Step(G, 0.01)
        self.assertIsNotNone(d.inhale)                                       # it draws breath first,
        e.update(0.05)
        self.assertTrue(G.drakeTex.shown)
        self.assertEqual(G.drakeTex.texture, G.ART.drake)
        self.assertTrue(G.drakeGlow.shown)                                   # its mouth glowing: time to get clear
        self.assertEqual(len(G.fires), 0)
        G.grace = 99
        for _ in range(int(G.DRAKE_INHALE / 0.02) + 2):
            G.y, G.vy = 70, 0
            G.Step(G, 0.02)
        self.assertIsNotNone(d.breath)                                       # then a breath,
        for _ in range(int(G.DRAKE_BREATH / 0.02) + 2):
            G.y, G.vy = 70, 0
            G.Step(G, 0.02)
        heights = [f.vy for f in G.fires.values()]
        self.assertGreater(len(heights), 8)
        self.assertGreater(max(heights) - min(heights), 30)                  # sweeping across where you were
        G.fires = e.lua.table()
        d.wait = 0
        G.Step(G, 0.01)
        for _ in range(int(G.DRAKE_INHALE / 0.02) + 2):
            G.Step(G, 0.02)
        balls = list(G.fires.values())
        self.assertEqual(len(balls), 2)                                      # two fireballs,
        self.assertTrue(all(b.big for b in balls))
        self.assertEqual(sorted(b.ay > 0 for b in balls), [False, True])     # bending in from above and below
        G.grace = 0
        lives = G.lives
        G.fires = e.lua.table_from([e.lua.table(x=G.X + 2, y=G.y, vy=0, t=0)])
        G.Step(G, 0.01)
        self.assertEqual(G.lives, lives - 1)                                 # its fire costs a life
        self.assertIn("Scorched", plain(G.word))
        G.grace = 99
        gold = G.gold
        for _ in range(d.full):                                              # netted enough, it flees
            G.nets = e.lua.table_from([e.lua.table(x=d.x - 2, y=d.y, spin=0)])
            G.Step(G, 0.001)
        self.assertTrue(d.fled)
        self.assertEqual(G.gold, gold + G.DRAKE_BONUS)
        for _ in range(100):
            G.Step(G, 0.1)
            if G.phase == "open":
                break
        self.assertEqual((G.phase, G.roundNo), ("open", 4))                  # and the round is cleared
        self.assertEqual(e.errors(), [])

    def test_your_sides_zeppelin_crosses_keep_their_nets_off_it(self):
        e = self.env(faction="Horde")
        G = e.ns.FlightGame
        self.play(e)
        G.BeginEvent(G)                                                      # round one: an escort
        ship = G.ship
        self.assertEqual((G.phase, ship.side), ("escort", "Horde"))          # your side's own
        self.assertIn("keep their nets off it", plain(G.word))
        ship.x = 150
        r = e.lua.table(x=230, y=60, base=60, speed=0, race="Human", female=False, mount="gryphon", phase=0)
        G.riders = e.lua.table_from([r])
        G.nextRider = 9999
        G.Step(G, 0.01)
        self.assertTrue(r.threw)                                             # their rider nets at it
        self.assertEqual(len(G.foes), 1)
        self.assertEqual(G.foes[1].at, "ship")
        G.riders = e.lua.table()
        G.nets = e.lua.table_from([e.lua.table(x=G.foes[1].x - 1, y=G.foes[1].y, spin=0)])
        G.Step(G, 0.01)
        self.assertEqual(len(G.foes), 0)                                     # a net of yours stops a net of theirs
        G.foes = e.lua.table_from([e.lua.table(x=ship.x + 4, y=ship.y, vy=0, at="ship", spin=0)])
        G.Step(G, 0.01)
        self.assertEqual(ship.hits, 1)                                       # one got through
        e.update(1)
        self.assertTrue(G.shipTex.shown)
        self.assertTrue(G.shipTex.texture.endswith("zeppelin_horde"))        # in the Horde's colours,
        self.assertEqual(G.shipBadge.texture, G.BADGE.Horde)                 # with the game's own badge
        gold = G.gold
        ship.x = -ship.w / 2 + 0.1
        G.riders = e.lua.table()
        G.Step(G, 0.1)
        self.assertEqual(G.phase, "open")                                    # across:
        self.assertEqual(G.gold, gold + G.ESCORT_BONUS - G.ESCORT_LOSS)      # paid, less the net that got through
        self.assertIn("Seen safely across", plain(G.word))
        self.assertEqual(G.roundNo, 2)                                       # the round cleared
        self.assertEqual(e.errors(), [])

    def test_their_zeppelin_nets_at_you_net_it_down_or_it_sails_off(self):
        e = self.env(faction="Horde")
        G = e.ns.FlightGame
