        self.assertEqual(B.Step(13, "down", 15, 10), "bags")         # the last row: down to the bag row
        self.assertEqual(B.Step(12, "up", 15, 10), 2)
        self.assertEqual(B.Step(2, "up", 15, 10), 2)
        e = self.env()
        e.g.ToggleAllBags()
