        e.mock.put(-1, 1, T(id=301, name="Silk Cloth", quality=1, price=40, count=20, **{"class": 7}))
        e.mock.openBank(True)
        e.g.OpenAllBags()
        B, o, m = e.ns.Bags, e.mock.overrides, e.g.GamepadMode.FrameControlsManager
        e.update(0.05)
        self.assertTrue(B.hasPad)                                    # the game's focus on its bags: ours
        self.assertEqual(B.view, "bags")
        self.assertIn("PADLTRIGGER or PADRTRIGGER: to the bank", plain(B.frame.legend.text))
        # side by side in the game's order (LT its bags, RT its bank): ours on the left, the bank to its right
        bank = e.g.BankFrame
        self.assertTrue(B.sided)
        self.assertEqual(bank.points[1][1], "TOPLEFT")
        self.assertTrue(e.same(bank.points[1][2], B.frame))
        self.assertEqual(bank.points[1][3], "TOPRIGHT")
        self.assertEqual(B.frame.points[1][1], "TOPLEFT")
        self.press(e, "PADBACK")                                     # the back button: the bank in this window
        self.assertEqual(B.view, "bank")
        self.assertTrue(B.hasPad)
        e.mock.keysDown.PADLTRIGGER = True                           # LT: the game moves its focus to its bank
        m.focusedFrame = e.g.BankFrame
        e.update(0.25)
        self.assertFalse(B.hasPad)                                   # its window's own buttons now
        self.assertEqual(B.view, "bags")                             # (the bank is there, beside: ours is your bags)
        for key in ("PAD1", "PAD2", "PAD3", "PADDUP", "PADDRIGHT"):
            self.assertIsNone(o[key], key)
        self.assertIn("back to bags", plain(B.frame.legend.text))
        e.mock.keysDown.PADLTRIGGER = False
        e.update(0.05)
        self.assertFalse(B.hasPad)                                   # (never toggled out of step)
        slot = e.g.CreateFrame("Button", "BankFrameItem2", e.g.BankFrame)   # the game's cursor on its 2nd slot:
        slot.GetBagID = e.lua.eval("function() return -1 end")
        slot.id = 2
        slot.GetID = e.lua.eval("function(self) return self.id end")
        e.mock.put(-1, 2, T(id=302, name="Iron Ore", quality=1, price=25, count=13, **{"class": 7}))
        e.g.GameTooltip.SetOwner(e.g.GameTooltip, slot, "ANCHOR_RIGHT")   # (its tooltip, the game's)
        e.g.GameTooltip.Show(e.g.GameTooltip)
        e.update(0.05)
        self.assertEqual(o.PAD3, "CLICK ControllerCamHUD_BagUse:LeftButton")   # X: into your bags, from there
        self.assertEqual(e.g.ControllerCamHUD_BagUse.attrs.macrotext, "/use -1 2")
        self.assertIsNone(o.PADDUP)                                  # (the rest stays the window's)
        self.assertIn("PAD3 To bags", plain(B.frame.legend.text))
        e.mock.keysDown.PADRTRIGGER = True                           # RT: back to its bags, so ours
        m.focusedFrame = e.g.ContainerFrameCombinedBags
        e.update(0.25)
        self.assertTrue(B.hasPad)
        self.assertEqual(o.PADDUP, "CLICK ControllerCamHUD_BagNav_PADDUP:LeftButton")
        e.mock.keysDown.PADRTRIGGER = False
        e.update(0.05)
        self.assertEqual(B.view, "bags")
        e.mock.openBank(False)                                       # the bank closes: ours back where it was
        e.update(0.05)
        self.assertFalse(B.sided)
        self.assertEqual(B.frame.points[1][1], "TOPRIGHT")           # (by its top: it fills downward)
        self.assertTrue(e.same(B.frame.points[1][2], B.spot))
        self.assertEqual(e.errors(), [])

