class HealerFrames(unittest.TestCase):
    """The healer's look: the party beside your character with the buttons that target them, slim raid tiles,
    and on each only how much healing they need, a debuff you can cure, and whether they are in range."""

    # the Gamepad UI's friendly targeting bar: hold LB, and each D-pad direction is a party member
    BAR = """function(units)
        local bar = CreateFrame("Frame", "GamepadMainActionBarFramePageUnitFriendlyTargetingActionBar", UIParent)
        for field, unit in pairs(units) do
            local b = CreateFrame("CheckButton", nil, bar)
            b.attrs.unit = unit
            bar[field] = b
        end
        return bar
    end"""

    def env(self, holy=True, mode=None, combat=False, setup=None, **kw):
        db = "{ v = 5%s }" % ("" if mode is None else ", healerFrames = %d" % mode)
        e = Env(db=db, setup=setup, **kw)
        e.mock.units.player["class"], e.mock.units.player.level = "PALADIN", 45
        e.lua.eval(SpecUpgrades.TALENTS)(e.mock, True)
        e.lua.execute("TALENTS.groups = { { 31, 5, 0 } }")
        if not holy:
            e.lua.execute("TALENTS.groups = { { 0, 5, 31 } }")              # retribution
        e.mock.state.combat = combat
        e.mock.fire("ACTIVE_TALENT_GROUP_CHANGED")
        return e

    def member(self, e, i=1, **kw):
        data = e.lua.table(name="Friend%d" % i, health=800, healthMax=1000, isPlayer=True, **{"class": "MAGE"})
        for k, v in kw.items():
            data[k] = v
        e.mock.setUnit("party%d" % i, data)
        e.update(0.3)
        return data

    def test_a_healing_spec_is_the_tree_with_the_most_points(self):
        G = self.env().ns.Group
        self.assertEqual(G.HealingSpec(), (True, 1))                         # holy
        e = self.env(holy=False)
        self.assertEqual(e.ns.Group.HealingSpec(), (False, 3))                # retribution: not a healer's
        self.assertFalse(e.ns.Group.Wanted())
        self.assertTrue(self.env(holy=False, mode=3).ns.Group.Wanted())      # Always
        self.assertFalse(self.env(mode=1).ns.Group.Wanted())                 # Off
        e = self.env(holy=False)                                             # respecced to holy: asked again
        e.lua.execute("TALENTS.groups = { { 31, 5, 0 } }")
        e.mock.fire("PLAYER_TALENT_UPDATE")
        self.assertTrue(e.ns.Group.Wanted())
        defs = [d for d in e.ns.settings.values() if d.key == "healerFrames"]
        self.assertEqual(list(defs[0].choices.values()), ["Off", "In a healing spec", "Always"])
        self.assertEqual(e.db.healerFrames, 2)
        self.assertEqual(e.errors(), [])

    def test_the_party_sits_beside_your_character_with_its_buttons(self):
        e = self.env()
        e.lua.eval(self.BAR)(e.lua.table(dpadTopButton="party1", dpadRightButton="party2", faceBottomButton="player"))
        e.g.GamepadMainActionBarFramePageUnitFriendlyTargetingActionBar.dpadRightButton = None
        right = e.g.CreateFrame("CheckButton", "GamepadMainActionBarFramePageUnitFriendlyTargetingActionBarActionButton3")
        right.attrs.unit = "party2"                                          # (by its place: the third is right)
        self.member(e, 1)
        self.member(e, 2, health=1000)
        G = e.ns.Group
        self.assertTrue(G.ownParty)                                          # ours, though the game shows its own
        self.assertEqual(G.arranged, "healer")
        x, y = e.ns.Numbers.Soon.Spot()[:2]
        point = list(G.partyMover.points[1].values())
        self.assertTrue(e.same(point[1], e.g.UIParent))
        self.assertEqual(point[:1] + point[2:5], ["RIGHT", "CENTER", x - 22, y])
        b1, h1 = G.party[1].button, G.party[1].h
        self.assertEqual((b1.width, b1.height), (150, 24))
        self.assertTrue(h1.shown)
        self.assertFalse(G.party[1].o.shown)
        self.assertEqual(h1.bind.text, "PADLSHOULDERPADDUP")                 # LB and up
        self.assertEqual(G.party[2].h.bind.text, "PADLSHOULDERPADDRIGHT")
        self.assertEqual(h1.name.text, "Friend1")
        self.assertEqual(h1.need.text, "-200")                               # how much they need
        self.assertEqual(G.party[2].h.need.text, "")                         # full: nothing to say
        # the name gives way to the need at its line's end, never under it (the mock measures text as 80 wide)
        line = 150 - 36 - 1 - 19
        self.assertEqual(G.party[2].h.name.width, line)
        self.assertEqual(h1.name.width, line - 84)
        self.assertEqual(h1.bind.width, 36)                                  # the button keeps to its column
        self.assertEqual(h1.bind.wordWrap, False)
        self.assertFalse(e.ns.Group.overlays[e.g.PartyFrame.MemberFrame1] and
                         e.ns.Group.overlays[e.g.PartyFrame.MemberFrame1].shown)   # not twice
        self.assertEqual(e.g.PartyFrame.alpha, 0)
        self.assertIsNone(h1.power)                                          # nothing else: no power bar
        e.mock.units.party1.health = 300
        e.mock.fire("UNIT_HEALTH", "party1")
        self.assertEqual(h1.need.text, "-700")
        self.assertEqual(e.color(h1.health), e.theme("danger"))
        self.assertEqual(e.ns.RunCheck(False)[0], 0)
        e.cmd("healerframes 1")                                              # Off: back to the plain look
        e.update(0.3)
        self.assertFalse(G.ownParty)                                         # (the game shows its own here)
        self.assertFalse(h1.shown)
        self.assertTrue(e.ns.Group.overlays[e.g.PartyFrame.MemberFrame1].shown)
        self.assertEqual(e.errors(), [])

    def test_a_binding_of_the_games_own_when_the_bar_says_nothing(self):
        e = self.env()
        e.mock.bindings["TARGETPARTYMEMBER1"] = e.lua.table("SHIFT-PADDUP")
        self.member(e, 1)
        self.assertEqual(e.ns.Group.party[1].h.bind.text, "SHIFTPADDUP")
        self.assertEqual(e.errors(), [])

    def test_in_a_fight_the_party_is_not_moved(self):
        e = self.env(holy=False)
        self.member(e, 1)
        G = e.ns.Group
        self.assertNotEqual(G.arranged, "healer")
        e.mock.state.combat = True
        e.lua.execute("TALENTS.groups = { { 31, 5, 0 } }")
        e.mock.fire("PLAYER_TALENT_UPDATE")
        e.update(0.3)
        self.assertNotEqual(G.arranged, "healer")                            # secure frames: not in a fight
        e.mock.state.combat = False
        e.mock.fire("PLAYER_REGEN_ENABLED")
        e.update(0.3)
        self.assertEqual(G.arranged, "healer")
        self.assertTrue(G.party[1].h.shown)
        self.assertEqual(e.errors(), [])

    def test_only_a_debuff_you_can_cure_is_shown(self):
        e = self.env()
        self.member(e, 1, auras=e.lua.table(e.lua.table(icon=7, dispelName="Curse")))
        h = e.ns.Group.party[1].h
        self.assertFalse(h.cureButton.shown)                                 # a paladin cures no curse
        e.mock.units.party1.auras = e.lua.table(e.lua.table(icon=7, dispelName="Curse"),
                                                e.lua.table(icon=9, dispelName="Magic"))
        e.mock.fire("UNIT_AURA", "party1")
        self.assertTrue(h.cureButton.shown)
        self.assertEqual(h.cureButton.icon.texture, 9)
        self.assertEqual(h.cureButton.kind, "Magic")                         # edged in magic's blue
        self.assertEqual(e.mock.auraFilter, "HARMFUL|RAID")                  # the game's own: what you can dispel
        e.mock.units.party1.auras = e.lua.table()
        e.mock.fire("UNIT_AURA", "party1")
        self.assertFalse(h.cureButton.shown)
        e.lua.execute("IsPlayerSpell = function(id) return id == 1152 end")  # Purify only (no Cleanse yet)
        e.mock.fire("SPELLS_CHANGED")
        self.assertEqual(sorted(e.ns.Group.Cures().keys()), ["Disease", "Poison"])
        self.assertEqual(e.errors(), [])

    def test_the_games_own_icon_where_it_draws_them(self):
        e = self.env(setup=lambda env: setattr(env.mock, "auraContainer", True))
        self.member(e, 1)
        row = e.ns.Group.party[1].h.cureRow
        self.assertEqual(row.groups["1"].filter, "HARMFUL|RAID")
        self.assertTrue(row.enabled)
        self.assertEqual(row.unit, "party1")
        self.assertIsNotNone(row.groups["1"].icon.dispelTex)                 # edged in its kind's colour
        self.assertIsNone(row.groups["1"].icon.timeText)                     # the icon alone: no time, no stacks
        self.assertIsNone(row.groups["1"].icon.countText)
        self.assertEqual(e.errors(), [])

    def test_out_of_range_and_out_of_sight_are_dimmed(self):
        e = self.env()
        data = self.member(e, 1)
        h = e.ns.Group.party[1].h
        self.assertEqual(h.alpha, 1)
        data.far = True
        e.update(0.3)
        self.assertEqual(h.alpha, 0.4)
        e.lua.execute("UnitIsVisible = function(unit) return unit ~= 'party1' end")
        e.update(0.3)
        self.assertEqual(h.alpha, 0.25)
        self.assertEqual(h.need.text, "Too far")
        e.lua.execute("UnitIsVisible = function() return true end")
        data.far = False
        e.update(0.3)
        self.assertEqual((h.alpha, h.need.text), (1, "-200"))
        e.mock.units.target = data
        e.update(0.3)
        self.assertTrue(h.edge.shown)                                        # your target
        self.assertEqual(e.errors(), [])

    def test_raid_frames_wear_a_slim_tile(self):
        e = self.env()
        native = e.mock.raidFrame(1, "raid1")
        native.height = 36
        e.mock.setUnit("raid1", e.lua.table(name="Raider", health=600, healthMax=1000))
        e.update(0.3)
        G = e.ns.Group
        t = G.slim[native]
        self.assertTrue(t.shown)
        self.assertIsNone(G.overlays[native])
        p1, p2 = list(t.points[1].values()), list(t.points[2].values())
        self.assertTrue(e.same(p1[1], native) and e.same(p2[1], native))
        self.assertEqual(p1[:1] + p1[2:5], ["TOPLEFT", "TOPLEFT", 6, -5])        # a little inside
        self.assertEqual(p2[:1] + p2[2:5], ["BOTTOMRIGHT", "BOTTOMRIGHT", -6, 5])
        self.assertEqual(t.name.text, "Raider")
        self.assertEqual(t.need.text, "")                                    # the bar says it: no number
        self.assertEqual(t.name.width, 60 - 1)                               # the whole top line (the cure sits low)
        self.assertFalse(t.health.shadow.shown)                              # no shadow over the neighbours
        self.assertIsNone(t.bind)
        self.assertEqual(e.color(t.health), e.theme("caution"))
        e.mock.units.raid1.offline = True
        e.mock.fire("UNIT_CONNECTION", "raid1")
        self.assertEqual(t.need.text, "Offline")
        self.assertEqual(t.name.width, 10)                                   # (at its least)
        e.mock.units.raid1.offline = False
        e.mock.fire("UNIT_CONNECTION", "raid1")
        self.assertEqual(e.g.CompactRaidFrameContainer.alpha, 0)             # the game's keep their navigation
        e.cmd("healerframes 1")
        e.update(0.3)
        self.assertFalse(t.shown)
        self.assertTrue(G.overlays[native].shown)                            # the plain look again
        self.assertEqual(e.errors(), [])


class SpecGearKept(unittest.TestCase):
    """Gear for another spec of yours is never junk: a Holy paladin's Protection sword and shield stay."""

    def env(self, mode=None, sets=True):
        db = "{ v = 5, sell = { gear = true }%s }" % ("" if mode is None else ", upgradeSpecs = %d" % mode)
        e = Env(db=db)
        e.mock.units.player["class"], e.mock.units.player.level = "PALADIN", 45      # plate
        e.lua.eval(SpecUpgrades.TALENTS)(e.mock, True)
        e.g.TALENTS.groups[2] = e.lua.table(0, 31, 5)                    # holy on, protection the second
        T = e.lua.table

        def item(iid, name, loc, cls, sub, bag_slot=None, in_set=False, **stats):
            it = T(id=iid, name=name, quality=1, ilvl=30, price=50, loc=loc, sub=sub, inSet=in_set,
                   stats=T(**stats), **{"class": cls})
            if bag_slot:
                e.mock.put(0, bag_slot, it)
            else:
                e.mock["items"][iid] = it
        # what you wear for holy
        item(980, "Worn Plate of Wisdom", "INVTYPE_CHEST", 4, 4, ITEM_MOD_INTELLECT_SHORT=10, ITEM_MOD_STAMINA_SHORT=5)
        item(990, "Holy Mace", "INVTYPE_WEAPONMAINHAND", 2, 4, ITEM_MOD_INTELLECT_SHORT=10, ITEM_MOD_STAMINA_SHORT=4)
        item(991, "Tome of Light", "INVTYPE_HOLDABLE", 4, 0, ITEM_MOD_INTELLECT_SHORT=20)
        e.mock.worn[5], e.mock.worn[16], e.mock.worn[17] = 980, 990, 991
        # the tank set in your bags
        item(992, "Tank Sword", "INVTYPE_WEAPON", 2, 7, 1, sets, ITEM_MOD_STAMINA_SHORT=15,
             ITEM_MOD_STRENGTH_SHORT=6, ITEM_MOD_DAMAGE_PER_SECOND_SHORT=20)
        item(993, "Tank Shield", "INVTYPE_SHIELD", 4, 6, 2, sets, ITEM_MOD_STAMINA_SHORT=12, RESISTANCE0_NAME=1000)
        # protection chests: the best (not in a set), one nearly as good, and one plainly outclassed
        item(994, "Bulwark Plate", "INVTYPE_CHEST", 4, 4, 3, ITEM_MOD_STAMINA_SHORT=20, ITEM_MOD_STRENGTH_SHORT=4)
        item(995, "Spare Bulwark", "INVTYPE_CHEST", 4, 4, 4, ITEM_MOD_STAMINA_SHORT=19, ITEM_MOD_STRENGTH_SHORT=4)
        item(996, "Rusty Breastplate", "INVTYPE_CHEST", 4, 4, 5, ITEM_MOD_STAMINA_SHORT=6)
        if sets:
            e.lua.execute("""C_EquipmentSet = {
                GetEquipmentSetIDs = function() return { 4 } end,
                GetItemIDs = function(set) return { [16] = 992, [17] = 993, [5] = -1 } end,
                GetEquipmentSetInfo = function(set) return "Tank" end,
            }""")
        e.ns.Market.HasData = e.lua.eval("function() return true end")   # (the auction house has had its say)
        return e

    def verdict(self, e, iid):
        v = e.ns.Market.Verdict(iid)
        v = v if isinstance(v, tuple) else (v, None, None)
        return v[0], v[2] and v[2].why

    def junk(self, e, iid):
        return bool(e.ns.Bags.IsJunk(e.lua.table(id=iid, quality=1)))

    def sold(self, e):
        items, _ = e.ns.Vendor.Collect(e.ns.Vendor, "rules", None)
        smart = e.ns.Vendor.Recommend(e.ns.Vendor)
        return sorted(i.id for i in items.values()), sorted(i.id for i in smart.vendor.values())

    def test_the_tank_set_and_the_best_protection_chest_are_kept_with_a_reason(self):
        e = self.env()
        self.assertEqual(self.verdict(e, 992), ("keep", "in your equipment set Tank"))
        self.assertEqual(self.verdict(e, 993), ("keep", "in your equipment set Tank"))
        self.assertEqual(self.verdict(e, 994), ("keep", "your Protection gear"))   # the best you own for it
        rules, smart = self.sold(e)
        for iid in (992, 993, 994):
            self.assertNotIn(iid, rules)
            self.assertNotIn(iid, smart)
            self.assertFalse(self.junk(e, iid))
            self.assertFalse(e.ns.Vendor.Decide(e.ns.Vendor, iid, 1, 4, "rules", None, 4, "INVTYPE_CHEST", None))
        self.assertIn("your Protection gear", e.ns.Market.BestText(*e.ns.Market.Verdict(994)))
        self.assertEqual(e.errors(), [])

    def test_without_a_set_the_sword_and_shield_are_still_protection_gear(self):
        e = self.env(sets=False)
        self.assertEqual(self.verdict(e, 992)[0], "keep")
        self.assertEqual(self.verdict(e, 993)[0], "keep")
        self.assertIsNotNone(self.verdict(e, 992)[1])
        rules, smart = self.sold(e)
        self.assertNotIn(992, rules + smart)
        self.assertNotIn(993, rules + smart)
        self.assertEqual(e.errors(), [])

    def test_even_with_the_setting_on_current_spec_only_both_talent_groups_count(self):
        e = self.env(mode=1)
        self.assertEqual(self.verdict(e, 994), ("keep", "your Protection gear"))
        self.assertNotIn(994, self.sold(e)[0])
        self.assertEqual(e.errors(), [])

    def test_a_piece_outclassed_for_every_spec_still_sells(self):
        e = self.env()
        e.db.adviceUnsure = 2                                            # (Item advice: when unsure, Sell)
        self.assertEqual(self.verdict(e, 996)[0], "vendor")
        rules, smart = self.sold(e)
        self.assertIn(996, rules)
        self.assertIn(996, smart)
        self.assertTrue(self.junk(e, 996))
        self.assertEqual(e.errors(), [])


class KeepByDefault(unittest.TestCase):
    """Kept unless clearly junk (Item advice: when unsure, Keep): only grey and your junk are advised for sale."""

    def env(self):
        e = Env(db="{ v = 5, sell = { gear = true } }")
        T = e.lua.table
        put = e.mock.put
        put(0, 1, T(id=700, name="Fine Linen Shirt", quality=2, ilvl=20, price=100, stack=1, loc="INVTYPE_BODY",
                    sub=1, **{"class": 4}))
        put(0, 2, T(id=701, name="Cozy Sleeping Bag", quality=1, price=25, stack=1, use="Sleep", sub=0,
                    **{"class": 15}))
        put(0, 3, T(id=702, name="Healing Potion", quality=1, price=40, stack=20, count=5, use="Healing Potion", sub=1,
                    **{"class": 0}))
        put(0, 4, T(id=703, name="Charm of Luck", quality=2, price=50, stack=1, use="Luck", sub=0, **{"class": 15}))
        put(0, 5, T(id=704, name="Old Relic", quality=2, price=60, stack=1, sub=0, **{"class": 15}))
        put(0, 6, T(id=705, name="Broken Relic", quality=0, price=10, stack=1, sub=0, **{"class": 15}))
        put(0, 7, T(id=706, name="Wand of Three", quality=1, price=30, stack=1, use="Zap", sub=0, **{"class": 15}))
        e.lua.eval("""function(mock)
            local tips = { [703] = { "Charm of Luck", "Unique", "Use: luck" }, [704] = { "Old Relic", "Unique (1)" },
                           [705] = { "Broken Relic", "Unique" }, [706] = { "Wand of Three", "Use: zap", "3 Charges" },
                           [701] = { "Cozy Sleeping Bag", "Use: sleep a while" } }
            C_TooltipInfo.GetItemByID = function(id)
                local lines = {}
                for i, text in ipairs(tips[id] or { "?" }) do lines[i] = { leftText = text } end
                return { lines = lines }
            end
        end""")(e.mock)
        for iid in (700, 701, 703, 704):                                  # the auction house pays well for each
            e.db.auction[iid] = T(p=50000, t=e.g.time(), q=40, n=40)
        e.ns.Market.HasData = e.lua.eval("function() return true end")
        return e

    def verdict(self, e, iid):
        v = e.ns.Market.Verdict(iid)
        v = v if isinstance(v, tuple) else (v, None, None)
        return v[0], v[2] and v[2].why

    def junk(self, e, iid, quality=1):
        return bool(e.ns.Bags.IsJunk(e.lua.table(id=iid, quality=quality)))

    def smart(self, e):
        return sorted(i.id for i in e.ns.Vendor.Recommend(e.ns.Vendor).vendor.values())

    def test_an_ordinary_item_with_a_price_is_kept_and_still_on_the_market(self):
        e = self.env()
        self.assertEqual(e.db.adviceUnsure, 1)                           # Keep, the default
        self.assertEqual(self.verdict(e, 700), ("keep", "kept: nothing says it's junk"))
        best = plain(e.ns.Market.BestText(*e.ns.Market.Verdict(700)))
        self.assertIn("Keep", best)
        self.assertIn("could fetch 5g at the auction house", best)
        self.assertFalse(self.junk(e, 700))
        self.assertNotIn(700, self.smart(e))
        shown, _ = e.ns.AuctionPanel.Sellable(False)                    # the Market still offers it for sale
        mine = [x for x in shown.values() if x.id == 700]
        self.assertEqual(len(mine), 1)
        self.assertTrue(mine[0].worth)
        self.assertGreater(mine[0].each, 0)
        self.assertEqual(self.verdict(e, 705)[0], "vendor")             # grey: still junk
        self.assertTrue(self.junk(e, 705, 0))
        e.db.sell.junk[700] = True                                       # your own mark: junk
        self.assertEqual(self.verdict(e, 700)[0], "vendor")
        e.db.sell.junk[700] = None
        e.cmd("adviceunsure 2")                                          # Sell: 1.4.9's advice
        self.assertEqual(self.verdict(e, 700)[0], "auction")
        self.assertEqual(e.errors(), [])

    def test_the_sleeping_bag_is_kept_because_you_use_it(self):
        e = self.env()
        for mode in (1, 2):
            e.db.adviceUnsure = mode
            self.assertEqual(self.verdict(e, 701), ("keep", "you use it"))
            self.assertFalse(self.junk(e, 701))
            self.assertNotIn(701, self.smart(e))
            self.assertNotIn(701, [i.id for i in e.ns.Vendor.Collect(e.ns.Vendor, "quality", 3)[0].values()])
        self.assertTrue(e.ns.Vendor.Reusable(701))
        self.assertFalse(e.ns.Vendor.Reusable(702))                      # potions stack: used up
        self.assertFalse(e.ns.Vendor.Reusable(706))                      # charges: used up
        e.db.adviceUnsure = 2
        self.assertNotEqual(self.verdict(e, 702)[1], "you use it")       # a potion follows the usual advice
        self.assertEqual(self.verdict(e, 706)[0], "vendor")
        self.assertEqual(e.errors(), [])

    def test_unique_things_are_kept_even_when_the_auction_house_pays_well(self):
        e = self.env()
        e.db.adviceUnsure = 2                                            # even where it would be sold
        self.assertEqual(self.verdict(e, 703), ("keep", "you use it"))   # unique with a use: you use it
        self.assertEqual(self.verdict(e, 704), ("keep", "unique, and yours"))
        self.assertTrue(e.ns.Vendor.UniqueKeep(704))
        self.assertFalse(e.ns.Vendor.UniqueKeep(705))                    # grey unique: junk all the same
        self.assertEqual(self.verdict(e, 705)[0], "vendor")
        self.assertNotIn(704, self.smart(e))
        self.assertFalse(self.junk(e, 704, 2))
        self.assertEqual(e.errors(), [])

    def test_the_setting_has_two_choices(self):
        e = self.env()
        defs = [d for d in e.ns.settings.values() if d.key == "adviceUnsure"]
        self.assertEqual(list(defs[0].choices.values()), ["Keep", "Sell"])
        self.assertEqual(defs[0].default, 1)


class PlainSale(unittest.TestCase):
    """White, or green that binds when equipped and isn't bound yet, below what you wear or not your armour type:
    sold, even when unsure items are kept."""

    def env(self):
        e = Env(db="{ v = 5, sell = { gear = true } }")                  # (Item advice: when unsure, Keep)
        e.mock.units.player["class"], e.mock.units.player.level = "PALADIN", 45      # plate
        e.lua.eval(AdviceRule.STATS)(e.mock)
        T = e.lua.table

        def gear(iid, name, quality, ilvl, loc, sub, bag_slot=None, bind=None, **stats):
            it = T(id=iid, name=name, quality=quality, ilvl=ilvl, price=200, stack=1, loc=loc, sub=sub, bind=bind,
                   stats=T(**stats), **{"class": 4})
            if bag_slot:
                e.mock.put(0, bag_slot, it)
            else:
                e.mock["items"][iid] = it
        gear(1100, "Worn Plate Helm", 2, 30, "INVTYPE_HEAD", 4, ITEM_MOD_STRENGTH_SHORT=10)
        gear(1105, "Worn Plate Chest", 2, 30, "INVTYPE_CHEST", 4, ITEM_MOD_STRENGTH_SHORT=10)
        e.mock.worn[1], e.mock.worn[5] = 1100, 1105
        gear(1101, "Green Leather Cap", 2, 40, "INVTYPE_HEAD", 2, 1, bind=2, ITEM_MOD_AGILITY_SHORT=12)
        gear(1102, "Old Plate Helm", 2, 25, "INVTYPE_HEAD", 4, 2, bind=2, ITEM_MOD_STRENGTH_SHORT=10)
        gear(1103, "New Plate Helm", 2, 35, "INVTYPE_HEAD", 4, 3, bind=2, ITEM_MOD_STRENGTH_SHORT=10)
        gear(1104, "Plain Mail Vest", 1, 20, "INVTYPE_CHEST", 3, 4, ITEM_MOD_STAMINA_SHORT=3)
        gear(1106, "Blue Leather Cap", 3, 20, "INVTYPE_HEAD", 2, 5, bind=2, ITEM_MOD_AGILITY_SHORT=12)
        gear(1107, "Bound Leather Cap", 2, 20, "INVTYPE_HEAD", 2, 6, bind=1, ITEM_MOD_AGILITY_SHORT=12)
        gear(1108, "Green Cloth Bracers", 2, 30, "INVTYPE_WRIST", 1, 7, bind=2, ITEM_MOD_INTELLECT_SHORT=5)
        for iid, name in ((11083, "Soul Dust"), (11082, "Greater Astral Essence"), (11084, "Large Glimmering Shard")):
            e.mock["items"][iid] = T(id=iid, name=name, quality=1, price=0, **{"class": 7})
        e.mock.fire("PLAYER_EQUIPMENT_CHANGED")
        e.update(0.5)
        e.ns.Market.HasData = e.lua.eval("function() return true end")
        return e

    def verdict(self, e, iid):
        v = e.ns.Market.Verdict(iid)
        v = v if isinstance(v, tuple) else (v, None, None)
        return v[0], v[2] and v[2].why

    def smart(self, e):
        return sorted(i.id for i in e.ns.Vendor.Recommend(e.ns.Vendor).vendor.values())

    def junk(self, e, iid, quality=2):
        return bool(e.ns.Bags.IsJunk(e.lua.table(id=iid, quality=quality)))

    def test_not_your_armour_type_sells(self):
        e = self.env()
        self.assertEqual(self.verdict(e, 1101), ("vendor", "not your armour type"))
        self.assertIn("not your armour type", plain(e.ns.Market.BestText(*e.ns.Market.Verdict(1101))))
        self.assertIn(1101, self.smart(e))
        self.assertTrue(self.junk(e, 1101))
        self.assertEqual(e.errors(), [])

    def test_below_what_you_wear_sells_and_above_is_kept(self):
        e = self.env()
        self.assertEqual(self.verdict(e, 1102), ("vendor", "below what you wear"))
        self.assertIn(1102, self.smart(e))
        verdict, why = self.verdict(e, 1103)                             # as good, a higher level: could be yours
        self.assertEqual(verdict, "keep")
        self.assertNotIn(1103, self.smart(e))
        self.assertFalse(self.junk(e, 1103))
        e.db.auction[1102] = e.lua.table(p=50000, t=e.g.time(), q=40, n=40)
        self.assertEqual(self.verdict(e, 1102), ("auction", "below what you wear"))   # where it pays clearly more
        self.assertEqual(e.errors(), [])

    def test_white_of_any_binding_below_or_not_your_armour_sells(self):
        e = self.env()
        self.assertEqual(self.verdict(e, 1104)[0], "vendor")             # white mail at 45, level 20 under 30
        self.assertIsNotNone(self.verdict(e, 1104)[1])
        self.assertIn(1104, self.smart(e))
        self.assertEqual(e.errors(), [])

    def test_never_blue_nor_a_soulbound_green(self):
        e = self.env()
        self.assertEqual(self.verdict(e, 1106)[0], "keep")               # blue: never by this rule
        self.assertEqual(self.verdict(e, 1107)[0], "keep")               # soulbound green: the keep rules decide
        for iid in (1106, 1107):
            self.assertNotIn(iid, self.smart(e))
        self.assertIsNone(e.ns.Vendor.PlainlySellable(1102, "INVTYPE_HEAD", True))   # bound: not covered
        self.assertEqual(e.errors(), [])

    def test_a_green_an_enchanter_of_yours_skills_up_on_is_disenchanted(self):
        e = self.env()
        self.assertEqual(self.verdict(e, 1108), ("vendor", "not your armour type"))   # cloth: no enchanter yet
        T = e.lua.table
        e.db.inventory["Ench-Forever"] = T(level=30, faction="Horde", bags=T(), bank=T(), money=0, seen=0,
                                           prof=T(enchanting=T(name="Enchanting", rank=100, cap=150, at=e.g.time(),
                                                               uses=e.lua.table_from({11083: 3}))),
                                           **{"class": "MAGE"})
        verdict, more, want = e.ns.Market.Verdict(1108)
        self.assertEqual(verdict, "disenchant")
        self.assertTrue(want.skill)
        self.assertNotIn(1108, self.smart(e))
        self.assertEqual(e.errors(), [])




class QuestItems(SellWhenUnsure, unittest.TestCase):
    """The Quest verdict: what a quest of yours still needs is never sold or put up for auction."""

    stock, shop, advised = Vendor.stock, Vendor.shop, Vendor.advised

    @staticmethod
    def kind(e, iid):
        r = e.ns.Market.Verdict(iid)
        return r[0] if isinstance(r, tuple) else r

    def quests(self, e):
        T, put = e.lua.table, e.mock.put
        for i, row in enumerate([T(title="Duskwood", isHeader=True),
                                 T(title="The Weaver's Cloth", questID=1, level=30),
                                 T(title="Old Fangs", questID=2, level=12),              # grey at 33
                                 T(title="Rags for Remy", questID=3, level=10)], 1):     # grey, but ready
            e.mock.log[i] = row
        put(2, 2, T(id=8, name="Torn Letter", quality=1, price=0, ilvl=30, questID=500, **{"class": 12}))
        put(2, 3, T(id=9, name="Faded Note", quality=1, price=0, ilvl=10, questID=501, **{"class": 12}))
        put(2, 4, T(id=10, name="Signed Order", quality=1, price=0, ilvl=30, questID=502, **{"class": 12}))
        e.lua.eval("""function(mock)
            mock.objectives = {
                [1] = { { text = "Linen Cloth: 3/10", type = "item", numFulfilled = 3, numRequired = 10 } },
                [2] = { { text = "Broken Fang: 1/8", type = "item", numFulfilled = 1, numRequired = 8 } },
                [3] = { { text = "Grey Rag: 1/1", type = "item", numFulfilled = 1, numRequired = 1, finished = true } },
            }
            mock.ready = { [3] = true }
            C_QuestLog.GetQuestObjectives = function(id) return mock.objectives[id] end
            C_QuestLog.ReadyForTurnIn = function(id) return mock.ready[id] or false end
            C_QuestLog.IsQuestFlaggedCompleted = function(id) return id == 502 end
            C_Container.GetContainerItemQuestInfo = function(bag, slot)
                local it = mock.bags[bag] and mock.bags[bag][slot]
                return { isQuestItem = it and it.questID ~= nil or false, questID = it and it.questID,
                         isActive = it and it.questActive or false }
            end
        end""")(e.mock)
        e.mock.fire("QUEST_LOG_UPDATE")
        return e

    def test_what_your_quests_want_is_a_quest_item(self):
        e = self.quests(self.shop())
        M = e.ns.Market
        verdict, more, want = M.Verdict(4)
        self.assertEqual(verdict, "quest")                        # Linen Cloth: The Weaver's Cloth wants it
        self.assertEqual(want.title, "The Weaver's Cloth")
        self.assertIn("Quest: [30] The Weaver's Cloth 3/10 in Duskwood", M.BestText(verdict, more, want))
        self.assertEqual(self.kind(e, 1), "vendor")                  # Broken Fang: its quest is grey for you
        self.assertEqual(self.kind(e, 7), "quest")                   # Grey Rag: grey, but ready to hand in
        self.assertIn("ready to hand in", e.ns.Quests.WantText(M.Verdict(7)[2]))
        verdict, more, want = M.Verdict(8)
        self.assertEqual(verdict, "quest")                        # Torn Letter starts a quest at your level
        self.assertTrue(want.starts)
        self.assertIn("starts a quest", M.BestText(verdict, more, want))
        self.assertNotEqual(self.kind(e, 9), "keep")                 # its quest is grey: kept for nothing
        self.assertNotEqual(self.kind(e, 10), "keep")                # its quest is done already: nor this
        advice = M.Advice(*M.Verdict(4), 4)
        self.assertIn("Quest", advice[2][1])
        self.assertIn("The Weaver's Cloth", advice[3][1])
        self.assertIn("items for quests true", e.ns.Quests.Describe())
        self.assertEqual(e.errors(), [])

    def test_never_sold_and_kept_out_of_the_auction_list(self):
        e = self.quests(self.advised())
        self.assertEqual(sorted(i.id for i in e.ns.Vendor.Collect(e.ns.Vendor, "rules")[0].values()), [1])
        r = e.ns.Vendor.Recommend(e.ns.Vendor)
        self.assertEqual(sorted(i.id for i in r.quest.values()), [4, 7, 8])                        # (and the letter)
        self.assertNotIn(4, [i.id for i in r.auction.values()])
        self.assertNotIn(7, [i.id for i in r.vendor.values()])
        e.ns.Vendor.ConfirmAdvised(e.ns.Vendor)
        quests = e.ns.Dialog.visible.text.split("Kept for your quests")[1]
        self.assertIn("Linen Cloth  x 20", quests)                   # one line each, with how many
        self.assertIn("Grey Rag", quests)
        AP = e.ns.AuctionPanel
        shown, hidden = AP.Sellable(False)
        self.assertNotIn(4, [x.id for x in shown.values()])
        self.assertIn("Quest: [30] The Weaver's Cloth", AP.Reason(e.lua.table(verdict="quest", want=e.ns.Market.Verdict(4)[2], price=1)))
        self.assertEqual(e.errors(), [])

    def test_follows_the_log_your_level_and_the_switch(self):
        e = self.quests(self.advised())
        M = e.ns.Market
        self.assertEqual(self.kind(e, 4), "quest")
        e.mock.log[2] = e.lua.table(title="Something Else", questID=4, level=30)     # handed in
        e.mock.fire("QUEST_LOG_UPDATE")
        self.assertEqual(self.kind(e, 4), "auction")              # Linen Cloth is worth more there again
        e.mock.log[2] = e.lua.table(title="The Weaver's Cloth", questID=1, level=30)
        e.mock.fire("QUEST_LOG_UPDATE")
        self.assertEqual(self.kind(e, 4), "quest")
        e.mock.units.player.level = 40                            # the quest turned grey
        e.mock.fire("PLAYER_LEVEL_UP", 40)
        self.assertNotEqual(self.kind(e, 4), "quest")
        self.assertNotEqual(self.kind(e, 8), "quest")                # and so did the letter's
        e.mock.units.player.level = 33
        e.mock.fire("PLAYER_LEVEL_UP", 33)
        self.assertEqual(self.kind(e, 4), "quest")
        e.cmd("questitems off")
        self.assertNotEqual(self.kind(e, 4), "quest")
        self.assertEqual(sorted(i.id for i in e.ns.Vendor.Collect(e.ns.Vendor, "rules")[0].values()), [1, 7])
        e.cmd("questitems on")
        self.assertEqual(self.kind(e, 4), "quest")
        e.db.sell.junk[4] = True                                  # your own mark comes first
        self.assertEqual(self.kind(e, 4), "vendor")
        self.assertEqual(e.errors(), [])

    def test_secret_objectives_are_left_alone(self):
        e = self.quests(self.shop())
        e.mock.objectives[1][1].text = e.mock.secret()
        e.mock.fire("QUEST_LOG_UPDATE")
        self.assertNotEqual(e.ns.Market.Verdict(4), "quest")
        self.assertEqual(e.errors(), [])


class AdviceRule(SellWhenUnsure, unittest.TestCase):
    """The advice: sell by default (the auction house where it pays, else a vendor), unless it is an upgrade for
    you or another character of yours, a profession of one of yours wants it (a skill-up, or disenchanting), or
    a quest you can still do wants it; and every keep says why."""

    STATS = """function(mock)
        C_Item.GetItemStats = function(link)
            local id = tonumber(tostring(link):match("item:(%d+)")) or link
            local it = mock.items[id]
            return it and it.stats
        end
        UnitFactionGroup = function(unit) return mock.faction or "Horde" end
    end"""

    def env(self, level=42, cls="PALADIN"):
        e = Env(db="{ v = 5, sell = { gear = true } }")
        e.mock.units.player["class"], e.mock.units.player.level = cls, level
        e.lua.eval(self.STATS)(e.mock)
        T = e.lua.table
        e.mock["items"][980] = T(id=980, name="Worn Plate", quality=2, ilvl=38, req=35, price=400,
                                 loc="INVTYPE_CHEST", sub=4, stats=T(ITEM_MOD_STRENGTH_SHORT=10), **{"class": 4})
        e.mock.worn[5] = 980
        for iid, name in ((11083, "Soul Dust"), (11082, "Greater Astral Essence"), (11084, "Large Glimmering Shard")):
            e.mock["items"][iid] = T(id=iid, name=name, quality=1, price=0, **{"class": 7})
        e.mock.fire("PLAYER_EQUIPMENT_CHANGED")
        e.update(0.5)                                                       # (your record: class, level, side)
        return e

    def alt(self, e, who="Sol-Forever", cls="WARRIOR", level=35, faction="Horde", worn=None, prof=None):
        T = e.lua.table
        rec = T(level=level, faction=faction, bags=T(), bank=T(), money=0, seen=0, **{"class": cls})
        if worn is not None:
            rec.worn = e.lua.table_from({slot: "item:%d" % iid for slot, iid in worn.items()})
        if prof is not None:
            rec.prof = prof
        e.db.inventory[who] = rec
        return rec

    def mail(self, e, iid=990, strength=15, req=33):
        T = e.lua.table
        e.mock.put(0, 1, T(id=iid, name="Chain of Strength", quality=2, ilvl=36, req=req, price=500,
                           loc="INVTYPE_CHEST", sub=3, stats=T(ITEM_MOD_STRENGTH_SHORT=strength,
                                                               ITEM_MOD_STAMINA_SHORT=10), **{"class": 4}))
        e.mock["items"][991] = T(id=991, name="Old Chain", quality=1, ilvl=25, price=50, loc="INVTYPE_CHEST",
                                 sub=3, stats=T(ITEM_MOD_STRENGTH_SHORT=5, ITEM_MOD_STAMINA_SHORT=4), **{"class": 4})

    def verdict(self, e, iid, bound=None):
        r = e.ns.Market.Verdict(iid, bound)
        return r if isinstance(r, tuple) else (r, None, None)

    def justified(self, e, iid):
        """Whatever is not to be sold says why, beside its word."""
        M = e.ns.Market
        verdict, more, want = self.verdict(e, iid)
        text = plain(M.BestText(verdict, more, want))
        word = plain(M.WORDS[verdict]) if M.WORDS[verdict] else ""
        self.assertTrue(text.replace(word, "").strip(), "%s: %s with no reason" % (iid, verdict))
        return text

    def advice(self, e, iid, bound=None):
        verdict, more, want = self.verdict(e, iid, bound)
        return "\n".join(plain(list(l.values())[0]) for l in e.ns.Market.Advice(verdict, more, want, iid).values())

    def test_sold_by_default_and_a_sidegrade_is_no_reason_to_keep(self):
        e = self.env()
        T = e.lua.table
        e.mock.put(0, 2, T(id=981, name="Same Plate", quality=2, ilvl=38, req=35, price=400, loc="INVTYPE_CHEST",
                           sub=4, stats=T(ITEM_MOD_STRENGTH_SHORT=10), **{"class": 4}))
        self.assertEqual(self.verdict(e, 981)[0], "vendor")          # as good as what you wear: sold
        e.db.auction[981] = T(p=5000, t=e.g.time(), q=40, n=40)
        self.assertEqual(self.verdict(e, 981)[0], "auction")         # where it pays more: the auction house
        verdict, _, want = self.verdict(e, 980)                      # what you wear is not for sale
        self.assertEqual((verdict, want.why), ("keep", "you wear it"))
        self.justified(e, 980)
        self.assertEqual(e.errors(), [])

    def test_an_upgrade_for_another_character_of_yours(self):
        e = self.env()
        self.mail(e)
        self.assertEqual(self.verdict(e, 990)[0], "vendor")          # mail: not for a paladin of 42
        self.alt(e, worn={5: 991, 1: 980})
        verdict, _, want = self.verdict(e, 990)
        self.assertEqual((verdict, want.why), ("keep", "Upgrade for Sol"))
        self.assertIn("Upgrade for Sol", self.justified(e, 990))
        self.assertIn("Upgrade for Sol", self.advice(e, 990))
        self.assertNotIn(990, [i.id for i in e.ns.Vendor.Collect(e.ns.Vendor, "quality", 2)[0].values()])
        self.assertEqual(self.verdict(e, 990, True)[0], "vendor")    # bound to you: it cannot go to Sol
        self.assertEqual(e.errors(), [])

    def test_only_one_who_could_wear_it_now_and_is_better_off(self):
        e = self.env()
        self.mail(e)
        rec = self.alt(e, worn={5: 991, 1: 980})
        rec.level = 30                                               # it asks for level 33
        self.assertNotEqual(self.verdict(e, 990)[0], "keep")
        rec.level, rec.faction = 35, "Alliance"                      # the other side: no mail between you
        self.assertNotEqual(self.verdict(e, 990)[0], "keep")
        rec.faction, rec["class"] = "Horde", "MAGE"                  # a mage wears no mail
        self.assertNotEqual(self.verdict(e, 990)[0], "keep")
        rec["class"] = "SHAMAN"                                      # a shaman of 35 wears leather yet
        self.assertNotEqual(self.verdict(e, 990)[0], "keep")
        rec.level = 40                                               # and mail from 40
        self.assertEqual(self.verdict(e, 990)[2].why, "Upgrade for Sol")
        self.mail(e, strength=1)                                     # no better than what Sol wears
        self.assertNotEqual(self.verdict(e, 990)[0], "keep")
        rec.worn = e.lua.table_from({1: "item:980"})                 # nothing on Sol's chest: anything is better
        self.assertEqual(self.verdict(e, 990)[0], "keep")
        rec.worn = None                                              # Sol not seen since: nothing is said for Sol
        self.assertNotEqual(self.verdict(e, 990)[0], "keep")
        self.assertEqual(e.errors(), [])

    def test_your_worn_gear_is_noted_for_your_other_characters(self):
        e = self.env()
        me = e.db.inventory["Ghostlight-Forever"]
        self.assertEqual((me["class"], me.level, me.faction), ("PALADIN", 42, "Horde"))
        self.assertEqual(me.worn[5], "item:980")
        again = Env(db=e.mock.serialize(e.g.ControllerCamHUDDB))     # kept with your settings
        self.assertEqual(again.db.inventory["Ghostlight-Forever"].worn[5], "item:980")
        self.assertEqual(again.db.inventory["Ghostlight-Forever"].level, 42)
        self.assertEqual(e.errors(), [])

    def test_a_bind_on_equip_upgrade_says_what_it_fetches_at_auction(self):
        e = self.env()
        T = e.lua.table
        e.mock.put(0, 2, T(id=985, name="Fine Plate", quality=2, ilvl=40, req=38, price=900, loc="INVTYPE_CHEST",
                           sub=4, bind=2, stats=T(ITEM_MOD_STRENGTH_SHORT=20), **{"class": 4}))
        self.assertIsNone(self.verdict(e, 985)[2])                   # no price yet: just the upgrade
        e.db.auction[985] = T(p=24000, t=e.g.time(), q=5, n=5)
        verdict, _, want = self.verdict(e, 985)
        self.assertEqual((verdict, want.worth, want.rich), ("equip", 24000, False))
        self.assertIn("worth 2g 40s at auction", self.justified(e, 985))
        self.assertIn("worth 2g 40s at auction", self.advice(e, 985))
        self.assertNotIn("more than it is worth to wear", self.advice(e, 985))
        e.db.auction[985].p = 150000                                 # 15g: more than an upgrade at 42 is worth
        self.assertIn("worth 15g at auction: more than it is worth to wear", self.advice(e, 985))
        reason = plain(e.ns.AuctionPanel.Reason(e.lua.table(verdict="equip", price=1, want=self.verdict(e, 985)[2])))
        self.assertIn("worth 15g at auction", reason)
        self.assertIsNone(self.verdict(e, 985, True)[2])             # bound to you already: nothing to sell
        e.mock.bags[0][2].bound = True                               # (as your bags say)
        self.assertIsNone(self.verdict(e, 985)[2])
        e.mock.bags[0][2].bound, e.mock["items"][985].bind = False, 1   # binds when picked up: never for sale
        self.assertIsNone(self.verdict(e, 985)[2])
        self.mail(e)                                                 # an upgrade for Sol that binds when equipped
        e.mock["items"][990].bind = 2
        e.db.auction[990] = T(p=5000, t=e.g.time(), q=5, n=5)
        self.alt(e, worn={5: 991, 1: 980})
        self.assertIn("Upgrade for Sol  ·  worth 50s at auction", self.justified(e, 990))
        self.assertEqual(e.errors(), [])

    def bracers(self, e, quality=2, ilvl=30):
        e.mock.put(0, 3, e.lua.table(id=995, name="Green Bracers", quality=quality, ilvl=ilvl, price=100,
                                     loc="INVTYPE_WRIST", sub=1, **{"class": 4}))       # cloth: no one's upgrade

    def enchanter(self, e, rank=100, uses=None, who="Ench-Forever"):
        T = e.lua.table
        p = T(name="Enchanting", rank=rank, cap=150)
        if uses is not None:
            p.at, p.uses = e.g.time(), e.lua.table_from(uses)
        if who in e.db.inventory and e.db.inventory[who] is not None:
            e.db.inventory[who].prof = T(enchanting=p)
            return e.db.inventory[who]
        return self.alt(e, who=who, cls="MAGE", level=30, prof=T(enchanting=p))

    def test_disenchant_when_an_enchanter_of_yours_gets_more_from_it(self):
        e = self.env()
        T = e.lua.table
        self.bracers(e)
        self.assertEqual(self.verdict(e, 995)[0], "vendor")          # no enchanter yet
        rec = self.enchanter(e)
        self.assertEqual(self.verdict(e, 995)[0], "vendor")          # no prices for what it gives: sold
        for iid, p in ((11083, 300), (11082, 2000), (11084, 1500)):
            e.db.auction[iid] = T(p=p, t=e.g.time(), q=20, n=20)
        verdict, more, want = self.verdict(e, 995)
        self.assertEqual(verdict, "disenchant")
        self.assertGreater(more, 700)                                # its dust, essence and shard, against 1s
        self.assertEqual([m.id for m in want.mats.values()], [11083, 11082, 11084])
        text = self.justified(e, 995)
        self.assertIn("Disenchant", text)
        self.assertIn("Enchanting 100/150, Ench", text)
        advice = self.advice(e, 995)
        self.assertIn("Soul Dust x1.5 75%  3s each", advice)
        self.assertIn("Large Glimmering Shard 5%", advice)
        r = e.ns.Vendor.Recommend(e.ns.Vendor)
        self.assertIn(995, [i.id for i in r.skill.values()])         # kept, with your professions' things
        self.assertNotIn(995, [i.id for i in r.vendor.values()])
        reason = plain(e.ns.AuctionPanel.Reason(e.lua.table(verdict=verdict, price=100, want=want)))
        self.assertIn("Disenchant  Enchanting 100/150, Ench", reason)
        self.assertEqual(self.verdict(e, 995, True)[0], "vendor")    # bound to you: Ench cannot have it
        rec.prof.enchanting.rank = 40                                # level 30 gear wants 50 Enchanting
        self.assertEqual(self.verdict(e, 995)[0], "vendor")
        rec.prof.enchanting.rank, rec.faction = 100, "Alliance"      # the other side
        self.assertEqual(self.verdict(e, 995)[0], "vendor")
        rec.faction = "Horde"
        self.bracers(e, quality=1)                                   # white: nothing to disenchant
        self.assertEqual(self.verdict(e, 995)[0], "vendor")
        self.assertEqual(e.errors(), [])

    def test_disenchant_for_a_skill_up_and_your_own_bound_gear(self):
        e = self.env()
        self.bracers(e)
        self.enchanter(e, uses={11083: 2})                           # Soul Dust still gives Ench a point
        verdict, more, want = self.verdict(e, 995)
        self.assertEqual((verdict, more, want.skill), ("disenchant", None, True))
        self.assertIn("what it gives still gives a skill-up", self.advice(e, 995))
        e.db.inventory["Ench-Forever"] = None
        self.enchanter(e, uses={11083: 2}, who="Ghostlight-Forever")   # you are the enchanter
        self.assertEqual(self.verdict(e, 995, True)[0], "disenchant")  # bound or not
        self.assertTrue(self.verdict(e, 995, True)[2].mine)
        self.assertIn("Enchanting 100/150", self.justified(e, 995))
        self.assertEqual(e.errors(), [])

    def test_disenchanting_materials_by_item_level_and_quality(self):
        e = self.env()
        P = e.ns.Professions
        self.bracers(e, ilvl=18)
        mats, skill = P.DisenchantMats(995)
        self.assertEqual(([m.id for m in mats.values()], skill), ([10940, 10939, 10978], 1))
        self.bracers(e, quality=3, ilvl=42)
        mats, skill = P.DisenchantMats(995)
        self.assertEqual(([(m.id, m.chance) for m in mats.values()], skill), ([(11177, 1)], 125))
        self.bracers(e, quality=4, ilvl=60)
        self.assertEqual(P.DisenchantMats(995)[0][1].id, 20725)      # a Nexus Crystal
        e.mock.put(0, 4, e.lua.table(id=996, name="Green Sword", quality=2, ilvl=33, price=100,
                                     loc="INVTYPE_WEAPON", sub=7, **{"class": 2}))
        mats, _ = P.DisenchantMats(996)
        self.assertEqual([(m.id, m.chance) for m in mats.values()], [(11134, 0.75), (11083, 0.2), (11138, 0.05)])
        self.assertEqual(e.errors(), [])

    QUEST = (582, "Headhunting", 37, "Stranglethorn Vale", "H", 20)

    def heads(self, e, quests=(QUEST,)):
        T = e.lua.table
        e.mock.put(1, 1, T(id=1532, name="Shrunken Head", quality=1, price=0, count=4, stack=20, **{"class": 12}))
        e.db.auction[1532] = T(p=300, t=e.g.time(), q=40, n=40)
        e.ns.QuestItemData[1532] = e.lua.table_from([e.lua.table_from(list(q)) for q in quests])
        e.lua.execute("C_QuestLog.IsQuestFlaggedCompleted = function(id) return DONE_QUESTS and DONE_QUESTS[id] or false end")
        e.mock.fire("QUEST_LOG_UPDATE")

    def test_a_quest_not_in_your_log_yet_names_its_level_and_place(self):
        e = self.env(level=33, cls="HUNTER")
        self.heads(e)
        verdict, _, want = self.verdict(e, 1532)
        self.assertEqual(verdict, "quest")
        self.assertEqual(e.ns.Quests.WantText(want), "[37] Headhunting 4/20 in Stranglethorn Vale")
        self.assertIn("Quest: [37] Headhunting 4/20 in Stranglethorn Vale", self.justified(e, 1532))
        self.assertIn("[37] Headhunting 4/20 in Stranglethorn Vale", self.advice(e, 1532))
        self.assertNotIn(1532, [i.id for i in e.ns.Vendor.Recommend(e.ns.Vendor).auction.values()])
        e.mock.units.player.level = 45                               # 8 levels over it: still worth doing
        self.assertEqual(self.verdict(e, 1532)[0], "quest")
        e.mock.units.player.level = 50                               # grey for you: sold
        self.assertEqual(self.verdict(e, 1532)[0], "auction")
        self.assertEqual(e.errors(), [])

    def test_a_quest_of_the_other_side_or_done_already_keeps_nothing(self):
        e = self.env(level=33, cls="HUNTER")
        self.heads(e)
        e.mock.faction = "Alliance"
        self.assertEqual(self.verdict(e, 1532)[0], "auction")
        e.mock.faction = "Horde"
        self.assertEqual(self.verdict(e, 1532)[0], "quest")
        e.lua.execute("DONE_QUESTS = { [582] = true }")
        self.assertEqual(self.verdict(e, 1532)[0], "auction")
        e.lua.execute("DONE_QUESTS = nil")
        e.cmd("questitems off")
        self.assertEqual(self.verdict(e, 1532)[0], "auction")        # the switch covers these too
        self.assertEqual(e.errors(), [])

    def test_of_two_quests_the_lowest_you_can_still_do(self):
        e = self.env(level=33, cls="HUNTER")
        self.heads(e, quests=((1, "Too Easy", 20, "The Barrens", None, 5), (2, "Later On", 44, "Tanaris", None, 8),
                              self.QUEST))
        self.assertEqual(self.verdict(e, 1532)[2].title, "Headhunting")
        e.lua.execute("DONE_QUESTS = { [582] = true }")
        self.assertEqual(self.verdict(e, 1532)[2].title, "Later On")  # for both sides, and done later
        self.assertEqual(e.errors(), [])

    def test_the_bundled_quest_list_is_well_formed(self):
        e = self.env()
        n = 0
        for iid, quests in e.ns.QuestItemData.items():
            self.assertIsInstance(iid, int)
            self.assertGreater(len(quests), 0, iid)
            for q in quests.values():
                qid, name, level, zone, side, count = (q[i] for i in range(1, 7))
                self.assertIsInstance(qid, int, iid)
                self.assertTrue(isinstance(name, str) and name and isinstance(zone, str) and zone, iid)
                self.assertTrue(isinstance(level, int) and 1 <= level <= 60, iid)
                self.assertIn(side, ("A", "H", None), iid)
                self.assertTrue(isinstance(count, int) and count >= 1, iid)
                n += 1
        self.assertGreater(n, 20)
        self.assertEqual(e.errors(), [])


COMPASS_WORLD = """
local mock = ...
mock.facing, mock.mapSize = 0, 1000                 -- a map 1000 yards across: north is up, west is left
mock.done, mock.ways, mock.focus, mock.mapCalls = {}, {}, 0, 0
function GetPlayerFacing() return mock.facing end
function CreateVector2D(x, y) return { x = x, y = y, GetXY = function(s) return s.x, s.y end } end
C_Map.GetWorldPosFromMapPos = function(map, v)       -- (the world counts north and west)
    return 0, CreateVector2D(-v.y * mock.mapSize, -v.x * mock.mapSize)
end
C_QuestLog.IsOnQuest = function() return true end
C_QuestLog.ReadyForTurnIn = function(id) return mock.done[id] == true end
C_QuestLog.GetNextWaypointForMap = function(id) local w = mock.ways[id]; if w then return w[1], w[2] end end
local onMap = C_QuestLog.GetQuestsOnMap
C_QuestLog.GetQuestsOnMap = function(...) mock.mapCalls = mock.mapCalls + 1; return onMap(...) end
C_SuperTrack = { GetSuperTrackedQuestID = function() return mock.focus end,
                 SetSuperTrackedQuestID = function(id) mock.focus = id end }
mock.playerPos = { 0.5, 0.5 }
StatusTrackingBarManager.points = { { "BOTTOM", UIParent, "BOTTOM", 0, 0 } }
"""


class Compass(unittest.TestCase):
    """The quest compass: the strip, the marks on it, and the experience bar it swaps places with."""

    def env(self, quests=(), tracked=(), db=None, focus=0, **kw):
        def setup(e):
            e.lua.execute(COMPASS_WORLD, e.mock)
            for i, (qid, x, y) in enumerate(quests, 1):
                e.mock.onMap[i] = e.lua.table(questID=qid, x=x, y=y)
            for qid in tracked:
                e.mock.tracked[qid] = True
            e.mock.focus = focus
        e = Env(db=db, setup=setup, **kw)
        e.update(0.6)
        return e

    def mark(self, e, key):
        for s in e.ns.Compass.shownMarks.values():
            if s.m.key == key:
                return s
        return None

    def look(self, e, seconds=0.4):
        e.mock.fire("QUEST_LOG_UPDATE")
        e.update(seconds)

    def test_the_strip_draws_and_a_mark_moves_as_you_turn(self):
        import math
        e = self.env(quests=((101, 0.5, 0.4),))             # 100 yards to the north
        C = e.ns.Compass
        self.assertTrue(C.frame.shown)
        self.assertIsNone(C.why)
        self.assertEqual(C.frame.points[1][1], "TOP")
        s = self.mark(e, "q101")
        self.assertAlmostEqual(s.x, 0, 3)
        self.assertEqual(s.w.label.text, "100 yd")
        self.assertTrue(s.w.icon.shown)
        e.mock.facing = math.pi / 4                         # turned 45 degrees left: north is to the right
        e.update(0.1)
        s = self.mark(e, "q101")
        self.assertAlmostEqual(s.x, 90, 3)
        self.assertAlmostEqual(s.w.icon.points[1][4], 90, 3)
        e.mock.facing = -math.pi / 4                        # and to the right: north is to the left
        e.update(0.1)
        self.assertAlmostEqual(self.mark(e, "q101").x, -90, 3)
        north = C.letters[1]
        self.assertEqual(north.fs.text, "N")
        self.assertAlmostEqual(north.fs.points[1][4], -90, 3)
        e.mock.facing = math.pi                             # behind you: off the strip
        e.update(0.1)
        self.assertIsNone(self.mark(e, "q101"))
        self.assertFalse(e.ns.Compass.pool[1].icon.shown)
        self.assertEqual(e.errors(), [])

    def test_marks_fade_in_and_fade_out_at_the_ends(self):
        import math
        def setup(e):
            e.lua.execute(COMPASS_WORLD, e.mock)
            e.mock.onMap[1] = e.lua.table(questID=101, x=0.5, y=0.44)     # 60 yards: full strength
        e = Env(setup=setup)
        e.update(0.1)
        early = self.mark(e, "q101").a
        self.assertGreater(early, 0)
        self.assertLess(early, 1)                           # coming in
        e.update(0.5)
        self.assertAlmostEqual(self.mark(e, "q101").a, 1, 3)
        e.mock.facing = -math.radians(80)                   # 80 degrees off: near the strip's end, faint
        e.update(0.1)
        s = self.mark(e, "q101")
        self.assertAlmostEqual(s.x, -160, 3)
        self.assertAlmostEqual(s.a, 20 / 45, 2)
        e.mock.onMap[1] = None                               # done with: it fades out, then it is gone
        self.look(e, 0.05)
        e.mock.facing = 0
        e.update(0.1)
        self.assertLess(self.mark(e, "q101").a, 1)
        e.update(0.6)
        self.assertIsNone(self.mark(e, "q101"))
        self.assertEqual(len(list(e.ns.Compass.marks.values())), 0)
        self.assertEqual(e.errors(), [])

    def test_nearer_marks_read_stronger(self):
        e = self.env(quests=((101, 0.5, 0.44), (102, 0.52, -0.3)))         # 60 yards and some 800, both ahead
        near, far = self.mark(e, "q101"), self.mark(e, "q102")
        self.assertAlmostEqual(near.a, 1, 3)
        self.assertEqual(near.w.icon.width, e.ns.Compass.ICON)
        self.assertAlmostEqual(far.a, e.ns.Compass.FAINT, 2)
        self.assertEqual(far.w.icon.width, e.ns.Compass.ICON_FAR)
        self.assertTrue(near.w.label.shown)                 # their distances would overlap: the nearer one's
        self.assertFalse(far.w.label.shown)
        self.assertEqual(e.errors(), [])

    def test_distances_follow_you(self):
        e = self.env(quests=((101, 0.5, 0.4),))
        self.assertEqual(self.mark(e, "q101").w.label.text, "100 yd")
        e.mock.playerPos = e.lua.table(0.5, 0.45)
        e.update(0.2)
        self.assertEqual(self.mark(e, "q101").w.label.text, "50 yd")
        Y = e.ns.Compass.Yards
        self.assertEqual(Y(5), "")                          # you are there
        self.assertEqual(Y(57.4), "57 yd")
        self.assertEqual(Y(234), "230 yd")                  # further off, to ten yards
        self.assertEqual(e.errors(), [])

    def test_the_focused_quest_stands_out(self):
        e = self.env(quests=((101, 0.4, 0.4), (102, 0.6, 0.4)), focus=102)
        plain, focused = self.mark(e, "q101"), self.mark(e, "q102")
        self.assertTrue(focused.m.focus)
        self.assertTrue(focused.w.glow.shown)
        self.assertFalse(plain.w.glow.shown)
        self.assertEqual(focused.w.icon.width, e.ns.Compass.ICON_FOCUS)
        caution = tuple(e.ns.colors.caution.values())
        self.assertEqual(tuple(focused.w.label.tcolor.values())[:3], caution)
        self.assertNotEqual(tuple(plain.w.label.tcolor.values())[:3], caution)
        self.assertEqual(e.errors(), [])

    def test_no_more_than_a_few_and_the_focused_one_always(self):
        quests = [(100 + i, 0.5, 0.45 - i * 0.04) for i in range(8)]       # one behind the other, northwards
        e = self.env(quests=quests, focus=107)
        keys = {m.key for m in e.ns.Compass.marks.values() if m.want}
        self.assertEqual(len(keys), e.ns.Compass.MAX)
        self.assertIn("q107", keys)                         # the furthest, but focused
        self.assertIn("q100", keys)
        self.assertNotIn("q106", keys)
        self.assertEqual(e.errors(), [])

    def test_a_quest_to_hand_in_has_its_own_mark(self):
        e = self.env(quests=((101, 0.5, 0.4),))
        self.assertEqual(self.mark(e, "q101").m.kind, "quest")
        e.mock.done[101] = True
        self.look(e)
        s = self.mark(e, "q101")
        self.assertEqual(s.m.kind, "turnin")
        self.assertEqual(s.w.kind, "turnin")
        self.assertEqual(e.errors(), [])

    def test_the_quests_you_track_when_you_track_any(self):
        e = self.env(quests=((101, 0.45, 0.4), (102, 0.55, 0.4)), tracked=(101,))
        self.assertIsNotNone(self.mark(e, "q101"))
        e.update(0.5)
        self.assertIsNone(self.mark(e, "q102"))
        e.mock.tracked[101] = None                           # nothing here tracked: all of yours here
        self.look(e)
        self.assertIsNotNone(self.mark(e, "q102"))
        self.assertEqual(e.errors(), [])

    def test_a_focused_quest_elsewhere_shows_the_way_there(self):
        import math
        e = self.env(focus=200)
        e.mock.ways[200] = e.lua.table(0.9, 0.5)             # the way out of the zone, 400 yards east
        e.mock.facing = -math.pi / 2                          # facing east
        self.look(e)
        s = self.mark(e, "q200")
        self.assertTrue(s.m.way and s.m.focus)
        self.assertAlmostEqual(s.x, 0, 3)
        self.assertEqual(s.w.label.text, "400 yd")
        self.assertEqual(e.errors(), [])

    def test_your_map_pin(self):
        e = self.env()
        e.lua.execute("""C_Map.HasUserWaypoint = function() return true end
            C_Map.GetUserWaypoint = function() return { uiMapID = 1, position = CreateVector2D(0.5, 0.3) } end""")
        self.look(e)
        s = self.mark(e, "pin")
        self.assertEqual(s.m.kind, "pin")
        self.assertEqual(s.w.label.text, "200 yd")
        self.assertEqual(e.errors(), [])

    def test_at_the_bottom_it_swaps_places_with_the_experience_bar(self):
        e = self.env(quests=((101, 0.5, 0.4),))
        C, bar = e.ns.Compass, e.g.StatusTrackingBarManager
        self.assertEqual(bar.points[1][1], "BOTTOM")        # at the top, the bar stays the game's
        e.cmd("compassplace 2")
        self.assertEqual(C.frame.points[1][1], "BOTTOM")
        self.assertEqual(bar.points[1][1], "TOP")
        self.assertTrue(C.xp.moved)
        e.update(0.2)
        s = self.mark(e, "q101")
        self.assertEqual(s.w.label.points[1][1], "BOTTOM")  # its distance above the mark, clear of the edge
        self.assertGreater(s.w.label.points[1][5], 0)
        self.assertEqual(e.ns.RunCheck(False)[0], 0)
        e.cmd("compassplace 1")
        self.assertEqual(bar.points[1][1], "BOTTOM")
        self.assertEqual(C.frame.points[1][1], "TOP")
        e.cmd("compassplace 2")
        e.cmd("compass off")                                # the bar goes back with the compass
        self.assertEqual(bar.points[1][1], "BOTTOM")
        self.assertEqual(e.ns.RunCheck(False)[0], 0)
        e.cmd("compass on")
        self.assertEqual(bar.points[1][1], "TOP")
        e.mock.editMode(True)                               # Edit Mode: the bar back where the game keeps it
        self.assertEqual(bar.points[1][1], "BOTTOM")
        e.update(0.5)
        self.assertEqual(C.why, "edit mode")
        e.mock.editMode(False)
        self.assertEqual(bar.points[1][1], "TOP")
        e.mock.state.combat = True                          # a change in a fight waits for it to end
        e.cmd("compassplace 1")
        self.assertEqual(bar.points[1][1], "TOP")
        e.mock.state.combat = False
        e.mock.fire("PLAYER_REGEN_ENABLED")
        self.assertEqual(bar.points[1][1], "BOTTOM")
        e.cmd("compassplace 2")
        e.cmd("off")                                        # the HUD stops: everything as it was
        self.assertEqual(bar.points[1][1], "BOTTOM")
        self.assertEqual(len(list(bar.points.values())), 1)
        self.assertFalse(C.frame.shown)
        self.assertEqual(e.errors(), [])

    def test_the_switch(self):
        e = self.env(quests=((101, 0.5, 0.4),))
        C = e.ns.Compass
        e.cmd("compass off")
        self.assertFalse(C.running)
        self.assertFalse(C.frame.shown)
        self.assertEqual(e.ns.RunCheck(False)[0], 0)
        drawn = C.drawn
        e.mock.facing = 1
        e.update(1)
        self.assertEqual(C.drawn, drawn)                    # nothing runs while it is off
        e.cmd("compass on")
        e.update(0.5)
        self.assertTrue(C.frame.shown)
        self.assertIsNotNone(self.mark(e, "q101"))
        self.assertEqual(e.ns.RunCheck(False)[0], 0)
        self.assertEqual(e.errors(), [])

    def test_it_steps_away_where_the_game_does_not_say(self):
        e = self.env(quests=((101, 0.5, 0.4),))
        C = e.ns.Compass
        e.mock.facing = e.mock.secret()                     # the way you face kept secret
        e.update(1.5)
        self.assertEqual(C.why, "no facing")
        self.assertFalse(C.frame.shown)
        e.mock.facing = 0
        e.update(1.5)
        self.assertTrue(C.frame.shown)
        e.mock.playerPos = None                              # in a dungeon
        e.update(1.5)
        self.assertEqual(C.why, "no place")
        self.assertFalse(C.frame.shown)
        e.mock.playerPos = e.lua.table(0.5, 0.5)
        e.mock.taxi.onTaxi = True                            # on a flight
        e.update(1.5)
        self.assertEqual(C.why, "flight")
        e.mock.taxi.onTaxi = False
        e.update(1.5)
        self.assertIsNone(C.why)
        self.assertTrue(C.frame.shown)
        self.assertEqual(e.ns.RunCheck(False)[0], 0)
        self.assertEqual(e.errors(), [])

    def test_it_costs_little_while_nothing_changes(self):
        e = self.env(quests=((101, 0.5, 0.4),))
        C = e.ns.Compass
        drawn, calls = C.drawn, e.mock.mapCalls
        e.update(10)
        self.assertEqual(C.drawn, drawn)                    # standing still: not drawn again
        self.assertTrue(4 <= e.mock.mapCalls - calls <= 6)  # the quests looked up every two seconds
        for i in range(20):                                 # turning: drawn as you turn
            e.mock.facing = i * 0.05
            e.update(0.05)
        self.assertGreaterEqual(C.drawn - drawn, 18)
        self.assertEqual(e.errors(), [])

    def test_a_fight_steps_it_back(self):
        e = self.env(quests=((101, 0.5, 0.4),))
        C = e.ns.Compass
        self.assertAlmostEqual(C.frame.alpha, 1, 3)
        e.mock.fire("PLAYER_REGEN_DISABLED")
        e.update(0.6)
        self.assertAlmostEqual(C.frame.alpha, C.FIGHT, 3)
        e.mock.fire("PLAYER_REGEN_ENABLED")
        e.update(0.6)
        self.assertAlmostEqual(C.frame.alpha, 1, 3)
        self.assertEqual(e.errors(), [])

    def test_the_demo(self):
        e = self.env()
        e.cmd("compassdemo")
        e.update(0.5)
        keys = {s.m.key for s in e.ns.Compass.shownMarks.values()}
        self.assertTrue({"demo1", "demo2", "demo4"} <= keys)       # (the third far off to the left)
        e.update(e.ns.Compass.DEMO + 3)
        self.assertEqual(len(list(e.ns.Compass.marks.values())), 0)
        e.cmd("compass off")
        self.assertIn("off", plain(e.cmd("compassdemo")))
        self.assertEqual(e.errors(), [])

    def test_it_stays_clear_of_your_buffs(self):
        e = self.env()
        C = e.ns.Compass
        self.assertEqual(C.width, C.W)
        e.lua.execute("""local mock = ...
            UIParent.GetWidth = function() return 1365 end
            UIParent.GetEffectiveScale = function() return 1 end
            local b = mock.addBuff()
            b.shown = true
            b.GetLeft = function() return 820 end
            b.GetEffectiveScale = function() return 1 end""", e.mock)
        e.mock.fire("UNIT_AURA", "player")
        e.update(0.6)
        self.assertAlmostEqual(C.width, 2 * (820 - 682.5 - 16), 3)
        self.assertEqual(C.frame.width, C.width)
        e.cmd("compassplace 2")                             # at the bottom the buffs are not in its way
        e.mock.fire("UNIT_AURA", "player")
        e.update(0.6)
        self.assertEqual(C.width, C.W)
        self.assertEqual(e.errors(), [])


class ClassShown(unittest.TestCase):
    """A player's class colour on the name, and their class icon, also where the game keeps the class secret."""

    def test_a_plain_class_colours_the_name(self):
        e = Env()
        e.target(name="Uther", isPlayer=True, attackable=True, reaction=2, **{"class": "MAGE"})
        e.update(0.3)
        f = e.frames.target
        self.assertEqual(tuple(round(f.name.tcolor[i], 2) for i in (1, 2, 3)), (0.25, 0.78, 0.92))
        e.cmd("classnames off")
        e.mock.fire("PLAYER_TARGET_CHANGED")
        self.assertEqual(tuple(round(f.name.tcolor[i], 2) for i in (1, 2, 3)),
                         tuple(round(v, 2) for v in e.ns.colors.text.values()))
        self.assertEqual(e.errors(), [])

    def test_a_secret_class_is_shown_by_the_game(self):
        e = Env()
        e.lua.execute("""
            SECRET_CLASS = { secret = true }
            UnitClass = function(u) if u == "target" or u:match("^nameplate") then return SECRET_CLASS, SECRET_CLASS end end
            local col = { secret = true }
            C_ClassColor = { GetClassColor = function(c) return { GetRGB = function() return col, col, col end } end }
            GetClassAtlas = function(c) return { secret = true, atlas = true } end
        """)
        e.target(name="Joshua", isPlayer=True, attackable=True, reaction=2)
        e.update(0.3)
        f = e.frames.target
        self.assertTrue(e.lua.eval("function(t) return t.tcolor and t.tcolor[1] and t.tcolor[1].secret end")(f.name))
        tex = f.visual.classTex
        self.assertTrue(tex.shown)                                    # the icon, from the game's own atlas
        p = e.mock.addPlate("nameplate1", e.mock.units.target)
        o = e.ns.Nameplates.byPlate[p]
        self.assertTrue(o.classTex.shown)
        self.assertTrue(e.ns.secretWays.classIcon)
        # a way the game refuses is never tried again (each refusal counts as an addon error)
        e.lua.execute("TRIES = 0; GetClassAtlas = function() TRIES = TRIES + 1; error('refused') end; ns_reset = true")
        e.ns.secretWays.classAtlas = None
        for _ in range(5):
            e.mock.fire("PLAYER_TARGET_CHANGED")
        self.assertEqual(e.g.TRIES, 1)
        self.assertFalse(f.visual.classTex.shown)
        self.assertEqual(e.errors(), [])


class PvPPlates(unittest.TestCase):
    """A battleground is crowded: the class icon never over a name; your side a slim green bar, the other side
    the need-to-know (health, power, level, class, name)."""

    def secret(self, e):
        e.lua.execute("""
            SECRET_CLASS = { secret = true }
            UnitClass = function(u) if u == "target" or u:match("^nameplate") then return SECRET_CLASS, SECRET_CLASS end end
            local col = { secret = true }
            C_ClassColor = { GetClassColor = function(c) return { GetRGB = function() return col, col, col end } end }
            GetClassAtlas = function(c) return { secret = true, atlas = true } end
            SECRET_W = { secret = true }
        """)

    def test_the_class_icon_goes_to_the_bar_when_the_names_width_is_secret(self):
        e = Env()
        self.secret(e)
        e.target(name="Foxidin", isPlayer=True, attackable=True, reaction=2)
        e.update(0.3)
        p = e.mock.addPlate("nameplate1", e.mock.units.target)
        o = e.ns.Nameplates.byPlate[p]
        o.name.GetStringWidth = e.lua.eval("function() return SECRET_W end")   # (refused: kept secret)
        e.ns.SecretClassIcon(o, o.name, "nameplate1", True, o.health)
        t = o.classTex
        self.assertTrue(t.shown)
        self.assertEqual((t.points[1][1], t.points[1][3]), ("RIGHT", "LEFT"))
        self.assertTrue(e.same(t.points[1][2], o.health))            # at the bar's end, never over the name
        f = e.frames.target
        f.name.GetStringWidth = e.lua.eval("function() return SECRET_W end")
        e.mock.fire("PLAYER_TARGET_CHANGED")
        ft = f.visual.classTex
        self.assertTrue(e.same(ft.points[1][2], f.health))            # the target frame the same
        badge = e.lua.eval("function(bar) local t = bar:CreateTexture(); bar.factionBadge = t; t:Show(); return t end")(f.health)
        e.ns.SecretClassIcon(f.visual, f.name, "target", True, f.health)   # the other faction's badge there too:
        self.assertTrue(e.same(ft.points[1][2], badge))               # the icon beside it, not under it
        self.assertEqual(e.errors(), [])

    def test_a_secret_class_colours_the_bar_through_its_texture_tried_once(self):
        e = Env()
        self.secret(e)
        e.lua.execute("""
            TINTS = 0
            local col = { secret = true }
            C_ClassColor = { GetClassColor = function(c) return { GetRGB = function() return col, col, col end } end }
        """)
        e.target(name="Gnomesayin Slime", isPlayer=True, attackable=True, reaction=2)
        e.update(0.3)
        f = e.frames.target
        self.assertTrue(e.ns.secretWays.classBarColor)               # the bar's texture took the class's colour
        # refused: never tried again (each refusal would count as an addon error)
        e.ns.secretWays.classBarColor = False
        tries = e.lua.eval("function(bar) local n = 0; local t = bar.fill:GetStatusBarTexture(); local v = t.SetVertexColor; t.SetVertexColor = function(...) n = n + 1; return v(...) end; return function() return n end end")(f.health)
        for _ in range(3):
            e.mock.fire("PLAYER_TARGET_CHANGED")
            e.update(0.2)
        self.assertEqual(tries(), 0)
        self.assertEqual(e.errors(), [])

    def test_the_games_countdown_moves_below_the_target_frame(self):
        e = Env()
        e.lua.execute("TimerTrackerTimer1 = CreateFrame('StatusBar', 'TimerTrackerTimer1', UIParent); TimerTrackerTimer1:SetPoint('TOP', UIParent, 'TOP', 0, -155)")
        e.mock.fire("START_TIMER")
        e.mock.advance(0.6)
        t = e.g.TimerTrackerTimer1
        self.assertEqual((t.points[1][1], t.points[1][3]), ("TOP", "BOTTOM"))
        self.assertTrue(e.same(t.points[1][2], e.frames.target))      # below the target frame, clear of it
        self.assertEqual(e.errors(), [])

    def test_the_spirit_healers_countdown_stays_in_sight(self):
        e = Env()
        e.mock.state.instance = "pvp"
        e.lua.execute("""
            GHOST, LEFT = true, 14.2
            UnitIsGhost = function() return GHOST end
            GetAreaSpiritHealerTime = function() return LEFT end
        """)
        e.update(0.5)
        f = e.g.ControllerCamHUD_Resurrect                            # a ghost in a battleground: always there
        self.assertTrue(f.shown)
        self.assertEqual(plain(f.text.text), "Resurrection in 15 s")
        e.mock.fire("AREA_SPIRIT_HEALER_IN_RANGE")                    # talking to the healer: its window says it
        self.assertFalse(f.shown)
        e.mock.fire("AREA_SPIRIT_HEALER_OUT_OF_RANGE")                # its window closed: ours again
        self.assertTrue(f.shown)
        e.g.LEFT = 0                                                   # (cancelled)
        e.update(0.5)
        self.assertIn("Talk to the spirit healer", plain(f.text.text))
        e.mock.fire("PLAYER_ALIVE")
        e.g.GHOST = False
        e.update(0.5)
        self.assertFalse(f.shown)                                     # alive: gone
        self.assertEqual(e.errors(), [])

    def test_your_side_is_a_slim_green_bar_and_theirs_the_need_to_know(self):
        e = Env()
        e.mock.state.instance = "pvp"
        ally = e.mock.addPlate("nameplate2", e.lua.table(name="Reyla", isPlayer=True, attackable=False, reaction=5,
                                                          health=800, healthMax=1000, level=39))
        a = e.ns.Nameplates.byPlate[ally]
        self.assertTrue(a.pvpAlly and a.mini and a.bars)              # small, with its bar, at a glance
        c = a.health.fill.color
        self.assertEqual((round(c[1], 2), round(c[2], 2), round(c[3], 2)), (0.30, 0.82, 0.34))
        self.assertEqual(e.ns.Nameplates.NameAlpha(a), 0)             # (no name on it)
        enemy = e.mock.addPlate("nameplate3", e.lua.table(name="Foxidin", isPlayer=True, attackable=True, reaction=2,
                                                           health=800, healthMax=1000, level=39, guild="Colombia forever"))
        o = e.ns.Nameplates.byPlate[enemy]
        self.assertTrue(o.pvpEnemy and not o.mini)
        self.assertFalse(o.sub.shown)                                 # no guild line
        self.assertIn("39", plain(o.name.text))                       # the level, and the name
        self.assertIn("Foxidin", plain(o.name.text))
        self.assertFalse(o.health.factionShown)                       # no faction tint over red: it read as pink
        e.mock.state.instance = None                                  # out of the battleground: as ever
        e.mock.fire("PLAYER_ENTERING_WORLD")
        e.update(0.6)
        self.assertEqual(e.errors(), [])


class CompassCamera(unittest.TestCase):
    """The compass shows the way the camera looks, which the analog stick can leave apart from the character."""

    def test_without_a_way_to_read_the_camera_there_is_no_switch_for_it(self):
        e = Env()
        keys = [d.key for d in e.ns.settings.values()]
        self.assertIn("compassPlace", keys)
        self.assertNotIn("compassCamera", keys)                       # it could not do anything here
        self.assertIn("none to read in this game", e.ns.Compass.Describe())
        has = Env(setup=lambda env: env.lua.execute("GetCameraYaw = function() return 1.0 end"))
        self.assertIn("compassCamera", [d.key for d in has.ns.settings.values()])
        self.assertAlmostEqual(has.ns.Compass.Facing(), 1.0)
        self.assertEqual(e.errors() + has.errors(), [])

    def test_the_compass_follows_the_camera_where_the_game_says_and_the_character_otherwise(self):
        e = Env(setup=lambda env: env.lua.execute("GetCameraYaw = function() return 1.0 end"))
        C = e.ns.Compass
        e.lua.execute("GetPlayerFacing = function() return 0.2 end; GetCameraYaw = nil")
        C.cam = None
        self.assertAlmostEqual(C.Facing(), 0.2)                      # no camera API: the character's
        e.lua.execute("GetCameraYaw = function() return 1.0 end")
        C.cam = None                                                  # (looked for again)
        self.assertAlmostEqual(C.Facing(), 1.0)                      # the camera's
        e.cmd("compasscamera off")
        self.assertAlmostEqual(C.Facing(), 0.2)                      # off: the character's again
        self.assertIn("camera: GetCameraYaw", C.Describe())
        self.assertEqual(e.errors(), [])


class ItemActions(unittest.TestCase):
    """Hold R3 on an item in the game's own bags or bank: try on, mark, details, destroy (in a window of ours)."""

    GAME = """
        mock.cursor, mock.deleted, mock.tried = nil, {}, {}
        function ClearCursor() mock.cursor = nil end
        function GetCursorInfo() if mock.cursor then return "item", mock.cursor.id end end
        C_Container.PickupContainerItem = function(bag, slot)
            local it = mock.bags[bag] and mock.bags[bag][slot]
            if it then mock.cursor = { id = it.id, bag = bag, slot = slot } end
        end
        function DeleteCursorItem()
            if mock.keep then return end
            local c = mock.cursor
            if c then mock.deleted[#mock.deleted + 1] = c.id; mock.bags[c.bag][c.slot] = nil; mock.cursor = nil end
        end
        C_Item.IsDressableItemByID = function(id) return id == 2000 end
        function DressUpItemLink(link) mock.tried[#mock.tried + 1] = link end
    """

    def game(self, env):
        env.lua.globals().mock = env.mock                            # (the mock, by name, for the lines above)
        env.lua.execute(self.GAME)

    def env(self, **kw):
        e = Env(setup=self.game, **kw)
        put, T = e.mock.put, e.lua.table
        put(0, 1, T(id=2589, name="Linen Cloth", quality=1, price=13, count=20, stack=20, **{"class": 7}))
        put(0, 2, T(id=2000, name="Bronze Axe", quality=2, price=500, **{"class": 2}))
        put(0, 3, T(id=3000, name="Rare Ring", quality=3, price=900, **{"class": 4}))
        e.g.ContainerFrame1.Show(e.g.ContainerFrame1)
        e.update(0.5)
        return e

    def stick(self, e, held):
        b = e.g.ControllerCamHUD_StickKey
        b.scripts.OnClick(b, "LeftButton", True)
        e.update(held)
        b.scripts.OnClick(b, "LeftButton", False)

    def asked(self, e):
        v = e.ns.Dialog.visible
        return v.which if v else None

    def buttons(self, e):
        spec = e.ns.Dialog.visible.dialog
        return [spec.button1, spec.button2, spec.button3, spec.button4]

    def key(self, e, key):
        b = e.g["ControllerCamHUD_Key_Ask_" + key]
        b.scripts.OnClick(b)

    def test_a_tap_still_sorts_and_a_hold_on_an_item_asks_about_it(self):
        e = self.env()
        self.assertEqual(e.mock.overrides.PADRSTICK, "CLICK ControllerCamHUD_StickKey:LeftButton")
        e.mock.pointAt(0, 1)
        self.stick(e, 0.1)                                           # a tap: the bags are sorted, nothing asked
        self.assertIn("sorted", list(e.mock.printed.values())[-1])
        self.assertIsNone(self.asked(e))
        self.stick(e, 0.8)                                           # a hold: asked about the item
        self.assertEqual(self.asked(e), "CCHUD_ITEM")
        self.assertIn("Linen Cloth", e.ns.Dialog.visible.text)
        self.assertEqual(self.buttons(e), ["Item details", "Close", "Change mark", "More"])
        self.assertEqual(e.errors(), [])

    def test_a_hold_on_nothing_does_what_a_tap_does(self):
        e = self.env()
        e.mock.pointAt(None)
        self.stick(e, 0.8)
        self.assertIsNone(self.asked(e))
        self.assertIn("sorted", list(e.mock.printed.values())[-1])
        self.assertEqual(e.errors(), [])

    def test_with_the_switch_off_the_hold_is_gone(self):
        e = self.env()
        e.cmd("padactions off")
        e.update(0.5)
        self.assertEqual(e.mock.overrides.PADRSTICK, "CCHUD_SORT")   # the sort binding itself, as before
        e.cmd("padsort off")
        e.update(0.5)
        self.assertIsNone(e.mock.overrides.PADRSTICK)                # and R3 is never taken for the hold alone
        self.assertEqual(e.errors(), [])

    def test_with_the_hold_off_a_press_moves_once(self):
        e = self.env()
        e.cmd("padactions off")
        e.mock.openBank(True)
        e.update(0.5)
        e.mock.pointAt(0, 1)
        self.stick(e, 0.8)                                           # pressed and let go: one move, as let go
        self.assertEqual(list(e.mock.moved.values()), [2589])
        self.assertIsNone(self.asked(e))
        self.assertEqual(e.errors(), [])

    def test_the_hold_is_told_of_once(self):
        e = self.env()
        told = [m for m in e.mock.printed.values() if "Hold R3 on an item" in m]
        self.assertEqual(len(told), 1)
        e.g.ContainerFrame1.Hide(e.g.ContainerFrame1)
        e.update(0.5)
        e.g.ContainerFrame1.Show(e.g.ContainerFrame1)
        e.update(0.5)
        self.assertEqual(len([m for m in e.mock.printed.values() if "Hold R3 on an item" in m]), 1)
        self.assertTrue(e.db.actionsTold)

    def test_try_on_and_the_mark(self):
        e = self.env()
        e.mock.pointAt(0, 2)
        e.g.ControllerCamHUD_ItemActions()                           # the key binding
        self.assertEqual(self.buttons(e), ["Try on", "Close", "Change mark", "More"])
        self.key(e, "PAD3")                                          # the mark: junk, and asked again
        self.assertTrue(e.db.sell.junk[2000])
        self.assertEqual(self.asked(e), "CCHUD_ITEM")
        self.assertIn("Your mark: junk", e.ns.Dialog.visible.text)
        self.key(e, "PAD1")
        self.assertEqual(len(list(e.mock.tried.values())), 1)
        self.assertIn("item:2000", e.mock.tried[1])
        self.assertIsNone(self.asked(e))
        self.assertEqual(e.errors(), [])

    def test_destroy_takes_three_different_buttons(self):
        e = self.env()
        e.mock.pointAt(0, 1)
        e.cmd("itemmenu")
        self.key(e, "PAD4")                                          # More
        self.assertEqual(self.asked(e), "CCHUD_ITEM_MORE")
        self.key(e, "PAD3")                                          # Destroy
        self.assertEqual(self.asked(e), "CCHUD_ITEM_DESTROY")
        self.assertIn("Destroy", e.ns.Dialog.visible.text)
        self.assertIn("x20", e.ns.Dialog.visible.text)
        self.key(e, "PAD1")                                          # the first button again: only closes
        self.assertIsNone(self.asked(e))
        self.assertEqual(list(e.mock.deleted.values()), [])
        e.cmd("itemmenu")
        self.key(e, "PAD4")
        self.key(e, "PAD3")
        self.key(e, "PAD4")                                          # Destroy, on a button of its own
        self.assertEqual(list(e.mock.deleted.values()), [2589])
        self.assertIsNone(e.mock.cursor)
        self.assertTrue(any("Destroyed" in m for m in e.mock.printed.values()))
        self.assertEqual(e.errors(), [])

    def test_what_is_never_destroyed(self):
        e = self.env()
        A = e.ns.ItemActions
        self.assertTrue(A.CanDestroy(A.Entry(0, 1)))
        self.assertFalse(A.CanDestroy(A.Entry(0, 3)))                # rare: the game's own way, with DELETE
        e.db.sell.keep[2589] = True
        self.assertFalse(A.CanDestroy(A.Entry(0, 1)))                # marked as kept
        e.db.sell.keep[2589] = None
        e.mock.state.combat = True
        self.assertFalse(A.CanDestroy(A.Entry(0, 1)))
        e.mock.state.combat = False
        e.mock.bags[0][2].inSet, e.mock.bags[0][2].bound = True, True
        self.assertFalse(A.CanDestroy(A.Entry(0, 2)))
        e.mock.pointAt(0, 3)
        e.cmd("itemmenu")
        self.assertEqual(self.buttons(e), ["Item details", "Close", "Change mark", None])
        self.assertEqual(e.errors(), [])

    def test_a_slot_that_changed_or_a_game_that_refuses_destroys_nothing(self):
        e = self.env()
        A = e.ns.ItemActions
        asked = A.Entry(0, 1)
        e.mock.bags[0][1].count = 3                                  # the stack changed since it was asked about
        self.assertFalse(A.Destroy(asked))
        self.assertEqual(list(e.mock.deleted.values()), [])
        e.mock.keep = True                                           # the game will not delete it
        self.assertFalse(A.Destroy(A.Entry(0, 1)))
        self.assertIsNone(e.mock.cursor)                             # and nothing is left on the cursor
        self.assertTrue(any("The game kept" in m for m in e.mock.printed.values()))
        self.assertEqual(e.errors(), [])

    def test_the_games_cursor_names_the_item_where_the_pointer_does_not(self):
        e = self.env()
        e.mock.pointAt(None)
        e.lua.execute("""
            local b = CreateFrame("Button", nil, ContainerFrame1)
            b.GetBagID = function() return 0 end
            b.GetID = function() return 2 end
            HIDDEN = false
            SmartNavigation = { GetCurrentButton = function() return b end,
                                IsCursorHidden = function() return HIDDEN end }""")
        self.assertTrue(e.ns.ItemActions.Open(e.ns.ItemActions))
        self.assertIn("Bronze Axe", e.ns.Dialog.visible.text)
        e.ns.Dialog.Close("override")
        e.g.HIDDEN = True                                            # (the cursor not in use: nothing pointed at)
        self.assertFalse(e.ns.ItemActions.Open(e.ns.ItemActions))
        self.assertEqual(e.errors(), [])

    def test_the_newer_banks_buttons_are_known_by_their_own_methods(self):
        e = self.env()
        slot = e.lua.eval("""function(SlotOf)
            local b = CreateFrame("Button")
            b.GetBankTabID = function() return 6 end
            b.GetContainerSlotID = function() return 4 end
            return SlotOf(b) end""")(e.ns.ItemActions.SlotOf)
        self.assertEqual(tuple(slot), (6, 4))

    def test_nothing_in_a_fight_and_nothing_once_the_hud_is_off(self):
        e = self.env()
        e.mock.pointAt(0, 1)
        e.mock.state.combat = True
        self.assertFalse(e.ns.ItemActions.Open(e.ns.ItemActions))
        e.mock.state.combat = False
        e.cmd("itemmenu")
        self.assertEqual(self.asked(e), "CCHUD_ITEM")
        e.cmd("off")
        self.assertIsNone(self.asked(e))
        self.assertEqual(e.errors(), [])


class BagProbe(unittest.TestCase):
    """/cchud bagprobe: what the game's own bags, bank and menus are here (read only), kept for the next reload."""

    def test_it_notes_the_menu_functions_the_cursor_and_an_open_menu_then_stops(self):
        e = Env()
        e.lua.execute("""
            local menu = CreateFrame("Frame", nil, UIParent)
            menu.GetMenuDescription = function() return { GetTag = function() return "MENU_TEST_ITEM" end } end
            local words = menu:CreateFontString()
            words.text = "Split Stack"
            words.GetText = function(self) return self.text end
            OPEN = false
            Menu = { ModifyMenu = function() error("never called") end, GetManager = function()
                return { IsAnyMenuOpen = function() return OPEN end, GetOpenMenu = function() return menu end } end }
            local b = CreateFrame("Button", nil, ContainerFrame1)
            b.GetBagID = function() return 0 end
            b.GetID = function() return 1 end
            SmartNavigation = { GetCurrentButton = function() return b end }
            ContainerFrame1:Show()""")
        e.cmd("bagprobe")
        out = e.db.nativeProbe
        self.assertEqual(out.exists["Menu.ModifyMenu"], "function")
        self.assertEqual(out.exists["Menu.PrintOpenMenuTags"], "nil")
        e.update(1)
        self.assertEqual(len(list(out.menus.values())), 0)
        e.g.OPEN = True
        e.update(1)
        menus = list(out.menus.values())
        self.assertEqual(len(menus), 1)
        self.assertEqual(menus[0].tag, "MENU_TEST_ITEM")
        self.assertIn("Split Stack", menus[0].words)
        self.assertIsNotNone(out.windows.ContainerFrame1)
        cursor = list(out.cursor.values())[0]
        self.assertEqual(cursor.slotFound, "0 1")
        e.update(95)
        self.assertTrue(any("Done looking" in m for m in e.mock.printed.values()))
        self.assertIsNone(e.ns.BagProbe.out)
        self.assertEqual(list(out.errors.values()), [])
        self.assertEqual(e.errors(), [])

    def test_the_combined_bags_layout_is_kept_as_they_open(self):
        e = Env()
        e.lua.execute("""
            local bags = CreateFrame("Frame", "ContainerFrameCombinedBags", UIParent)
            local function at(f, x, y) f.GetLeft = function() return x end; f.GetTop = function() return y end end
            at(bags, 100, 500)
            local bar = CreateFrame("Frame", nil, bags)
            bags.GamepadBagBar = bar
            local head = CreateFrame("Button", nil, bar)
            bar.Bag0SlotButton = head
            head.kind = "Button"
            head.BagSlotOnClick = function() end
            head:SetPoint("TOPLEFT", bags, "TOPLEFT", 8, -60)
            at(head, 108, 440)
            local inside = CreateFrame("Frame", nil, head)
            local item = CreateFrame("Button", nil, bags)
            item.kind = "Button"
            item.GetBagID = function() return 1 end
            item.GetID = function() return 3 end
            item.IsProtected = function() return true, true end
            bags:Hide()""")
        e.db.debug = True
        e.update(1)
        self.assertIsNone(e.db.bagLayout)                            # (closed: nothing to read)
        e.g.ContainerFrameCombinedBags.Show(e.g.ContainerFrameCombinedBags)
        e.update(1)
        lines = list(e.db.bagLayout.lines.values())
        head = [line for line in lines if line.startswith("GamepadBagBar.Bag0SlotButton ")]
        self.assertEqual(len(head), 1, lines)
        self.assertIn("at 8,60", head[0])
        self.assertIn("TOPLEFT>ContainerFrameCombinedBags:TOPLEFT 8,-60", head[0])
        self.assertIn("(a bag's button)", head[0])
        self.assertFalse(any(line.startswith("GamepadBagBar.Bag0SlotButton.") for line in lines))
        self.assertTrue(any("protected" in line and "GetBagID=1 GetID=3" in line for line in lines), lines)
        e.g.ContainerFrameCombinedBags.Hide(e.g.ContainerFrameCombinedBags)
        e.update(1)
        self.assertEqual(len(list(e.db.bagLayout.lines.values())), len(lines))    # (kept once they close)
        self.assertEqual(e.errors(), [])

    def test_a_client_with_none_of_it_is_only_noted(self):
        e = Env()
        e.cmd("bagprobe")
        e.update(2)
        self.assertEqual(e.db.nativeProbe.exists["Menu.ModifyMenu"], "nil")
        self.assertEqual(e.errors(), [])


class SelfManaging(unittest.TestCase):
    """A handler that keeps failing steps aside instead of failing on every frame, then is tried again."""

    def test_a_failing_handler_steps_aside_and_comes_back(self):
        e = Env()
        e.lua.execute("CALLS = 0; BAD = ns_protect(function() CALLS = CALLS + 1; error('always') end)") if False else None
        bad = e.lua.eval("""function(Protect) CALLS = 0
            return Protect(function() CALLS = CALLS + 1; error("always") end) end""")(e.ns.Protect)
        for _ in range(12):
            bad()
        self.assertEqual(e.g.CALLS, 5)                               # five failures, then it steps aside
        self.assertEqual(len(e.errors()) > 0, True)
        e.mock.advance(31)
        bad()
        self.assertEqual(e.g.CALLS, 6)                               # and is tried again after its while
        self.assertTrue(len(list(e.ns.BREAKER.trips.values())) >= 1)

    def test_one_failing_handler_leaves_the_others_alone(self):
        e = Env()
        good, bad = e.lua.eval("""function(Protect) GOOD = 0
            return Protect(function() GOOD = GOOD + 1 end), Protect(function() error("no") end) end""")(e.ns.Protect)
        for _ in range(10):
            bad()
            good()
        self.assertEqual(e.g.GOOD, 10)                               # the good one never stepped aside


class NoSecretArithmetic(unittest.TestCase):
    """A blocked operation on a value the game keeps secret counts as an addon error even inside a pcall; in a
    battleground they reached the game's "large number of errors" warning. None is ever tried."""

    def test_a_hidden_health_percent_is_never_multiplied(self):
        e = Env()
        e.lua.execute("""
            TRIED = 0
            local mt = { __mul = function() TRIED = TRIED + 1; error("blocked") end,
                         __add = function() TRIED = TRIED + 1; error("blocked") end,
                         __lt = function() TRIED = TRIED + 1; error("blocked") end }
            SECRET_PCT = setmetatable({ secret = true }, mt)
            UnitHealthPercent = function() return SECRET_PCT end
        """)
        fs = e.g.CreateFrame("Frame").CreateFontString(e.g.CreateFrame("Frame"))
        e.ns.SecretPercent(fs, "target")
        self.assertEqual(e.g.TRIED, 0)
        self.assertEqual(e.errors(), [])


class NoSecretAlpha(unittest.TestCase):
    def test_a_plates_hidden_alpha_is_never_worked_on(self):
        # in a battleground the game may keep a plate name's alpha to itself: the threat glow behind the name
        # multiplied it on every frame, refused each time, an addon error each (PlateStates.lua:346, 1.4.15)
        e = Env()
        e.lua.execute("""
            TRIED = 0
            local mt = { __mul = function() TRIED = TRIED + 1; error("blocked") end,
                         __sub = function() TRIED = TRIED + 1; error("blocked") end,
                         __lt = function() TRIED = TRIED + 1; error("blocked") end }
            HIDDEN_ALPHA = setmetatable({ secret = true }, mt)
        """)
        p = e.mock.addPlate("nameplate1", e.lua.table(name="Foe", level=40, health=5, healthMax=10,
                                                      attackable=True, reaction=2, combat=True))
        o = e.ns.Nameplates.byPlate[p]
        e.lua.eval("function(o) o.name.GetAlpha = function() return HIDDEN_ALPHA end; o.threatState = 'aggro'; o.threatPop = 0.3 end")(o)
        e.update(1.0, step=0.05)
        self.assertEqual(e.g.TRIED, 0)
        self.assertIsNone(e.ns.AlphaOf(o.name))
        self.assertEqual(e.errors(), [])


class TestFileShape(unittest.TestCase):
    def test_every_class_runs_when_the_file_is_run_as_a_script(self):
        # CI runs this file as a script: classes written after unittest.main() never ran there (1.4.12)
        text = open(os.path.abspath(__file__), encoding="utf-8").read().rstrip()
        self.assertTrue(text.endswith('if __name__ == "__main__":' + chr(10) + '    unittest.main()'))
        self.assertEqual(len(re.findall(r"(?m)^\s*unittest\.main\(", text)), 1)   # (the one call: at the end)


class OptionsLayout(unittest.TestCase):
    """Every setting on the page you would look for it on, under a heading that says what it is."""

    def defs(self, e):
        out = []
        for i in range(1, 5000):
            d = e.ns.settings[i]
            if d is None:
                break
            if d.label and d.key != "advancedOptions":
                out.append(d)
        return out

    def test_every_setting_has_its_place(self):
        e = Env()
        place = e.ns.OptionsLook.PlaceOf
        missing = [d.key or d.id or d.label for d in self.defs(e) if not place(d)]
        self.assertEqual(missing, [])                                # none falls to the end of a page

    def test_every_name_in_the_layout_is_a_setting(self):
        e = Env()
        names = set()
        for d in self.defs(e):
            names.update(n for n in (d.key, d.id, d.label) if n)
        pages = list(e.ns.OptionsLook.PAGES.values())
        for p in e.ns.OptionsLook.LAYOUT.values():
            self.assertTrue(p.page == "General" or p.page in pages, p.page)
            for g in p.groups.values():
                for k, name in g.items():
                    if k != "head":
                        self.assertIn(name, names)                      # (no typo leaves a setting unplaced)

    def test_the_aiming_dot_has_its_own_place(self):
        e = Env()
        e.ns.BuildOptions()
        rows = {r["def"].label: r for r in e.ns.optionRows.values()}
        for label in ("Aiming dot", "Aiming dot: colour", "Aiming dot: size", "Aiming dot: opacity"):
            self.assertEqual(rows[label].page, "Camera and aiming", label)
        self.assertTrue(rows["Aiming dot"].widget.shown)             # found without the advanced options
        self.assertEqual(rows["Controller vibration"].page, "Vibration")
        self.assertEqual(rows["Flights: a game on the way"].page, "Flights")
        self.assertEqual(rows["Market tab at the auction house"].page, "Items and auction house")
        self.assertEqual(rows["Target of target"].page, "Target, party and raid")
        self.assertEqual(e.errors(), [])

    def test_headings_show_with_what_is_under_them(self):
        e = Env()
        e.ns.BuildOptions()
        rows = {r["def"].label: r for r in e.ns.optionRows.values()}
        # the camera page: "Aiming dot" heading shown (its first row is basic), "Camera" hidden until advanced
        content = rows["Aiming dot"].widget.parent
        texts = {fs.text: fs for fs in e.lua.eval("function(f) return {f:GetRegions()} end")(content).values()
                 if fs.kind == "FontString"}
        self.assertTrue(texts["Aiming dot"].shown)
        self.assertFalse(texts["Camera"].shown)
        cb = rows["Show advanced options"].widget
        cb.checked = True
        cb.scripts.OnClick(cb)
        self.assertTrue(texts["Camera"].shown)
        self.assertTrue(rows["Presets set the camera distance"].widget.shown)
        self.assertEqual(e.errors(), [])


class TransmogSets(unittest.TestCase):
    """The Transmogrify window's own Sets tab (hidden in this client), filled with the sets of your collection."""

    GREEN = [(1, "Helm"), (2, "Shoulders"), (7, "Bracers"), (8, "Gauntlets"), (9, "Belt"), (10, "Leggings"), (11, "Boots")]

    def env(self, have=4, **kw):
        e = Env(**kw)
        for i, (cat, piece) in enumerate(self.GREEN):                # the first `have` of them collected
            e.mock.tmItem(cat, 100 + i, 200 + i, "Green Iron " + piece, i < have)
        return e

    def bear(self, e):
        for i, (cat, piece) in enumerate([(1, "Helm"), (8, "Gloves"), (11, "Boots")]):
            e.mock.tmItem(cat, 300 + i, 400 + i, piece + " of the Bear", True)

    def open_sets(self, e):
        win = e.mock.openTransmog()
        w = win.WardrobeCollection
        w.SetTab(w, 2)                                               # (RB from Items)
        e.update(1)
        return e.ns.TransmogSets

    def slot(self, e, n):
        return e.mock.tm.slots[n]

    def press_x(self, e):
        e.g.ControllerCamHUD_Key_TransmogSets_PAD3.scripts.OnClick()

    def test_y_deletes_the_custom_set_the_cursor_is_on_after_asking(self):
        e = self.env()
        e.lua.execute("""
            SETS = { [11] = "Raid night", [12] = "Town look" }
            DELETED = {}
            C_TransmogCollection.GetCustomSets = function() return { 11, 12 } end
            C_TransmogCollection.GetCustomSetInfo = function(id) return SETS[id], 1 end
            C_TransmogCollection.DeleteCustomSet = function(id) DELETED[#DELETED + 1] = id; SETS[id] = nil end
        """)
        win = e.mock.openTransmog()
        e.update(0.5)
        TS = e.ns.TransmogSets
        self.assertTrue(TS.hint.shown)                               # the hint under the window
        self.assertEqual(e.mock.overrides.PAD4, "CLICK ControllerCamHUD_Key_TransmogCustom_PAD4:LeftButton")
        e.lua.execute("""
            local row = CreateFrame("Button", nil, UIParent)
            local fs = row:CreateFontString()
            fs:SetText("Town look")
            MOCK_ROW = row
            GetMouseFoci = function() return { MOCK_ROW } end
        """)
        e.g.ControllerCamHUD_Key_TransmogCustom_PAD4.scripts.OnClick()
        self.assertIn("Town look", plain(e.ns.Dialog.visible.text))    # asked first, by name
        self.assertEqual(len(e.g.DELETED), 0)
        e.mock.answer("accept")
        e.mock.advance(0.1)
        self.assertEqual(list(e.g.DELETED.values()), [12])
        e.lua.execute("GetMouseFoci = function() return {} end")
        e.g.ControllerCamHUD_Key_TransmogCustom_PAD4.scripts.OnClick()
        self.assertIsNone(e.ns.Dialog.visible)                       # nothing under the cursor: nothing asked
        self.assertEqual(e.errors(), [])

    def test_the_games_hidden_sets_tab_shows_where_it_belongs_and_its_page_is_ours(self):
        e = self.env()
        win = e.mock.openTransmog()
        w = win.WardrobeCollection
        self.assertEqual([t.shown for t in w.TabHeaders.tabs.values()], [True, True, True, True])
        self.assertTrue(e.mock.tm.updateTabs >= 2)                   # (the game's own UpdateTabs ran: we only add on)
        page = w.TabContent.SetsFrame
        TS = e.ns.TransmogSets
        self.assertTrue(e.same(TS.panel.parent, page))               # our list lives in the tab's own page
        self.assertEqual(page.PagedContent.alpha, 0)                 # the game's empty one out of sight
        self.assertTrue(e.mock.tm.ignored[page.PagedContent])        # and out of the cursor's reach
        self.assertIsNone(e.mock.overrides["PAD3"])                  # X is ours only while the Sets page shows
        w.SetTab(w, 2)
        self.assertEqual(e.mock.overrides["PAD3"], "CLICK ControllerCamHUD_Key_TransmogSets_PAD3:LeftButton")
        w.SetTab(w, 3)                                               # RB on to Custom Sets: X is the game's again
        self.assertIsNone(e.mock.overrides["PAD3"])
        self.assertEqual(e.errors(), [])

    def test_a_set_whose_names_are_not_loaded_shows_once_they_come(self):
        e = self.env()
        e.lua.execute("""
            NAMES, ASKED = {}, {}
            C_Item.GetItemNameByID = function(id) return NAMES[id] end
            GetItemInfo = function() return nil end
            C_Item.RequestLoadItemDataByID = function(id) ASKED[#ASKED + 1] = id end""")
        quiet = []
        for i, (cat, piece) in enumerate([(1, "Helm"), (8, "Gloves"), (11, "Boots")]):
            quiet.append((e.mock.tmItem(cat, 700 + i, 800 + i, None, True), "Veteran Adventurer " + piece))
        TS = self.open_sets(e)
        names = lambda: [s.name for s in TS.sets.values()]
        self.assertNotIn("Veteran Adventurer", names())              # no names yet: not to be made out
        self.assertEqual(sorted(e.g.ASKED.values()), [s.itemID for s, _ in quiet])   # each asked for, once
        for s, name in quiet:                                        # they arrive
            e.g.NAMES[s.itemID] = name
            e.mock.fire("ITEM_DATA_LOAD_RESULT", s.itemID, True)
        e.mock.advance(TS.AGAIN + 0.1)
        e.update(1)
        self.assertIn("Veteran Adventurer", names())
        self.assertEqual(len(list(e.g.ASKED.values())), 3)           # (never asked again)
        self.assertEqual(TS.unnamedCount, 0)
        self.assertIn("no name yet at the last read 0", "\n".join(TS.Describe().values()))
        self.assertEqual(e.errors(), [])

    def test_a_name_that_never_comes_is_not_asked_for_again(self):
        e = self.env()
        e.lua.execute("""
            ASKED = {}
            C_Item.GetItemNameByID = function() return nil end
            GetItemInfo = function() return nil end
            C_Item.RequestLoadItemDataByID = function(id) ASKED[#ASKED + 1] = id end""")
        s = e.mock.tmItem(1, 900, 901, None, True)
        TS = self.open_sets(e)
        e.mock.fire("ITEM_DATA_LOAD_RESULT", s.itemID, False)        # the game has no such item to give
        e.mock.advance(TS.AGAIN + 0.1)
        TS.ScanAll(TS)
        self.assertEqual(list(e.g.ASKED.values()), [s.itemID])
        self.assertEqual(e.errors(), [])

    def test_sets_come_from_the_item_names_and_say_what_is_missing(self):
        e = self.env()
        self.bear(e)
        e.mock.tmItem(1, 500, 600, "Boots of Speed", True)           # a name nothing else shares: no set
        TS = self.open_sets(e)
        sets = [(s.name, s.have, s.total) for s in TS.sets.values()]
        self.assertEqual(sets, [("... of the Bear", 3, 3), ("Green Iron", 4, 7)])   # whole sets first
        green = TS.rows[2]
        self.assertEqual(green.name.text, "Green Iron")
        self.assertEqual(green.count.text, "4 of 7 pieces")
        self.assertEqual(green.missing.text, "Missing: Waist, Legs, Feet")
        self.assertEqual(TS.rows[1].count.text, "All 3 pieces")
        self.assertEqual(TS.rows[1].missing.text, "")
        self.assertEqual(plain(TS.panel.status.text), "2 sets you have pieces of")
        green.scripts.OnEnter(green)                                 # the cursor on it: its pieces, below
        lines = [fs.text for fs in TS.panel.pane.lines.values() if fs.shown]
        self.assertEqual(lines[0], "Head:  Green Iron Helm")
        self.assertEqual(lines[4], "Waist:  Green Iron Belt  (missing)")
        self.assertEqual(len(lines), 7)
        self.assertEqual(TS.panel.pane.title.text, "Green Iron")
        self.assertEqual(e.errors(), [])

    def test_the_cursor_goes_to_the_first_set_with_the_games_own_call(self):
        e = self.env()
        TS = self.open_sets(e)
        nav = e.mock.tm.nav
        self.assertGreaterEqual(len(nav), 1)
        last = nav[len(nav)]
        self.assertTrue(e.same(last.frame, e.g.TransmogFrame))
        self.assertTrue(e.same(last.button, TS.rows[1]))

    def test_picking_a_set_puts_on_only_what_you_have_and_keeps_nothing(self):
        e = self.env()
        TS = self.open_sets(e)
        row = TS.rows[1]
        row.scripts.OnClick(row)                                     # A on it
        log = [tuple(x.values()) for x in e.mock.tm.setLog.values()]
        self.assertEqual(log, [(0, 0, 0, 200, 1), (1, 0, 0, 201, 1), (7, 0, 0, 202, 1), (8, 0, 0, 203, 1)])
        for n in (0, 1, 7, 8):
            self.assertEqual(self.slot(e, n).saved, 0)               # nothing kept, nothing paid: that is Apply
        self.assertIsNone(e.mock.tm.slots[9])                        # a missing piece leaves its slot alone
        self.assertEqual(plain(TS.panel.status.text), "Green Iron: 4 of 7 pieces put on.")
        self.assertIn("Apply keeps it", TS.panel.hint.text)
        self.assertTrue(TS.panel.undo.enabled)
        self.assertTrue(row.worn.shown)
        e.update(0.5)                                                # every piece took: the line stays
        self.assertEqual(plain(TS.panel.status.text), "Green Iron: 4 of 7 pieces put on.")
        self.assertEqual(e.errors(), [])

    def test_the_slots_option_is_the_one_the_window_shows(self):
        e = self.env()
        e.mock.tm.options[7] = 12                                    # (the wrist slot on another option)
        TS = self.open_sets(e)
        TS.rows[1].scripts.OnClick(TS.rows[1])
        wrist = [x for x in e.mock.tm.setLog.values() if x[1] == 7][0]
        self.assertEqual(wrist[3], 12)

    def test_x_puts_back_what_the_slots_had_before(self):
        e = self.env()
        O = e.g.C_TransmogOutfitInfo
        O.SetPendingTransmog(0, 0, 0, 999, 1)                        # a change of yours on the head, not yet kept
        e.mock.tm.slots[7] = e.lua.table(saved=555, shown=1)         # the wrist as it was kept
        TS = self.open_sets(e)
        TS.rows[1].scripts.OnClick(TS.rows[1])
        self.assertEqual(self.slot(e, 0).pending, 200)
        self.press_x(e)
        self.assertEqual(self.slot(e, 0).pending, 999)               # your own change, back
        self.assertIsNone(self.slot(e, 7).pending)                   # the wrist as it was kept
        self.assertEqual(self.slot(e, 7).saved, 555)
        self.assertIsNone(self.slot(e, 1).pending)
        self.assertEqual(plain(TS.panel.status.text), "Your outfit is back as it was.")
        self.assertFalse(TS.panel.undo.enabled)
        n = len(e.mock.tm.setLog)
        self.press_x(e)                                              # nothing more to undo: nothing happens
        self.assertEqual(len(e.mock.tm.setLog), n)
        self.assertEqual(e.errors(), [])

    def test_two_sets_then_undo_goes_back_to_before_the_first(self):
        e = self.env()
        self.bear(e)
        TS = self.open_sets(e)
        green = [r for r in TS.rows.values() if r.name.text == "Green Iron"][0]
        bear = [r for r in TS.rows.values() if r.name.text == "... of the Bear"][0]
        green.scripts.OnClick(green)
        bear.scripts.OnClick(bear)                                   # the head and hands again, and the feet
        self.assertEqual(self.slot(e, 0).pending, 400)
        TS.panel.undo.scripts.OnClick(TS.panel.undo)                 # the button does what X does
        for n in (0, 1, 7, 8, 11):
            self.assertIsNone(self.slot(e, n).pending, n)
        self.assertEqual(e.errors(), [])

    def test_after_apply_there_is_nothing_to_undo(self):
        e = self.env()
