class CraftValue(unittest.TestCase):
    """What your professions will need soon (the guides' next steps), and a material as it is against crafted."""

    NAMES = {"blacksmithing": "Blacksmithing", "mining": "Mining", "engineering": "Engineering"}
    ITEMS = {3860: ("Mithril Bar", 2000, 20), 3858: ("Mithril Ore", 250, 10), 3577: ("Gold Bar", 150, 20),
             11128: ("Golden Rod", 500, 20), 3478: ("Coarse Grinding Stone", 10, 20), 12359: ("Thorium Bar", 600, 20),
             99001: ("Shiny Scale", 40, 20), 99002: ("Shiny Helm", 900, 1)}

    def env(self, who="Ghostlight-Forever", **ranks):
        e = Env()
        T = e.lua.table
        for id, (name, price, stack) in self.ITEMS.items():
            e.mock["items"][id] = T(name=name, quality=1, price=price, stack=stack, **{"class": 7})
        self.skills(e, **ranks) if who == "Ghostlight-Forever" else self.skills(e)
        if who != "Ghostlight-Forever":
            e.db.inventory[who] = T(bags=T(), bank=T(), prof=T(**{k: T(name=self.NAMES[k], rank=r, cap=300)
                                                                   for k, r in ranks.items()}))
        return e

    def skills(self, e, **ranks):
        T = e.lua.table
        e.mock.skills = e.lua.table_from([T(name=self.NAMES[k], rank=r, cap=300) for k, r in ranks.items()])
        e.mock.fire("SKILL_LINES_CHANGED")
        e.update(0.5)

    def me(self, e):
        return e.db.inventory["Ghostlight-Forever"]

    def advice(self, e, id):
        lines = [plain(list(l.values())[0]) for l in e.mock.itemTooltip(id).values()]
        return lines[lines.index("Recommendation:"):]

    def why(self, e, id):
        verdict, _, want = e.ns.Market.Verdict(id)
        return verdict, want and want.why

    def test_a_bar_the_next_steps_use_is_kept_and_says_when(self):
        e = self.env(blacksmithing=180)
        M = e.ns.Market
        self.assertEqual(self.why(e, 3860),
                         ("keep", "Blacksmithing needs it from 210 (you're at 180), for Heavy Mithril Gauntlet"))
        self.assertKept(M, 3860)
        advice = self.advice(e, 3860)
        self.assertEqual(advice[1:3], ["Keep", "Blacksmithing needs it from 210 (you're at 180), for Heavy Mithril Gauntlet"])
        self.skills(e, blacksmithing=225)                               # the user's case: 225, the coif ahead
        self.assertEqual(self.why(e, 3860)[1], "Blacksmithing needs it from 235 (you're at 225), for Mithril Coif")
        self.skills(e, blacksmithing=240)                               # in the middle of its stretch: now
        self.assertEqual(self.why(e, 3860)[1], "Blacksmithing needs it now (you're at 240), for Mithril Coif")
        self.skills(e, blacksmithing=250)                               # an alternative of a later step
        self.assertEqual(self.why(e, 3860)[1], "Blacksmithing needs it from 260 (you're at 250), for Heavy Mithril Boots")
        self.skills(e, blacksmithing=265)                               # past every step that uses it
        self.assertEqual(self.why(e, 3860), ("keep", "kept: nothing says it's junk"))
        self.skills(e, blacksmithing=100)                               # Thorium is 160 points away: not soon
        verdict, _, want = M.Verdict(12359)
        self.assertIsNone(want.ahead)
        self.assertEqual(e.errors(), [])

    def test_ore_counts_through_the_bar_a_miner_of_yours_smelts(self):
        e = self.env(blacksmithing=180, mining=150)
        self.assertEqual(self.why(e, 3858)[1], "made into Mithril Bar: Blacksmithing needs it from 210 (you're at 180), "
                                               "for Heavy Mithril Gauntlet")
        self.skills(e, blacksmithing=180, mining=90)                    # Mithril smelting is a long way off
        self.assertIsNone(e.ns.Market.Verdict(3858)[2].ahead)
        self.skills(e, blacksmithing=180)                               # nobody of yours smelts it
        self.assertIsNone(e.ns.Professions.Ahead(3858))
        self.assertEqual(e.errors(), [])

    def test_another_character_of_yours_and_the_setting(self):
        e = self.env(who="Sol-Forever", blacksmithing=180)
        self.assertEqual(self.why(e, 3860)[1], "Blacksmithing needs it from 210 (Sol is at 180), for Heavy Mithril Gauntlet")
        e.db.inventory["Far-Elsewhere"] = e.db.inventory["Sol-Forever"]
        e.db.inventory["Sol-Forever"] = None                            # another realm: cannot be mailed there
        self.assertIsNone(e.ns.Professions.Ahead(3860))
        e.db.inventory["Sol-Forever"] = e.db.inventory["Far-Elsewhere"]
        e.cmd("skillkeep off")
        self.assertIsNone(e.ns.Professions.Ahead(3860))
        self.assertEqual(e.errors(), [])

    def test_a_recipe_another_of_yours_knows_counts_from_where_it_was_seen(self):
        e = self.env(blacksmithing=150)
        e.lua.eval("""function(db)
            db.skillKnown = { ["Sol-Forever"] = { blacksmithing = { ["Shiny Helm"] = 99002 } } }
            db.skillMakes = { [99002] = { m = 1, k = "blacksmithing", r = { [99001] = 3 } } }
            db.skillSteps = { blacksmithing = { ["Shiny Helm"] = { o = 190 } } }
        end""")(e.db)
        self.assertEqual(self.why(e, 99001)[1], "Blacksmithing needs it from 190 (you're at 150), for Shiny Helm")
        e.lua.eval("function(db) db.skillKnown['Ghostlight-Forever'] = { blacksmithing = { ['Shiny Helm'] = 99002 } } end")(e.db)
        self.assertIsNone(e.ns.Professions.Ahead(99001))                # yours already: its colour says (skill-ups)
        self.assertEqual(e.errors(), [])

    def golden_rod(self, e):
        T, now = e.lua.table, e.g.time()
        bs = self.me(e).prof.blacksmithing
        bs.crafts = e.lua.table_from({3577: e.lua.table_from([T(p=11128, n=1, m=1)]),
                                      3478: e.lua.table_from([T(p=11128, n=2, m=1)])})
        e.lua.eval("function(db) db.skillMakes = { [11128] = { m = 1, k = 'blacksmithing', r = { [3577] = 1, [3478] = 2 } } } end")(e.db)
        e.db.auction[11128] = T(p=12000, t=now)                         # Golden Rod 1g 20s
        e.db.auction[3577] = T(p=4500, t=now)                           # Gold Bar 45s
        e.db.auction[3478] = T(p=1000, t=now)                           # Coarse Grinding Stone 10s

    def test_a_material_as_it_is_against_crafted_every_material_counted(self):
        e = self.env(blacksmithing=225)                                 # (past the steps that use them)
        M, P = e.ns.Market, e.ns.Professions
        self.golden_rod(e)
        c = M.CraftValue(3577)
        # 1g 20s less the house's cut (1g 14s), less two grinding stones (20s): 94s for one Gold Bar, against 42s 75c
        self.assertEqual((round(c.each), round(c.own), c.others, c.worth), (9400, 4275, 2000, True))
        verdict, more, want = M.Verdict(3577)
        self.assertEqual((verdict, more), ("craft", 5125))
        self.assertEqual(self.advice(e, 3577)[1:], ["Keep", "Craft into Golden Rod: 94s each vs 42s 75c as it is",
                                                    "Golden Rod sells for 1g 20s at auction; the other materials cost 20s"])
        lines = [[plain(x) for x in l.values()] for l in M.Lines(3577).values()]
        self.assertIn(["Crafting", "Craft into Golden Rod: 94s each vs 42s 75c as it is"], lines)
        e.db.auction[3577].p = 9000                                     # the bars bring nearly as much as they are
        self.assertEqual(M.Verdict(3577)[0], "keep")
        self.assertIn("Crafting into Golden Rod isn't worth the effort: 94s each vs 85s 50c as it is", self.advice(e, 3577))
        e.db.auction[11128].p = 2000                                    # the materials cost more than it sells for
        self.assertIn("Crafting into Golden Rod isn't worth the effort: the materials cost more than it sells for",
                      self.advice(e, 3577))
        e.db.auction[11128] = None                                      # nothing to go by
        self.assertIn("No auction price for Golden Rod yet: visit the auction house to compare", self.advice(e, 3577))
        e.db.auction[11128] = e.lua.table(p=12000, t=e.g.time() - 9 * 86400)
        e.db.auction[3478] = None
        self.assertIn("No auction price for Coarse Grinding Stone yet: visit the auction house to compare",
                      self.advice(e, 3577))
        e.db.merchantPrice[3478] = 1000                                 # a merchant's price will do
        advice = self.advice(e, 3577)
        self.assertIn("Crafting into Golden Rod isn't worth the effort: 94s each vs 85s 50c as it is", advice)
        self.assertEqual(advice[-1], "these prices are 9 days old")    # and an old price says so
        self.assertEqual(P.Crafts(3577, 8550), None)
        self.assertEqual(e.errors(), [])

    def test_ore_against_its_bars(self):
        e = self.env(mining=200)
        M, now = e.ns.Market, e.g.time()
        e.db.auction[3858] = e.lua.table(p=300, t=now)
        e.db.auction[3860] = e.lua.table(p=1000, t=now)
        # 9s 50c a bar against 2s 85c an ore: 6s 65c more each, 66s 50c over a stack of ten
        self.assertEqual(M.Verdict(3858)[0], "craft")
        self.assertEqual(self.advice(e, 3858)[1:], ["Keep", "Smelt into Mithril Bar: 9s 50c each vs 2s 85c as it is",
                                                    "Mithril Bar sells for 10s at auction"])
        e.db.auction[3858].p = 900
        self.assertIn("Smelting into Mithril Bar isn't worth the effort: 9s 50c each vs 8s 55c as it is",
                      self.advice(e, 3858))
        self.assertEqual(e.errors(), [])

    def test_what_making_one_costs_against_what_it_sells_for(self):
        e = self.env(blacksmithing=225)
        M = e.ns.Market
        self.golden_rod(e)
        tip = [plain(list(l.values())[0]) for l in e.mock.itemTooltip(11128).values()]
        self.assertIn("Materials: 65s", tip)                            # a Gold Bar and two stones, at what they cost
        self.assertIn("Profit: +49s", tip)                              # 1g 14s after the house's cut
        e.db.auction[11128].p = 6000
        self.assertIn("Profit: -8s", [plain(list(l.values())[0]) for l in e.mock.itemTooltip(11128).values()])
        e.db.auction[3478] = None
        self.assertIn("Materials: no price for Coarse Grinding Stone yet",
                      [plain(list(l.values())[0]) for l in e.mock.itemTooltip(11128).values()])
        self.skills(e, blacksmithing=225, mining=200)                   # a bar a miner of yours smelts
        e.db.auction[3858] = e.lua.table(p=300, t=e.g.time())
        e.db.auction[3860] = e.lua.table(p=1000, t=e.g.time())
        self.assertEqual([[plain(x) for x in l.values()] for l in M.CostLines(3860).values()],
                         [["Materials", "3s"], ["Profit", "+6s 50c"]])
        e.cmd("craftcost off")
        self.assertEqual(len(M.CostLines(3860)), 0)
        self.assertEqual(e.errors(), [])

    def test_merchant_prices_are_noted(self):
        def setup(env):
            env.lua.execute("""
                MERCHANT = { { 2880, 100, 1, -1 }, { 4470, 190, 5, -1 }, { 5000, 500, 1, 3 }, { 5001, 700, 1, -1, true },
                             { 5002, 0, 1, -1 } }
                GetMerchantNumItems = function() return #MERCHANT end
                GetMerchantItemLink = function(i) return "|Hitem:" .. MERCHANT[i][1] .. "|h[x]|h" end
                GetMerchantItemInfo = function(i)
                    local m = MERCHANT[i]
                    return "x", 1, m[2], m[3], m[4], true, true, m[5] or false
                end""")
        e = Env(setup=setup)
        e.mock.openMerchant(True)
        prices = e.db.merchantPrice
        self.assertEqual((prices[2880], prices[4470]), (100, 38))       # each, also for what comes five at a time
        self.assertEqual((prices[5000], prices[5001], prices[5002]), (None, None, None))   # few, tokens, free
        P = e.ns.Professions
        self.assertEqual(P.Cost(2880)[0], 100)
        e.db.auction[2880] = e.lua.table(p=60, t=e.g.time())           # the lower of the two
        self.assertEqual(P.Cost(2880)[0], 60)
        again = Env(db=e.mock.serialize(e.g.ControllerCamHUDDB))        # kept with your settings
        self.assertEqual(again.db.merchantPrice[2880], 100)
        self.assertEqual(e.errors(), [])


class CookingRecipes(unittest.TestCase):
    """A Cooking or First Aid drop is kept for a recipe you could still learn, and says where to get it."""

    ITEMS = {12037: "Mystery Meat", 12232: "Recipe: Carrion Surprise", 12213: "Carrion Surprise",
             12214: "Mystery Stew", 12217: "Dragonbreath Chili", 2673: "Coyote Meat", 2678: "Mild Spices",
             16072: "Expert Cookbook", 6291: "Raw Brilliant Smallfish", 4306: "Silk Cloth"}

    def env(self, rank=180, cap=225, faction="Horde", prof="Cooking"):
        e = Env()
        T = e.lua.table
        for id, name in self.ITEMS.items():
            e.mock["items"][id] = T(name=name, quality=1, price=40, stack=10, **{"class": 7})
        self.skill(e, rank, cap, prof)
        e.db.inventory["Ghostlight-Forever"].faction = faction
        e.db.auction[12037] = T(p=900, t=e.g.time())
        return e

    def skill(self, e, rank, cap=225, prof="Cooking"):
        e.mock.skills = e.lua.table_from([e.lua.table(name=prof, rank=rank, cap=cap)])
        e.mock.fire("SKILL_LINES_CHANGED")
        e.update(0.5)

    def advice(self, e, id):
        lines = [plain(list(l.values())[0]) for l in e.mock.itemTooltip(id).values()]
        return lines[lines.index("Recommendation:") + 1:]

    def test_every_recipe_of_the_cooking_and_first_aid_guides_is_known(self):
        e = Env()
        for kind in ("cooking", "firstaid"):
            for step in e.ns.LevelGuides[kind].values():
                for o in [step] + list((step.alts or {}).values()):
                    if not o.p:
                        continue
                    rec = e.ns.Recipes.For(kind, o.p)
                    self.assertTrue(rec, "%s: %s" % (kind, o.name))
                    self.assertEqual(sorted(o.r.values()), sorted(rec.r.values()), o.name)
        for kind in ("cooking", "firstaid"):
            for rec in e.ns.RecipeData[kind].values():                 # every one can be learned somewhere
                self.assertTrue(e.ns.Recipes.Source(rec, None) or rec.raid, rec.name)

    def test_mystery_meat_is_kept_and_says_where_the_recipe_is_sold(self):
        e = self.env()
        advice = self.advice(e, 12037)
        self.assertEqual(advice, [
            "Keep", "Cooking: makes Carrion Surprise (needs 175, you're at 180)",
            "The recipe is sold by Ogg'marr in Brackenwall Village, Dustwallow Marsh (more sellers: 2)",
            "Also goes into Dragonbreath Chili (200), Mystery Stew (175)", "could fetch 9s at the auction house"])
        self.assertKept(e.ns.Market, 12037)
        lines = [[plain(x) for x in l.values()] for l in e.ns.Market.Lines(12037).values()]
        self.assertIn(["", "The recipe is sold by Ogg'marr in Brackenwall Village, Dustwallow Marsh (more sellers: 2)"],
                      lines)
        e.db.inventory["Ghostlight-Forever"].faction = "Alliance"      # the other side's vendors
        self.assertEqual(self.advice(e, 12037)[1:3], [
            "Cooking: makes Mystery Stew (needs 175, you're at 180)",
            "The recipe is sold by Helenia Olden in Theramore Isle, Dustwallow Marsh (more sellers: 2)"])
        self.assertEqual(e.errors(), [])

    def test_a_vendor_in_your_zone_is_named_first_and_walking_traders_last(self):
        e = self.env()
        e.mock.zone = "Desolace"
        self.assertEqual(self.advice(e, 12037)[2],
                         "The recipe is sold by Kireena in Ghost Walker Post, Desolace (more sellers: 2)")
        R = e.ns.Recipes
        stew = R.For("cooking", 12214)                                   # a Horde cook: only the walking trader
        source = R.Source(stew, "H")
        self.assertEqual((source.how, source.order), ("vendor", 4))
        self.assertEqual(R.Where(source, "Cooking"),
                         "The recipe is sold by Super-Seller 680, who walks the road in Desolace")
        self.assertEqual(e.errors(), [])

    def test_a_trainers_recipe_a_known_one_and_one_that_has_gone_green(self):
        e = self.env(rank=60, cap=150)
        self.assertEqual(self.advice(e, 2673)[:3], ["Keep", "Cooking: makes Coyote Steak (needs 50, you're at 60)",
                                                    "Any Cooking trainer teaches it"])
        self.skill(e, 115, 150)                                        # Coyote Steak is green: not kept for it
        self.assertIsNone(e.ns.Recipes.Keep(2673))
        self.skill(e, 180)
        e.lua.eval("""function(db)
            db.skillKnown = { ["Ghostlight-Forever"] = { cooking = { ["Carrion Surprise"] = 12213 } } }
        end""")(e.db)
        self.assertEqual(self.advice(e, 12037)[1], "Cooking: your Carrion Surprise still gives a skill-up")
        self.assertIsNone(e.ns.Recipes.Book(12232))                    # you know it: its recipe is not kept
        self.skill(e, 280, 300)                                        # past every Mystery Meat recipe
        self.assertIsNone(e.ns.Recipes.Keep(12037))
        self.assertEqual(e.errors(), [])

    def test_a_recipe_far_off_is_a_note_under_the_usual_advice(self):
        e = self.env(rank=40, cap=75)
        self.assertIsNone(e.ns.Recipes.Keep(12037))
        advice = self.advice(e, 12037)
        self.assertIn("Later, Cooking: makes Carrion Surprise at 175 (you're at 40)", advice)
        self.assertIn("The recipe is sold by Ogg'marr in Brackenwall Village, Dustwallow Marsh (more sellers: 2)",
                      advice)
        e.db.adviceUnsure = 2                                          # sold when nothing says keep: still noted
        self.assertEqual(e.ns.Market.Verdict(12037)[0], "auction")
        self.assertIn("Later, Cooking: makes Carrion Surprise at 175 (you're at 40)", self.advice(e, 12037))
        self.assertEqual(e.errors(), [])

    def test_another_character_of_yours_cooks_and_nobody_does(self):
        e = self.env(rank=10, prof="Alchemy")                          # you do not cook
        self.assertIsNone(e.ns.Recipes.Keep(12037))
        T = e.lua.table
        e.db.inventory["Sol-Forever"] = T(bags=T(), bank=T(), faction="Horde",
                                          prof=T(cooking=T(name="Cooking", rank=190, cap=225)))
        self.assertEqual(self.advice(e, 12037)[1], "Sol's Cooking: makes Carrion Surprise (needs 175, now at 190)")
        self.assertEqual(self.advice(e, 12232)[1], "teaches Carrion Surprise (Cooking 175, for Sol, now at 190)")
        e.cmd("skillkeep off")
        self.assertIsNone(e.ns.Recipes.Keep(12037))
        self.assertIsNone(e.ns.Recipes.Book(12232))
        self.assertEqual(e.errors(), [])

    def test_a_recipe_item_and_a_skill_book_are_kept_for_who_can_use_them(self):
        e = self.env(rank=140, cap=150)
        self.assertEqual(self.advice(e, 12232)[:2], ["Keep", "teaches Carrion Surprise (Cooking 175, you're at 140)"])
        self.assertEqual(self.advice(e, 16072)[:2], ["Keep", "raises your Cooking to 225 (your cap is 150)"])
        self.skill(e, 180, 225)                                        # you have it already
        self.assertIsNone(e.ns.Recipes.Book(16072))
        self.assertEqual(e.errors(), [])

    def test_first_aid_too(self):
        e = self.env(rank=160, prof="First Aid")
        self.assertEqual(self.advice(e, 4306)[1:3], [
            "First Aid: makes Silk Bandage (needs 150, you're at 160)", "Any First Aid trainer teaches it"])
        self.skill(e, 180, prof="First Aid")                           # Silk Bandage green now: the manual's
        self.assertEqual(self.advice(e, 4306)[1:3], [
            "First Aid: makes Heavy Silk Bandage (needs 180, you're at 180)",
            "The recipe is sold by Balai Lok'Wein in Brackenwall Village, Dustwallow Marsh"])
        self.assertEqual(e.errors(), [])

    def test_where_a_material_comes_from(self):
        e = self.env()
        R = e.ns.Recipes
        self.assertEqual(R.How(6291), "auction")                       # fish, and you do not fish
        self.assertEqual(tuple(R.How(2678)), ("vendor", "trade supply vendors sell it"))
        self.assertEqual(R.How(12037), "auction")                      # meat: no profession brings it in
        e.mock.skills = e.lua.table_from([e.lua.table(name="Cooking", rank=180, cap=225),
                                          e.lua.table(name="Fishing", rank=90, cap=150)])
        e.mock.fire("SKILL_LINES_CHANGED")
        e.update(0.5)
        self.assertEqual(tuple(R.How(6291)), ("farm", "Fishing"))
        self.assertEqual(e.db.gatherSkills["Ghostlight-Forever"].fishing.rank, 90)
        self.assertEqual(len(e.ns.Professions.Unread()), 1)            # (fishing has no window to open)
        e.lua.execute("""
            GetMerchantNumItems = function() return 1 end
            GetMerchantItemLink = function() return "|Hitem:2678|h[x]|h" end
            GetMerchantItemInfo = function() return "x", 1, 10, 1, -1, true, true, false end""")
        e.mock.setUnit("npc", e.lua.table(name="Zargh"))
        e.mock.zone = "The Barrens"
        e.mock.openMerchant(True)
        self.assertEqual(tuple(R.How(2678)), ("vendor", "last seen sold by Zargh in The Barrens"))
        again = Env(db=e.mock.serialize(e.g.ControllerCamHUDDB))
        self.assertEqual(again.db.merchantSeen[2678][1], "Zargh")
        self.assertEqual(again.db.gatherSkills["Ghostlight-Forever"].fishing.rank, 90)
        self.assertEqual(e.errors(), [])


class CookingMentor(unittest.TestCase):
    """The Mentor's materials: the most you could need, and farm, vendor or auction on every line."""

    WINDOW = """
        RECIPES = {
            { name = "Cooking" },
            { name = "Longjaw Mud Snapper", kind = "optimal", reagents = { 6289 }, need = { 1 }, product = 4592 },
        }
        TRADE = { "Cooking", 51, 75 }
        GetTradeSkillLine = function() return TRADE[1], TRADE[2], TRADE[3] end
        GetNumTradeSkills = function() return #RECIPES end
        GetTradeSkillInfo = function(i) local r = RECIPES[i]; return r.name, r.kind or "header", 0, false, nil, r.ups end
        GetTradeSkillNumReagents = function(i) return #(RECIPES[i].reagents or {}) end
        GetTradeSkillReagentItemLink = function(i, k) return "|Hitem:" .. RECIPES[i].reagents[k] .. "|h[x]|h" end
        GetTradeSkillReagentInfo = function(i, k) return "x", 1, RECIPES[i].need[k], 0 end
        GetTradeSkillItemLink = function(i) return RECIPES[i].product and ("|Hitem:" .. RECIPES[i].product .. "|h[x]|h") end
        GetTradeSkillNumMade = function(i) return 1, 1 end
    """

    def env(self, fishing=False, guide=None):
        def setup(env):
            env.lua.execute(self.WINDOW)
        e = Env(setup=setup)
        if guide:
            e.lua.eval("function(ns) " + guide + " end")(e.ns)
        T = e.lua.table
        skills = [T(name="Cooking", rank=51, cap=75)]
        if fishing:
            skills.append(T(name="Fishing", rank=75, cap=150))
        e.mock.skills = e.lua.table_from(skills)
        for id, name in ((6289, "Raw Longjaw Mud Snapper"), (12037, "Mystery Meat"), (2678, "Mild Spices")):
            e.mock["items"][id] = T(name=name, stack=20, **{"class": 7})
        e.mock.fire("PLAYER_ENTERING_WORLD")
        e.update(0.5)
        e.window = e.g.CreateFrame("Frame", "TradeSkillFrame", e.g.UIParent)
        e.window.shown = True
        e.mock.fire("TRADE_SKILL_SHOW")
        e.update(0.5)
        return e

    def rows(self, e):
        LV = e.ns.Levelling
        LV.Refresh(LV)
        return [(plain(r.text.text), plain(r.right.text)) for r in LV.rows.values() if r.shown]

    def test_the_worst_case_covers_the_points_that_may_not_come(self):
        e = self.env()
        LV = e.ns.Levelling
        self.assertEqual(LV.Worst(10, 0), 10)                          # all orange: certain
        self.assertEqual(LV.Worst(12.5, 4), 17)                        # 12.5 on average, two spreads more
        step = LV.plan.steps[1]
        # 51 to 75 with Longjaw Mud Snapper (yellow from 90): orange all the way, a point each
        self.assertEqual((step.rec.n, step.crafts, LV.plan.need[6289]), ("Longjaw Mud Snapper", 24, 24))
        guided = LV.Plan(LV.read)
        guided.rank = 51
        e.lua.execute("TRADE = { 'Cooking', 95, 150 }")
        e.mock.fire("TRADE_SKILL_UPDATE")
        e.update(0.5)
        yellow = LV.plan.steps[1]
        self.assertGreater(yellow.crafts, yellow.to - yellow["from"])   # past 90 it is not a point every time
        self.assertEqual(e.errors(), [])

    def test_every_material_says_farm_vendor_or_auction(self):
        e = self.env()
        rows = self.rows(e)
        self.assertIn(("Raw Longjaw Mud Snapper  (auction)", "up to 24"), rows)
        self.assertIn("Still needed to reach 75, at most:", [r[0] for r in rows])
        e = self.env(fishing=True)
        self.assertIn(("Raw Longjaw Mud Snapper  (farm)", "up to 24"), self.rows(e))
        LV = e.ns.Levelling
        LV.Focus(LV, True)
        LV.Choose(LV, len(list(LV.entries.values())))
        detail = plain(e.g.ControllerCamHUD_SkillPlanPanel.detail.text)
        self.assertEqual(detail, "Raw Longjaw Mud Snapper: at most 24 to reach 75. You have 0, so 24 more at most."
                                 "\nFarm it: your Fishing brings it in.")
        self.assertEqual(LV.HowWords(e.lua.table(how="farm", route=e.lua.table_from(
            [e.lua.table(id=6289, n=12), e.lua.table(id=12037, n=2)]))), "farm: Raw Longjaw Mud Snapper x12, ...")
        self.assertEqual(LV.HowWords(e.lua.table(how="farm", buy=True)), "farm")   # never turned into "buy it"
        self.assertEqual(LV.HowSentence(2678), "Buy it from a vendor: trade supply vendors sell it.")
        e.db.auction[12037] = e.lua.table(p=900, t=e.g.time())
        self.assertEqual(LV.HowSentence(12037), "Buy it at the auction house (9s each when last seen).")
        self.assertEqual(e.errors(), [])

    def test_a_recipe_to_learn_says_who_sells_it(self):
        e = self.env(guide="""ns.LevelGuides = { cooking = {
            { 1, 300, p = 12213, n = 400, learn = "vendor", at = 175, r = { 12037, 1, 2692, 1 }, name = "Carrion Surprise" },
        } }""")
        LV = e.ns.Levelling
        rows = self.rows(e)
        self.assertIn("up to x", rows[0][0])
        self.assertIn("(auction)", [t for t, _ in rows if t.startswith("Mystery Meat")][0])
        self.assertIn("(vendor)", [t for t, _ in rows if t.startswith("item 2692")][0])
        LV.Focus(LV, True)
        LV.Choose(LV, 1)
        self.assertIn("Learn it at 175. The recipe is sold by Ogg'marr in Brackenwall Village, Dustwallow Marsh",
                      plain(e.g.ControllerCamHUD_SkillPlanPanel.detail.text))
        self.assertEqual(e.errors(), [])


class MentorGrey(unittest.TestCase):
    """The game's colour wins over the guide: a recipe it rates grey never teaches and never gets an arrow."""

    # Leatherworking 106/150, as in the game: Cured Medium Hide is grey, the guide still has it for 100-115
    WINDOW = """
        RECIPES = {
            { name = "Reagents" },
            { name = "Cured Medium Hide", kind = "trivial", reagents = { 4232, 4289 }, need = { 1, 1 }, product = 4233 },
            { name = "Medium Leather", kind = "trivial", reagents = { 2318 }, need = { 4 }, product = 2319 },
            { name = "Fine Leather Belt", kind = "trivial", reagents = { 2318, 2320 }, need = { 6, 2 }, product = 4246 },
            { name = "Fine Leather Tunic", kind = "easy", reagents = { 2318, 2321 }, need = { 3, 4 }, product = 4243 },
            { name = "Gray Leather Boots", kind = "medium", reagents = { 2319, 2321 }, need = { 4, 2 }, product = 2315 },
        }
        TRADE = { "Leatherworking", 106, 150 }
        GetTradeSkillLine = function() return TRADE[1], TRADE[2], TRADE[3] end
        GetNumTradeSkills = function() return #RECIPES end
        GetTradeSkillInfo = function(i) local r = RECIPES[i]; return r.name, r.kind or "header", 0, false, nil, r.ups end
        GetTradeSkillNumReagents = function(i) return #(RECIPES[i].reagents or {}) end
        GetTradeSkillReagentItemLink = function(i, k) return "|Hitem:" .. RECIPES[i].reagents[k] .. "|h[x]|h" end
        GetTradeSkillReagentInfo = function(i, k) return "x", 1, RECIPES[i].need[k], 0 end
        GetTradeSkillItemLink = function(i) return RECIPES[i].product and ("|Hitem:" .. RECIPES[i].product .. "|h[x]|h") end
        GetTradeSkillNumMade = function(i) return 1, 1 end
    """

    NAMES = {4232: "Medium Hide", 4289: "Salt", 4233: "Cured Medium Hide", 2318: "Light Leather",
             2319: "Medium Leather", 2320: "Coarse Thread", 2321: "Fine Thread", 4246: "Fine Leather Belt",
             4249: "Dark Leather Belt", 4340: "Gray Dye", 2934: "Ruined Leather Scraps", 2315: "Dark Leather Boots"}

    def env(self, change=""):
        e = Env(setup=lambda env: env.lua.execute(self.WINDOW + change))
        T = e.lua.table
        e.mock.skills = e.lua.table_from([T(name="Leatherworking", rank=106, cap=150)])
        for id, name in self.NAMES.items():
            e.mock["items"][id] = T(name=name, stack=20, **{"class": 7})
        e.mock.fire("PLAYER_ENTERING_WORLD")
        e.update(0.5)
        e.window = e.g.CreateFrame("Frame", "TradeSkillFrame", e.g.UIParent)
        e.window.shown = True
        e.mock.fire("TRADE_SKILL_SHOW")
        e.update(0.5)
        return e

    def rows(self, e):
        LV = e.ns.Levelling
        LV.Refresh(LV)
        return [(str(r.text.text), plain(r.right.text)) for r in LV.rows.values() if r.shown]

    def test_a_grey_recipe_is_made_for_a_later_step_and_teaches_nothing(self):
        e = self.env()
        LV = e.ns.Levelling
        plan = LV.plan
        steps = list(plan.steps.values())
        self.assertNotIn("Cured Medium Hide", [s.rec.n for s in steps])
        for s in steps:
            self.assertGreaterEqual(s.colour, 1, s.rec.n)
        self.assertEqual(steps[0]["from"], 106)                        # its points go to a recipe that teaches
        self.assertIn(steps[0].rec.n, ("Gray Leather Boots", "Fine Leather Tunic"))
        for a, b in zip(steps, steps[1:]):
            self.assertEqual(a.to, b["from"])
        self.assertEqual(steps[-1].to, 150)
        m = plan.makes[1]
        self.assertEqual((m.rec.n, m.wants), ("Cured Medium Hide", "Dark Leather Belt"))
        belt = steps[-1]
        self.assertEqual((belt.rec.n, m.count, m.crafts), ("Dark Leather Belt", belt.crafts, belt.crafts))
        rows = self.rows(e)
        hide = [(t, n) for t, n in rows if t.startswith("Cured Medium Hide  x")]
        self.assertEqual(len(hide), 1)
        self.assertEqual(plain(hide[0][0]), "Cured Medium Hide  x%d  make for Dark Leather Belt" % belt.crafts)
        self.assertEqual(hide[0][1], "")                               # no skill range
        for text, right in rows:
            if "Cured Medium Hide" in text:
                self.assertNotIn("|A:", text)                          # and no skill-up arrow
                self.assertNotIn("-", right)
        self.assertNotIn("Cured Medium Hide", LV.Words(plan))
        self.assertEqual(plan.raw[4232], belt.crafts)                  # its materials are still listed
        self.assertEqual(plain(LV.RecipeText("Old", 0)), "Old")
        LV.Focus(LV, True)
        at = next(i for i, x in enumerate(LV.entries.values(), 1) if x.mat)
        LV.Choose(LV, at)
        self.assertIn("Grey for you now, so it gives no skill points. Make it for Dark Leather Belt.",
                      plain(e.g.ControllerCamHUD_SkillPlanPanel.detail.text))
        LV.Farm(LV, False)
        self.assertEqual(sorted(x.id for x in e.db.farm.values()), [4232, 4289])
        e.mock.put(0, 1, e.lua.table(id=4233, name="Cured Medium Hide", count=belt.crafts))
        e.mock.fire("BAG_UPDATE_DELAYED")
        e.update(0.5)
        self.assertEqual(len(LV.Plan(LV.read).makes), 0)               # you hold them all: nothing to make
        self.assertEqual(e.errors(), [])

    # at 113 as in the game: the guide's boots have turned green, a rare belt of dropped scales is still orange
    LATER = """
        RECIPES[6].kind = "easy"
        RECIPES[#RECIPES + 1] = { name = "Deviate Scale Belt", kind = "optimal", reagents = { 6470, 6471 },
            need = { 10, 10 }, product = 6468 }
        RECIPES[#RECIPES + 1] = { name = "Dark Leather Cloak", kind = "medium", reagents = { 2319, 2321, 4340 },
            need = { 8, 1, 1 }, product = 2316 }
        TRADE[2] = 113
    """

    def test_a_green_recipe_and_a_rare_one_give_way_to_a_yellow_one(self):
        e = self.env(self.LATER)
        LV = e.ns.Levelling
        steps = list(LV.plan.steps.values())
        self.assertEqual((steps[0].rec.n, steps[0]["from"]), ("Dark Leather Cloak", 113))
        self.assertGreaterEqual(steps[0].to, 125)                      # the guide's green boots are passed over
        self.assertNotIn("Deviate Scale Belt", [s.rec.n for s in steps])
        self.assertNotIn("Gray Leather Boots", [s.rec.n for s in steps])
        self.assertNotIn(6471, [i for i in LV.plan.need.keys()])
        self.assertEqual(e.errors(), [])

    def test_what_you_can_farm_counts_as_the_cheapest_and_is_never_to_buy(self):
        e = self.env()
        LV = e.ns.Levelling
        e.lua.execute("""
            local ns = ControllerCamHUD.ns
            ns.db.auction = { [2319] = { p = 900, t = 0 }, [2318] = { p = 800, t = 0 }, [2321] = { p = 200, t = 0 } }
        """)
        self.assertEqual(LV.Effort(2319), 900)                         # bought: its price
        e.lua.execute("""
            local R = ControllerCamHUD.ns.Recipes
            local how = R.How
            R.How = function(id) if id == 2318 or id == 2319 then return "farm", "Skinning" end return how(id) end
        """)
        self.assertEqual((LV.Effort(2319), LV.Effort(2318)), (1, 1))   # farmed: next to nothing
        self.assertEqual(LV.Effort(2321), 200)                         # thread is still bought
        plan = e.lua.eval("""{ raw = { [2318] = 40 }, total = { [2318] = 40 }, made = { [2319] = 10 },
            need = { [2319] = 10 }, via = { [2318] = 2319 } }""")
        row = LV.Wanted(plan)[1]                                       # buying would be cheaper, but you farm it
        self.assertFalse(row.buy)
        self.assertEqual(row.how, "farm")
        self.assertEqual(e.errors(), [])

    def test_a_material_you_gather_is_not_broken_down_into_lesser_ones(self):
        e = self.env()
        LV = e.ns.Levelling
        e.lua.execute("""
            ControllerCamHUD.ns.db.skillMakes = { [2319] = { m = 1, k = "leatherworking", r = { [2318] = 4 } },
                [2318] = { m = 1, k = "leatherworking", r = { [2934] = 3 } } }
            local R = ControllerCamHUD.ns.Recipes
            R.How = function(id) if id == 2318 or id == 2319 or id == 2934 then return "farm", "Skinning" end return "auction" end
        """)
        need = e.lua.eval("{ [2319] = 20 }")
        raw, total, made, via = LV.Breakdown(need)
        self.assertEqual(dict(raw.items()), {2319: 20})                # skinned as it is
        self.assertEqual(total[2319], 20)
        e.mock.put(0, 1, e.lua.table(id=2318, name="Light Leather", count=9))   # parts you hold are used first
        e.mock.fire("BAG_UPDATE_DELAYED")
        e.update(0.5)
        raw, total, made, via = LV.Breakdown(need)
        self.assertEqual(dict(raw.items()), {2319: 18})                # two are made from what you hold
        self.assertEqual(total[2319], 20)
        self.assertEqual(e.errors(), [])

    def test_a_recipe_that_sells_well_wears_the_coin(self):
        e = self.env()
        LV = e.ns.Levelling
        rec = next(r for r in LV.read.list.values() if r.n == "Fine Leather Belt")     # grey, 6 leather, 2 thread
        self.assertIsNone(LV.Sells(rec))                               # no prices: no flag
        e.lua.execute("""
            ControllerCamHUD.ns.db.auction = { [4246] = { p = 10000, t = 0 }, [2318] = { p = 100, t = 0 },
                [2320] = { p = 100, t = 0 } }
        """)
        worth = LV.Sells(rec)
        self.assertEqual((worth.income, worth.cost, worth.profit), (9500, 800, 8700))
        rows = self.rows(e)
        self.assertIn("Worth making to sell:", [plain(t) for t, _ in rows])
        belt = [(t, n) for t, n in rows if "UI-GoldIcon" in t and "Fine Leather Belt" in t]
        self.assertEqual(len(belt), 1)
        self.assertIn("87s", plain(belt[0][1]))
        LV.Focus(LV, True)
        LV.Choose(LV, next(i for i, x in enumerate(LV.entries.values(), 1) if x.sell))
        self.assertIn("Sells well: about 87s profit each", plain(e.g.ControllerCamHUD_SkillPlanPanel.detail.text))
        self.assertEqual(LV.Farm(LV, False), 0)
        e.lua.execute("ControllerCamHUD.ns.db.auction[4246].p = 1000")  # barely above its materials
        self.assertIsNone(LV.Sells(rec))
        self.assertEqual(e.errors(), [])

    def test_the_headline_credits_the_guides_only_with_what_is_theirs(self):
        e = self.env(self.LATER)
        LV = e.ns.Levelling
        T = e.lua.table
        first = LV.plan.steps[1]
        self.assertTrue(first.filled)                                  # a pick of your own recipes
        other = T(rec=T(n="Dark Leather Boots"), why=e.lua.table_from(["nohide"]), side=True, crafts=3)
        first.alts = e.lua.table_from([other])
        for voice in range(4):
            LV.voice = voice
            self.assertNotIn("guides", LV.Words(LV.plan))
            self.assertIn("if you'd rather: no slow farm", LV.Words(LV.plan))
        bought = T(rec=T(n="Deviate Scale Belt"), why=e.lua.table(), side=True, crafts=3)
        first.alts = e.lua.table_from([bought])                       # for money to spend: not put forward
        for voice in range(6):
            LV.voice = voice
            self.assertNotIn("Deviate", LV.Words(LV.plan))
            self.assertNotIn("guides", LV.Words(LV.plan))
        self.assertEqual(e.errors(), [])

    def test_a_marked_row_keeps_its_mark_on_one_line(self):
        e = self.env()
        marked = [t for t, _ in self.rows(e) if "[slow farm]" in t or "[costly]" in t or "[by auction]" in t]
        self.assertTrue(marked)
        for text in marked:
            name = plain(text).split("\n")[0]
            self.assertNotIn("[", name, text)                         # the mark is on the line under the name
        self.assertEqual(e.errors(), [])

    def test_a_recipe_you_do_not_have_says_where_to_get_it(self):
        e = self.env()                                                # Dark Leather Belt asks for 125; you're at 106
        LV = e.ns.Levelling
        belt = next(t for t, right in self.rows(e) if "Dark Leather Belt" in plain(t) and "up to x" in t)
        self.assertIn("|cffff2020^|r", belt)                          # beyond your skill: the red mark
        self.assertNotIn("ActiveQuestIcon", belt)
        self.assertIn("\n", belt)                                    # and where to get it, on its own line
        self.assertIn("Learn it at a trainer, at 125.", plain(belt))
        e.lua.execute("""
            C_Texture = C_Texture or {}
            C_Texture.GetAtlasInfo = function() return { file = 4200, leftTexCoord = 0, rightTexCoord = 0.5,
                topTexCoord = 0.25, bottomTexCoord = 0.75 } end
        """)
        self.assertEqual(LV.RedArrow(), "|T4200:12:12:0:0:1024:1024:0:512:256:768:255:40:40|t")
        plan = LV.plan
        step = list(plan.steps.values())[-1]
        plan.rank = 130                                               # now you could learn it: the game's "?"
        self.assertIn("ActiveQuestIcon", LV.Unowned(plan, step.rec, step.learn))
        self.assertEqual(e.errors(), [])

    def test_a_hard_pick_has_an_easier_one_and_a_bought_one_beside_it(self):
        e = self.env(self.LATER + """
            RECIPES[#RECIPES + 1] = { name = "Hillman's Shoulders", kind = "optimal", reagents = { 2319, 4233 },
                need = { 4, 1 }, product = 4251 }
        """)
        LV = e.ns.Levelling
        e.lua.execute("""
            local ns = ControllerCamHUD.ns
            ns.db.skillMakes = ns.db.skillMakes or {}
            ns.db.skillMakes[4233] = { m = 1, k = "leatherworking", r = { [4232] = 1, [4289] = 1 } }
            local R = ns.Recipes
            R.How = function(id) if id == 2319 or id == 4232 then return "farm", "Skinning" end
                if id == 4289 or id == 2321 or id == 4340 then return "vendor" end return "auction" end
        """)
        usual = LV.Usual("leatherworking")
        rec = {r.n: r for r in LV.read.list.values()}
        hides = LV.Cost(rec["Hillman's Shoulders"], 20, usual)
        self.assertEqual((LV.Hard(hides), hides.slow[4232]), ("slow", 20))
        self.assertEqual(LV.Hard(LV.Cost(rec["Deviate Scale Belt"], 5, usual)), "auction")
        self.assertIsNone(LV.Hard(LV.Cost(rec["Dark Leather Cloak"], 5, usual)))
        plan = LV.Plan(LV.read)
        first = plan.steps[1]
        self.assertEqual(len(list(first.cost.auction.values())), 0)    # the plan itself: nothing to buy at auction
        names = [a.rec.n for a in first.alts.values() if a.rec]
        if LV.Hard(first.cost):
            self.assertIn("Deviate Scale Belt", names)                  # beside it, for money to spend
        self.assertNotIn("Deviate Scale Belt", [s.rec.n for s in plan.steps.values()])
        LV.plan = plan
        for text, right in self.rows(e):
            if "Deviate Scale Belt" in text:
                self.assertIn("[by auction]", text)
        self.assertIn("you'd buy at the auction house",
                      plain(LV.CostSentence(LV.Cost(rec["Deviate Scale Belt"], 5, usual))))
        self.assertIn("A slow farm:", LV.CostSentence(hides))
        self.assertEqual(e.errors(), [])

    def test_a_green_or_rare_recipe_is_used_when_nothing_better_teaches(self):
        e = self.env(self.LATER + "RECIPES[#RECIPES].kind = 'trivial'")       # no yellow cloak
        LV = e.ns.Levelling
        usual = LV.Usual("leatherworking")
        fit = lambda name: LV.Fitness(next(r for r in LV.read.list.values() if r.n == name), usual)
        self.assertEqual(fit("Gray Leather Boots"), 2)                 # green
        self.assertEqual(fit("Deviate Scale Belt"), 3)                 # dropped scales, no guide uses them
        steps = list(LV.plan.steps.values())
        self.assertNotEqual(steps[0].rec.n, "Deviate Scale Belt")
        self.assertEqual(e.errors(), [])

    def test_no_recipe_of_yours_teaches_and_the_plan_says_so(self):
        e = self.env("RECIPES[5].kind = 'trivial'; RECIPES[6].kind = 'trivial'")
        plan = e.ns.Levelling.plan
        steps = list(plan.steps.values())
        for s in steps:
            self.assertTrue(s.learn, s.rec.n)                          # only what is still to learn teaches
            self.assertNotEqual(s.rec.n, "Cured Medium Hide")
        covered = sum(s.to - s["from"] for s in steps)
        self.assertEqual(plan.short or 0, 150 - 106 - covered)         # the rest is said to be short
        self.assertGreater(plan.short, 0)
        self.assertEqual(e.errors(), [])

    def test_the_games_colour_wins_over_the_recipe_table(self):
        e = Env()
        LV = e.ns.Levelling
        T = e.lua.table
        rec = T(n="Longjaw Mud Snapper", p=4592, c=1, u=1)             # the table: orange at 60; the game: green
        learned = T()
        table = (90, 110, 130)
        self.assertNotEqual(tuple(LV.Colours("cooking", rec, True, 60, learned)), table)
        rec.c = 3
        self.assertEqual(tuple(LV.Colours("cooking", rec, True, 60, learned)), table)
        self.assertEqual(tuple(LV.Colours("cooking", rec, False, 60, learned)), table)
        self.assertNotEqual(tuple(LV.Colours("cooking", rec, True, 135, learned)), table)   # grey there, not here
        self.assertEqual(e.errors(), [])

    def test_guessed_colours_never_run_the_counts_away(self):
        e = self.env()
        LV = e.ns.Levelling
        for s in LV.plan.steps.values():
            points = s.to - s["from"]
            self.assertGreaterEqual(s.crafts, 1, s.rec.n)
            self.assertLessEqual(s.crafts, max(points * 4, 15 * 4), s.rec.n)
        self.assertEqual(LV.Bound(500, 10, 2), 20)
        self.assertEqual(LV.Bound(12, 10, 2), 12)
        self.assertEqual(LV.Bound(None, 10, 1), 40)
        self.assertEqual(e.errors(), [])

    def test_no_row_prints_over_the_next(self):
        e = self.env()
        LV = e.ns.Levelling
        LV.Refresh(LV)
        down, two = 0, 0
        for r in LV.rows.values():
            if not r.shown:
                continue
            self.assertEqual(r.points[1][5], -(LV.layout.top + down))
            tall = r.height + 1
            self.assertGreaterEqual(tall, LV.TextHeight(r.text, 9, r.text.width) + 6)
            if "\n" in str(r.text.text):
                two += 1
                self.assertGreater(tall, 20)
            down += tall
        self.assertGreater(two, 0)                                     # a route takes its own line
        self.assertEqual(LV.layout.tall, down)
        self.assertGreaterEqual(e.g.ControllerCamHUD_SkillPlanPanel.height, LV.layout.top + down + 24)
        self.assertEqual(e.errors(), [])


class Commentary(unittest.TestCase):
    """Your character has something to say now and then: out loud in your people's voice, or a plain thought."""

    RACES = ("Human", "Dwarf", "Gnome", "NightElf", "Draenei", "Worgen", "Pandaren", "Orc", "Scourge", "Tauren",
             "Troll", "BloodElf", "Goblin", "HighOrder", "Windshaper")

    def env(self, race="Dwarf", pole=True, **kw):
        e = FishJournal().env(pole=pole, **kw)
        e.lua.execute("function UnitRace() return '%s', '%s' end" % (race, race))
        e.update(2)                                                   # (logged in; the fishing interface up)
        return e

    def roll(self, e, value, weight=0.5):
        e.ns.Commentary.random = lambda: value
        e.ns.FishLog.random = lambda: weight

    def words(self, e):
        r = e.ns.Commentary.Current()
        return plain(e.ns.Commentary.Words(r)) if r else None

    def land(self, e, *ids):
        FishJournal().land(e, *ids)

    def test_a_switch_of_its_own_under_the_narrative(self):
        e = self.env()
        C = e.ns.Commentary
        self.assertTrue(e.db.commentary)
        place = e.ns.OptionsLook.PlaceOf(next(d for d in e.ns.settings.values() if d.key == "commentary"))
        self.assertEqual((place.page, place.group.head), ("General", "Narrative"))
        self.assertTrue(e.ns.BASIC_OPTIONS["Character commentary"])
        self.assertTrue(C.On())
        e.cmd("commentary off")
        self.assertFalse(C.On())
        self.roll(e, 0.0)
        self.land(e, 6291)
        self.assertIsNone(self.words(e))
        self.assertTrue(e.ns.Narrative.On())                         # the windows keep their characters
        e.cmd("commentary on")
        e.cmd("narrative off")                                       # the narrative's switch turns it off too
        self.assertFalse(C.On())
        self.land(e, 6303)
        self.assertIsNone(self.words(e))
        self.assertEqual(e.errors(), [])

    def test_a_new_fish_is_a_thought_and_sometimes_a_word_out_loud(self):
        e = self.env()
        C = e.ns.Commentary
        self.roll(e, 0.0)                                             # (out loud this time)
        self.land(e, 6291)
        said = self.words(e).split("\n")
        self.assertEqual(said[0], "\u201cOch, now what're you, then?\u201d")
        self.assertIn("Raw Brilliant Smallfish, ", said[1])
        self.assertIn(" lb. A new one for my journal. The first fish most anglers ever land", said[1])
        self.assertTrue(e.db.remarkMemory.told["fish:6291"])          # lore is told once
        card = e.g.ControllerCamHUD_Speaker_fish                      # on your card at the water
        self.assertTrue(card.shown)
        self.assertEqual(plain(card.words.text), self.words(e))
        self.assertIn("|c" + C.THOUGHT, card.words.text)              # the thought is pale
        self.assertIsNone(e.g.ControllerCamHUD_Speaker_remark)
        self.roll(e, 0.9)
        self.land(e, 6303)                                            # quiet this time: a thought, lips still
        self.assertNotIn("\u201c", self.words(e))
        self.assertIn("Raw Slitherskin Mackerel", self.words(e))
        self.assertTrue(C.Speaker(C.Current()).still)
        e.update(C.HOLD + 1)                                          # and your card goes back to what it said
        self.assertIsNone(self.words(e))
        self.assertNotIn("journal", str(e.ns.Narrative.Said("fish")))
        self.assertEqual(e.errors(), [])

    def test_a_record_worth_the_name_is_cheered_in_your_peoples_voice(self):
        e = self.env(race="MagharOrc")                                # kin speak alike
        C = e.ns.Commentary
        self.roll(e, 0.9, weight=0.2)
        self.land(e, 6291)
        was = e.db.fishLog.fish[6291].best
        e.update(C.HOLD + 1)
        self.roll(e, 0.9, weight=1.0)
        self.land(e, 6291)
        words = self.words(e)
        self.assertTrue(words.startswith("\u201cA worthy opponent!\u201d")
                        or words.startswith("\u201cIt fought with honour."), words)
        self.assertIn("My best before was %.1f lb." % was, words)
        self.assertFalse(C.Speaker(C.Current()).still)                # lips move for what is said out loud
        e.update(C.HOLD + 1)
        e.db.fishLog.fish[6291].best = e.db.fishLog.fish[6291].best - 0.1   # barely past it: not worth a cheer
        self.land(e, 6291)
        self.assertIsNone(self.words(e))
        self.assertEqual(e.errors(), [])

    def test_most_ordinary_catches_pass_without_a_word(self):
        e = self.env()
        C = e.ns.Commentary
        self.roll(e, 0.9)
        self.land(e, 6291)                                            # new
        e.update(C.QUIET)
        self.land(e, 6291)                                            # ordinary, and the dice say no
        self.assertIsNone(self.words(e))
        self.roll(e, 0.0)
        self.land(e, 6291)
        first = self.words(e)
        self.assertTrue(first.startswith("Raw Brilliant Smallfish, "), first)
        self.assertNotIn("\u201c", first)                             # a thought
        e.update(C.HOLD + 1)
        self.land(e, 6291)                                            # too soon after the last
        self.assertIsNone(self.words(e))
        e.update(C.QUIET)
        self.land(e, 6291)
        self.assertNotEqual(self.words(e), first)                     # another sort of thought
        e.update(C.QUIET)
        self.land(e, 6297)                                            # an old skull is no fish
        self.assertTrue(self.words(e).startswith("Old Skull. "), self.words(e))
        self.assertNotIn(" lb", self.words(e))
        self.assertEqual(e.errors(), [])

    def test_the_thoughts_that_fit_a_catch(self):
        e = self.env()
        C, T = e.ns.Commentary, e.lua.table
        e.lua.execute("function BASE(J) return (J.Base(6291, 'x')) end")
        base = e.g.BASE(e.ns.FishLog)

        def sorts(**kw):
            entry = T(**kw.pop("entry", {}))
            return {t.what: t.line for t in C.CatchThoughts(T(entry=entry, **kw)).values()}
        got = sorts(id=6308, name="Catfish", weight=1.0, where="Durotar", map=1411, count=3, away=2, total=50,
                    entry=dict(n=7, firstAt="Westfall", best=9.0, bestAt="Loch Modan"))
        self.assertEqual(got["count"], "That makes 7 of these in my journal.")
        self.assertEqual(got["first"], "My journal's first of these came from Westfall.")
        self.assertEqual(got["heaviest"], "My heaviest of these is still 9.0 lb, landed at Loch Modan.")
        self.assertEqual(got["session"], "That's 3 of these since I got to this water.")
        self.assertEqual(got["away"], "2 got away since I started here. This one didn't.")
        self.assertEqual(got["total"], "Catch number 50 for the journal.")
        self.assertIn("whiskers", got["sort"])                        # what sort of fish it is
        self.assertIn("whiskers like a dwarven elder", got["lore"])   # the journal's own lore
        self.assertIn("Durotar", got["water"])                        # and the water's
        self.assertIn("musing", got)
        few = sorts(id=999, name="Odd Fish", weight=1.0, where="Durotar", count=1, away=0, total=3,
                    entry=dict(n=1, firstAt="Durotar"))
        self.assertEqual(set(few) - {"big", "small"}, {"musing"})
        names = lambda w: set(sorts(id=6291, name="x", weight=w, where="Durotar", entry=dict(n=1)))
        self.assertIn("big", names(base * 1.5))
        self.assertIn("small", names(base * 0.6))
        self.assertFalse({"big", "small"} & names(base))
        self.assertNotIn("big", sorts(id=6311, name="22 Pound Catfish", weight=22, where="Durotar",
                                      entry=dict(n=1)))              # a fish that names its weight
        self.assertEqual(e.errors(), [])

    def test_no_line_comes_round_again_until_the_others_have(self):
        e = self.env()
        C = e.ns.Commentary
        pool = e.lua.table_from(["a", "b", "c", "d"])
        said = [C.Pick("t", pool) for _ in range(40)]
        self.assertEqual(set(said[:4]), {"a", "b", "c", "d"})
        self.assertTrue(all(x != y for x, y in zip(said, said[1:])), said)     # never twice running
        self.assertTrue(all(said.count(x) >= 8 for x in "abcd"), said)
        two = [C.Pick("u", e.lua.table_from(["x", "y"])) for _ in range(10)]
        self.assertTrue(all(x != y for x, y in zip(two, two[1:])), two)
        self.assertEqual(C.Pick("v", e.lua.table_from(["only"])), "only")
        self.assertEqual(C.Pick("v", e.lua.table_from(["only"])), "only")

    def test_every_people_has_its_voice_for_every_occasion(self):
        e = self.env()
        said, N = e.ns.Remarks.said, e.ns.Narrative
        for race in self.RACES:
            self.assertTrue(N.CALM[race] and N.RACE[race], race)
            for occasion in ("new", "record", "boss", "treasure"):
                self.assertEqual(len(said[occasion][race]), 2, (race, occasion))
        e.lua.execute("function UnitRace() return 'Fox', 'Vulpera' end")        # no voice: it only thinks
        self.assertIsNone(e.ns.Commentary.Aloud("record"))

    def test_the_two_skyborne_speak_apart(self):
        e = self.env()
        N = e.ns.Narrative
        for number, people in ((95, "HighOrder"), (96, "Windshaper")):  # one name in the game, two peoples
            e.lua.execute("function UnitRace() return 'Skyborne', 'Skyborne', %d end" % number)
            self.assertEqual(N.Race(), people)
        for side, people in (("Alliance", "HighOrder"), ("Horde", "Windshaper")):   # without a number: by side
            e.lua.execute("""function UnitRace() return 'Skyborne', 'Skyborne' end
                             function UnitFactionGroup() return '%s' end""" % side)
            self.assertEqual(N.Race(), people)
        e.ns.Commentary.random = lambda: 0.0
        self.assertEqual(e.ns.Commentary.Aloud("boss"), "The winds were with us. We owe them for it.")
        self.assertEqual(e.errors(), [])

    def test_without_the_fishing_interface_it_has_a_card_of_its_own(self):
        e = self.env(pole=False)
        C = e.ns.Commentary
        self.roll(e, 0.9)
        self.assertTrue(C.Say(e.lua.table(thought="A thought.", rank=2)))
        card = e.g.ControllerCamHUD_Speaker_remark
        self.assertTrue(card.shown)
        self.assertEqual(plain(card.words.text), "A thought.")
        self.assertTrue(e.same(card.parent, e.g.ControllerCamHUD_RemarkSpot))
        self.assertFalse(C.Say(e.lua.table(thought="Less.", rank=1)))  # something greater is on show
        self.assertEqual(self.words(e), "A thought.")
        e.update(C.HOLD - 0.7)
        self.assertLess(card.alpha, 1)                                # fading
        e.update(1)
        self.assertFalse(card.shown)
        self.assertIsNone(self.words(e))
        self.assertEqual(e.errors(), [])

    def test_never_in_a_fight_and_said_after_it(self):
        e = self.env(pole=False)
        C = e.ns.Commentary
        e.mock.state.combat = True
        e.mock.fire("PLAYER_REGEN_DISABLED")
        C.Say(e.lua.table(thought="Later.", rank=4))
        C.Say(e.lua.table(thought="Not as much.", rank=1))
        self.assertIsNone(self.words(e))
        e.mock.state.combat = False
        e.mock.fire("PLAYER_REGEN_ENABLED")
        e.update(2)
        self.assertEqual(self.words(e), "Later.")
        e.mock.state.combat = True                                    # a fight begins: the card gets out of the way
        e.mock.fire("PLAYER_REGEN_DISABLED")
        self.assertFalse(e.g.ControllerCamHUD_Speaker_remark.shown)
        e.update(C.WAIT + 5)
        e.mock.state.combat = False
        e.mock.fire("PLAYER_REGEN_ENABLED")                           # old news by now
        e.update(2)
        self.assertIsNone(self.words(e))
        self.assertEqual(e.errors(), [])

    def test_lore_held_back_by_a_fight_is_not_counted_as_heard(self):
        e = self.env(pole=False)
        C = e.ns.Commentary
        e.mock.state.combat = True
        C.Say(e.lua.table(thought="A story.", rank=3, lore="water:1"))
        self.assertIsNone(e.db.remarkMemory.told["water:1"])
        e.update(C.WAIT + 5)
        e.mock.state.combat = False
        e.mock.fire("PLAYER_REGEN_ENABLED")                           # too late to be said: still to be told
        e.update(2)
        self.assertIsNone(e.db.remarkMemory.told["water:1"])
        C.Say(e.lua.table(thought="A story.", rank=3, lore="water:1"))
        self.assertTrue(e.db.remarkMemory.told["water:1"])
        self.assertEqual(e.errors(), [])

    def dungeon(self, e, number=36, name="The Deadmines"):
        e.lua.execute("function GetInstanceInfo() return '%s', 'party', 1, 'Normal', 5, 0, false, %d end"
                      % (name, number))

    def test_a_boss_down_the_first_time_and_the_times_after(self):
        e = self.env(pole=False)
        C = e.ns.Commentary
        self.dungeon(e)
        self.roll(e, 0.0)
        e.mock.fire("ENCOUNTER_END", 1144, "Edwin VanCleef", 1, 5, 1)
        e.mock.fire("BOSS_KILL", 1144, "Edwin VanCleef")             # the game may tell it twice
        words = self.words(e)
        self.assertEqual(words.split("\n")[0], "\u201cHa! Down ye go, and stay down!\u201d")
        self.assertIn("Edwin VanCleef is down. The Defias turned an old mine into a hideout", words)
        self.assertEqual(C.Mine().bosses["Edwin VanCleef"], 1)
        self.assertEqual((e.db.remarkMemory.events.ENCOUNTER_END, e.db.remarkMemory.events.BOSS_KILL), (1, 1))
        self.assertIn("ENCOUNTER_END 1, BOSS_KILL 1", e.ns.Narrative.Describe())
        e.update(60)
        e.mock.fire("ENCOUNTER_END", 1145, "Cookie", 1, 5, 0)        # a wipe is not a kill
        self.assertIsNone(self.words(e))
        e.mock.fire("ENCOUNTER_END", 1145, "Cookie", 1, 5, 1)
        self.assertIn("Cookie is down. All that digging", self.words(e))   # the place's other line
        e.update(60)
        e.mock.fire("BOSS_KILL", 1146, "Mr. Smite")                  # both told: a thought that fits any boss
        self.assertIn("Mr. Smite is down. ", self.words(e))
        self.assertNotIn("Defias", self.words(e))
        e.update(60)
        e.mock.fire("BOSS_KILL", 1144, "Edwin VanCleef")             # again: now and then
        self.assertEqual(self.words(e), "Edwin VanCleef again. That makes 2 times.")
        e.update(60)
        self.roll(e, 0.9)
        e.mock.fire("BOSS_KILL", 1144, "Edwin VanCleef")
        self.assertIsNone(self.words(e))
        self.assertEqual(C.Mine().bosses["Edwin VanCleef"], 3)       # counted all the same
        self.assertEqual(e.errors(), [])

    def test_a_boss_whose_name_the_game_keeps_secret(self):
        e = self.env(pole=False)
        self.dungeon(e, 999, "Somewhere New")
        self.roll(e, 0.0)
        e.lua.execute("SECRET = { secret = true }")
        e.mock.state.combat = True                                    # it ends with the fight: said after
        e.mock.fire("ENCOUNTER_END", e.g.SECRET, e.g.SECRET, 1, 5, 1)
        e.mock.fire("BOSS_KILL", e.g.SECRET, e.g.SECRET)
        e.mock.state.combat = False
        e.mock.fire("PLAYER_REGEN_ENABLED")
        e.update(2)
        words = self.words(e)
        self.assertNotIn("is down", words)                            # no name, and no "nil" in its place
        self.assertNotIn("nil", words)
        self.assertIn("\u201c", words)
        self.assertEqual(len(list(e.ns.Commentary.Mine().bosses.keys())), 0)
        self.assertEqual(e.errors(), [])

    def test_a_new_place_gets_a_thought_but_not_too_often(self):
        e = self.env(pole=False)
        C = e.ns.Commentary
        self.assertTrue(C.Mine().zones["Durotar"])                    # where you stood at login: no news
        self.roll(e, 0.0)

        def walk(zone):
            e.mock.zone = zone
            e.mock.fire("ZONE_CHANGED_NEW_AREA")
            e.update(C.SETTLE + 1)
        walk("Durotar")
        self.assertIsNone(self.words(e))
        walk("The Barrens")
        self.assertEqual(self.words(e), "The Barrens. Worth a good look around.")
        e.update(C.HOLD)
        walk("Ashenvale")                                             # too soon: not noted, for another visit
        self.assertIsNone(self.words(e))
        self.assertIsNone(C.Mine().zones["Ashenvale"])
        e.update(C.AMBIENT)
        e.db.fishLog.zones["Ashenvale"] = e.lua.table(n=12, fish=e.lua.table())
        walk("Ashenvale")
        self.assertEqual(self.words(e), "Ashenvale. My journal has 12 catches from here.")
        e.update(C.AMBIENT)
        walk("The Barrens")                                           # been there
        self.assertIsNone(self.words(e))
        e.mock.taxi.onTaxi = True
        walk("Winterspring")                                          # flying over is not arriving
        self.assertIsNone(C.Mine().zones["Winterspring"])
        e.mock.taxi.onTaxi = False
        e.mock.zone = "Westfall"
        e.mock.fire("PLAYER_ENTERING_WORLD", False, False)           # a boat or a hearthstone is arriving
        e.update(C.SETTLE + 1)
        self.assertIn("Westfall. ", self.words(e))
        e.update(C.AMBIENT)
        e.mock.zone = "Duskwood"
        e.mock.fire("PLAYER_ENTERING_WORLD", False, True)            # a reload is not
        e.update(C.SETTLE + 1)
        self.assertIsNone(self.words(e))
        self.assertEqual(e.errors(), [])

    def test_only_some_jobs_done_get_a_word(self):
        e = self.env(pole=False)
        C = e.ns.Commentary
        e.lua.execute("""
            TITLES = { [1] = "Sting of the Scorpid", [2] = "Vile Familiars", [3] = "The Defias Brotherhood" }
            C_QuestLog.GetTitleForQuestID = function(id) return TITLES[id] or ("Job " .. id) end
            C_QuestLog.GetQuestTagInfo = function(id) if id == 3 then return { tagID = 81 } end end""")
        self.roll(e, 0.0)

        def hand_in(quest):
            e.mock.fire("QUEST_TURNED_IN", quest, 100, 0)
        hand_in(1)                                                    # the first here
        self.assertEqual(self.words(e), "\u201cSting of the Scorpid\u201d, finished. Someone's day just got better.")
        e.update(C.AMBIENT + 1)
        hand_in(2)
        self.assertIsNone(self.words(e))                              # an ordinary one: not a word
        e.lua.execute("function GetQuestID() return 3 end function GetTitleText() return TITLES[3] end")
        e.mock.fire("QUEST_COMPLETE")                                 # read while the log still has it
        e.lua.execute("C_QuestLog.GetQuestTagInfo = function() return nil end")
        hand_in(3)
        self.assertEqual(self.words(e), "\u201cThe Defias Brotherhood\u201d, done. That one was no errand.")
        for quest in range(4, 10):
            e.update(C.AMBIENT + 1)
            hand_in(quest)
            self.assertIsNone(self.words(e), quest)
        e.update(C.AMBIENT + 1)
        hand_in(10)
        self.assertEqual(self.words(e), "Durotar: 10 jobs done here since I started keeping count.")
        self.assertEqual(C.Mine().quests["Durotar"], 10)
        self.assertEqual(e.errors(), [])

    def loot(self, e, source, *items, coin=False):
        """A loot window: items are (id, name, quality, the game's sort); source is the GUID's first word."""
        rows = []
        for i, name, quality, sort in items:
            e.mock["items"][i] = e.lua.table(name=name, **{"class": sort})
            rows.append(e.lua.table(id=i, name=name, quality=quality))
        if coin:
            rows.append(e.lua.table(name="12 Copper", coin=True))
        e.lua.execute("""
            LOOT_FROM = nil
            function GetLootSourceInfo() return LOOT_FROM end
            local link = GetLootSlotLink_ or GetLootSlotLink
            local info = GetLootSlotInfo_ or GetLootSlotInfo
            GetLootSlotLink_, GetLootSlotInfo_ = link, info
            function GetLootSlotInfo(i)                          -- (coin: a name, and no item behind it)
                local it = require_mock.loot[i]
                if it and it.coin then return 1, it.name, 0, nil, 0, false end
                return info(i)
            end
            function GetLootSlotLink(i)
                if require_mock.loot[i] and require_mock.loot[i].coin then return nil end
                return link(i)
            end""".replace("require_mock", "MOCK"))
        e.g.MOCK = e.mock
        e.g.LOOT_FROM = source and "%s-0-1-2-3-%d" % (source, self.looted()) or None
        e.mock.loot = e.lua.table_from(rows)
        e.mock.fire("LOOT_READY")
        e.mock.fire("LOOT_OPENED")
        e.mock.loot = e.lua.table()
        e.mock.fire("LOOT_CLOSED")

    count = 0

    def looted(self):
        Commentary.count += 1
        return Commentary.count

    def test_a_chest_you_loot_gets_a_word(self):
        e = self.env(pole=False)
        C = e.ns.Commentary
        self.roll(e, 0.0)
        self.loot(e, "GameObject", (2000, "Green Iron Boots", 2, 4), coin=True)
        words = self.words(e)
        self.assertEqual(words.split("\n")[0], "\u201cOch, now there's a bit o' treasure!\u201d")
        self.assertIn("Green Iron Boots. Somebody left this behind. Did they mean to come back?", words)
        self.assertEqual(C.Mine().finds, 1)
        e.update(C.HOLD + 1)
        self.loot(e, "GameObject", (2001, "Ice Cold Milk", 1, 0), (2002, "Linen Cloth", 1, 7))   # soon after
        self.assertIsNone(self.words(e))
        self.assertEqual(C.Mine().finds, 2)                           # counted all the same
        self.loot(e, "GameObject", (2003, "Blade of the Deep", 3, 2))   # something rare is not kept waiting
        self.assertIn("Blade of the Deep. Why would anyone leave something like this behind?", self.words(e))
        self.assertIn("\u201c", self.words(e))
        e.update(C.TREASURE + 1)
        self.roll(e, 0.9)
        self.loot(e, "Item", coin=True)                               # a lockbox from your bags, coin alone
        self.assertNotIn("\u201c", self.words(e))                     # a quiet one
        self.assertEqual(e.errors(), [])

    def test_a_find_is_counted_once_and_every_tenth_is_told(self):
        e = self.env(pole=False)
        C = e.ns.Commentary
        self.roll(e, 0.9)
        C.Mine().finds = 9
        self.loot(e, "GameObject", coin=True)
        self.assertEqual(self.words(e), "10 finds like this since I started keeping count.")
        same = e.g.LOOT_FROM
        e.update(C.TREASURE + 1)
        e.mock.loot = e.lua.table_from([e.lua.table(name="1 Copper", coin=True)])
        e.g.LOOT_FROM = same
        e.mock.fire("LOOT_READY")                                     # the chest left half full, opened again
        e.mock.fire("LOOT_CLOSED")
        self.assertIsNone(self.words(e))
        self.assertEqual(C.Mine().finds, 10)
        self.assertEqual(e.errors(), [])

    def test_what_is_not_treasure_passes_without_a_word(self):
        e = self.env(pole=False)
        C = e.ns.Commentary
        self.roll(e, 0.0)
        rich = ((3001, "Malachite", 2, 7), (3002, "Rough Stone", 1, 7))
        self.loot(e, "Creature", (3000, "Fine Boots", 2, 4), coin=True)           # a corpse
        self.loot(e, None, (3000, "Fine Boots", 2, 4), coin=True)                 # the game does not say from what
        self.loot(e, "GameObject", (3003, "Red Candle", 1, 12), coin=True)        # what a quest wants
        self.loot(e, "GameObject", (3004, "Mushroom", 1, 0))                      # one plain thing
        self.loot(e, "Item", (3005, "Clam Meat", 1, 7), (3006, "Shell", 1, 15))   # a clam
        self.loot(e, "GameObject", *rich)                                         # ore: all trade goods
        e.lua.execute("SECRET = { secret = true }")
        e.g.GetNumLootItems_ = e.g.GetNumLootItems
        for spell, name in ((2575, "Mining"), (2366, "Herb Gathering"), (13262, "Disenchant"), (99999, "Mining")):
            e.mock.spellNames[spell] = name
            e.mock.fire("UNIT_SPELLCAST_SENT", "player", "Vein", "cast", spell)
            self.loot(e, "GameObject", (3001, "Malachite", 2, 7), (3007, "Silver Bar", 2, 4))
        self.assertIsNone(self.words(e))
        self.assertIsNone(C.Mine().finds)
        e.mock.fire("UNIT_SPELLCAST_SENT", "player", "Battered Chest", "cast", 3365)   # opening a chest is not work
        self.loot(e, "GameObject", (3000, "Fine Boots", 2, 4))
        self.assertIn("Fine Boots. ", self.words(e))
        e.update(C.TREASURE + 1)
        e.mock.fishingLoot = True                                     # what is on the line is the catch's affair
        self.loot(e, "GameObject", coin=True)
        self.assertIsNone(self.words(e))
        self.assertEqual(e.errors(), [])

    def test_a_box_on_the_line_is_treasure_not_junk(self):
        e = self.env()
        C = e.ns.Commentary
        self.roll(e, 0.9)
        e.mock["items"][21150] = e.lua.table(name="Iron Bound Trunk", **{"class": 15})
        self.land(e, 21150)
        self.assertEqual(self.words(e), "Iron Bound Trunk. A box on a fishing line. What could be inside?")
        self.assertEqual(C.Mine().finds, 1)
        e.update(C.TREASURE + 1)
        e.cmd("commentary off")
        self.land(e, 21150)
        self.assertIsNone(self.words(e))
        self.assertEqual(e.errors(), [])

    def test_what_is_remembered_survives_and_bad_data_is_cleaned(self):
        e = Env(db="""{ remarkMemory = { told = { ["fish:6291"] = true, [4] = true }, chars = { ["A-B"] = {
            zones = { Durotar = true }, bosses = "junk" } }, events = { BOSS_KILL = 2, x = "y" } } }""")
        m = e.db.remarkMemory
        self.assertTrue(m.told["fish:6291"])
        self.assertIsNone(m.told[4])
        self.assertTrue(m.chars["A-B"].zones.Durotar)
        self.assertEqual(len(list(m.chars["A-B"].bosses.keys())), 0)
        self.assertEqual(m.events.BOSS_KILL, 2)
        self.assertIsNone(m.events.x)
        self.assertEqual(e.errors(), [])


class HealerNames(unittest.TestCase):
    """Who is healing: the others' names on a bar while their heals are on their way, only as the game tells it."""

    # the game's answer per healer: a unit's "healers" = { [healer unit] = amount }, its "incoming" the total
    PER_HEALER = """function(mock)
        function UnitGetIncomingHeals(unit, healer)
            local u = mock.units[unit]
            if not u then return nil end
            if not healer then return u.incoming end
            return (u.healers and u.healers[healer]) or 0
        end
    end"""

    def env(self, **kw):
        e = Env(**kw)
        e.lua.eval(self.PER_HEALER)(e.mock)
        return e

    def unit(self, e, token, name, **kw):
        data = e.lua.table(name=name, health=500, healthMax=1000, isPlayer=True, **{"class": "PRIEST"})
        for k, v in kw.items():
            data[k] = v
        e.mock.setUnit(token, data)
        return data

    def heal(self, e, data, token, total, **healers):
        data.incoming, data.healers = total, e.lua.table(**healers)
        e.mock.fire("UNIT_HEAL_PREDICTION", token)

    def overlay(self, e, i=1):
        return e.ns.Group.overlays[e.g.PartyFrame["MemberFrame%d" % i]]

    def party(self, e):
        return [self.unit(e, "party%d" % i, name)
                for i, name in enumerate(("Mira Dawnfield", "Tovin-Ashe", "Anselm", "Brannoc"), 1)]

    def said(self, bar):
        fs = bar.healerText
        return fs.text if fs and fs.shown else None

    def test_another_healer_is_named_yours_is_not_and_it_clears_as_the_heal_lands(self):
        e = self.env()
        mira = self.party(e)[0]
        bar = self.overlay(e).health
        self.heal(e, mira, "party1", 300, player=100, party2=200)
        self.assertEqual(self.said(bar), "Tovin")                           # first name, and not yours
        self.heal(e, mira, "party1", 100, player=100)                       # only yours left: nobody to name
        self.assertIsNone(self.said(bar))
        self.heal(e, mira, "party1", 200, party3=200)
        self.assertEqual(self.said(bar), "Anselm")
        self.heal(e, mira, "party1", 0)                                     # landed or cancelled
        self.assertIsNone(self.said(bar))
        self.assertEqual(e.errors(), [])

    def test_several_healers_two_names_then_how_many_more(self):
        e = self.env()
        me = e.mock.units.player
        self.party(e)
        bar = e.frames.player.health
        self.heal(e, me, "player", 600, party1=100, party2=200, party4=300)
        self.assertEqual(self.said(bar), "Mira, Tovin +1")                  # in the group's order: they hold still
        self.heal(e, me, "player", 500, party2=200, party4=300)
        self.assertEqual(self.said(bar), "Tovin, Brannoc")
        e.cmd("healernames off")
        self.assertIsNone(self.said(bar))
        self.assertTrue(bar.othersBar.shown)                                # the heal itself stays
        e.cmd("healernames on")
        self.assertEqual(self.said(bar), "Tovin, Brannoc")
        self.assertEqual(e.errors(), [])

    def test_the_vertical_bars_stack_them_and_pet_bars_have_none(self):
        e = self.env(db="{ v = 4, units = { vertical = true, pet = true } }")
        me = e.mock.units.player
        self.party(e)
        pet = self.unit(e, "pet", "Snarl", isPlayer=False)
        self.heal(e, me, "player", 600, party1=100, party2=100, party3=200, party4=200)
        self.assertEqual(self.said(e.frames.vertical.health), "Mira\nTovin\nAnselm\n+1")
        self.heal(e, pet, "pet", 100, party1=100)
        self.assertTrue(e.frames.vpet.health.healBar or e.frames.vpet.health.othersBar)
        self.assertIsNone(self.said(e.frames.vpet.health))
        self.assertEqual(e.errors(), [])

    def test_a_healer_outside_the_group_is_named_once_by_your_target_or_focus(self):
        e = self.env()
        me = e.mock.units.player
        self.unit(e, "party1", "Mira", guid="g-mira")
        self.unit(e, "target", "Mira", guid="g-mira")                       # your target: the same person
        self.unit(e, "focus", "Stranger Hale", guid="g-hale")
        bar = e.frames.player.health
        self.heal(e, me, "player", 900, party1=200, target=200, focus=300)
        self.assertEqual(self.said(bar), "Mira, Stranger")
        self.assertEqual(e.errors(), [])

    def test_an_amount_the_game_keeps_to_itself_names_nobody(self):
        e = self.env()
        mira = self.party(e)[0]
        bar = self.overlay(e).health
        secret = e.mock.secret
        mira.incoming, mira.healers = secret(), e.lua.table(player=secret(), party2=secret())
        e.mock.fire("UNIT_HEAL_PREDICTION", "party1")
        self.assertIsNone(self.said(bar))                                   # no guess at who
        self.assertTrue(bar.healBar.shown)                                  # the heal itself still shows
        # a healer's own amount told, the totals kept: that one is named
        mira.healers = e.lua.table(player=secret(), party2=secret(), party3=150)
        e.mock.fire("UNIT_HEAL_PREDICTION", "party1")
        self.assertEqual(self.said(bar), "Anselm")
        # a name kept secret is handed to the game to write, never read
        e.mock.units.party3.name = secret()
        e.mock.fire("UNIT_HEAL_PREDICTION", "party1")
        self.assertTrue(bar.healerText.shown)
        self.assertEqual(e.errors(), [])

    def test_in_a_raid_the_raid_is_asked_and_never_you(self):
        e = self.env()
        me = e.mock.units.player
        e.mock.units.raid1 = me                                             # you, as the raid counts you
        self.unit(e, "raid7", "Oriel Vance")
        self.heal(e, me, "player", 400, player=100, raid1=100, raid7=300)
        self.assertEqual(self.said(e.frames.player.health), "Oriel")
        self.assertEqual(e.errors(), [])

    def test_the_healers_rows_name_them_too(self):
        e = HealerFrames().env(mode=3)
        e.lua.eval(self.PER_HEALER)(e.mock)
        mira = HealerFrames().member(e, 1)
        HealerFrames().member(e, 2)
        row = e.ns.Group.party[1].h
        self.heal(e, mira, "party1", 200, party2=200)
        self.assertEqual(self.said(row.health), "Friend2")
        self.heal(e, mira, "party1", 0)
        self.assertIsNone(self.said(row.health))
        HealerFrames().member(e, 3)                          # a healer's party row has room for two names
        self.heal(e, mira, "party1", 600, party2=200, party3=400)
        self.assertEqual(self.said(row.health), "Friend2, Friend3")
        self.assertEqual(e.errors(), [])

    def test_a_raid_tile_has_room_for_one_name_and_how_many_more(self):
        e = HealerFrames().env(mode=3)
        e.lua.eval(self.PER_HEALER)(e.mock)
        native = e.mock.raidFrame(1, "raid1")
        native.height = 36
        data = self.unit(e, "raid1", "Raider")
        self.unit(e, "raid2", "Mira")
        self.unit(e, "raid3", "Tovin")
        e.update(0.3)
        tile = e.ns.Group.slim[native]
        self.heal(e, data, "raid1", 400, raid2=200, raid3=200)
        self.assertEqual(self.said(tile.health), "Mira +1")
        self.assertEqual(e.errors(), [])


class FormSets(unittest.TestCase):
    """Each form and stance its own actions: the game's own Stance Bar, its setting in our options, and a form's
    bar filled with its abilities the first time you shift into it (FormSets.lua)."""
    ON = "{ enabled = true, asked = true, screenAsked = true }"
    # the game: a druid's forms, its stance bar (eight slots for each stance, bear's from 281), its setting, the
    # spells you know by name (the highest rank's id), and dragging as the game does it
    GAME = """function(mock)
        mock.forms = { { spell = 5487, name = "Bear Form" }, { spell = 768, name = "Cat Form" },
                       { spell = 783, name = "Travel Form" } }
        mock.form = 0
        GetNumShapeshiftForms = function() return #mock.forms end
        GetShapeshiftFormInfo = function(i) return 132276, i == mock.form, true, mock.forms[i].spell end
        GetShapeshiftForm = function() return mock.form end
        mock.known, mock.names = {}, {}
        mock.learn = function(base, name, id) mock.names[base], mock.known[name] = name, id end
        GetSpellInfo = function(id)
            if type(id) == "string" then
                if mock.known[id] then return id, nil, nil, nil, nil, nil, mock.known[id] end
                return nil
            end
            for _, f in ipairs(mock.forms) do if f.spell == id then return f.name end end
            if mock.names[id] then return mock.names[id] end
            for name, known in pairs(mock.known) do if known == id then return name end end
        end
        C_GamepadUI = {
            GetFirstGamepadActionBarStorageSlotIndexForActiveStance = function()
                if mock.form > 0 then return 281 + (mock.form - 1) * 8 end
            end,
            GetFirstGamepadActionStorageSlotIndex = function() return 181 end,
            IsValidGamepadActionStorageSlotIndex = function(i) return i >= 181 and i <= 320 end,
        }
        mock.cvars.GamepadStanceBarOverride, mock.defaults.GamepadStanceBarOverride = "3", "3"
        mock.knownCVars.GamepadStanceBarOverride = true
        Enum = Enum or {}
        Enum.GamepadStanceBarOverride = { None = 1, Page1LeftBar = 2, Page1RightBar = 3, Page1BottomBar = 4,
                                          Page2RightBar = 7 }
        mock.placed, mock.bonus, mock.actions, mock.refuses = {}, 0, {}, {}
        GetBonusBarOffset = function() return mock.bonus end
        GetActionInfo = function(slot) local a = mock.actions[slot]; if a then return a[1], a[2] end end
        PickupSpell = function(id) mock.cursor = id end
        PickupMacro = function(id) mock.cursor = id end
        GetCursorInfo = function() if mock.cursor then return "spell", mock.cursor end end
        ClearCursor = function() mock.cursor = nil end
        PlaceAction = function(slot)
            if mock.refuses[slot] then return end
            mock.placed[slot], mock.cursor = mock.cursor, nil
        end
        HasAction = function(slot) return mock.placed[slot] ~= nil end
    end"""

    def env(self, db=None, game=True, cluster=None, **kw):
        def setup(env):
            if game:
                env.lua.eval(self.GAME)(env.mock)
            if cluster:
                env.mock.cvars["GamepadStanceBarOverride"] = cluster
        return Env(db=db or self.ON, setup=setup, **kw)

    def bear(self, e):
        e.mock.learn(6807, "Maul", 6809)                                          # (rank 2)
        e.mock.learn(6795, "Growl", 6795)
        e.mock.names[779] = "Swipe"                                               # not learned yet

    def shift(self, e, form):
        e.mock.form = form
        before = len(e.mock.printed)
        e.mock.fire("UPDATE_SHAPESHIFT_FORM")
        e.update(0.4)
        return "\n".join(list(e.mock.printed.values())[before:])

    def test_a_forms_own_bar_is_filled_once(self):
        e = self.env()
        self.bear(e)
        e.mock.learn(1082, "Claw", 1082)
        said = self.shift(e, 1)                                                    # bear: the game's slots 281-288
        self.assertIn("Bear Form now has 2 of its abilities on the game's own stance bar", said)
        self.assertEqual((e.mock.placed[281], e.mock.placed[282]), (6809, 6795))   # in order, the rank you know
        self.assertIsNone(e.mock.placed[283])
        self.assertEqual(self.shift(e, 1), "")                                     # once
        e.mock.state.combat = True
        self.assertEqual(self.shift(e, 2), "")                                     # cat, in a fight: not now
        self.assertIsNone(e.mock.placed[289])
        e.mock.state.combat = False
        e.mock.fire("PLAYER_REGEN_ENABLED")                                        # after it
        self.assertEqual(e.mock.placed[289], 1082)
        self.assertEqual(self.shift(e, 0), "")                                     # out of any form: no bar
        self.assertEqual(e.errors(), [])

    def test_what_is_on_the_bar_stays_and_the_rest_is_added(self):
        e = self.env()
        self.bear(e)
        e.mock.placed[282] = 6795                                                  # the game's own: growl, second
        e.mock.actions[282] = e.lua.table("spell", 6795)
        e.mock.placed[284] = 5                                                     # and something of yours
        said = self.shift(e, 1)
        self.assertIn("Bear Form now has 1 of its abilities", said)                # maul only: growl is there
        self.assertEqual(e.mock.placed[281], 6809)                                 # on the first empty button
        self.assertEqual((e.mock.placed[282], e.mock.placed[284]), (6795, 5))      # what was there, untouched
        self.assertIsNone(e.mock.placed[283])
        e.mock.placed[281] = None                                                  # you take it off: it stays off
        self.assertEqual(self.shift(e, 1), "")
        self.assertIsNone(e.mock.placed[281])
        self.assertEqual(e.errors(), [])

    def test_a_button_that_wont_take_one_is_passed_over(self):
        e = self.env()
        self.bear(e)
        e.mock.refuses[281] = True
        self.assertIn("now has 1 of its abilities", self.shift(e, 1))
        self.assertIsNone(e.mock.placed[281])
        self.assertEqual(e.mock.placed[282], 6795)                                 # the next ability, the next button
        self.assertEqual(e.errors(), [])

    def test_the_keyboard_bars_own_set_for_the_form_comes_first(self):
        e = self.env()
        self.bear(e)
        e.mock.bonus = 3                                                           # the bear bar: slots 97-108
        e.mock.actions[97] = e.lua.table("spell", 6795)                            # growl, first
        e.mock.actions[98] = e.lua.table("macro", 7)
        self.shift(e, 1)
        self.assertEqual([e.mock.placed[s] for s in (281, 282, 283)], [6795, 7, 6809])
        self.assertEqual(e.errors(), [])

    def test_a_full_bar_nothing_known_or_switched_off_does_nothing(self):
        e = self.env()
        self.bear(e)
        for slot in range(281, 289):
            e.mock.placed[slot] = 5
        self.assertEqual(self.shift(e, 1), "")
        self.assertEqual(e.mock.placed[281], 5)
        e2 = self.env()                                                            # nothing learned
        self.assertEqual(self.shift(e2, 1), "")
        self.bear(e2)                                                              # learned since: at the next shift
        self.assertIn("now has 2", self.shift(e2, 1))
        e3 = self.env()
        self.bear(e3)
        e3.cmd("formfill off")
        self.assertEqual(self.shift(e3, 1), "")
        self.assertIsNone(e3.mock.placed[281])
        self.assertEqual(e.errors() + e2.errors() + e3.errors(), [])

    def test_the_left_trigger_to_begin_with_once_for_each_character(self):
        e = self.env()
        self.assertEqual(e.mock.cvars["GamepadStanceBarOverride"], "2")           # the game's own start: ours
        self.assertEqual(e.ns.FormSets.StanceOverride()[0], "Page1LeftBar")
        e.mock.cvars["GamepadStanceBarOverride"] = "3"                            # you go back to the right trigger
        e.ns.Apply()
        self.assertEqual(e.mock.cvars["GamepadStanceBarOverride"], "3")           # it is left alone
        self.assertEqual(e.errors(), [])

    def test_a_cluster_you_chose_is_never_changed(self):
        e = self.env(cluster="4")                                                  # both triggers', from the game's menus
        self.assertEqual(e.mock.cvars["GamepadStanceBarOverride"], "4")
        self.assertEqual(e.errors(), [])

    def test_the_options_choose_which_cluster_a_form_takes(self):
        e = self.env()
        e.ns.BuildOptions()
        e.ns.RefreshOptions()
        row = [r for r in e.ns.optionRows.values() if r["def"].id == "stanceCluster"][0]
        self.assertTrue(row["basic"])
        self.assertTrue(row["buttons"][2].chosen)                                 # the left trigger, to begin with
        row["buttons"][4].scripts.OnClick(row["buttons"][4])                      # both triggers'
        self.assertEqual(e.mock.cvars["GamepadStanceBarOverride"], "4")
        self.assertTrue(row["buttons"][4].chosen)
        e.mock.state.combat = True
        self.assertIn("Not in combat", e.cmd("stancebar 3"))
        self.assertEqual(e.mock.cvars["GamepadStanceBarOverride"], "4")
        e.mock.state.combat = False
        e.mock.cvars["GamepadStanceBarOverride"] = "7"                            # a cluster of set 2: none lit
        e.ns.RefreshOptions()
        self.assertFalse(any(b.chosen for b in row["buttons"].values()))
        self.assertEqual(e.errors(), [])

    def test_the_report_and_check_say_how_it_stands(self):
        e = self.env()
        self.bear(e)
        self.shift(e, 1)
        report = "\n".join(e.ns.FormSets.Describe().values())
        self.assertIn("in place of Page1LeftBar (2)", report)
        self.assertIn("stance bar slots (counted): 281* 282* 283", report)
        self.assertIn("Bear Form: filled once", report)
        self.assertIn("Cat Form: not filled yet", report)
        self.assertEqual(e.ns.RunCheck(False)[0], 0)
        e.ns.Debug.Collect("test")
        self.assertEqual(e.errors(), [])

    def test_a_client_without_the_stance_bar_is_left_alone(self):
        e = self.env(game=False)
        self.assertFalse(e.ns.FormSets.Available())
        e.mock.fire("UPDATE_SHAPESHIFT_FORM")
        e.update(0.4)
        e.ns.BuildOptions()
        e.ns.Debug.Collect("test")
        self.assertEqual(e.ns.RunCheck(False)[0], 0)
        self.assertEqual(e.errors(), [])


if __name__ == "__main__":
    unittest.main()
